window.CFA_DEEP_CI =[{"module_id":"CFA26-03-01","module_title":"Organizational Forms, Corporate Issuer Features, and Ownership","subject":"Corporate Issuers","version":"1.9","language":"Vietnamese teaching with English CFA terms and English practice","qa_status":"DETAILED_DRAFT_PENDING_INDEPENDENT_ACADEMIC_AUDIT","disclaimer_vi":"Corporate Issuers Module 1 được biên soạn mới theo ba LOS CFAI 2026, đối chiếu Kaplan và slide. Nội dung pháp lý/thuế là mô tả khái quát theo giáo trình, thay đổi theo jurisdiction. Ví dụ và câu hỏi là tình huống minh họa tự tạo; kiểm tra số học/nguồn đã giới hạn phạm vi, chưa nghiệm thu đáp án độc lập toàn bộ.","los":[{"id":"CFA26-03-01-LOS01","letter":"1.a","title_en":"Organizational Forms of Businesses","outcome_en":"compare the organizational forms of businesses","overview_vi":"Phân biệt sole proprietorship, general partnership, limited partnership, LLP, private limited company và public limited company theo legal identity, owner-manager relationship, liability, transferability, taxation và financing access.","source":[{"id":"CFA Institute Curriculum 2026 — Corporate Issuers LM1","pages":"11–22 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading20","pages":"224–225, 228 (physical PDF)"},{"id":"SAPP Corporate Issuers 2026 — Module1","pages":"4–20 (physical PDF)"}],"sections":[{"heading":"Why organizational form matters","body":"Hình thức tổ chức doanh nghiệp xác định quan hệ pháp lý của chủ sở hữu, ai quản lý, ai chịu trách nhiệm về nợ và phạm vi gọi vốn. CFA Level I yêu cầu so sánh theo tiêu chí, không chỉ nhớ tên tổ chức trong từng nước.","trap":"A business name alone does not establish its exact legal liability treatment."},{"heading":"Businesses versus governments and nonprofits","body":"Market economies có business for-profit, government organizations và nonprofits. Learning Module này chủ yếu tập trung for-profit enterprises vì nhà phân tích tài chính đánh giá quyền và nghĩa vụ của nhà cung cấp vốn.","trap":"Do not apply every business tax or shareholder assumption to non-profits."},{"heading":"Five comparison dimensions","body":"So sánh bằng separate legal identity, owner–manager relationship, owner liability, access to financing và taxation; thêm transferability, continuity, growth potential để giải thích. Các chiều có thể khác nhau theo jurisdiction và loại agreement.","trap":"An entity can have limited liability but restricted ownership transfer."},{"heading":"Separate legal identity concept","body":"Một corporation/limited company có legal personhood tách khỏi owners theo luật, có thể own assets, borrow, sue và be sued. Sole proprietorship và general partnership trong khung CFAI được trình bày không có legal separation tương tự.","trap":"Separate legal entity and limited shareholder liability are related but distinct concepts."},{"heading":"Sole proprietorship ownership","body":"Sole proprietorship do một individual sở hữu, thường người này trực tiếp vận hành và quyết định operations. Chủ sở hữu giữ earnings sau thuế nhưng cũng tự gánh downside; legal entity thường là extension of owner.","trap":"Single ownership does not necessarily imply no employees."},{"heading":"Sole proprietorship unlimited liability","body":"Chủ sole proprietor có unlimited personal liability đối với obligations của business, có thể phải dùng personal assets để trả nợ nếu business assets thiếu. Khác với shareholder of a limited company có exposure chủ yếu ở equity investment.","trap":"Do not confuse business losses with a cap equal to initial contribution."},{"heading":"Sole proprietorship financing","body":"Growth của sole trader bị hạn chế bởi savings, bank credit, collateral và individual risk capacity; không thể dễ dàng bán public equity shares như large corporation. Ưu điểm là đơn giản và linh hoạt, chi phí hình thành thấp.","trap":"Simplicity does not create unlimited access to capital."},{"heading":"Sole proprietorship taxes","body":"Earnings của sole proprietor thường pass through to owner for personal income taxation, không chịu corporate-level tax thêm rồi dividend-level tax giống conventional public corporation. Thuế cụ thể luôn phụ thuộc jurisdiction.","trap":"Pass-through does not mean tax-free business income."},{"heading":"General partnership owners","body":"General partnership có nhiều partners cùng góp vốn, chia lợi nhuận, rủi ro và quyết định quản trị theo partnership agreement. Mọi partners thường có unlimited liability trong mô hình CFAI, kể cả khi một partner không điều hành từng ngày.","trap":"General partners are not limited partners."},{"heading":"General partnership liability sharing","body":"Khi partnership liabilities vượt tài sản đơn vị, general partners có thể bị yêu cầu dùng personal wealth chi trả theo luật và hợp đồng. Risk chịu trách nhiệm cho obligations của partner khác làm hình thức này khó scale.","trap":"A partner's loss can exceed the nominal invested amount."},{"heading":"Partnership agreement","body":"Partnership agreement xác định capital contributions, voting/control, distributions, management, partner entry/exit, transfer restrictions và sharing rules. Lợi nhuận không bắt buộc chia đều trừ khi thỏa thuận hoặc luật quy định.","trap":"Do not assume equal profit shares without agreement."},{"heading":"Pass-through partnership taxation","body":"Partnerships thường chuyển taxable income/loss đến individual partners, họ có nghĩa vụ thuế kể cả khi earnings retained trong partnership. Cách ghi nhận và deduct loss có thể bị giới hạn bởi local tax laws.","trap":"Retained partnership earnings may still create tax liabilities for partners."},{"heading":"Limited partnership architecture","body":"Limited partnership (LP) có ít nhất một general partner GP thường quản lý và chịu unlimited liability, còn limited partners đóng vốn với liability capped at investment. Chính GP nhận responsibility/risk cao hơn, LP thường là passive investors.","trap":"A limited partnership itself is not a partnership with zero general partners."},{"heading":"General partner in LP","body":"GP chịu management responsibility, legally exposed to partnership obligations theo mô hình tiêu chuẩn; partnership agreement có thể phân chia fee/profit cho GP lớn hơn do liability/control. Trong thực tế GP có thể là một corporation, giúp ultimate owners hưởng limited liability ở layer corporate.","trap":"Unlimited liability of corporate GP does not necessarily mean unlimited personal liability for its shareholders."},{"heading":"Limited partner in LP","body":"LP nhận economic return theo capital và partnership contract, thường không directly control day-to-day operations. LP mất tối đa số vốn góp theo mô hình giới hạn trách nhiệm; các ngoại lệ pháp lý phụ thuộc luật.","trap":"Limited partner generally does not run the partnership like a GP."},{"heading":"LP ownership transfer","body":"Partnership interests thường có restrictions về transfer và partner admission nên liquidity thấp hơn traded corporate shares. Agreement có thể phức tạp về waterfalls và rights; không mặc định units LP freely quoted on exchange.","trap":"Liquidity and legal liability are separate attributes."},{"heading":"LLP special form","body":"Limited liability partnership (LLP) có thể cho all partners liability protection without requiring a separate GP, đồng thời cho phép partners share management. Hình thức này phụ thuộc jurisdiction và nhiều nơi giới hạn professional-service firms.","trap":"LLP is not universal and is not identical to a conventional LP with one unlimited-liability GP."},{"heading":"Private limited company architecture","body":"Private limited companies có shareholder/member ownership, limited liability, shares và owner–manager separation through board. Chúng có separate legal identity trong khung conceptual corporate nhưng ownership transfer, investor numbers và tax treatment có thể bị giới hạn theo jurisdiction.","trap":"Private limited companies are not automatically listed on exchanges."},{"heading":"Public limited company architecture","body":"Public limited companies/corporations phát hành equity shares với limited liability và board management, thường có ít restriction trên number of shareholders/transferability. Chúng thích hợp raise large external capital, dù tốn governance/compliance và có thể có corporate-plus-dividend taxation.","trap":"Public limited legal form is not necessarily identical to being exchange-listed in every jurisdiction."},{"heading":"Limited liability company owners","body":"Trong limited companies, shareholder tài sản cá nhân thường được tách khỏi issuer debt obligations; investment can go to zero, nhưng không tự động trở thành guarantor của issuer debt. Personal guarantees và fraud cases có thể thay đổi kết quả.","trap":"Liability protection is conditional on not separately guaranteeing liabilities."},{"heading":"Owner-manager split across forms","body":"Sole proprietor tự quản lý; GP partners trực tiếp quản; LP có GP managerial authority, còn limited companies cho shareholders elect board appointing executives. Separation cho phép pooled capital from owners không cần trực tiếp quản lý.","trap":"Shareholders do not normally vote on daily purchase orders."},{"heading":"Capital access spectrum","body":"Sole owner thường limited personal capital, partnership bị giới hạn bởi partner pool và contractual risk; corporate shares/debt mở rộng access to diversified investors và capital markets. Đây là tendency, không phải guarantee mọi corporation sẽ raise funds cheaply.","trap":"Legal ability to issue shares does not imply a liquid market."},{"heading":"Transferability comparison","body":"Equity shares của public listed firms thường dễ transfer; private limited shares có restrictions, partnership interests có consent rules, sole proprietorship ownership thường transfer business as assets. Liquidity phụ thuộc market participation và contract.","trap":"Private and public are ownership/market access features, not different limited-liability guarantees."},{"heading":"Tax comparison by form","body":"Sole proprietorship và many partnerships là pass-through, còn conventional public corporation trả corporate income tax rồi shareholder có thể trả taxes on dividends. Một số private limited companies có pass-through treatment; không suy mọi loại private company bị double tax.","trap":"State tax differences as general tendencies, not universal laws."},{"heading":"Risk–reward allocation","body":"GP có greater downside risk due unlimited liability nên có thể đòi larger profit share/management fee; LP share upside theo contract nhưng thường ít control. Shareholder corporation nhận residual claim nhưng exposure limited to invested equity, không được guaranteed dividend.","trap":"Liability and cash-flow priority are different dimensions."},{"heading":"Corporate GP of limited partnership","body":"GP có thể là một corporation sở hữu partnership interest; GP entity vẫn legally chịu liability, nhưng shareholders của GP corporation thường chỉ mất giá trị equity. Layers giải thích tổ chức multi-entity complex mà không tự động xóa nợ partnership.","trap":"Analyze each legal layer, not just the top company name."},{"heading":"Fund legal form comparison","body":"Investment funds có thể được thiết kế dạng corporation (investors own fund shares, elect board) hoặc limited partnership (investors LPs và manager-controlled GP). Loại hình ảnh hưởng control, liquidity, tax và governance, không chỉ assets fund đang nắm.","trap":"An investment fund need not be organized only as a corporation."},{"heading":"Jurisdictional caveat","body":"Names LLC, GmbH, SARL, S-corporation, LLP hay C-corporation mang specific laws từng nước; CFAI dùng conceptual contrasts nên không nên suy quy định thuế/liability của một market áp dụng universally.","trap":"Business-form vocabulary is not a universal legal taxonomy."},{"heading":"Exam decision rule","body":"Xác định ownership count, entity/legal separation, unlimited/limited liability, who manages, tax pass-through/double, how ownership transferred và ability to issue listed shares; sau đó chọn form phù hợp hơn thay vì dựa trên một tên gọi.","trap":"Typical exam trap is mixing a limited partner with a general partner."}],"formulas":[{"name":"Forms comparison vector","expr":"Form = {legal identity, owner-manager relation, liability, financing, tax, transferability}","meaning":"Khung đánh giá đa chiều các loại hình kinh doanh.","conditions":"Qualitative checklist, not quantitative CFAI formula."},{"name":"Sole proprietor liability","expr":"Owner downside may exceed invested business equity","meaning":"Liabilities có thể đòi personal wealth nếu business insufficient.","conditions":"Depends on jurisdiction and debts."},{"name":"General partnership liability","expr":"General partners personally exposed to partnership debts","meaning":"GPs có thể chịu unlimited liability.","conditions":"Details depend on partnership law/agreements."},{"name":"Limited partnership GP/LP","expr":"GP: typically unlimited liability/management; LP: limited liability/passive capital","meaning":"Phân biệt các cấp partner.","conditions":"Limited partner rights may vary by agreement."},{"name":"LLP feature","expr":"LLP: no separate unlimited-liability GP required; partners generally limited liability","meaning":"LLP khác standard LP.","conditions":"Jurisdiction-dependent form."},{"name":"Corporate ownership ratio","expr":"Ownership % = shares held / shares outstanding × 100%","meaning":"Minh họa vốn chia thành cổ phần.","conditions":"Ordinary simple shares, multiple voting classes can differ."},{"name":"Shareholder maximum conventional loss","expr":"Loss_sh = invested amount (at most)","meaning":"Shareholder có thể mất hết đầu tư nhưng không automatically pay debts.","conditions":"Excludes specific guarantees/fraud and other legal exceptions."},{"name":"Partner taxable allocation","expr":"Partner taxable income = allocable pass-through business income (subject to local rules)","meaning":"Thuế có thể phát sinh dù cash distribution chưa có.","conditions":"Illustrative, not local tax law."},{"name":"Partnership allocated profit","expr":"Allocated partner profit = total distributable profit × agreed fraction","meaning":"Sharing theo hợp đồng không mặc định equal.","conditions":"Profit and tax allocation may differ."},{"name":"Equity investment risk","expr":"Shareholder cash-flow claim residual after contractual obligations","meaning":"Equity chịu loss first trong insolvency.","conditions":"Detailed debt-equity priority in subsequent module."},{"name":"Debt/equity financing range","expr":"External capital = new equity + borrowings (simplified)","meaning":"Khả năng huy động vốn corporates vượt một nhóm partner nhỏ.","conditions":"Accounting identity simplified; retained earnings also an internal source."},{"name":"Pass-through effective cash","expr":"Post-tax income = pretax income × (1−owner tax rate)","meaning":"Minh họa pass-through cho một mức personal income tax giả định.","conditions":"No other deductions, limited liability or rate caps considered."},{"name":"Corporate distributed cash","expr":"Net shareholder dividend = pretax income×(1−corporate tax rate)×payout ratio×(1−dividend tax rate)","meaning":"Mô hình tax hai cấp khi earnings phân phối.","conditions":"Only simplifying illustration for corporation and dividend taxes."},{"name":"Ownership share distribution","expr":"Shareholder profit claim = firm distributable profit × economic ownership share","meaning":"Tỷ lệ kinh tế có thể khác votes nếu dual-class shares.","conditions":"Charter overrides."},{"name":"LLP professional services","expr":"Professional partnership protection depends on local law","meaning":"Hạn chế generalizing legal treatment.","conditions":"Qualitative rather than formula."},{"name":"Financing growth constraint","expr":"Financing capacity depends on owner capital + market access + risk tolerance","meaning":"Khung so sánh doanh nghiệp và corporate access.","conditions":"Not a numerical CFAI identity."}],"examples":[{"question_en":"A small business has one owner, who runs operations and remains personally liable for all debts. Identify the form.","answer":"Sole proprietorship","steps_vi":["Một chủ vận hành và có unlimited personal liability là sole proprietor.","Không phải corporation vì corporation tách legal person và giới hạn liability cho shareholders."],"check":"Organizational classification."},{"question_en":"A business has three general partners who all manage operations. One partner cannot meet a debt obligation. Which risk matters?","answer":"The other general partners may face personal liability","steps_vi":["General partners thường chịu unlimited liability nên risk có thể kéo sang personal assets.","Partnership agreement/law xác định mechanics cụ thể; không nói investors có cổ phần public."],"check":"Partnership exposure."},{"question_en":"An LP has one GP and five LP investors. Who typically manages the partnership?","answer":"The general partner","steps_vi":["GP usually retains day-to-day management authority under LP structure.","LPs thường passive and limited liability; management rights follow agreement."],"check":"LP governance."},{"question_en":"An LP loses $3 million but a limited partner contributed $200,000. What is the conventional maximum loss of the LP?","answer":"$200,000","steps_vi":["Limited partner liability thông thường capped ở contributed capital.","Không tự động gán pro rata $3m debt lên personal assets of LP."],"check":"Absent guarantees and legal exceptions."},{"question_en":"Two business partners want both management participation and liability protection without an unlimited-liability GP. Which form may be suitable where permitted?","answer":"Limited liability partnership","steps_vi":["LLP thường cho limited-liability partners sharing management, không require traditional GP.","Phạm vi use của LLP phụ thuộc jurisdiction; một số nơi chỉ cho professional firms."],"check":"Conditional on local law."},{"question_en":"A partnership has pretax income $600,000, one partner is allocated 25%, and all profits are retained. Estimate the partner's taxable income under pass-through rules.","answer":"$150,000","steps_vi":["Pass-through allocation =600.000×25%=150.000 taxable income theo simplified model.","Giữ earnings lại không đồng nghĩa không có income tax obligation."],"check":"Hypothetical tax scenario."},{"question_en":"A sole proprietor earns $100,000 taxable business income and pays 30% personal tax. Find post-tax income under the simplified rule.","answer":"$70,000","steps_vi":["Income after personal tax=100.000×(1−0,30)=70.000.","Ví dụ không bao gồm other taxes hoặc tax brackets."],"check":"Simplified illustrative calculation."},{"question_en":"A company has 1 million ordinary shares, and an investor owns 40,000. What is the economic ownership percentage?","answer":"4%","steps_vi":["Shareholding ratio =40.000/1.000.000×100%=4%.","Voting rights có thể khác nếu multiple share classes."],"check":"Ordinary equal-share example."},{"question_en":"A limited company shareholder buys shares for $80,000 and the company later goes bankrupt. No personal guarantee exists. What is the standard maximum shareholder loss?","answer":"$80,000","steps_vi":["Limited liability nghĩa mất tối đa invested equity, không tự động gánh toàn bộ issuer debt.","Share value can go zero; personal assets generally protected."],"check":"No personal guarantee assumption."},{"question_en":"A sole proprietor invests $40,000, and the business has $100,000 unpaid debt with no assets. Does limited investment cap the owner's liability?","answer":"No: unlimited personal liability can exceed $40,000","steps_vi":["Sole ownership không có legal shield tương đương shareholder, nên debt claim có thể vượt invested capital.","Actual collectible amount depends on law and owner assets."],"check":"Unbounded liability principle."},{"question_en":"An investment fund is set up as an LP where clients contribute passive capital and a management company is GP. Identify investors' roles.","answer":"Limited partners","steps_vi":["Clients có LP rights/cash-flow interests, còn management company GP điều hành.","GP là entity corporation có thể shield shareholders dù entity GP legally liable."],"check":"Fund LP structure."},{"question_en":"A corporation has 2 million shares, and a founder holds 800,000. What is the founder's economic ownership percentage?","answer":"40%","steps_vi":["Founder ownership=800.000/2.000.000×100%=40%.","Không suy founder có 40% voting nếu dual-class voting rights."],"check":"Simple shares ratio."},{"question_en":"A public corporation earns $1,000 pretax, pays 20% corporate tax, distributes all post-tax profit, and shareholders pay 25% dividend tax. What is net cash to shareholders?","answer":"$600","steps_vi":["Phân loại hình thức doanh nghiệp và xác định quyền/nghĩa vụ của chủ sở hữu trước khi làm phép tính. Corporate net =1.000×0,80=800; after dividend tax=800×0,75=600.","Combined effective tax =40% here, not 45% (rates multiply)."],"check":"Simplified two-layer tax illustration."},{"question_en":"A partnership has four partners, with profit split 40%, 30%, 20%, 10%. On $200,000 profit, how much is allocated to the second partner?","answer":"$60,000","steps_vi":["Agreement allocates 30% to partner two nên 200.000×0,30=60.000.","Equal split 25% would be incorrect."],"check":"Agreement controls allocations."}],"questions":[{"stem_en":"A sole proprietorship is usually characterized by:","options":["Ownership by multiple publicly traded shareholders.","One owner with unlimited personal liability.","Mandatory board oversight and limited shareholder liability."],"correct":1,"why_vi":"Sole trader có một owner trực tiếp quản và personal liability thường unlimited.","trap_vi":"Do not confuse with a corporation."},{"stem_en":"Which organizational form generally has a separate legal identity from its shareholders?","options":["Corporation.","Sole proprietorship.","General partnership as modeled in the basic CFAI comparison."],"correct":0,"why_vi":"Corporation là legal person khác với shareholders theo khung kiến thức.","trap_vi":"Separate identity differs from mere contractual agreement."},{"stem_en":"In a standard limited partnership, which party generally assumes unlimited liability?","options":["Every limited partner.","A public shareholder.","At least one general partner."],"correct":2,"why_vi":"LP có GP management và unlimited liability, LP investors liability limited.","trap_vi":"Names LP and LLP differ."},{"stem_en":"A limited partner in a conventional limited partnership typically:","options":["Runs all daily operations with unlimited liability.","Has limited liability and a less active management role.","Must issue shares on a listed exchange."],"correct":1,"why_vi":"Limited partner góp vốn, ít quản trị và thường chỉ exposed contributed investment.","trap_vi":"GP remains a distinct role."},{"stem_en":"Compared with a traditional LP, a limited liability partnership generally:","options":["Requires one personally liable GP in every jurisdiction.","Eliminates the need for a separate unlimited-liability GP where the LLP structure is permitted.","Is necessarily a listed corporation."],"correct":1,"why_vi":"LLP có limited-liability partners và can share management, tùy jurisdiction.","trap_vi":"Do not assume all countries recognize identical LLPs."},{"stem_en":"Which business form is most often subject to pass-through taxation?","options":["A sole proprietorship.","A conventional publicly traded corporation with dividend taxation.","Every public company regardless of jurisdiction."],"correct":0,"why_vi":"Sole proprietor earnings thường taxed at owner level, không double-tax corporate+dividend.","trap_vi":"Pass-through income is still taxable."},{"stem_en":"A general partnership's partners typically:","options":["Have unlimited personal liability for partnership obligations.","Always receive identical shares of profit without agreements.","Hold only exchange-listed equity instruments."],"correct":0,"why_vi":"Đáp án được xác định theo legal liability và form của doanh nghiệp, rồi áp dụng thông tin tình huống. General partners personally liable; profit sharing theo agreement.","trap_vi":"Agreement does not automatically limit all liability."},{"stem_en":"The primary role of a partnership agreement is to:","options":["Guarantee liquidity of partnership interests on exchanges.","Define capital contributions, management and income-sharing rights.","Make all partners legal corporations."],"correct":1,"why_vi":"Agreement governs contributions, duties và profit/loss sharing.","trap_vi":"Partnership terms can vary greatly."},{"stem_en":"A shareholder of a standard limited company who has not given a personal guarantee can generally lose:","options":["The amount invested in shares.","The company's entire outstanding bank debt plus personal wealth.","An amount fixed at zero regardless of share price."],"correct":0,"why_vi":"Đáp án được xác định theo legal liability và form của doanh nghiệp, rồi áp dụng thông tin tình huống. Limited liability caps ordinary investor loss at equity invested.","trap_vi":"Shareholders can still lose all their investment."},{"stem_en":"Which characteristic best differentiates a corporation from a sole proprietorship?","options":["Restriction to only one employee.","Separate legal identity and transferability of shares.","A guarantee that it will make a profit."],"correct":1,"why_vi":"Corporation có entity separation và share structure facilitates owner transfer.","trap_vi":"Legal form does not guarantee earnings."},{"stem_en":"The managers of a traditional limited partnership are primarily the:","options":["Limited partners.","General partners.","Public preferred shareholders."],"correct":1,"why_vi":"GP typically điều hành partnership, LPs mainly financial capital.","trap_vi":"Distinguish management from investment."},{"stem_en":"Partnership profits retained for reinvestment under pass-through taxation are:","options":["Necessarily exempt from all taxes.","Potentially taxable to partners despite no cash distribution.","Always taxed twice on dividends."],"correct":1,"why_vi":"Pass-through taxable earnings allocate cho partners ngay cả khi cash không distributed.","trap_vi":"Tax treatment depends on jurisdiction."},{"stem_en":"Which organization typically has the greatest structural ability to raise large amounts of outside equity funding?","options":["Sole proprietor.","Small general partnership.","Public limited company/corporation."],"correct":2,"why_vi":"Corporation có share ownership transferable và external financing access lớn hơn.","trap_vi":"Not guaranteed that funding is inexpensive."},{"stem_en":"Under a conventional limited partnership, LP risk is generally:","options":["Unlimited even without guarantees.","Limited to invested capital under standard liability protections.","Exactly equal to the GP's personal asset exposure."],"correct":1,"why_vi":"Đáp án được xác định theo legal liability và form của doanh nghiệp, rồi áp dụng thông tin tình huống. LP liability capped, GP often bears unlimited personal/entity liability.","trap_vi":"Actual exceptions depend on law."},{"stem_en":"Why might a corporation have a better ability to scale than a sole proprietorship?","options":["Shareholders can finance the business without personally managing it.","The corporation cannot issue debt.","Its shares are never transferred."],"correct":0,"why_vi":"Đáp án được xác định theo legal liability và form của doanh nghiệp, rồi áp dụng thông tin tình huống. Separation management-ownership allows broader capital pool.","trap_vi":"Corporate capital access comes with legal/compliance costs."},{"stem_en":"Corporate shareholders' economic claims are generally:","options":["Residual claims after debt and other obligations.","Guaranteed fixed payments senior to lenders.","A promise that no equity losses will occur."],"correct":0,"why_vi":"Shareholder cash flows là residual, limited liability chỉ giảm personal loss cap.","trap_vi":"Liability and payout priority are different."},{"stem_en":"The conventional tax disadvantage of many public corporations is:","options":["Income is never taxed.","Corporate income may be taxed and subsequent dividends taxed at the shareholder level.","All profits must be distributed immediately."],"correct":1,"why_vi":"Double taxation là entity-level tax rồi shareholder dividend tax nếu distributed.","trap_vi":"Retained profits may avoid second layer until realization."},{"stem_en":"A company owned by ten shareholders with limited liability and a board but no exchange listing is most consistent with a:","options":["Sole trader.","Private limited company.","General partnership with unlimited partner liability."],"correct":1,"why_vi":"Private limited company có shares, limited liability, board và unlisted ownership.","trap_vi":"Listing status is separate from corporate legal form."},{"stem_en":"A pass-through partnership allocates 20% of $400,000 taxable profits to partner A, with profits retained. Under a simplified rule, partner A taxable allocation is:","options":["$80,000","$120,000","$60,000"],"correct":0,"why_vi":"Allocated taxable profit=400,000×0.20=$80,000; retained cash không làm taxable income bằng zero.","trap_vi":"Pass-through taxes may apply to retained earnings."},{"stem_en":"A pass-through partnership allocates 40% of $850,000 taxable profits to partner A, with profits retained. Under a simplified rule, partner A taxable allocation is:","options":["$425,000","$340,000","$297,500"],"correct":1,"why_vi":"Allocated taxable profit=850,000×0.40=$340,000; retained cash không làm taxable income bằng zero.","trap_vi":"Pass-through taxes may apply to retained earnings."},{"stem_en":"A pass-through partnership allocates 35% of $120,000 taxable profits to partner A, with profits retained. Under a simplified rule, partner A taxable allocation is:","options":["$36,000","$54,000","$42,000"],"correct":2,"why_vi":"Allocated taxable profit=120,000×0.35=$42,000; retained cash không làm taxable income bằng zero.","trap_vi":"Pass-through taxes may apply to retained earnings."},{"stem_en":"A pass-through partnership allocates 10% of $980,000 taxable profits to partner A, with profits retained. Under a simplified rule, partner A taxable allocation is:","options":["$98,000","$196,000","$49,000"],"correct":0,"why_vi":"Allocated taxable profit=980,000×0.10=$98,000; retained cash không làm taxable income bằng zero.","trap_vi":"Pass-through taxes may apply to retained earnings."},{"stem_en":"A pass-through partnership allocates 28% of $135,000 taxable profits to partner A, with profits retained. Under a simplified rule, partner A taxable allocation is:","options":["$51,300","$37,800","$31,050"],"correct":1,"why_vi":"Allocated taxable profit=135,000×0.28=$37,800; retained cash không làm taxable income bằng zero.","trap_vi":"Pass-through taxes may apply to retained earnings."}],"cards":[{"front_en":"1. Explain: Why organizational form matters","back_vi":"Hình thức tổ chức doanh nghiệp xác định quan hệ pháp lý của chủ sở hữu, ai quản lý, ai chịu trách nhiệm về nợ và phạm vi gọi vốn. CFA Level I yêu cầu so sánh theo tiêu chí, không chỉ nhớ tên tổ chức trong từng nước."},{"front_en":"2. Explain: Businesses versus governments and nonprofits","back_vi":"Market economies có business for-profit, government organizations và nonprofits. Learning Module này chủ yếu tập trung for-profit enterprises vì nhà phân tích tài chính đánh giá quyền và nghĩa vụ của nhà cung cấp vốn."},{"front_en":"3. Explain: Five comparison dimensions","back_vi":"So sánh bằng separate legal identity, owner–manager relationship, owner liability, access to financing và taxation; thêm transferability, continuity, growth potential để giải thích. Các chiều có thể khác nhau theo jurisdiction và loại agreement."},{"front_en":"4. Explain: Separate legal identity concept","back_vi":"Một corporation/limited company có legal personhood tách khỏi owners theo luật, có thể own assets, borrow, sue và be sued. Sole proprietorship và general partnership trong khung CFAI được trình bày không có legal separation tương tự."},{"front_en":"5. Explain: Sole proprietorship ownership","back_vi":"Sole proprietorship do một individual sở hữu, thường người này trực tiếp vận hành và quyết định operations. Chủ sở hữu giữ earnings sau thuế nhưng cũng tự gánh downside; legal entity thường là extension of owner."},{"front_en":"6. Explain: Sole proprietorship unlimited liability","back_vi":"Chủ sole proprietor có unlimited personal liability đối với obligations của business, có thể phải dùng personal assets để trả nợ nếu business assets thiếu. Khác với shareholder of a limited company có exposure chủ yếu ở equity investment."},{"front_en":"7. Explain: Sole proprietorship financing","back_vi":"Growth của sole trader bị hạn chế bởi savings, bank credit, collateral và individual risk capacity; không thể dễ dàng bán public equity shares như large corporation. Ưu điểm là đơn giản và linh hoạt, chi phí hình thành thấp."},{"front_en":"8. Explain: Sole proprietorship taxes","back_vi":"Earnings của sole proprietor thường pass through to owner for personal income taxation, không chịu corporate-level tax thêm rồi dividend-level tax giống conventional public corporation. Thuế cụ thể luôn phụ thuộc jurisdiction."},{"front_en":"9. Explain: General partnership owners","back_vi":"General partnership có nhiều partners cùng góp vốn, chia lợi nhuận, rủi ro và quyết định quản trị theo partnership agreement. Mọi partners thường có unlimited liability trong mô hình CFAI, kể cả khi một partner không điều hành từng ngày."},{"front_en":"10. Explain: General partnership liability sharing","back_vi":"Khi partnership liabilities vượt tài sản đơn vị, general partners có thể bị yêu cầu dùng personal wealth chi trả theo luật và hợp đồng. Risk chịu trách nhiệm cho obligations của partner khác làm hình thức này khó scale."},{"front_en":"11. Explain: Partnership agreement","back_vi":"Partnership agreement xác định capital contributions, voting/control, distributions, management, partner entry/exit, transfer restrictions và sharing rules. Lợi nhuận không bắt buộc chia đều trừ khi thỏa thuận hoặc luật quy định."},{"front_en":"12. Explain: Pass-through partnership taxation","back_vi":"Partnerships thường chuyển taxable income/loss đến individual partners, họ có nghĩa vụ thuế kể cả khi earnings retained trong partnership. Cách ghi nhận và deduct loss có thể bị giới hạn bởi local tax laws."},{"front_en":"13. Explain: Limited partnership architecture","back_vi":"Limited partnership (LP) có ít nhất một general partner GP thường quản lý và chịu unlimited liability, còn limited partners đóng vốn với liability capped at investment. Chính GP nhận responsibility/risk cao hơn, LP thường là passive investors."},{"front_en":"14. Explain: General partner in LP","back_vi":"GP chịu management responsibility, legally exposed to partnership obligations theo mô hình tiêu chuẩn; partnership agreement có thể phân chia fee/profit cho GP lớn hơn do liability/control. Trong thực tế GP có thể là một corporation, giúp ultimate owners hưởng limited liability ở layer corporate."},{"front_en":"15. Explain: Limited partner in LP","back_vi":"LP nhận economic return theo capital và partnership contract, thường không directly control day-to-day operations. LP mất tối đa số vốn góp theo mô hình giới hạn trách nhiệm; các ngoại lệ pháp lý phụ thuộc luật."},{"front_en":"16. Explain: LP ownership transfer","back_vi":"Partnership interests thường có restrictions về transfer và partner admission nên liquidity thấp hơn traded corporate shares. Agreement có thể phức tạp về waterfalls và rights; không mặc định units LP freely quoted on exchange."},{"front_en":"17. Explain: LLP special form","back_vi":"Limited liability partnership (LLP) có thể cho all partners liability protection without requiring a separate GP, đồng thời cho phép partners share management. Hình thức này phụ thuộc jurisdiction và nhiều nơi giới hạn professional-service firms."},{"front_en":"18. Explain: Private limited company architecture","back_vi":"Private limited companies có shareholder/member ownership, limited liability, shares và owner–manager separation through board. Chúng có separate legal identity trong khung conceptual corporate nhưng ownership transfer, investor numbers và tax treatment có thể bị giới hạn theo jurisdiction."},{"front_en":"19. Explain: Public limited company architecture","back_vi":"Public limited companies/corporations phát hành equity shares với limited liability và board management, thường có ít restriction trên number of shareholders/transferability. Chúng thích hợp raise large external capital, dù tốn governance/compliance và có thể có corporate-plus-dividend taxation."},{"front_en":"20. Explain: Limited liability company owners","back_vi":"Trong limited companies, shareholder tài sản cá nhân thường được tách khỏi issuer debt obligations; investment can go to zero, nhưng không tự động trở thành guarantor của issuer debt. Personal guarantees và fraud cases có thể thay đổi kết quả."},{"front_en":"21. Explain: Owner-manager split across forms","back_vi":"Sole proprietor tự quản lý; GP partners trực tiếp quản; LP có GP managerial authority, còn limited companies cho shareholders elect board appointing executives. Separation cho phép pooled capital from owners không cần trực tiếp quản lý."},{"front_en":"22. Explain: Capital access spectrum","back_vi":"Sole owner thường limited personal capital, partnership bị giới hạn bởi partner pool và contractual risk; corporate shares/debt mở rộng access to diversified investors và capital markets. Đây là tendency, không phải guarantee mọi corporation sẽ raise funds cheaply."},{"front_en":"23. Explain: Transferability comparison","back_vi":"Equity shares của public listed firms thường dễ transfer; private limited shares có restrictions, partnership interests có consent rules, sole proprietorship ownership thường transfer business as assets. Liquidity phụ thuộc market participation và contract."},{"front_en":"24. Explain: Tax comparison by form","back_vi":"Sole proprietorship và many partnerships là pass-through, còn conventional public corporation trả corporate income tax rồi shareholder có thể trả taxes on dividends. Một số private limited companies có pass-through treatment; không suy mọi loại private company bị double tax."},{"front_en":"25. Explain: Risk–reward allocation","back_vi":"GP có greater downside risk due unlimited liability nên có thể đòi larger profit share/management fee; LP share upside theo contract nhưng thường ít control. Shareholder corporation nhận residual claim nhưng exposure limited to invested equity, không được guaranteed dividend."},{"front_en":"26. Explain: Corporate GP of limited partnership","back_vi":"GP có thể là một corporation sở hữu partnership interest; GP entity vẫn legally chịu liability, nhưng shareholders của GP corporation thường chỉ mất giá trị equity. Layers giải thích tổ chức multi-entity complex mà không tự động xóa nợ partnership."},{"front_en":"27. Explain: Fund legal form comparison","back_vi":"Investment funds có thể được thiết kế dạng corporation (investors own fund shares, elect board) hoặc limited partnership (investors LPs và manager-controlled GP). Loại hình ảnh hưởng control, liquidity, tax và governance, không chỉ assets fund đang nắm."},{"front_en":"28. Explain: Jurisdictional caveat","back_vi":"Names LLC, GmbH, SARL, S-corporation, LLP hay C-corporation mang specific laws từng nước; CFAI dùng conceptual contrasts nên không nên suy quy định thuế/liability của một market áp dụng universally."},{"front_en":"29. Explain: Exam decision rule","back_vi":"Xác định ownership count, entity/legal separation, unlimited/limited liability, who manages, tax pass-through/double, how ownership transferred và ability to issue listed shares; sau đó chọn form phù hợp hơn thay vì dựa trên một tên gọi."}]},{"id":"CFA26-03-01-LOS02","letter":"1.b","title_en":"Corporate Issuer Characteristics and Financing","outcome_en":"describe key features of corporate issuers","overview_vi":"Legal personhood, corporate charter/regulation, owner–manager separation, shareholders/board/executive hierarchy, limited liability, ownership units, debt/equity finance, financial vs economic balance sheets, profit vs economic profit, taxes and agency risk.","source":[{"id":"CFA Institute Curriculum 2026 — Corporate Issuers LM1","pages":"23–28 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading20","pages":"225–227, 228 (physical PDF)"},{"id":"SAPP Corporate Issuers 2026 — Module1","pages":"20–25 (physical PDF)"}],"sections":[{"heading":"Corporate issuer legal personhood","body":"Corporate issuer có separate legal identity: assets và obligations thuộc corporate entity, không mặc nhiên thuộc cá nhân shareholders. Corporation thường được thành lập qua registration/charter theo luật applicable và chịu các reporting/disclosure/capital market rules tùy jurisdiction.","trap":"Separate legal personhood and limited owner liability should be distinguished."},{"heading":"Corporate registration and charter","body":"Incorporation yêu cầu registration với competent authority và corporate charter/articles xác định hoạt động, share rights và governing bodies. Corporate identity giúp company giao kết contracts, own property, borrow và tồn tại dù shareholder thay đổi.","trap":"Registration is not the same as exchange listing."},{"heading":"Continuity of corporate existence","body":"Corporation thường có continuity beyond founders và không kết thúc chỉ vì individual shareholder bán shares hoặc qua đời. Điều này hỗ trợ huy động long-term capital và planning, nhưng insolvency hoặc voluntary liquidation vẫn có thể chấm dứt entity.","trap":"Perpetual life does not guarantee solvency."},{"heading":"Separation of owners and managers","body":"Shareholders cung cấp equity ownership nhưng thường không quản lý daily operations; board được bầu để oversee/hire executives, còn CEO/CFO vận hành company. Phân biệt quyền sở hữu, board governance và managerial control.","trap":"Shareholder voting rights do not mean daily control."},{"heading":"Shareholders elect board","body":"Shareholders thường dùng voting rights để elect hoặc remove directors; board làm nhiệm vụ strategic oversight, lựa chọn executives và phê duyệt policies lớn. Corporate governance rules chịu constraints khác nhau theo law, share classes, ownership concentration.","trap":"Direct election of every executive by all shareholders is not the standard structure."},{"heading":"Board appoints executives","body":"Board thường appoint CEO, CFO và các senior managers. Executives chịu trách nhiệm investing, financing, operating decisions, còn board monitor management và protect owners/stakeholders under governing duties.","trap":"CEO is not simply synonymous with board of directors."},{"heading":"Agency conflicts in owner–manager separation","body":"Managers có incentives như empire building, perquisite consumption hoặc short-term bonuses lệch shareholders' long-term value; monitoring, compensation alignment và voting có thể giảm nhưng không xóa agency costs. Đây là governance implication, không phải guarantee of perfect alignment.","trap":"Separation benefits financing but creates monitoring needs."},{"heading":"Shareholder voting as recourse","body":"Nếu directors không hoạt động trong best interests, owners có thể bầu lại board hoặc engage/activate governance rights; quyền ảnh hưởng phụ thuộc share class, voting structure và legal framework. Minority shareholder không có complete control đối với decisions.","trap":"Liquid shares are not the same as strong voting rights."},{"heading":"Shareholder limited liability","body":"Conventional shareholder downside limited to money invested in shares, không bắt buộc personally repay corporate debt. Investor có thể mất full equity value; personal guarantees hoặc misconduct có thể tạo legal exceptions.","trap":"Limited liability does not mean zero investment risk."},{"heading":"Separate entity balance sheet","body":"Corporation owns cash, operating assets, securities và obligations; claims of banks/bondholders khác residual equity of owners. Financial balance sheet assets được tài trợ bởi liabilities và shareholders' equity trong accounting identity.","trap":"Corporate assets are not personally owned by shareholders."},{"heading":"Equity ownership units","body":"Shares chia ownership thành nhỏ units, giúp nhiều investors participate. Economic rights và votes có thể khác nếu firm issues multiple classes; không mặc nhiên one share one vote ở mọi company.","trap":"Percentage shares does not always equal percentage voting power."},{"heading":"Dividends are discretionary residual distributions","body":"Shareholders có quyền hưởng distributions of profit khi declared theo governance and legal requirements; không có nghĩa mọi accounting profit đều tự động trả dividends. Reinvested earnings có thể tăng capital base và future earnings capacity.","trap":"Dividends are not contractual coupon payments."},{"heading":"External equity issuance","body":"Corporate raises equity bằng issuing new shares đến investors hoặc reinvesting earnings as internal equity financing; investors nhận residual claim và risk. Primary issuance khác secondary trading giữa shareholders; giao dịch secondary không tự tạo new cash cho issuer.","trap":"Secondary-market share purchases usually do not directly raise issuer capital."},{"heading":"Debt as external financing","body":"Debt finance gồm bank loans, bonds và leases theo contractual repayment/interest terms; lender claim thường senior to equity, company phải trả obligations trước khi equity distributions. Debt có fixed commitments ảnh hưởng financial risk/solvency.","trap":"Debt repayment is contractual, unlike equity dividends."},{"heading":"Debt and equity differences","body":"Lender expects principal/interest; shareholder gains from dividends/capital appreciation after liabilities. Issuer có thể hưởng leverage upside nhưng gia tăng fixed obligations làm insolvency risk cao hơn; investors thấy equity riskier than secured debt broadly.","trap":"Risk to issuer differs from risk to security holder."},{"heading":"Capital providers and financing access","body":"Shareholders, individuals, mutual/pension funds, banks, other companies và governments có thể finance corporation. Issuance of marketable securities mở financing universe rộng hơn partnership privately pooled capital.","trap":"Large investor base does not mean unlimited cheap capital."},{"heading":"Financial balance sheet","body":"Financial statement convention Assets=Liabilities+Equity, nơi assets gồm operating cash, PP&E, inventory, investments; liabilities gồm suppliers, lenders và other contractual obligations. Shareholders' equity là residual accounting funding.","trap":"Book value of equity is not necessarily market capitalization."},{"heading":"Economic balance sheet concept","body":"Broader economic balance sheet includes hard-to-measure values như workforce skills, brand, supplier/customer relations, reputation, sustainability obligations. Một asset intangible economically valuable có thể không xuất hiện với fair value trên financial balance sheet.","trap":"Financial reports do not capture every stakeholder asset or obligation."},{"heading":"Revenue to net income waterfall","body":"Financial income statement bắt đầu revenue/sales, trừ supplier costs, labor/operating costs, interest, taxes để có net income. Net income là accounting result, chưa đảm bảo return surpasses owners' required opportunity cost.","trap":"Positive net income does not establish positive economic profit."},{"heading":"Economic profit versus accounting net income","body":"Economic profit sau khi trừ shareholders' opportunity cost of capital; một corporate có net income dương nhưng tạo return <required return thì economic profit âm. Đây là đánh giá value creation beyond accounting expenses.","trap":"Positive accounting earnings can destroy economic value."},{"heading":"Required rate of return on equity","body":"Shareholders đòi return vì opportunity cost, risk và alternative investments; cost of equity không phải explicit expense line trên traditional income statement. Deducting implicit required return converts financial profit toward economic profit.","trap":"Required equity return is not the same as loan coupon."},{"heading":"Economic profit hypothetical measure","body":"Cho invested equity E, required equity return k và income NI (simplified), economic profit≈NI−kE. Nếu NI chỉ $80 nhưng E=$1.000 và k=10%, shortfall economic profit=$−20 dù accounting earnings positive.","trap":"This teaching approximation assumes NI and invested equity are aligned."},{"heading":"Corporate income tax","body":"Corporation có thể chịu corporate-level income taxation; tax law varies, some jurisdictions lower corporate rates or special exemptions. Không nên đồng nhất pretax income, accounting tax expense và cash taxes without further detail.","trap":"Taxable income is not always identical to financial-reporting pretax income."},{"heading":"Double taxation of distributed profits","body":"Trong conventional public corporation, profits bị taxed at corporate level, rồi after-tax distributed dividends có thể bị taxed again in shareholders' hands. Combined rate = 1−(1−t_c)(1−t_d) nếu distribute toàn bộ, không đơn giản cộng rates.","trap":"Combined corporate-plus-dividend tax is multiplicative."},{"heading":"Retention versus distribution tax effect","body":"Nếu after-tax profits giữ lại/reinvest, dividend shareholder tax chưa phát sinh at that point; capital gains taxation có thể xuất hiện sau khi shares sold hoặc trong hệ thống khác. Việc retention có lợi thuế hay không phụ thuộc local laws, capital opportunities và investors.","trap":"Retaining earnings does not mean all shareholder taxes disappear forever."},{"heading":"Financial/economic profitability distinction","body":"Một firm có revenue tăng nhưng lợi ích owners không tăng nếu return on incremental capital thấp hơn required rate. Phải phân tích investment productivity và stakeholder relationships, không chỉ nhìn reported net income.","trap":"Growth is not automatically value creation."},{"heading":"Management decision categories","body":"Executives phải quyết định operating: produce/sell; investing: acquire/divest assets; financing: how much debt/equity. Các quyết định liên kết cash flow, solvency và business growth.","trap":"Investment decisions and financing decisions are not identical."},{"heading":"Corporate financing and shareholder dilution","body":"New equity issuance increases shares outstanding, làm ownership percentage of existing holders giảm nếu họ không tham gia issuance. Tuy nhiên new funds có thể tạo value, nên dilution in percentage không tự động có nghĩa loss of economic value per old share.","trap":"Share dilution and value destruction are different things."},{"heading":"Corporate stakeholder relationships","body":"Employees, suppliers, customers, communities và government tạo/nhận economic value beyond shareholder contractual cash flows. Mối quan hệ có thể là economic asset/risk dù không có simple accounting measure tương ứng. Detailed governance ESG module sau sẽ đi sâu.","trap":"Economic balance sheet is broader than reported liabilities."},{"heading":"Corporate form trade-offs","body":"Corporation có limited liability, transferable ownership và wider capital access nhưng yêu cầu registration, reporting, board governance và potentially double taxes. So sánh cấu trúc là trade-off; không có one-size-fits-all business form.","trap":"Benefits are accompanied by compliance and agency costs."},{"heading":"Exam classification procedure","body":"Khi đề nói owners elect directors, managers run operations, separate legal person, shares và limited owners liability => corporate form. Khi hỏi economic profit, trừ equity opportunity cost from accounting earnings; khi hỏi taxable dividend, áp tax sequentially.","trap":"Distinguish owner liability, cash-flow seniority and tax layers."}],"formulas":[{"name":"Accounting balance sheet","expr":"Assets = Liabilities + Shareholders' Equity","meaning":"Tài sản của corporate được tài trợ bằng debt/other liabilities và equity.","conditions":"Book accounting identity; not market value valuation."},{"name":"Share ownership percent","expr":"Economic ownership % = shares held / total economic shares ×100%","meaning":"Tính share ownership proportion.","conditions":"Multiple-class dividend/voting rights require more detailed treatment."},{"name":"Limited liability standard","expr":"Maximum ordinary equity investor loss = price paid for shares (if no personal guarantee)","meaning":"Giới hạn downside của shareholder.","conditions":"Jurisdiction and separate obligations matter."},{"name":"Corporate pretax to net income","expr":"NI = pretax income − corporate tax expense (simplified)","meaning":"Chênh lệch thuế corporate tính sau earnings before tax.","conditions":"Not full financial statement with deferred taxes."},{"name":"Corporate tax cash example","expr":"After-corporate-tax profit = pretax profit×(1−t_c)","meaning":"Mô hình thuế đơn giản.","conditions":"Assume earnings equals taxable base."},{"name":"Dividend distribution example","expr":"Gross dividends to shareholders = after-tax profit×payout ratio","meaning":"Tiền available for dividend distribution theo payout policy.","conditions":"Board declaration and legal distributions required."},{"name":"Net dividends after personal tax","expr":"Net cash dividends = pretax earnings×(1−t_c)×payout×(1−t_d)","meaning":"Thuế corporate rồi thuế dividend sequentially.","conditions":"Simplified full distribution in one period."},{"name":"Combined tax at full distribution","expr":"t_combined=1−(1−t_c)(1−t_d)","meaning":"Không cộng trực tiếp t_c+t_d.","conditions":"Applies when all earnings distributed as taxed dividends."},{"name":"Retained earnings allocation","expr":"Retained current profit≈after-tax net income×(1−payout ratio)","meaning":"Internal equity capital accumulation.","conditions":"Simplified cash income, no other adjustments."},{"name":"Expected issuer funding","expr":"New investment funding≈new equity + borrowed funds + internally retained cash","meaning":"Khung financing sources.","conditions":"Simplified conceptual sum, not a cash-flow equality in all statements."},{"name":"New share dilution","expr":"Post-issue ownership=shares holder owns/(old shares+new shares)","meaning":"Tỷ lệ ownership giảm nếu không subscribe thêm.","conditions":"Multiple share classes can change voting details."},{"name":"Debt interest obligation","expr":"Contractual interest ≈ principal×coupon rate×time fraction","meaning":"Payment to lenders, independent of dividend declarations.","conditions":"Simple interest teaching illustration, actual bonds may differ."},{"name":"Financial profit","expr":"Financial/accounting profit = revenues − recognized expenses − taxes","meaning":"Profit theo income statement convention.","conditions":"Noncash and accrual items apply."},{"name":"Required equity profit","expr":"Equity opportunity cost=k_e×E","meaning":"Số lợi nhuận owners cần theo required return.","conditions":"E aligned to model (invested capital or equity base)."},{"name":"Economic profit approximation","expr":"Economic profit≈NI−k_e×E","meaning":"Lợi nhuận vượt required equity return.","conditions":"Teaching simplification not an audited economic value-added equation."},{"name":"Residual equity claim","expr":"Residual resources for equity = asset realization proceeds − senior contractual claims (subject to priority)","meaning":"Liquidation hierarchy: debt obligations ahead of residual equity.","conditions":"Actual priority includes taxes, secured claims, other liabilities."},{"name":"Issuer capital structure","expr":"Total financial capital ≈ debt + shareholder equity","meaning":"Nợ và equity là nguồn tài trợ cơ bản.","conditions":"Different from full assets accounting with other obligations."},{"name":"Net value created if NI below hurdle","expr":"NI<kE ⇒ economic profit<0","meaning":"Positive NI need not exceed cost of equity.","conditions":"Simplified return model."},{"name":"Board governance chain","expr":"Shareholders elect board → board appoints/oversees managers → managers operate","meaning":"Phân công quyền sở hữu và điều hành.","conditions":"Actual board systems vary by jurisdiction."},{"name":"Economic balance sheet","expr":"Economic obligations/assets may extend beyond recognized financial statements","meaning":"Các stakeholder relationships và reputation có economic implications.","conditions":"Qualitative framework, not a GAAP calculation."}],"examples":[{"question_en":"A corporation has $1,000,000 in assets and $650,000 in total liabilities. What is book equity?","answer":"$350,000","steps_vi":["Dựa trên financial balance sheet: equity=assets−liabilities.","1.000.000−650.000=350.000 USD book equity, không phải share market capitalization."],"check":"Accounting book identity."},{"question_en":"A firm earns $500,000 before corporate tax; tax rate is 25%. Find simplified net income.","answer":"$375,000","steps_vi":["Áp dụng trình tự tính thu nhập, thuế hoặc mức vốn phù hợp với corporate issuer. Corporate-level tax=500.000×25%=125.000.","Net income simplified=500.000−125.000=375.000 USD."],"check":"Assumes pretax equals taxable earnings."},{"question_en":"Corporation earnings before tax are $1 million, corporate tax 30%, dividend payout 100%, dividend tax 20%. Compute net dividends to owners.","answer":"$560,000","steps_vi":["Áp dụng trình tự tính thu nhập, thuế hoặc mức vốn phù hợp với corporate issuer. After corporate tax 1.000.000×70%=700.000.","After dividend tax 700.000×80%=560.000, effective combined tax 44%."],"check":"Do not add 30% and 20%=50%."},{"question_en":"Same corporation pays no dividends and retains all after-tax earnings. How much is retained before any later shareholder taxes?","answer":"$700,000","steps_vi":["Corporate net income vẫn bằng 1.000.000×(1−30%)=700.000.","Dividend tax chưa phát sinh trong mô hình ngay khi retention; future CG taxes depend on investor/jurisdiction."],"check":"Retained earnings not automatically tax-free forever."},{"question_en":"An investor has $100,000 of ordinary shares; the company fails. With no personal guarantee, what is the typical maximum equity loss?","answer":"$100,000","steps_vi":["Limited liability chặn việc creditor tự đòi thêm personal assets.","Shares có thể giảm về zero nên investor mất 100.000, but not corporate debt beyond invested amount."],"check":"No separate owner guarantee."},{"question_en":"A corporation has 4 million shares outstanding and an investor holds 80,000. What is the ownership percentage?","answer":"2%","steps_vi":["Áp dụng trình tự tính thu nhập, thuế hoặc mức vốn phù hợp với corporate issuer. 80.000/4.000.000×100=2%.","Voting share can be different if multiple-class stock, but ownership ratio here assumes ordinary equal shares."],"check":"Equal economic shares."},{"question_en":"A founder owns 40% of 1 million shares. The firm issues 250,000 new equal shares; founder buys none. What is the founder's new percentage?","answer":"32%","steps_vi":["Áp dụng trình tự tính thu nhập, thuế hoặc mức vốn phù hợp với corporate issuer. Founder initially has 400.000 shares unchanged.","New total 1.250.000 shares; 400.000/1.250.000=32%."],"check":"Ownership dilution not necessarily value destruction."},{"question_en":"A firm reports $80,000 net income, equity capital $1,000,000, required return 10%. Compute simplified economic profit.","answer":"−$20,000","steps_vi":["Equity opportunity cost =1.000.000×0,10=100.000.","Economic profit=80.000−100.000=−20.000 dù NI dương."],"check":"Positive NI is not always value creation."},{"question_en":"A company earns $160,000 net income, equity capital $1,000,000, required return 12%. Compute economic profit.","answer":"$40,000","steps_vi":["Required equity profit=120.000.","Economic profit=160.000−120.000=40.000 >0 nên vượt opportunity cost."],"check":"Model is illustrative."},{"question_en":"A corporation has $200,000 in net income and pays out 40% as dividends. Find retained earnings for this year in simplified model.","answer":"$120,000","steps_vi":["Áp dụng trình tự tính thu nhập, thuế hoặc mức vốn phù hợp với corporate issuer. Retention ratio=1−40%=60%.","Retained earnings=200.000×0,60=120.000 USD, before other changes."],"check":"Dividend policy affects amount."},{"question_en":"A corporation borrows $500,000 at a 6% annual simple interest rate. What is one year's contractual interest?","answer":"$30,000","steps_vi":["Áp dụng trình tự tính thu nhập, thuế hoặc mức vốn phù hợp với corporate issuer. Loan interest=principal×rate×time.","500.000×0,06×1=30.000 USD; unlike dividends this is contractual."],"check":"Simplified fixed loan."},{"question_en":"A corporation distributes after-tax earnings of $900,000 with a 60% payout ratio. What gross dividends are paid?","answer":"$540,000","steps_vi":["Áp dụng trình tự tính thu nhập, thuế hoặc mức vốn phù hợp với corporate issuer. Payout amount = net profit×60%.","900.000×0,60=540.000 USD, subject to lawful declaration."],"check":"Corporate tax already deducted."},{"question_en":"A corporation has pretax income $250,000 and corporation tax 20%. It distributes half of after-tax profit. Find cash dividends before personal tax.","answer":"$100,000","steps_vi":["Áp dụng trình tự tính thu nhập, thuế hoặc mức vốn phù hợp với corporate issuer. Profit after corporate tax=250.000×0,8=200.000.","Dividend payout half gives 100.000 USD before shareholder tax."],"check":"Two-stage financial flow."},{"question_en":"An issuer has 100 million shares and each trades at $12. What is equity market capitalization?","answer":"$1.2 billion","steps_vi":["Equity market value=shares outstanding×market price/share.","100 triệu×12 USD=1,2 tỷ USD; not book equity."],"check":"Conceptually relevant but not primary LOS formula."},{"question_en":"A business pays $20,000 interest on bonds and declares zero dividends. What type of capital provider has a contractual income claim?","answer":"Bondholders","steps_vi":["Áp dụng trình tự tính thu nhập, thuế hoặc mức vốn phù hợp với corporate issuer. Interest is contractual obligation of issuer; dividend is discretionary and residual.","Managers/board may retain profit instead of dividend distribution; issuer remains liable for debt obligations."],"check":"Security cash-flow distinction."}],"questions":[{"stem_en":"The separation of ownership and management in a corporation most directly allows:","options":["Owners to provide capital without managing daily operations.","All shareholders to manage procurement personally.","Corporate debt to disappear."],"correct":0,"why_vi":"Shareholders elect board và appointed executives operate, tạo ability to pool outside capital.","trap_vi":"Owner involvement not required daily."},{"stem_en":"A board of directors is typically elected by:","options":["The company's creditors solely.","Shareholders exercising voting rights.","Every supplier by default."],"correct":1,"why_vi":"Hãy phân biệt quyền lợi của shareholders, quản trị của board và nguồn vốn nợ/vốn chủ trước khi chọn. Shareholders vote to elect directors, board appoints/oversees management.","trap_vi":"Do not skip the board intermediary."},{"stem_en":"Which group usually appoints the chief executive officer of a corporation?","options":["The board of directors.","Every customer.","Shareholders via daily purchase orders."],"correct":0,"why_vi":"Board thường có authority appoint executives; CEO runs company.","trap_vi":"Governance hierarchy matters."},{"stem_en":"Limited liability for a corporation's shareholders means:","options":["Their shares can never lose value.","They usually are not personally responsible for corporate debts beyond their investment.","Their dividends must be paid annually."],"correct":1,"why_vi":"Limited liability hạn chế creditor claim lên personal owner assets absent guarantees.","trap_vi":"Equity can go to zero."},{"stem_en":"Compared with corporate debt, ordinary corporate equity is typically:","options":["A residual claim.","A contract with guaranteed interest payments.","Senior to secured bank claims in liquidation."],"correct":0,"why_vi":"Hãy phân biệt quyền lợi của shareholders, quản trị của board và nguồn vốn nợ/vốn chủ trước khi chọn. Shareholder cash flows sau debt/other obligations, debt has fixed contractual terms.","trap_vi":"Equity dividends are discretionary."},{"stem_en":"Which of the following is usually a contractual claim of a corporation's lender?","options":["Unlimited price appreciation only.","Interest and principal payments under the loan terms.","A right to elect the CEO daily."],"correct":1,"why_vi":"Hãy phân biệt quyền lợi của shareholders, quản trị của board và nguồn vốn nợ/vốn chủ trước khi chọn. Lender expects interest/principal contractual repayment, unlike shareholder residual.","trap_vi":"Bonds and shares have different claims."},{"stem_en":"A corporate board's principal role is most accurately:","options":["Day-to-day execution of every invoice payment.","Oversight of executives and key policies on behalf of owners.","Trading competitors' shares for clients as a mandatory duty."],"correct":1,"why_vi":"Hãy phân biệt quyền lợi của shareholders, quản trị của board và nguồn vốn nợ/vốn chủ trước khi chọn. Board oversight protects shareholders; executives execute operating tasks.","trap_vi":"Distinguish governance from operations."},{"stem_en":"A corporation's shares are valuable to investors partly because:","options":["They make the investor personally liable for all corporate debt.","They can represent divisible, potentially transferable ownership interests.","They eliminate all agency conflicts."],"correct":1,"why_vi":"Hãy phân biệt quyền lợi của shareholders, quản trị của board và nguồn vốn nợ/vốn chủ trước khi chọn. Shares chia owners units; public listing can improve liquidity, depending on market.","trap_vi":"Shareholders remain exposed to investment loss."},{"stem_en":"Which statement about a corporation's legal identity is most accurate?","options":["Its assets are automatically the personal assets of each shareholder.","It is a separate legal entity able to enter contracts and own assets.","It ceases to exist whenever one shareholder sells a share."],"correct":1,"why_vi":"Corporation separate legal person có thể own assets, borrow and continue beyond holder change.","trap_vi":"Entity continuity distinct from shareholder turnover."},{"stem_en":"What is a primary benefit of outside equity financing to a corporate issuer?","options":["It avoids any need for external investors.","It enables capital raising from many investors without promised fixed debt repayment.","It guarantees higher returns on invested capital."],"correct":1,"why_vi":"New shareholders fund company và chịu residual risk; no fixed bond coupon.","trap_vi":"New ownership may dilute percentages."},{"stem_en":"Which transaction typically generates new equity financing cash directly for the issuer?","options":["An existing shareholder sells shares on the exchange.","The company issues new shares for cash.","Two investors trade a secondary-market block of existing shares."],"correct":1,"why_vi":"Primary issue đưa new funds vào issuer; secondary trade changes owner only.","trap_vi":"Secondary liquidity still helps issuer indirectly."},{"stem_en":"For a corporation, the basic financial balance-sheet identity is:","options":["Assets = Liabilities + Equity.","Equity = Assets + Liabilities.","Assets = Revenue + Expenses."],"correct":0,"why_vi":"Hãy phân biệt quyền lợi của shareholders, quản trị của board và nguồn vốn nợ/vốn chủ trước khi chọn. Assets financed by liabilities and equity; book equity residual after recorded liabilities.","trap_vi":"Market equity may differ from book."},{"stem_en":"A company reports positive accounting net income but a negative economic profit. This is most consistent with:","options":["Return to equity not covering owners' required opportunity return.","The company necessarily having negative sales.","A legal requirement to pay dividends."],"correct":0,"why_vi":"Economic profit trừ implicit cost of equity; NI dương chưa đủ exceed required return.","trap_vi":"Cost of equity is not a traditional income statement expense."},{"stem_en":"If a company's reported net income is $80 and investors require $100 return on capital, economic profit is closest to:","options":["$180.","$20.","−$20."],"correct":2,"why_vi":"Hãy phân biệt quyền lợi của shareholders, quản trị của board và nguồn vốn nợ/vốn chủ trước khi chọn. Economic profit≈NI−required return=80−100=−20.","trap_vi":"Economic profit not equal financial NI."},{"stem_en":"Which tax treatment best describes the traditional double-taxation issue for public corporations?","options":["Profits may be taxed at corporate level and dividends taxed to shareholders.","Profits taxed only to suppliers.","Dividends are never taxable in any jurisdiction."],"correct":0,"why_vi":"Thuế doanh nghiệp rồi dividends investor-level có thể khiến cùng earnings chịu two layers.","trap_vi":"Tax rules vary by jurisdiction."},{"stem_en":"A corporation earns $100 pretax, pays 20% corporate income tax, then pays all remaining cash as dividends taxed at 25%. Shareholders receive:","options":["$80.","$60.","$55."],"correct":1,"why_vi":"Hãy phân biệt quyền lợi của shareholders, quản trị của board và nguồn vốn nợ/vốn chủ trước khi chọn. 100×0,8×0,75=60 after both tax layers.","trap_vi":"Do not simply add 20% +25%."},{"stem_en":"A corporation earns $1 million, pays 30% corporate tax, and retains all after-tax earnings. Immediate dividend-tax liability on retained funds is:","options":["Corporate taxes automatically double immediately.","Zero in a simplified no-distribution model.","A guaranteed 30% of total assets."],"correct":1,"why_vi":"Không dividend distribution nghĩa chưa phát sinh dividend tax trong mô hình, nhưng future taxes và other laws khác vẫn possible.","trap_vi":"Do not confuse deferral with permanent exemption."},{"stem_en":"Which organizational trait most naturally supports access to financing from passive investors?","options":["Separation of ownership and professional management.","Mandatory unlimited liability of all shareholders.","Prohibition of equity issuance."],"correct":0,"why_vi":"Hãy phân biệt quyền lợi của shareholders, quản trị của board và nguồn vốn nợ/vốn chủ trước khi chọn. Passive shareholders fund corporate while board/executives manage.","trap_vi":"Institutional financing benefits separation."},{"stem_en":"From an economic-balance-sheet perspective, which could have value despite not appearing at market value in financial assets?","options":["Relationships with employees and customers.","Only cash on hand.","Only a company's public share price."],"correct":0,"why_vi":"Economic balance sheet rộng hơn financial balance sheet, includes human capital and relationships.","trap_vi":"Not every intangible is measured on accounting sheet."},{"stem_en":"Which activity is a financing decision rather than an operating decision?","options":["Choosing the coupon and amount of a bond issue.","Pricing a customer sale.","Scheduling production employees."],"correct":0,"why_vi":"Hãy phân biệt quyền lợi của shareholders, quản trị của board và nguồn vốn nợ/vốn chủ trước khi chọn. Financing concerns funding through debt or equity, not normal day-to-day production.","trap_vi":"Classify managerial decisions by cash-flow role."},{"stem_en":"A corporation earns net income $120,000, uses equity capital $1,000,000, and has an 9% required equity return. Its simplified economic profit is closest to:","options":["$30,000","$210,000","$120,000"],"correct":0,"why_vi":"Economic profit≈NI−kE=120,000−1,000,000×0.09=$30,000; return required là opportunity cost of equity.","trap_vi":"Positive accounting income may be below hurdle."},{"stem_en":"A corporation earns net income $160,000, uses equity capital $2,000,000, and has an 6% required equity return. Its simplified economic profit is closest to:","options":["$280,000","$40,000","$160,000"],"correct":1,"why_vi":"Economic profit≈NI−kE=160,000−2,000,000×0.06=$40,000; return required là opportunity cost of equity.","trap_vi":"Positive accounting income may be below hurdle."},{"stem_en":"A corporation earns net income $95,000, uses equity capital $700,000, and has an 12% required equity return. Its simplified economic profit is closest to:","options":["$95,000","$179,000","$11,000"],"correct":2,"why_vi":"Economic profit≈NI−kE=95,000−700,000×0.12=$11,000; return required là opportunity cost of equity.","trap_vi":"Positive accounting income may be below hurdle."},{"stem_en":"A corporation earns net income $60,000, uses equity capital $450,000, and has an 15% required equity return. Its simplified economic profit is closest to:","options":["$-7,500","$127,500","$60,000"],"correct":0,"why_vi":"Economic profit≈NI−kE=60,000−450,000×0.15=$-7,500; return required là opportunity cost of equity.","trap_vi":"Positive accounting income may be below hurdle."},{"stem_en":"A corporation earns net income $180,000, uses equity capital $1,500,000, and has an 10% required equity return. Its simplified economic profit is closest to:","options":["$330,000","$30,000","$180,000"],"correct":1,"why_vi":"Economic profit≈NI−kE=180,000−1,500,000×0.10=$30,000; return required là opportunity cost of equity.","trap_vi":"Positive accounting income may be below hurdle."}],"cards":[{"front_en":"1. Explain: Corporate issuer legal personhood","back_vi":"Corporate issuer có separate legal identity: assets và obligations thuộc corporate entity, không mặc nhiên thuộc cá nhân shareholders. Corporation thường được thành lập qua registration/charter theo luật applicable và chịu các reporting/disclosure/capital market rules tùy jurisdiction."},{"front_en":"2. Explain: Corporate registration and charter","back_vi":"Incorporation yêu cầu registration với competent authority và corporate charter/articles xác định hoạt động, share rights và governing bodies. Corporate identity giúp company giao kết contracts, own property, borrow và tồn tại dù shareholder thay đổi."},{"front_en":"3. Explain: Continuity of corporate existence","back_vi":"Corporation thường có continuity beyond founders và không kết thúc chỉ vì individual shareholder bán shares hoặc qua đời. Điều này hỗ trợ huy động long-term capital và planning, nhưng insolvency hoặc voluntary liquidation vẫn có thể chấm dứt entity."},{"front_en":"4. Explain: Separation of owners and managers","back_vi":"Shareholders cung cấp equity ownership nhưng thường không quản lý daily operations; board được bầu để oversee/hire executives, còn CEO/CFO vận hành company. Phân biệt quyền sở hữu, board governance và managerial control."},{"front_en":"5. Explain: Shareholders elect board","back_vi":"Shareholders thường dùng voting rights để elect hoặc remove directors; board làm nhiệm vụ strategic oversight, lựa chọn executives và phê duyệt policies lớn. Corporate governance rules chịu constraints khác nhau theo law, share classes, ownership concentration."},{"front_en":"6. Explain: Board appoints executives","back_vi":"Board thường appoint CEO, CFO và các senior managers. Executives chịu trách nhiệm investing, financing, operating decisions, còn board monitor management và protect owners/stakeholders under governing duties."},{"front_en":"7. Explain: Agency conflicts in owner–manager separation","back_vi":"Managers có incentives như empire building, perquisite consumption hoặc short-term bonuses lệch shareholders' long-term value; monitoring, compensation alignment và voting có thể giảm nhưng không xóa agency costs. Đây là governance implication, không phải guarantee of perfect alignment."},{"front_en":"8. Explain: Shareholder voting as recourse","back_vi":"Nếu directors không hoạt động trong best interests, owners có thể bầu lại board hoặc engage/activate governance rights; quyền ảnh hưởng phụ thuộc share class, voting structure và legal framework. Minority shareholder không có complete control đối với decisions."},{"front_en":"9. Explain: Shareholder limited liability","back_vi":"Conventional shareholder downside limited to money invested in shares, không bắt buộc personally repay corporate debt. Investor có thể mất full equity value; personal guarantees hoặc misconduct có thể tạo legal exceptions."},{"front_en":"10. Explain: Separate entity balance sheet","back_vi":"Corporation owns cash, operating assets, securities và obligations; claims of banks/bondholders khác residual equity of owners. Financial balance sheet assets được tài trợ bởi liabilities và shareholders' equity trong accounting identity."},{"front_en":"11. Explain: Equity ownership units","back_vi":"Shares chia ownership thành nhỏ units, giúp nhiều investors participate. Economic rights và votes có thể khác nếu firm issues multiple classes; không mặc nhiên one share one vote ở mọi company."},{"front_en":"12. Explain: Dividends are discretionary residual distributions","back_vi":"Shareholders có quyền hưởng distributions of profit khi declared theo governance and legal requirements; không có nghĩa mọi accounting profit đều tự động trả dividends. Reinvested earnings có thể tăng capital base và future earnings capacity."},{"front_en":"13. Explain: External equity issuance","back_vi":"Corporate raises equity bằng issuing new shares đến investors hoặc reinvesting earnings as internal equity financing; investors nhận residual claim và risk. Primary issuance khác secondary trading giữa shareholders; giao dịch secondary không tự tạo new cash cho issuer."},{"front_en":"14. Explain: Debt as external financing","back_vi":"Debt finance gồm bank loans, bonds và leases theo contractual repayment/interest terms; lender claim thường senior to equity, company phải trả obligations trước khi equity distributions. Debt có fixed commitments ảnh hưởng financial risk/solvency."},{"front_en":"15. Explain: Debt and equity differences","back_vi":"Lender expects principal/interest; shareholder gains from dividends/capital appreciation after liabilities. Issuer có thể hưởng leverage upside nhưng gia tăng fixed obligations làm insolvency risk cao hơn; investors thấy equity riskier than secured debt broadly."},{"front_en":"16. Explain: Capital providers and financing access","back_vi":"Shareholders, individuals, mutual/pension funds, banks, other companies và governments có thể finance corporation. Issuance of marketable securities mở financing universe rộng hơn partnership privately pooled capital."},{"front_en":"17. Explain: Financial balance sheet","back_vi":"Financial statement convention Assets=Liabilities+Equity, nơi assets gồm operating cash, PP&E, inventory, investments; liabilities gồm suppliers, lenders và other contractual obligations. Shareholders' equity là residual accounting funding."},{"front_en":"18. Explain: Economic balance sheet concept","back_vi":"Broader economic balance sheet includes hard-to-measure values như workforce skills, brand, supplier/customer relations, reputation, sustainability obligations. Một asset intangible economically valuable có thể không xuất hiện với fair value trên financial balance sheet."},{"front_en":"19. Explain: Revenue to net income waterfall","back_vi":"Financial income statement bắt đầu revenue/sales, trừ supplier costs, labor/operating costs, interest, taxes để có net income. Net income là accounting result, chưa đảm bảo return surpasses owners' required opportunity cost."},{"front_en":"20. Explain: Economic profit versus accounting net income","back_vi":"Economic profit sau khi trừ shareholders' opportunity cost of capital; một corporate có net income dương nhưng tạo return <required return thì economic profit âm. Đây là đánh giá value creation beyond accounting expenses."},{"front_en":"21. Explain: Required rate of return on equity","back_vi":"Shareholders đòi return vì opportunity cost, risk và alternative investments; cost of equity không phải explicit expense line trên traditional income statement. Deducting implicit required return converts financial profit toward economic profit."},{"front_en":"22. Explain: Economic profit hypothetical measure","back_vi":"Cho invested equity E, required equity return k và income NI (simplified), economic profit≈NI−kE. Nếu NI chỉ $80 nhưng E=$1.000 và k=10%, shortfall economic profit=$−20 dù accounting earnings positive."},{"front_en":"23. Explain: Corporate income tax","back_vi":"Corporation có thể chịu corporate-level income taxation; tax law varies, some jurisdictions lower corporate rates or special exemptions. Không nên đồng nhất pretax income, accounting tax expense và cash taxes without further detail."},{"front_en":"24. Explain: Double taxation of distributed profits","back_vi":"Trong conventional public corporation, profits bị taxed at corporate level, rồi after-tax distributed dividends có thể bị taxed again in shareholders' hands. Combined rate = 1−(1−t_c)(1−t_d) nếu distribute toàn bộ, không đơn giản cộng rates."},{"front_en":"25. Explain: Retention versus distribution tax effect","back_vi":"Nếu after-tax profits giữ lại/reinvest, dividend shareholder tax chưa phát sinh at that point; capital gains taxation có thể xuất hiện sau khi shares sold hoặc trong hệ thống khác. Việc retention có lợi thuế hay không phụ thuộc local laws, capital opportunities và investors."},{"front_en":"26. Explain: Financial/economic profitability distinction","back_vi":"Một firm có revenue tăng nhưng lợi ích owners không tăng nếu return on incremental capital thấp hơn required rate. Phải phân tích investment productivity và stakeholder relationships, không chỉ nhìn reported net income."},{"front_en":"27. Explain: Management decision categories","back_vi":"Executives phải quyết định operating: produce/sell; investing: acquire/divest assets; financing: how much debt/equity. Các quyết định liên kết cash flow, solvency và business growth."},{"front_en":"28. Explain: Corporate financing and shareholder dilution","back_vi":"New equity issuance increases shares outstanding, làm ownership percentage of existing holders giảm nếu họ không tham gia issuance. Tuy nhiên new funds có thể tạo value, nên dilution in percentage không tự động có nghĩa loss of economic value per old share."},{"front_en":"29. Explain: Corporate stakeholder relationships","back_vi":"Employees, suppliers, customers, communities và government tạo/nhận economic value beyond shareholder contractual cash flows. Mối quan hệ có thể là economic asset/risk dù không có simple accounting measure tương ứng. Detailed governance ESG module sau sẽ đi sâu."},{"front_en":"30. Explain: Corporate form trade-offs","back_vi":"Corporation có limited liability, transferable ownership và wider capital access nhưng yêu cầu registration, reporting, board governance và potentially double taxes. So sánh cấu trúc là trade-off; không có one-size-fits-all business form."},{"front_en":"31. Explain: Exam classification procedure","back_vi":"Khi đề nói owners elect directors, managers run operations, separate legal person, shares và limited owners liability => corporate form. Khi hỏi economic profit, trừ equity opportunity cost from accounting earnings; khi hỏi taxable dividend, áp tax sequentially."}]},{"id":"CFA26-03-01-LOS03","letter":"1.c","title_en":"Publicly versus Privately Owned Corporate Issuers","outcome_en":"compare publicly and privately owned corporate issuers","overview_vi":"Listed versus unlisted issuers, ownership and control concentration, liquidity, transfer, price transparency, free float, primary issuance vs secondary trading, qualified investors/private placements, disclosure, IPO/direct listing/SPAC/acquisitions and going private.","source":[{"id":"CFA Institute Curriculum 2026 — Corporate Issuers LM1","pages":"29–41 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading20","pages":"226–229 (physical PDF)"},{"id":"SAPP Corporate Issuers 2026 — Module1","pages":"26–38 (physical PDF)"}],"sections":[{"heading":"Public corporation versus listed company","body":"CFAI thảo luận publicly owned/listed và privately owned/unlisted issuer theo ownership market và exchange listings. Legal form public limited company có thể tồn tại nhưng không phải mọi share freely listed; đọc liệu đề đang nói public legal form hay listed equity.","trap":"Publicly owned and exchange-listed are related but not identical labels in every jurisdiction."},{"heading":"Exchange market structure","body":"Stock exchange là venue rules-based nơi buyers/sellers trade listed securities với volume/price transparency và exchange oversight. Listed equity cho investors chuyển nhượng thông qua secondary market, còn private trades negotiated bilaterally.","trap":"A stock exchange facilitates trading but is not the issuer itself."},{"heading":"Public listing and trading","body":"Listed company shares có thể available to broad market investors và giao dịch qua intermediaries, giảm search/negotiation cost; thanh khoản phụ thuộc free float, turnover và market depth. Listing không bảo đảm mọi share luôn liquid.","trap":"Listed does not automatically mean high trading liquidity."},{"heading":"Privately owned corporation","body":"Private company equity thường unlisted và giữ bởi founders, families, venture/PE funds hoặc institutional investors. Ownership transfer cần bilateral negotiation và có thể cần approval, làm exit horizon dài và valuation ít observable hơn.","trap":"Private shares are not necessarily worthless or forbidden to transfer."},{"heading":"Public ownership can be concentrated","body":"Một listed corporation vẫn có controlling family, government hoặc strategic shareholder; còn phần shares traded freely là free float. Therefore listed không đồng nghĩa dispersed ownership/voting power.","trap":"Listed and widely held are not always the same."},{"heading":"Free float concept","body":"Free float là shares available for public exchange trading, loại strategic/insider/locked-up holdings. Percentage free float có thể tính shares floating divided by total shares; thấp float thường khiến transaction price sensitive và limited liquidity.","trap":"Free float is not equal to all shares outstanding."},{"heading":"Liquidity and transaction costs","body":"Public liquid market cho nhà đầu tư bán từng small lot nhanh hơn, nhưng block trade ở illiquid microcap vẫn có market impact. Private positions often locked until sale, acquisition, IPO, or negotiated transaction.","trap":"Public market access does not eliminate liquidity risk."},{"heading":"Share price transparency","body":"Listed stock trades công bố quotes và reported last prices, giúp investors mark-to-market và estimate market capitalization. Private equity valuation dùng comparable companies, cash-flow models, transaction prices và illiquidity assumptions thay vì real-time exchange quote.","trap":"Private company can have value but no continuously observable share price."},{"heading":"Private ownership concentration","body":"Fewer owners có thể tạo concentrated voting control và potentially faster decisions, nhưng investors nhỏ có thể chịu governance opacity. Agency issues tồn tại ở cả public/private; không suy private automatically better operating performance.","trap":"Control concentration is both a governance benefit and risk."},{"heading":"Public corporate disclosure","body":"Listed public companies thường phải file periodic financial statements, material event disclosures và governance reports theo securities regulation. Disclosure improves investor information nhưng tạo compliance, legal và management costs.","trap":"Exact filing rules vary across jurisdictions."},{"heading":"Private company disclosure","body":"Private issuers thường ít public filing nghĩa transparency lower nhưng confidentiality higher và compliance costs lower. Lenders/qualified investors vẫn có thể yêu cầu audited records theo contracts, và regulators có requirements khác tùy size/business.","trap":"Private does not mean zero financial reporting obligations."},{"heading":"Primary issuance","body":"Primary market là nơi company issues newly created debt/equity to raise funds. Khi company bán new shares, issuer nhận cash proceeds (net of fees). Investor mua existing shares từ old investor trên secondary market không đưa new cash vào firm directly.","trap":"Primary financing and secondary share transfer must be kept distinct."},{"heading":"Secondary trading after listing","body":"Sau khi IPO, outstanding shares traded trên exchange giữa investors giúp liquidity và price discovery; issuer có thể issue secondary new shares sau đó nhưng không phải mọi exchange trade đều là financing event.","trap":"Secondary market volume is not the firm's new operating cash flow."},{"heading":"Private placement","body":"Private companies hoặc public companies có thể issue securities through nonpublic placements to few sophisticated/institutional investors. Qualified/accredited investor requirements thường hạn chế marketing và investor group, khác unrestricted retail public offering.","trap":"A private placement does not automatically list shares."},{"heading":"Qualified or accredited investors","body":"Qualified investors được xác định bởi local securities regulation dựa trên financial resources, professional expertise hay status để tham gia certain private offerings. Họ không phải investors chỉ được mua public shares; goal often reduce retail disclosure/protection burdens.","trap":"Accreditation criteria and rules differ across markets."},{"heading":"Public equity capital access","body":"Public listing và established governance có thể mở wider pool of investors và permit follow-on equity offerings at scale. Nhưng offering success, dilution, market sentiment và underwriter fees vẫn là funding costs.","trap":"Listing is not guaranteed to lower cost of capital in every state."},{"heading":"Going public concept","body":"Going public biến ownership from private to exchange-listed/publicly traded, potentially via IPO, direct listing, merger/acquisition or SPAC transaction under rules. Mục tiêu có thể là raise growth capital, provide exit và improve public awareness.","trap":"Going public is not only about new cash raised."},{"heading":"Traditional initial public offering","body":"IPO generally sells newly issued shares to public in a regulated process, often with investment-bank underwriting; issuer receives net proceeds from primary new-share portion. Existing shareholders có thể sell shares in secondary portion of IPO; need distinguish primary vs secondary shares.","trap":"An IPO can include existing-share sales alongside primary issuance."},{"heading":"IPO underwriting and disclosure","body":"Underwriters assist pricing, distribution and often guarantee placement commitments depending on underwriting contract. Issuer must meet listing rules, file prospectus và disclose information; fees và governance demands increase.","trap":"Not every IPO guarantee has identical underwriting terms."},{"heading":"Traditional direct listing","body":"Direct listing theo basic CFAI contrast chủ yếu đưa existing shares lên exchange mà không traditional underwritten new-share offering; giúp owners trade publicly nhưng firm có thể không receive new primary capital from that transaction. Modern primary direct-listing regimes may exist, so label the traditional model.","trap":"Direct listing and primary issuance are not synonymous."},{"heading":"SPAC structure","body":"SPAC (special-purpose acquisition company) raises funds publicly to acquire a private target within specified period; resulting combination may bring target to public markets. SPAC sponsor incentives, redemption rights, dilution và deal uncertainty create risks.","trap":"SPAC is not an operating business with established products at IPO."},{"heading":"Going public through acquisition","body":"Private company có thể được acquired by listed company in cash/share deal, hoặc merge into listed vehicle. Private owners có thể nhận listed shares, but terms/valuation and integration risks differ from direct IPO.","trap":"Acquisition transaction does not automatically replicate an IPO's issuance cash flow."},{"heading":"Primary vs secondary funds in an IPO","body":"Nếu company issues 5m new shares at $10, gross primary issuer proceeds=$50m before fees; if existing shareholders sell another 3m shares, $30m of their sale proceeds flow to sellers not issuer. IPO headline total proceeds can include both.","trap":"Separate new shares from secondary selling shareholders."},{"heading":"Post-issue ownership dilution","body":"Nếu company có 10m shares, issues 2m new shares, an old owner with 3m shares falls from 30% to 25% absent participation. Dilution percentage is not the same as shareholder economic loss, because issuer receives capital.","trap":"Count new shares in denominator; do not assume old number unchanged."},{"heading":"Free float and market concentration","body":"Nếu 100m shares, controlling shareholder 55m, strategic lock-up 20m và remaining 25m traded freely, float=25%; public listing can coexist with low float, governance control and wide price spreads.","trap":"Exclude insider and strategic holdings from floating shares."},{"heading":"Public-to-private conversion","body":"Một listed company có thể chuyển thành doanh nghiệp tư nhân (going private) sau khi được sponsor hoặc nhóm quản lý mua lại, thực hiện tender offer rồi delist. Chủ sở hữu tập trung hơn có thể tăng linh hoạt chiến lược, nhưng mất lợi thế thanh khoản và minh bạch công khai. Giao dịch thường có private equity và có thể dùng vốn vay.","trap":"Going private does not mean the company ceases operating."},{"heading":"Management buyout and LBO distinctions","body":"Management buyout (MBO) mô tả ai là bên mua: một nhóm quản lý; leveraged buyout (LBO) mô tả cách tài trợ: sử dụng đáng kể nợ. Một thương vụ có thể đồng thời là MBO và LBO và đưa doanh nghiệp rời sàn; hai thuật ngữ không hoàn toàn đồng nghĩa.","trap":"MBO and LBO answer different aspects of a transaction."},{"heading":"Private ownership potential upside","body":"Vốn góp vào early-stage private venture có thể tạo tỷ suất sinh lời cao nếu doanh nghiệp thành công, nhưng thường đi kèm information risk, nguy cơ phá sản và illiquidity rất lớn. Không thể khẳng định công ty tư nhân luôn đạt realized return cao hơn public shares.","trap":"Potential return is not guaranteed return."},{"heading":"Public company short-termism claim","body":"Có ý kiến cho rằng việc phải công bố báo cáo hàng quý khiến nhà quản lý công ty niêm yết tập trung vào kết quả ngắn hạn. Tuy nhiên, CFAI lưu ý bằng chứng thực nghiệm cho hiện tượng short-termism trên diện rộng vẫn còn hạn chế; đây là tranh luận, không phải ưu thế chắc chắn của going private.","trap":"Do not state that all public companies necessarily sacrifice long-term value."},{"heading":"Investor governance trade-offs","body":"Cổ đông listed company thường có thanh khoản và disclosure tốt hơn, nhưng minority voting power có thể hạn chế khi có controlling owners. Nhà đầu tư tư nhân có thể đàm phán board seat hoặc covenants riêng, đổi lại phải chịu limited exits. Cần so sánh quyền kiểm soát, thông tin, illiquidity và financing cost cùng lúc.","trap":"Public/private is a multidimensional trade-off."},{"heading":"Exam method for public/private classification","body":"Khi giải câu hỏi thi, kiểm tra lần lượt exchange listing, transferability, price transparency, periodic filings, share issuance, qualified investors, ownership concentration và free float. Đặc biệt phải phân biệt dòng tiền vào issuer qua newly issued shares với proceeds bán cổ phiếu cũ trên secondary market.","trap":"IPO, direct listing, private placement and going-private buyout are distinct."}],"formulas":[{"name":"Listed vs unlisted issuer","expr":"Listed: exchange transfer, public price/volume discovery, more disclosures; Unlisted: negotiated transfer, less public price transparency","meaning":"So sánh quyền mua bán và reporting obligations.","conditions":"Broad CFAI analytical framework, not universal local regulation."},{"name":"Exchange liquidity","expr":"Liquidity depends on bid-ask spread, order depth, float and turnover","meaning":"Public listing có thể cải thiện ease of transaction.","conditions":"Qualitative, not a guarantee."},{"name":"Free float shares","expr":"Floating shares = total shares − strategic/insider/restricted shares","meaning":"Lượng cổ phiếu có thể giao dịch freely.","conditions":"Definitions of free float vary by index/exchange."},{"name":"Free float percent","expr":"Float percentage = floating shares / total shares outstanding ×100%","meaning":"Đánh giá số shares traded freely.","conditions":"Exclude treasury shares where appropriate to chosen convention."},{"name":"Equity market capitalization","expr":"Market cap = exchange price per share × shares outstanding","meaning":"Listed issuer observable market value of common shares.","conditions":"Do not multiply by float only for total market capitalization."},{"name":"Free-float-adjusted market cap","expr":"Float-adjusted value = price×float shares","meaning":"Chỉ phần cổ phiếu freely tradeable.","conditions":"Common index analysis extension, not equal total market cap."},{"name":"Primary offering proceeds","expr":"Gross issuer proceeds = new shares issued × offer price","meaning":"Cash raised via primary new-share issue.","conditions":"Fees and share class terms not included."},{"name":"Secondary seller proceeds","expr":"Cash to seller = existing shares sold × sale price","meaning":"Secondary existing shareholder transfer, not new cash issuer.","conditions":"Brokerage fees omitted."},{"name":"Follow-on offering","expr":"Additional public company primary shares → additional firm cash and potential ownership dilution","meaning":"Secondary equity issue by listed company.","conditions":"Actual net financing depends on underwriter and fees."},{"name":"Post-issue ownership fraction","expr":"New ownership % = old owner shares /(old outstanding+new primary shares)","meaning":"Tính ownership dilution for nonsubscribing holder.","conditions":"Multi-class stocks may have different voting power."},{"name":"IPO key features","expr":"IPO: public securities offering, new-share primary financing often with underwriting/prospectus","meaning":"Giúp private company become listed and access broad investors.","conditions":"IPO can also include existing-share sales."},{"name":"Traditional direct listing","expr":"Existing shares enter exchange trading; no traditional underwritten primary new-share sale","meaning":"Tăng liquidity mà không necessarily raise new issuer cash.","conditions":"Modern exchange rules may permit primary direct listings; teaching contrast follows 2026 Curriculum."},{"name":"SPAC going public","expr":"SPAC publicly raises acquisition capital → merges with private target","meaning":"Alternative route with sponsor/redemption/dilution risk.","conditions":"Transaction mechanics subject to rules and market conditions."},{"name":"Private placement","expr":"Nonpublic sale to limited qualified/sophisticated investors","meaning":"Access capital without exchange listing or broad public prospectus.","conditions":"Private securities laws vary."},{"name":"Public disclosure","expr":"Listed issuers typically file periodic reports plus material-event disclosures","meaning":"Transparency benefits investors at compliance cost.","conditions":"Exact regulation market-specific."},{"name":"Private valuation approach","expr":"Valuation estimated by transactions, comparisons, DCF, with illiquidity/disclosure adjustments","meaning":"Private company lacks regular exchange marking.","conditions":"Different valuation methods can give different estimates."},{"name":"Liquidity discount intuition","expr":"Less transferable investment generally requires a higher expected return, other things equal","meaning":"Illiquidity can affect valuation and investor willingness.","conditions":"Conceptual relation, not fixed numeric discount."},{"name":"MBO vs LBO","expr":"MBO identifies management-led acquirer; LBO identifies debt-financed acquisition","meaning":"Going-private methods can overlap.","conditions":"Distinguish funding structure from buyer identity."},{"name":"Cost of listing","expr":"Net listing benefit = capital/liquidity/disclosure advantages − regulatory, underwriting and governance costs","meaning":"Trade-off selection for public company.","conditions":"Qualitative framework, not formula mandated by CFAI."}],"examples":[{"question_en":"A private company sells 2 million newly issued shares at $15 each through an IPO. What gross cash proceeds go to the issuer?","answer":"$30 million","steps_vi":["Xác định giao dịch thuộc primary hay secondary market và phân biệt dòng tiền issuer với shareholder. Issuer sells NEW shares so receives 2.000.000×15.","Gross primary proceeds=30.000.000 USD, before offering fees."],"check":"This is primary financing."},{"question_en":"An old founder separately sells 500,000 existing shares at $15 during an IPO. How much of this sale goes directly to the issuer?","answer":"$0","steps_vi":["Sale of existing founder shares là secondary sale nên proceeds thuộc founder.","500.000×15=$7,5m gross to selling shareholder, not firm."],"check":"Secondary versus primary distinction."},{"question_en":"A listed company has 100 million outstanding shares and 35 million are held by insiders/strategic holders. What is free float percentage?","answer":"65%","steps_vi":["Shares floating=100−35=65 triệu.","Float%=65/100×100%=65%."],"check":"Assume all remaining shares freely tradable."},{"question_en":"A corporation has 50 million shares trading at $8 each. What is total equity market capitalization?","answer":"$400 million","steps_vi":["Market capitalization dùng all outstanding shares not just free float.","50.000.000×8=400.000.000 USD."],"check":"Price versus market value."},{"question_en":"Same company has a free float of 60%. What is float-adjusted equity capitalization?","answer":"$240 million","steps_vi":["Floating shares=50 triệu×0,60=30 triệu.","Adjusted cap=30 triệu×8=$240 triệu, không phải total $400 triệu."],"check":"This is supplementary index-style calculation."},{"question_en":"A private company has no exchange listing. Its investor wants to sell shares immediately at a posted exchange price. What obstacle is most likely?","answer":"No readily observable trading quote and limited transferability","steps_vi":["Private shares cần find buyer, negotiate valuation và có thể require transfer approval.","Investor may wait until secondary transaction, acquisition or IPO."],"check":"Illiquidity risk."},{"question_en":"A listed corporation has an investor who owns 2 million shares out of 10 million. The issuer sells 5 million new shares; investor buys none. What is new ownership percentage?","answer":"13.33%","steps_vi":["Xác định giao dịch thuộc primary hay secondary market và phân biệt dòng tiền issuer với shareholder. Shares owned unchanged 2m, new total shares=15m.","Percentage drops from 20% to 2/15≈13,33%."],"check":"Economic value can change for other reasons."},{"question_en":"A company sells 3 million new shares at $12 and existing holders sell another 2 million. What gross offering cash reaches the issuer before fees?","answer":"$36 million","steps_vi":["Xác định giao dịch thuộc primary hay secondary market và phân biệt dòng tiền issuer với shareholder. New shares proceeds=3m×12=$36m.","Existing holders receive 2m×12=$24m separately, so issuer gross not $60m."],"check":"Separate primary and secondary tranches."},{"question_en":"A firm publicly lists existing shares with no new equity issuance in the traditional direct-listing model. Does the issuer automatically raise new share capital?","answer":"No","steps_vi":["Direct listing of existing shares enables exchange trading nhưng không generate new primary proceeds in traditional model.","Other contemporary variants allow primary offerings; here specified traditional."],"check":"Traditional direct listing."},{"question_en":"An acquisition vehicle raises cash before identifying a target, then later combines with a privately held company to bring it public. Identify the vehicle.","answer":"SPAC","steps_vi":["Xác định giao dịch thuộc primary hay secondary market và phân biệt dòng tiền issuer với shareholder. Special-purpose acquisition company raises capital to acquire a private company within a time horizon.","Sponsor interests, redemptions and dilution matter; not a business with operations initially."],"check":"SPAC scenario."},{"question_en":"A listed company is purchased by a group led by its management and then delisted. Identify the broad transaction.","answer":"Management buyout and going private","steps_vi":["Xác định giao dịch thuộc primary hay secondary market và phân biệt dòng tiền issuer với shareholder. Management is buyer group, exchange listing ends; potential overlap with LBO if funded through borrowing.","This is not an IPO or direct listing."],"check":"MBO / take-private scenario."},{"question_en":"Why might a private venture investor demand a higher expected return than a liquid public-equity investor, all else equal?","answer":"Greater illiquidity and information risk","steps_vi":["Private stake không liên tục traded và disclosure may be limited.","Higher demanded return is compensation for risk, not guaranteed realized outperformance."],"check":"Investor requirement."},{"question_en":"A company's shares are listed but 75% are held by a strategic family owner. What is the likely free float percentage if all remaining shares are freely tradable?","answer":"25%","steps_vi":["Float percentage=1−75%=25%; một listed company vẫn có controlling owner.","Share prices vẫn observable, nhưng liquidity có thể thấp hơn widely held issuer."],"check":"Listed does not mean dispersed."},{"question_en":"A private firm issues debt to three institutions under negotiated contracts. Must it become exchange-listed as a result?","answer":"No","steps_vi":["Private issuers can raise debt/equity financing from limited qualified investors without listing.","Issuing a security to institutions không đồng nghĩa shares traded on stock exchange."],"check":"Private placement."},{"question_en":"A company plans to make quarterly disclosures to public investors after listing. What likely increases relative to a private firm?","answer":"Reporting and compliance costs","steps_vi":["Public listing đi kèm periodic financial disclosures và securities oversight.","Greater transparency may improve market access/liquidity but costs rise."],"check":"Public-company obligations."}],"questions":[{"stem_en":"A public exchange listing is most directly associated with:","options":["Easier secondary-market transfer of ownership.","Guaranteed dividends.","No requirement to report financial information."],"correct":0,"why_vi":"Listed shares có organized market để buyers/sellers trade, improving liquidity.","trap_vi":"Trading conditions still depend on free float and volume."},{"stem_en":"A private company shareholder is most likely to:","options":["Sell shares instantly on a liquid stock exchange.","Negotiate transfer with a buyer under possible ownership restrictions.","Receive a continuously observable exchange price."],"correct":1,"why_vi":"Private shares unlisted và transfer restrictions/negotiated pricing khiến liquidity thấp.","trap_vi":"Private capital can still change hands."},{"stem_en":"Free float generally excludes shares held by:","options":["Public small investors who trade regularly.","All holders regardless of trading.","Strategic and insider owners with restricted holdings."],"correct":2,"why_vi":"Float là portion freely tradeable, exclude insider or strategic blocks.","trap_vi":"Total outstanding shares may greatly exceed float."},{"stem_en":"A listed corporation can have a controlling shareholder because:","options":["Listing does not require all ownership to be dispersed.","Listed shares must all have identical owners.","Strategic investors cannot hold any listed shares."],"correct":0,"why_vi":"Exchange listing không ngăn family/government hold majority block.","trap_vi":"Distinguish listed from widely held."},{"stem_en":"Compared with private issuers, listed public companies generally face:","options":["No financial reporting obligations.","Greater disclosure and regulatory compliance requirements.","Lower transparency on all trades."],"correct":1,"why_vi":"Public investors cần transparent periodic reports/material events, dẫn đến compliance costs.","trap_vi":"Market-specific exceptions exist."},{"stem_en":"In which market does a corporation receive new capital by selling newly issued shares?","options":["Primary market.","Secondary exchange trading between shareholders.","Resale of existing insider shares."],"correct":0,"why_vi":"Issuer nhận funds từ primary new securities.","trap_vi":"Secondary transactions transfer ownership not new firm capital."},{"stem_en":"An existing investor sells listed shares to another investor. The transaction generally results in:","options":["Immediate new funds paid into the issuer.","A transfer of ownership between investors.","Automatic increase in shares outstanding."],"correct":1,"why_vi":"Secondary sale chuyển wealth giữa buyer và seller; firm không issue new stock.","trap_vi":"Secondary trading is distinct from an equity offering."},{"stem_en":"In a traditional IPO, a common role of an investment bank is:","options":["Underwriting and distributing newly offered securities.","Replacing the government tax authority.","Guaranteeing all future share returns."],"correct":0,"why_vi":"Underwriters arrange/pricing/distribution according to contract và regulatory prospectus.","trap_vi":"Underwriting is not investment-return guarantee."},{"stem_en":"Under the basic traditional direct-listing model emphasized in this course, the firm:","options":["Primarily lists existing shares for public trading.","Must sell newly issued shares through a traditional underwriter.","Cannot allow current shareholders to trade."],"correct":0,"why_vi":"Cần xét listing, dòng tiền từ newly issued shares và quyền chuyển nhượng cổ phần trước khi kết luận. Direct listing gives exchange liquidity for existing shares; not necessarily issuer cash in traditional setting.","trap_vi":"Some newer primary direct listings differ."},{"stem_en":"An issuer uses a SPAC structure principally to:","options":["Eliminate the need to value acquisition targets.","Bring a private target public through a combination with a listed acquisition vehicle.","Prohibit shareholder redemptions in every market."],"correct":1,"why_vi":"Cần xét listing, dòng tiền từ newly issued shares và quyền chuyển nhượng cổ phần trước khi kết luận. SPAC raises public capital and acquires/merges with private target.","trap_vi":"SPAC financing involves sponsor/redemption risks."},{"stem_en":"A public firm seeks to cease stock exchange trading through an acquisition of public shareholders. This is most likely:","options":["An IPO.","A public follow-on equity offering.","A going-private transaction."],"correct":2,"why_vi":"Cần xét listing, dòng tiền từ newly issued shares và quyền chuyển nhượng cổ phần trước khi kết luận. Buyout and delisting convert publicly traded ownership into private ownership.","trap_vi":"Going private is the reverse direction of an IPO."},{"stem_en":"Which shareholder group commonly buys private placements?","options":["Only retail investors unrestricted.","Qualified or sophisticated investors.","Only central banks."],"correct":1,"why_vi":"Private placements thường marketed to qualified/accredited investors under local rules.","trap_vi":"Such investors can also trade public securities."},{"stem_en":"Compared with public firms, privately owned firms often benefit from:","options":["Less publicly required disclosure and greater confidentiality.","Guaranteed access to unlimited market liquidity.","Mandatory active exchange share pricing."],"correct":0,"why_vi":"Private company có less public transparency obligation and perhaps lower compliance cost.","trap_vi":"Investors must still obtain private information."},{"stem_en":"Which is an advantage often associated with listed shares?","options":["Greater visible price discovery and a potential liquidity market.","Elimination of all business risk.","Guaranteed return exceeding private equity."],"correct":0,"why_vi":"Cần xét listing, dòng tiền từ newly issued shares và quyền chuyển nhượng cổ phần trước khi kết luận. Listed exchanges publish trades/prices, facilitating valuation and transfer.","trap_vi":"Not all listed stocks are liquid."},{"stem_en":"An IPO offering has 1 million newly issued shares and 2 million existing shares sold by founders. Which amount is issuer primary issuance?","options":["3 million shares.","1 million shares.","2 million shares."],"correct":1,"why_vi":"Cần xét listing, dòng tiền từ newly issued shares và quyền chuyển nhượng cổ phần trước khi kết luận. Issuer only receives proceeds of new 1m shares; 2m belong existing holders.","trap_vi":"Gross offering size differs issuer funds."},{"stem_en":"When a corporation issues new shares and an existing holder does not participate, ownership percentage generally:","options":["Increases without new purchases.","Remains identical for every holder.","Decreases due to more shares outstanding."],"correct":2,"why_vi":"Dilution denominator tăng, old share count unchanged.","trap_vi":"This does not mechanically prove destruction of economic value."},{"stem_en":"A company listed on a stock exchange has 100 million shares, 40 million freely tradable and 60 million strategic or restricted. Its free float is:","options":["40%.","60%.","100%."],"correct":0,"why_vi":"Cần xét listing, dòng tiền từ newly issued shares và quyền chuyển nhượng cổ phần trước khi kết luận. Float shares=40m/100m=40%.","trap_vi":"Do not include strategic locked blocks."},{"stem_en":"A privately held company obtains external equity from a small group of venture capital investors. The issuance is best described as:","options":["A private placement.","A mandatory public IPO.","A listed secondary transaction."],"correct":0,"why_vi":"Cần xét listing, dòng tiền từ newly issued shares và quyền chuyển nhượng cổ phần trước khi kết luận. Negotiated nonpublic capital raising from few qualified investors is private placement.","trap_vi":"No listing required."},{"stem_en":"A management buyout of a listed company is most directly linked to:","options":["Newly listed public ownership.","The acquirer being management, potentially followed by going private.","Selling all operating assets through a retail market."],"correct":1,"why_vi":"Cần xét listing, dòng tiền từ newly issued shares và quyền chuyển nhượng cổ phần trước khi kết luận. MBO identifies management buyer group, can be takeover and delisting.","trap_vi":"A leveraged buyout describes use of debt, not who the acquirer is."},{"stem_en":"If two firms have similar operating prospects but one stock is illiquid, investors may demand:","options":["A higher expected required return for the illiquid security.","Guaranteed higher actual return.","No compensation for the inability to sell."],"correct":0,"why_vi":"Illiquidity risk thường khiến demanded return cao hơn ceteris paribus.","trap_vi":"Required return is not realized guarantee."},{"stem_en":"A firm has 10 million shares, an investor owns 2 million shares, and the firm issues 2 million new shares. The investor purchases none. The post-issue ownership is closest to:","options":["16.67%","20.00%","100.00%"],"correct":0,"why_vi":"Cần xét listing, dòng tiền từ newly issued shares và quyền chuyển nhượng cổ phần trước khi kết luận. New share count=12m; investor still owns 2m; new percentage=2/12≈16.67%.","trap_vi":"Denominator includes new shares."},{"stem_en":"A firm has 20 million shares, an investor owns 5 million shares, and the firm issues 5 million new shares. The investor purchases none. The post-issue ownership is closest to:","options":["25.00%","20.00%","100.00%"],"correct":1,"why_vi":"Cần xét listing, dòng tiền từ newly issued shares và quyền chuyển nhượng cổ phần trước khi kết luận. New share count=25m; investor still owns 5m; new percentage=5/25≈20.00%.","trap_vi":"Denominator includes new shares."},{"stem_en":"A firm has 30 million shares, an investor owns 6 million shares, and the firm issues 10 million new shares. The investor purchases none. The post-issue ownership is closest to:","options":["60.00%","20.00%","15.00%"],"correct":2,"why_vi":"Cần xét listing, dòng tiền từ newly issued shares và quyền chuyển nhượng cổ phần trước khi kết luận. New share count=40m; investor still owns 6m; new percentage=6/40≈15.00%.","trap_vi":"Denominator includes new shares."},{"stem_en":"A firm has 8 million shares, an investor owns 3 million shares, and the firm issues 2 million new shares. The investor purchases none. The post-issue ownership is closest to:","options":["30.00%","37.50%","150.00%"],"correct":0,"why_vi":"Cần xét listing, dòng tiền từ newly issued shares và quyền chuyển nhượng cổ phần trước khi kết luận. New share count=10m; investor still owns 3m; new percentage=3/10≈30.00%.","trap_vi":"Denominator includes new shares."},{"stem_en":"A firm has 15 million shares, an investor owns 4 million shares, and the firm issues 5 million new shares. The investor purchases none. The post-issue ownership is closest to:","options":["26.67%","20.00%","80.00%"],"correct":1,"why_vi":"Cần xét listing, dòng tiền từ newly issued shares và quyền chuyển nhượng cổ phần trước khi kết luận. New share count=20m; investor still owns 4m; new percentage=4/20≈20.00%.","trap_vi":"Denominator includes new shares."}],"cards":[{"front_en":"1. Explain: Public corporation versus listed company","back_vi":"CFAI thảo luận publicly owned/listed và privately owned/unlisted issuer theo ownership market và exchange listings. Legal form public limited company có thể tồn tại nhưng không phải mọi share freely listed; đọc liệu đề đang nói public legal form hay listed equity."},{"front_en":"2. Explain: Exchange market structure","back_vi":"Stock exchange là venue rules-based nơi buyers/sellers trade listed securities với volume/price transparency và exchange oversight. Listed equity cho investors chuyển nhượng thông qua secondary market, còn private trades negotiated bilaterally."},{"front_en":"3. Explain: Public listing and trading","back_vi":"Listed company shares có thể available to broad market investors và giao dịch qua intermediaries, giảm search/negotiation cost; thanh khoản phụ thuộc free float, turnover và market depth. Listing không bảo đảm mọi share luôn liquid."},{"front_en":"4. Explain: Privately owned corporation","back_vi":"Private company equity thường unlisted và giữ bởi founders, families, venture/PE funds hoặc institutional investors. Ownership transfer cần bilateral negotiation và có thể cần approval, làm exit horizon dài và valuation ít observable hơn."},{"front_en":"5. Explain: Public ownership can be concentrated","back_vi":"Một listed corporation vẫn có controlling family, government hoặc strategic shareholder; còn phần shares traded freely là free float. Therefore listed không đồng nghĩa dispersed ownership/voting power."},{"front_en":"6. Explain: Free float concept","back_vi":"Free float là shares available for public exchange trading, loại strategic/insider/locked-up holdings. Percentage free float có thể tính shares floating divided by total shares; thấp float thường khiến transaction price sensitive và limited liquidity."},{"front_en":"7. Explain: Liquidity and transaction costs","back_vi":"Public liquid market cho nhà đầu tư bán từng small lot nhanh hơn, nhưng block trade ở illiquid microcap vẫn có market impact. Private positions often locked until sale, acquisition, IPO, or negotiated transaction."},{"front_en":"8. Explain: Share price transparency","back_vi":"Listed stock trades công bố quotes và reported last prices, giúp investors mark-to-market và estimate market capitalization. Private equity valuation dùng comparable companies, cash-flow models, transaction prices và illiquidity assumptions thay vì real-time exchange quote."},{"front_en":"9. Explain: Private ownership concentration","back_vi":"Fewer owners có thể tạo concentrated voting control và potentially faster decisions, nhưng investors nhỏ có thể chịu governance opacity. Agency issues tồn tại ở cả public/private; không suy private automatically better operating performance."},{"front_en":"10. Explain: Public corporate disclosure","back_vi":"Listed public companies thường phải file periodic financial statements, material event disclosures và governance reports theo securities regulation. Disclosure improves investor information nhưng tạo compliance, legal và management costs."},{"front_en":"11. Explain: Private company disclosure","back_vi":"Private issuers thường ít public filing nghĩa transparency lower nhưng confidentiality higher và compliance costs lower. Lenders/qualified investors vẫn có thể yêu cầu audited records theo contracts, và regulators có requirements khác tùy size/business."},{"front_en":"12. Explain: Primary issuance","back_vi":"Primary market là nơi company issues newly created debt/equity to raise funds. Khi company bán new shares, issuer nhận cash proceeds (net of fees). Investor mua existing shares từ old investor trên secondary market không đưa new cash vào firm directly."},{"front_en":"13. Explain: Secondary trading after listing","back_vi":"Sau khi IPO, outstanding shares traded trên exchange giữa investors giúp liquidity và price discovery; issuer có thể issue secondary new shares sau đó nhưng không phải mọi exchange trade đều là financing event."},{"front_en":"14. Explain: Private placement","back_vi":"Private companies hoặc public companies có thể issue securities through nonpublic placements to few sophisticated/institutional investors. Qualified/accredited investor requirements thường hạn chế marketing và investor group, khác unrestricted retail public offering."},{"front_en":"15. Explain: Qualified or accredited investors","back_vi":"Qualified investors được xác định bởi local securities regulation dựa trên financial resources, professional expertise hay status để tham gia certain private offerings. Họ không phải investors chỉ được mua public shares; goal often reduce retail disclosure/protection burdens."},{"front_en":"16. Explain: Public equity capital access","back_vi":"Public listing và established governance có thể mở wider pool of investors và permit follow-on equity offerings at scale. Nhưng offering success, dilution, market sentiment và underwriter fees vẫn là funding costs."},{"front_en":"17. Explain: Going public concept","back_vi":"Going public biến ownership from private to exchange-listed/publicly traded, potentially via IPO, direct listing, merger/acquisition or SPAC transaction under rules. Mục tiêu có thể là raise growth capital, provide exit và improve public awareness."},{"front_en":"18. Explain: Traditional initial public offering","back_vi":"IPO generally sells newly issued shares to public in a regulated process, often with investment-bank underwriting; issuer receives net proceeds from primary new-share portion. Existing shareholders có thể sell shares in secondary portion of IPO; need distinguish primary vs secondary shares."},{"front_en":"19. Explain: IPO underwriting and disclosure","back_vi":"Underwriters assist pricing, distribution and often guarantee placement commitments depending on underwriting contract. Issuer must meet listing rules, file prospectus và disclose information; fees và governance demands increase."},{"front_en":"20. Explain: Traditional direct listing","back_vi":"Direct listing theo basic CFAI contrast chủ yếu đưa existing shares lên exchange mà không traditional underwritten new-share offering; giúp owners trade publicly nhưng firm có thể không receive new primary capital from that transaction. Modern primary direct-listing regimes may exist, so label the traditional model."},{"front_en":"21. Explain: SPAC structure","back_vi":"SPAC (special-purpose acquisition company) raises funds publicly to acquire a private target within specified period; resulting combination may bring target to public markets. SPAC sponsor incentives, redemption rights, dilution và deal uncertainty create risks."},{"front_en":"22. Explain: Going public through acquisition","back_vi":"Private company có thể được acquired by listed company in cash/share deal, hoặc merge into listed vehicle. Private owners có thể nhận listed shares, but terms/valuation and integration risks differ from direct IPO."},{"front_en":"23. Explain: Primary vs secondary funds in an IPO","back_vi":"Nếu company issues 5m new shares at $10, gross primary issuer proceeds=$50m before fees; if existing shareholders sell another 3m shares, $30m of their sale proceeds flow to sellers not issuer. IPO headline total proceeds can include both."},{"front_en":"24. Explain: Post-issue ownership dilution","back_vi":"Nếu company có 10m shares, issues 2m new shares, an old owner with 3m shares falls from 30% to 25% absent participation. Dilution percentage is not the same as shareholder economic loss, because issuer receives capital."},{"front_en":"25. Explain: Free float and market concentration","back_vi":"Nếu 100m shares, controlling shareholder 55m, strategic lock-up 20m và remaining 25m traded freely, float=25%; public listing can coexist with low float, governance control and wide price spreads."},{"front_en":"26. Explain: Public-to-private conversion","back_vi":"Một listed company có thể chuyển thành doanh nghiệp tư nhân (going private) sau khi được sponsor hoặc nhóm quản lý mua lại, thực hiện tender offer rồi delist. Chủ sở hữu tập trung hơn có thể tăng linh hoạt chiến lược, nhưng mất lợi thế thanh khoản và minh bạch công khai. Giao dịch thường có private equity và có thể dùng vốn vay."},{"front_en":"27. Explain: Management buyout and LBO distinctions","back_vi":"Management buyout (MBO) mô tả ai là bên mua: một nhóm quản lý; leveraged buyout (LBO) mô tả cách tài trợ: sử dụng đáng kể nợ. Một thương vụ có thể đồng thời là MBO và LBO và đưa doanh nghiệp rời sàn; hai thuật ngữ không hoàn toàn đồng nghĩa."},{"front_en":"28. Explain: Private ownership potential upside","back_vi":"Vốn góp vào early-stage private venture có thể tạo tỷ suất sinh lời cao nếu doanh nghiệp thành công, nhưng thường đi kèm information risk, nguy cơ phá sản và illiquidity rất lớn. Không thể khẳng định công ty tư nhân luôn đạt realized return cao hơn public shares."},{"front_en":"29. Explain: Public company short-termism claim","back_vi":"Có ý kiến cho rằng việc phải công bố báo cáo hàng quý khiến nhà quản lý công ty niêm yết tập trung vào kết quả ngắn hạn. Tuy nhiên, CFAI lưu ý bằng chứng thực nghiệm cho hiện tượng short-termism trên diện rộng vẫn còn hạn chế; đây là tranh luận, không phải ưu thế chắc chắn của going private."},{"front_en":"30. Explain: Investor governance trade-offs","back_vi":"Cổ đông listed company thường có thanh khoản và disclosure tốt hơn, nhưng minority voting power có thể hạn chế khi có controlling owners. Nhà đầu tư tư nhân có thể đàm phán board seat hoặc covenants riêng, đổi lại phải chịu limited exits. Cần so sánh quyền kiểm soát, thông tin, illiquidity và financing cost cùng lúc."},{"front_en":"31. Explain: Exam method for public/private classification","back_vi":"Khi giải câu hỏi thi, kiểm tra lần lượt exchange listing, transferability, price transparency, periodic filings, share issuance, qualified investors, ownership concentration và free float. Đặc biệt phải phân biệt dòng tiền vào issuer qua newly issued shares với proceeds bán cổ phiếu cũ trên secondary market."}]}]},{"module_id":"CFA26-03-02","module_title":"Investors and Other Stakeholders","subject":"Corporate Issuers","version":"2.0","language":"Vietnamese explanations with English CFA terminology and English exam questions","qa_status":"DETAILED_DRAFT_PENDING_INDEPENDENT_ACADEMIC_AUDIT","disclaimer_vi":"Nội dung biên soạn mới dựa trên ba LOS CFAI 2026, đối chiếu Kaplan Book 1 và slide Corporate Issuers. Bài tập và câu hỏi được tạo mới, không phải câu hỏi gốc CFAI. Các công thức minh họa ngoài trọng tâm LOS được gắn điều kiện áp dụng; toàn bộ đáp án chưa qua phản biện học thuật độc lập.","los":[{"id":"CFA26-03-02-LOS01","letter":"2.a","title_en":"Debt and Equity Investors: Claims and Motivations","outcome_en":"compare the financial claims and motivations of lenders and shareholders","overview_vi":"Phân biệt contractual priority claims của lenders và residual claims của shareholders, xét rủi ro từ hai góc nhìn issuer/investor, financial leverage, debt–equity conflicts và tax treatment.","source":[{"id":"CFA Institute Curriculum 2026 — Corporate Issuers LM2","pages":"45–56 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading21","pages":"230–232 (physical PDF)"},{"id":"SAPP Corporate Issuers 2026 — Module2","pages":"41–50 (physical PDF)"}],"sections":[{"heading":"Contractual debt claims","body":"Lenders cung cấp vốn trong thời hạn xác định. Issuer cam kết trả lãi và principal theo hợp đồng; nghĩa vụ thanh toán không phụ thuộc việc ban quản trị có muốn chi trả hay không.","trap":"Do not describe interest as discretionary distributions."},{"heading":"Permanent equity capital","body":"Shareholders cung cấp equity vốn thường không có maturity và issuer không buộc hoàn trả giá mua cổ phiếu; cổ đông hưởng residual cash flows sau các khoản có ưu tiên.","trap":"Permanent financing does not promise a positive return."},{"heading":"Priority in liquidation","body":"Khi thanh lý, secured creditors, các claims theo luật và unsecured lenders được xử lý theo ưu tiên liên quan; common equity chỉ nhận phần còn lại nếu đủ tài sản.","trap":"Debt is senior to common equity, but creditor ranking varies."},{"heading":"Residual payoff","body":"Equity payoff tăng cùng residual firm value sau khi trừ debt claims; upside có thể lớn trong khi tối đa loss của shareholder thông thường là phần vốn bỏ ra khi không bảo lãnh riêng.","trap":"Equity is residual; it is not a contractual coupon."},{"heading":"Finite versus indefinite term","body":"Debt thường có thời hạn xác định dù dài; common stock không có maturity. Một công ty có thể refinance debt chứ debt không tự biến thành perpetual capital.","trap":"Do not confuse long maturity with indefinite equity."},{"heading":"Investor risk–return ranking","body":"Từ góc nhìn người đầu tư vào cùng một issuer và cấu trúc ưu tiên, creditors thường chấp nhận lợi suất thấp hơn để đổi lấy priority; equity holders gánh nhiều downside trước và đòi return cao hơn.","trap":"Debt can still default and is not universally risk-free."},{"heading":"Issuer financing risk","body":"Với issuer, debt tạo nghĩa vụ trả lãi/principal và rủi ro default/financial distress; equity không buộc trả theo lịch, nên equity ít tạo financial distress từ contractual payments.","trap":"Lower funding cost of debt does not imply lower issuer risk."},{"heading":"Fixed upside of debt investors","body":"Payoff của lender thường bị giới hạn bởi promised interest + principal theo hợp đồng; nếu công ty phát đạt hơn dự tính thì lợi ích vượt trội thường thuộc equity.","trap":"Some convertible/participating debt changes this simple ranking."},{"heading":"Equity voting and control","body":"Common shareholders thường có quyền bầu board, trong khi lenders không trực tiếp tham gia vận hành nhưng có covenants, collateral và enforcement rights.","trap":"A loan covenant is not the same as ordinary voting rights."},{"heading":"Dividends at board discretion","body":"Dividend thường do board quyết định, phụ thuộc earnings, cash, pháp luật và policies. Không chia cổ tức không tự động cấu thành default như bỏ qua contractual debt payment.","trap":"Declared dividend obligations may follow local law."},{"heading":"Interest tax deductibility","body":"Interest expense thường được trừ khi tính taxable corporate income, còn dividends không phải expense được trừ, làm debt có lợi thế tax shield.","trap":"Limits on interest deductions and local tax rules may apply."},{"heading":"Financial leverage and ROE","body":"Debt financing làm equity vốn bỏ ra nhỏ hơn cho cùng assets; khi operating return cao hơn cost of debt, ROE của equity có thể tăng, nhưng khi earnings giảm thì loss cũng được khuếch đại.","trap":"Leverage magnifies both upside and downside."},{"heading":"Return on assets versus cost of debt","body":"Trực giác leverage: nếu after/pretax return từ assets cao hơn marginal financing cost đồng bộ với cơ sở thuế, sử dụng nợ có thể nâng return cho equity; ngược lại debt có thể làm ROE giảm.","trap":"Compare pre-tax with pre-tax, after-tax with after-tax."},{"heading":"Interest coverage intuition","body":"EBIT / interest expense đo earnings hoạt động trước lãi có đủ bao phủ coupon không; chỉ số giảm khi chi phí lãi tăng hoặc EBIT giảm.","trap":"A positive coverage ratio does not guarantee adequate cash liquidity."},{"heading":"Equity default threshold","body":"Trong mô hình đơn giản V là firm asset value, D là debt due: equity còn giá trị khi V>D; nếu V<=D thì payoff cho equity bằng zero.","trap":"Bankruptcy processes and claim priority may complicate real distributions."},{"heading":"Shareholders' incentive for extra risk","body":"Khi tài sản sát mức không đủ trả nợ, equity có cấu trúc payoff như call option; shareholders có thể ưa dự án rủi ro hơn vì downside bị giới hạn trong vốn còn lại, còn creditors chịu tổn thất.","trap":"Risk shifting can transfer value from debt to equity."},{"heading":"Asset substitution conflict","body":"Shareholders/management có thể thay assets ổn định bằng dự án biến động lớn sau khi vay nợ; lender không tham gia toàn bộ upside nhưng vẫn chịu default downside.","trap":"Covenants can restrict risky asset substitution."},{"heading":"Debt overhang / underinvestment","body":"Nếu doanh nghiệp có nợ quá lớn, một dự án NPV dương có thể chủ yếu đem lợi ích cho creditors, làm shareholders từ chối cấp vốn mới dù tổng firm value có thể tăng.","trap":"Underinvestment is a conflict distinct from risk shifting."},{"heading":"Dividend extraction conflict","body":"Shareholders có thể muốn rút cash dưới dạng dividend hoặc buyback trong khi lenders muốn duy trì liquidity và collateral, nhất là khi issuer gặp khó khăn.","trap":"Dividend restrictions are common covenants."},{"heading":"Leverage and risk premiums","body":"Debt tăng có thể khiến lenders đòi higher spreads và shareholders đòi higher required return, dù debt ban đầu rẻ hơn equity.","trap":"Average cost of debt need not remain constant as debt increases."},{"heading":"Stakeholder claims before dividends","body":"Trước discretionary dividends, doanh nghiệp cần đáp ứng chi phí suppliers, employees, taxes và các nghĩa vụ với bên thứ ba theo luật/hợp đồng.","trap":"Legal priority differs by jurisdiction; do not assume one ranking for all claims."},{"heading":"Economic versus financial balance sheet","body":"Financial balance sheet mô tả recognized assets/liabilities/equity, còn economic balance sheet nhận diện ảnh hưởng kinh tế đến suppliers, customers, people, community và environmental obligations.","trap":"An economic exposure is not necessarily a booked liability."},{"heading":"Preferred shares nuance","body":"Preferred shares có thể hưởng ưu tiên dividend/liquidation so với common nhưng thường vẫn là equity hoặc hybrid theo điều kiện cụ thể, không thể coi mọi preferred dividends là interest.","trap":"Check specific terms before classifying security."},{"heading":"Exam comparison checklist","body":"Để giải câu hỏi, phân biệt maturity, contractual payment, liquidation priority, voting, tax deductibility, return potential, risk to investor và risk to issuer.","trap":"One single characteristic rarely summarizes every debt/equity distinction."}],"formulas":[{"name":"Simple leverage share of financing","expr":"Debt ratio = debt / (debt + equity)","meaning":"Xác định tỷ trọng nợ theo capitalization trong ví dụ giản lược.","conditions":"Exclude nonfinancial liabilities when debt means interest-bearing debt."},{"name":"Equity residual value","expr":"Equity payoff = max(V − D, 0)","meaning":"Dạng payoff cổ đông trong mô hình một kỳ.","conditions":"Simplified debt face value and no bankruptcy/transaction costs."},{"name":"Lender recovery simplified","expr":"Debt payoff = min(V, D)","meaning":"Lender nhận tối đa số phải trả nếu chỉ có một class debt.","conditions":"Ignore senior claims and administrative costs."},{"name":"Financial leverage effect","expr":"ROE = Net income / beginning-or-average equity","meaning":"Tỷ suất lợi nhuận cổ đông.","conditions":"Time basis must be specified; average equity often used in analysis."},{"name":"ROA illustrative","expr":"ROA ≈ EBIT / assets (pre-interest operating proxy)","meaning":"So sánh khả năng sinh lời tài sản với chi phí nợ.","conditions":"EBIT/Assets is not necessarily reported after-tax ROA."},{"name":"Interest cost","expr":"Interest = principal × rate × time","meaning":"Dòng tiền theo hợp đồng giản lược.","conditions":"Simple rate and matched period."},{"name":"Income after interest and tax","expr":"NI = (EBIT − interest)×(1 − tax rate)","meaning":"Cho ví dụ lợi nhuận net dưới mô hình không có thu nhập khác.","conditions":"Applies when taxable income positive and tax shield usable."},{"name":"Interest tax shield","expr":"Tax saving ≈ deductible interest × corporate tax rate","meaning":"Minh họa lợi ích khấu trừ lãi.","conditions":"Deduction limits and sufficient taxable income assumed."},{"name":"Interest coverage","expr":"EBIT / interest expense","meaning":"Chỉ số earnings-based debt service coverage.","conditions":"Not cash flow coverage."},{"name":"Equity cash profit per unit invested","expr":"EPS return proxy = (NI / equity invested)×100%","meaning":"Ví dụ tác động leverage tới tỷ suất equity.","conditions":"Simplified one-period investment; not stock total return."},{"name":"Debt recovery rate","expr":"Recovery rate = lender cash recovered / contractual claim","meaning":"Khái niệm loss given default.","conditions":"Seniority, collateral and legal process may affect outcome."}],"examples":[{"question_en":"A firm has assets worth $120 million and one debt claim of $80 million. Compute the simplified residual equity value.","answer":"$40 million","steps_vi":["Theo mô hình residual: max(120−80,0).","Equity nhận 40 triệu USD sau debt; shareholder claim không cố định bằng toàn bộ asset value."],"check":"Single debt class simplified."},{"question_en":"A firm with $60 million of asset realization must repay $80 million of debt. Compute equity payoff in the simplified model.","answer":"$0","steps_vi":["Equity = max(60−80,0)=0.","Debt recovery là min(60,80)=60 triệu; deficit 20 triệu thuộc creditor exposure."],"check":"No additional claims assumed."},{"question_en":"An issuer has debt of $45 million and equity of $55 million. Calculate debt ratio using financial capital.","answer":"45%","steps_vi":["Debt share=45/(45+55).","Tỷ trọng nợ 45% trên invested debt-plus-equity."],"check":"Does not include trade payables."},{"question_en":"An issuer borrows $2 million at 6% simple annual interest. What is annual promised interest?","answer":"$120,000","steps_vi":["Interest =2m×0,06.","Lender được promised 120.000 USD dù earnings giảm."],"check":"Contract obligations apply."},{"question_en":"A firm has EBIT of $15 million and interest expense of $3 million. Calculate interest coverage.","answer":"5.0×","steps_vi":["EBIT/Interest=15/3=5.","Chỉ số dựa trên earnings; không bảo đảm cash conversion."],"check":"Higher is generally more cushion."},{"question_en":"A firm reports EBIT $10 million and interest $2 million, with a 25% corporate income tax. Calculate simplified net income.","answer":"$6 million","steps_vi":["Taxable income=10−2=8m; tax=2m.","NI=8m−2m=6m trong mô hình thuế tuyến tính."],"check":"No other income/costs."},{"question_en":"Compare two issuers with identical EBIT $12m and assets $100m. All-equity firm has no interest and $100m equity; levered firm has $60m debt at 5% and $40m equity; ignore tax. Which has higher ROE?","answer":"Levered firm: 22.5% vs 12%","steps_vi":["Với doanh nghiệp không vay nợ: ROE=12/100=12%. Công ty vay 60 triệu USD phải trả 60×5%=3 triệu USD lãi.","Levered ROE=(12−3)/40=22,5% so long as EBIT meets assumptions."],"check":"Leverage raises both risk and potential ROE."},{"question_en":"Same firms as above but EBIT falls to $2 million. Which firm has lower ROE?","answer":"Levered firm: −2.5% vs 2%","steps_vi":["Lãi vay vẫn cố định 3 triệu USD trong khi EBIT chỉ 2 triệu; thu nhập sau lãi của doanh nghiệp dùng nợ là âm 1 triệu.","Levered ROE=−1/40=−2,5%, lower than all-equity 2/100=2%."],"check":"Fixed financing cost worsens downside."},{"question_en":"A debt contract promises $100 million. If total firm assets are $140 million in a one-claim simplified model, what is lender payoff?","answer":"$100 million","steps_vi":["Debt payoff=min(140,100).","Lender không được thêm 40m chỉ vì firm value tăng."],"check":"Upside capped under plain debt."},{"question_en":"A loan of $50 million incurs tax-deductible interest of $4 million and issuer tax rate is 25%. Estimate tax shield.","answer":"$1 million","steps_vi":["Interest tax saving≈4m×0,25.","Tax shield 1m nếu đủ taxable income và expense deductible."],"check":"Tax shield may not be fully usable."},{"question_en":"A firm distributes no cash dividends despite high profit but pays its contractual bond interest. Is absence of dividends itself a debt default?","answer":"No","steps_vi":["Dividends normally discretionary, interest contractual.","Việc không chia cổ tức thường không vi phạm bond contract; vẫn phải trả debt đúng hạn."],"check":"Distinguish equity payments from covenants."},{"question_en":"A troubled issuer has $15m of proceeds and owes one creditor $20m. What is the creditor's recovery rate under the one-creditor model?","answer":"75%","steps_vi":["Tỷ lệ thu hồi của creditor=15/20=75%. Phần thiếu hụt là 25%; cổ đông nhận zero trong mô hình đơn giản.","Creditor shortfall 25%; common equity receives zero."],"check":"Actual secured/unsecured ranking ignored."}],"questions":[{"stem_en":"Which claim is normally residual after contractual and legally senior obligations?","options":["Common equity.","Senior secured debt.","Corporate income taxes."],"correct":0,"why_vi":"Common shareholders chỉ hưởng phần dư sau creditor claims và các nghĩa vụ ưu tiên.","trap_vi":"A share is not a loan."},{"stem_en":"From an issuer's perspective, which financing source creates a fixed contractual payment requirement?","options":["Common equity.","Debt.","Retained earnings."],"correct":1,"why_vi":"Debt yêu cầu interest/principal theo lịch, nên tăng issuer financial distress risk.","trap_vi":"Equity distributions are generally discretionary."},{"stem_en":"From an investor's perspective, plain debt compared with common equity usually offers:","options":["Ownership voting in board elections.","Unlimited participation in firm growth.","A higher liquidation priority."],"correct":2,"why_vi":"Lenders có priority claim, nhưng contracted upside bị giới hạn theo terms.","trap_vi":"High priority does not mean no default risk."},{"stem_en":"Which of the following best describes shareholders' capital in an ordinary corporation?","options":["Indefinite financing with no promised repayment schedule.","Capital that matures every year.","Guaranteed annual dividends."],"correct":0,"why_vi":"Common equity không có maturity hoặc repayment promise tương tự debt.","trap_vi":"Dividends are not bond coupons."},{"stem_en":"Which expense is typically deductible in computing corporate taxable income?","options":["Dividends to shareholders.","Interest on eligible debt.","Shareholder capital contribution."],"correct":1,"why_vi":"Lãi vay đáp ứng điều kiện thường được deduct, dividends thường không.","trap_vi":"Jurisdiction-specific limits apply."},{"stem_en":"A firm's EBIT is unchanged, but it replaces equity with more fixed-interest debt. The most direct effect is:","options":["A guarantee that ROE increases.","Elimination of shareholder risk.","Greater sensitivity of ROE to operating results."],"correct":2,"why_vi":"Interest cố định làm return of smaller equity base biến động mạnh hơn khi EBIT thay đổi.","trap_vi":"Leverage can reduce ROE in bad states."},{"stem_en":"A shareholder owns common stock and has signed no personal debt guarantee. The shareholder's usual maximum loss is:","options":["The amount invested in the shares.","Unlimited personal assets.","The market value of all corporate debt."],"correct":0,"why_vi":"Limited liability giới hạn exposure shareholder thông thường ở invested equity capital.","trap_vi":"Extra personal guarantees are exceptions."},{"stem_en":"If firm asset value is below plain outstanding debt and no other claims exist, equity payoff is:","options":["The debt face amount.","Zero.","The entire asset value."],"correct":1,"why_vi":"Công thức payoff residual=max(V−D,0). Khi giá trị tài sản thấp hơn nợ, cổ đông không còn phần dư.","trap_vi":"Equity cannot claim ahead of debt."},{"stem_en":"A lender's promised payoff on ordinary fixed debt normally has:","options":["Unlimited upside when profits rise.","No maximum contractual amount.","A contractual cap even if assets appreciate greatly."],"correct":2,"why_vi":"Payoff capped at contractual payments, trong khi equity hưởng residual upside.","trap_vi":"Convertible debt may differ."},{"stem_en":"Asset substitution risk is most directly a conflict in which:","options":["Shareholders pursue riskier assets after borrowing.","Lenders automatically elect all directors.","Suppliers receive stock dividends."],"correct":0,"why_vi":"Equity có thể hưởng upside từ high-volatility assets còn creditors gánh thêm default risk.","trap_vi":"Contrast with debt overhang."},{"stem_en":"Debt overhang is likely when:","options":["The company has no borrowing obligations.","Shareholders reject a positive-NPV project because most gains accrue to creditors.","Lenders receive residual upside beyond contracts."],"correct":1,"why_vi":"Nợ cũ quá cao có thể làm dự án tốt không hấp dẫn đối với existing equity holders.","trap_vi":"This differs from choosing excessive risk."},{"stem_en":"Which action would a distressed firm's creditor most likely seek to restrict?","options":["Timely interest payments.","Maintaining collateral.","Unusually large cash dividends to shareholders."],"correct":2,"why_vi":"Dividends có thể làm giảm assets/liquidity hỗ trợ recovery của creditors.","trap_vi":"Lenders may negotiate covenants."},{"stem_en":"A board declares no dividend, even though net income is positive. This is:","options":["Potentially consistent with ordinary equity financing.","A mandatory principal prepayment.","Automatically an interest default."],"correct":0,"why_vi":"Không có contractual dividend requirement thông thường cho common equity.","trap_vi":"Earnings and distributions are distinct."},{"stem_en":"A company's EBIT is $9m and interest expense is $3m. Its interest coverage is closest to:","options":["0.33×.","3.0×.","6.0×."],"correct":1,"why_vi":"9/3=3 lần coverage, dựa trên EBIT không phải cash balance.","trap_vi":"Do not subtract interest twice."},{"stem_en":"Which group generally elects the board of directors?","options":["All bondholders, regardless of covenants.","Every supplier.","Common shareholders exercising voting rights."],"correct":2,"why_vi":"Voting rights thuộc các equity class có quyền biểu quyết, board oversee management.","trap_vi":"A debt covenant is not a vote."},{"stem_en":"Which statement about a firm's debt and equity is most accurate?","options":["Debt is typically cheaper but increases issuer default risk.","Debt is always safer than equity for the issuing company.","Equity is always a cheaper funding source than debt."],"correct":0,"why_vi":"Debt cost thấp hơn một phần do investor priority và interest tax shield; phải trả lãi/principal làm issuer rủi ro hơn.","trap_vi":"Separate issuer and investor perspectives."},{"stem_en":"A firm's assets are worth $95m; one debt claim is $75m. Equity's simplified payoff is closest to:","options":["$95m.","$20m.","$75m."],"correct":1,"why_vi":"Equity residual=max(95−75,0)=20 triệu USD; creditors có contractual claim tối đa 75 triệu USD.","trap_vi":"No legal seniority complications."},{"stem_en":"With $90m in assets and $120m of one debt claim, the lender's simplified recovery is:","options":["$120m.","$30m.","$90m."],"correct":2,"why_vi":"min(90,120)=90m; lender mất 30m, equity zero.","trap_vi":"Do not confuse face claim with actual recovery."},{"stem_en":"In a shareholder–creditor conflict, shareholders most likely prefer:","options":["A sufficiently risky investment that transfers downside to debtholders.","Zero possible share-price upside.","Guaranteed protection of existing lender value at any cost."],"correct":0,"why_vi":"Limited downside và unlimited residual upside có thể tạo incentive nhận rủi ro vượt optimal total value.","trap_vi":"This is not a guarantee of investor rationality."},{"stem_en":"Why can a lender charge a lower required return than common shareholders in the same issuer?","options":["The lender owns the entire corporation.","The lender has priority and fixed contractual claims.","Corporate profits are guaranteed."],"correct":1,"why_vi":"Priority claim và limited contractual upside làm loan thường ít rủi ro hơn common stock cùng issuer.","trap_vi":"Rating and security details matter."}],"cards":[{"front_en":"Explain: Contractual debt claims","back_vi":"Lenders cung cấp vốn trong thời hạn xác định. Issuer cam kết trả lãi và principal theo hợp đồng; nghĩa vụ thanh toán không phụ thuộc việc ban quản trị có muốn chi trả hay không."},{"front_en":"Explain: Permanent equity capital","back_vi":"Shareholders cung cấp equity vốn thường không có maturity và issuer không buộc hoàn trả giá mua cổ phiếu; cổ đông hưởng residual cash flows sau các khoản có ưu tiên."},{"front_en":"Explain: Priority in liquidation","back_vi":"Khi thanh lý, secured creditors, các claims theo luật và unsecured lenders được xử lý theo ưu tiên liên quan; common equity chỉ nhận phần còn lại nếu đủ tài sản."},{"front_en":"Explain: Residual payoff","back_vi":"Equity payoff tăng cùng residual firm value sau khi trừ debt claims; upside có thể lớn trong khi tối đa loss của shareholder thông thường là phần vốn bỏ ra khi không bảo lãnh riêng."},{"front_en":"Explain: Finite versus indefinite term","back_vi":"Debt thường có thời hạn xác định dù dài; common stock không có maturity. Một công ty có thể refinance debt chứ debt không tự biến thành perpetual capital."},{"front_en":"Explain: Investor risk–return ranking","back_vi":"Từ góc nhìn người đầu tư vào cùng một issuer và cấu trúc ưu tiên, creditors thường chấp nhận lợi suất thấp hơn để đổi lấy priority; equity holders gánh nhiều downside trước và đòi return cao hơn."},{"front_en":"Explain: Issuer financing risk","back_vi":"Với issuer, debt tạo nghĩa vụ trả lãi/principal và rủi ro default/financial distress; equity không buộc trả theo lịch, nên equity ít tạo financial distress từ contractual payments."},{"front_en":"Explain: Fixed upside of debt investors","back_vi":"Payoff của lender thường bị giới hạn bởi promised interest + principal theo hợp đồng; nếu công ty phát đạt hơn dự tính thì lợi ích vượt trội thường thuộc equity."},{"front_en":"Explain: Equity voting and control","back_vi":"Common shareholders thường có quyền bầu board, trong khi lenders không trực tiếp tham gia vận hành nhưng có covenants, collateral và enforcement rights."},{"front_en":"Explain: Dividends at board discretion","back_vi":"Dividend thường do board quyết định, phụ thuộc earnings, cash, pháp luật và policies. Không chia cổ tức không tự động cấu thành default như bỏ qua contractual debt payment."},{"front_en":"Explain: Interest tax deductibility","back_vi":"Interest expense thường được trừ khi tính taxable corporate income, còn dividends không phải expense được trừ, làm debt có lợi thế tax shield."},{"front_en":"Explain: Financial leverage and ROE","back_vi":"Debt financing làm equity vốn bỏ ra nhỏ hơn cho cùng assets; khi operating return cao hơn cost of debt, ROE của equity có thể tăng, nhưng khi earnings giảm thì loss cũng được khuếch đại."},{"front_en":"Explain: Return on assets versus cost of debt","back_vi":"Trực giác leverage: nếu after/pretax return từ assets cao hơn marginal financing cost đồng bộ với cơ sở thuế, sử dụng nợ có thể nâng return cho equity; ngược lại debt có thể làm ROE giảm."},{"front_en":"Explain: Interest coverage intuition","back_vi":"EBIT / interest expense đo earnings hoạt động trước lãi có đủ bao phủ coupon không; chỉ số giảm khi chi phí lãi tăng hoặc EBIT giảm."},{"front_en":"Explain: Equity default threshold","back_vi":"Trong mô hình đơn giản V là firm asset value, D là debt due: equity còn giá trị khi V>D; nếu V<=D thì payoff cho equity bằng zero."},{"front_en":"Explain: Shareholders' incentive for extra risk","back_vi":"Khi tài sản sát mức không đủ trả nợ, equity có cấu trúc payoff như call option; shareholders có thể ưa dự án rủi ro hơn vì downside bị giới hạn trong vốn còn lại, còn creditors chịu tổn thất."},{"front_en":"Explain: Asset substitution conflict","back_vi":"Shareholders/management có thể thay assets ổn định bằng dự án biến động lớn sau khi vay nợ; lender không tham gia toàn bộ upside nhưng vẫn chịu default downside."},{"front_en":"Explain: Debt overhang / underinvestment","back_vi":"Nếu doanh nghiệp có nợ quá lớn, một dự án NPV dương có thể chủ yếu đem lợi ích cho creditors, làm shareholders từ chối cấp vốn mới dù tổng firm value có thể tăng."},{"front_en":"Explain: Dividend extraction conflict","back_vi":"Shareholders có thể muốn rút cash dưới dạng dividend hoặc buyback trong khi lenders muốn duy trì liquidity và collateral, nhất là khi issuer gặp khó khăn."},{"front_en":"Explain: Leverage and risk premiums","back_vi":"Debt tăng có thể khiến lenders đòi higher spreads và shareholders đòi higher required return, dù debt ban đầu rẻ hơn equity."},{"front_en":"Explain: Stakeholder claims before dividends","back_vi":"Trước discretionary dividends, doanh nghiệp cần đáp ứng chi phí suppliers, employees, taxes và các nghĩa vụ với bên thứ ba theo luật/hợp đồng."},{"front_en":"Explain: Economic versus financial balance sheet","back_vi":"Financial balance sheet mô tả recognized assets/liabilities/equity, còn economic balance sheet nhận diện ảnh hưởng kinh tế đến suppliers, customers, people, community và environmental obligations."},{"front_en":"Explain: Preferred shares nuance","back_vi":"Preferred shares có thể hưởng ưu tiên dividend/liquidation so với common nhưng thường vẫn là equity hoặc hybrid theo điều kiện cụ thể, không thể coi mọi preferred dividends là interest."},{"front_en":"Explain: Exam comparison checklist","back_vi":"Để giải câu hỏi, phân biệt maturity, contractual payment, liquidation priority, voting, tax deductibility, return potential, risk to investor và risk to issuer."}]},{"id":"CFA26-03-02-LOS02","letter":"2.b","title_en":"Corporate Stakeholders and Shareholder versus Stakeholder Theory","outcome_en":"describe a company’s stakeholder groups and compare their interests","overview_vi":"Phân tích mục tiêu shareholders, lenders, board, management, employees, suppliers, customers, governments, communities, môi trường; so sánh shareholder theory và stakeholder theory, nhận diện xung đột và cơ chế hài hòa.","source":[{"id":"CFA Institute Curriculum 2026 — Corporate Issuers LM2","pages":"56–62 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading21","pages":"232–234 (physical PDF)"},{"id":"SAPP Corporate Issuers 2026 — Module2","pages":"51–56 (physical PDF)"}],"sections":[{"heading":"Definition of stakeholders","body":"Stakeholders là cá nhân/nhóm có interests chịu ảnh hưởng hoặc tác động đến hoạt động và thành công của corporate issuer. Phạm vi rộng hơn shareholders và debt investors.","trap":"Stakeholder is not synonymous with shareholder."},{"heading":"Shareholder theory","body":"Shareholder theory ưu tiên tạo financial value cho owners trong khuôn khổ nghĩa vụ pháp lý và các quy tắc, xem value creation là tiêu chí trung tâm.","trap":"Not a license for fraud or violation of contracts."},{"heading":"Stakeholder theory","body":"Stakeholder theory yêu cầu management xét tới outcomes cho nhiều nhóm: creditors, staff, clients, suppliers, society và môi trường bên cạnh equity holders.","trap":"It need not reject long-term shareholder value."},{"heading":"Long-term alignment","body":"Trả lương công bằng, giữ khách hàng và tuân thủ pháp luật có thể bảo vệ cash flows, reputation và shareholder value lâu dài.","trap":"The theories are not always in conflict."},{"heading":"Trade-offs among claims","body":"Nguồn cash của công ty hữu hạn, tăng dividend ngắn hạn có thể hạn chế liquidity cho creditors, worker investment hoặc suppliers, tạo đánh đổi.","trap":"Trade-offs vary by horizon and firm circumstances."},{"heading":"Common shareholders","body":"Equity holders quan tâm total return, residual earnings, governance rights, business strategy và risk; một controlling shareholder có lợi ích khác minority holders.","trap":"Different share classes can carry different votes."},{"heading":"Debtholders and lenders","body":"Creditors ưu tiên trả nợ đúng hạn, bảo toàn collateral, covenant compliance và downside risk; không hưởng toàn bộ upside vượt contracted claims.","trap":"Financial covenant breaches can change creditor influence."},{"heading":"Board of directors","body":"Board được shareholders bầu, oversee strategy, risk, manager appointment và integrity of reporting; board members cũng có fiduciary duties theo luật.","trap":"Board does not normally run daily sales operations."},{"heading":"Managers and executives","body":"Management tìm compensation, career progression, performance rewards, discretion và job security; mục tiêu có thể lệch owners, tạo principal-agent conflict.","trap":"Manager interests cannot be assumed identical to shareholders."},{"heading":"Employees","body":"Workers quan tâm stable wages, safety, benefits, training, equitable treatment và job security; turnover/labor disputes ảnh hưởng productivity.","trap":"Employees are not always equity holders."},{"heading":"Customers","body":"Customers muốn quality, fairness, safety, reliable supply và privacy of data; consumer trust là asset cạnh tranh dù không nhất thiết ghi nhận trên balance sheet.","trap":"A low price alone does not resolve product-safety concerns."},{"heading":"Suppliers","body":"Suppliers quan tâm timely payment, predictable purchasing, credit quality và durable commercial relationships; họ có thể là creditors ngắn hạn qua trade payables.","trap":"Suppliers are not automatically shareholders."},{"heading":"Governments and regulators","body":"Governments quan tâm tax, labor/environmental compliance, competition và economic development; regulators có thể impose penalties và reporting obligations.","trap":"Government objectives are broader than dividend returns."},{"heading":"Communities and society","body":"Local community chịu ảnh hưởng từ employment, infrastructure, pollution, public health, resource use; loss of social license to operate có thể giảm giá trị issuer.","trap":"Externalities can become financial costs."},{"heading":"Environment as affected interest","body":"Natural resources, biodiversity, carbon emissions và waste có thể tạo exposure cho issuer dù môi trường không trực tiếp ký hợp đồng.","trap":"This is part of broad stakeholder analysis."},{"heading":"Investor stakeholder spectrum","body":"Một số investors ưu tiên financial materiality, một số đồng thời có ethical/impact goals; cần phân biệt objectives với actual financial consequences.","trap":"Do not assume every ESG preference improves short-run returns."},{"heading":"Conflict: labor versus owners","body":"Wage increases có thể nâng retention/morale, nhưng cũng tăng near-term cost và giảm profit nếu không tạo productivity offset.","trap":"Labor spending is neither always good nor always bad."},{"heading":"Conflict: suppliers versus liquidity","body":"Kéo dài thời hạn phải trả có thể tăng issuer cash availability nhưng gây cash-flow pressure cho suppliers, thậm chí tăng purchasing price/risk.","trap":"Improving DPO is not a free lunch."},{"heading":"Conflict: customers versus margins","body":"Giảm chất lượng để cắt cost có thể nâng short-run margin nhưng tạo recall, liability và reputational damage.","trap":"A temporary earnings increase may destroy value."},{"heading":"Conflicts among shareholders","body":"Controlling holders có thể thích transactions với affiliated parties, trong khi minority shareholders muốn arm's-length pricing và fair treatment.","trap":"Owning equity does not ensure uniform incentives."},{"heading":"Risk sharing and governance","body":"Contracts, independent directors, disclosure, compensation design, compliance và dialogue giúp phân bổ trách nhiệm và giảm agency conflicts.","trap":"No mechanism eliminates all conflicts."},{"heading":"Stakeholder-specific information","body":"Analysts dùng annual reports, proxy reports, sustainability data, customer retention, labor incidents, leverage ratios và public filings để hiểu stakeholder exposure.","trap":"A single narrative claim is not verification."},{"heading":"Economic obligations versus accounting liabilities","body":"Một issuer có ảnh hưởng đến air/water quality, employee trust hoặc customer privacy mà chưa phải ghi recognized liability; economic consequence vẫn có thể material.","trap":"Do not call every social exposure a balance-sheet provision."},{"heading":"Exam scenario mapping","body":"Khi đọc case, xác định stakeholder bị tác động, claim/expectation chính, horizon và trade-off; chọn explanation dựa trên objective chứ không chỉ danh xưng.","trap":"Stakeholders' goals can overlap or oppose depending on scenario."}],"formulas":[{"name":"Stakeholder mapping","expr":"Interest group → preferred outcome → sources of conflict → mitigation","meaning":"Khung đánh giá một nhóm stakeholder.","conditions":"Qualitative tool, not a CFAI computational formula."},{"name":"Shareholder value and broader effects","expr":"Long-term value may depend on customer trust + human capital + compliance + financial claims","meaning":"Liên kết tác động dài hạn từ nonfinancial interests.","conditions":"Illustrative conceptual relationship only."},{"name":"Liquidity available before dividends","expr":"Cash available to equity after senior obligations = discretionary residual cash","meaning":"Tư duy ưu tiên obligation.","conditions":"Not a standardized free-cash-flow formula."},{"name":"Supplier trade credit","expr":"Accounts payable = purchased goods/services not yet paid","meaning":"Suppliers có thể là creditors ngắn hạn.","conditions":"Accounting classification varies."},{"name":"Stakeholder conflict heatmap","expr":"Risk = likelihood × severity (qualitative ranking)","meaning":"Xác định ưu tiên giám sát các nhóm lợi ích.","conditions":"Author-created framework; not official CFAI formula."},{"name":"Human capital turnover","expr":"Staff turnover rate = departures / average workforce ×100%","meaning":"Chỉ báo exposure lao động.","conditions":"Supplemental illustration beyond LOS core."}],"examples":[{"question_en":"Employees demand better safety equipment after repeated accidents. Identify the primary stakeholders and likely shared long-run interest.","answer":"Employees and shareholders; fewer incidents can support long-run value","steps_vi":["Employees cần workplace safety và job security; shareholders cần operations không bị interrupted.","Safety investment tăng cost trước mắt nhưng có thể giảm litigation, downtime và turnover về sau."],"check":"Stakeholder objectives can align across time."},{"question_en":"A supplier offers 60-day credit but an issuer delays payment to 120 days without agreement. What stakeholder conflict arises?","answer":"Issuer liquidity versus supplier cash flow","steps_vi":["Issuer giữ cash lâu hơn, suppliers phải tài trợ trade receivables dài hơn.","Thời hạn trả kéo dài có thể hại supplier relationship hoặc tăng future supply costs."],"check":"Trade payable is a financing claim."},{"question_en":"A firm cuts product testing to improve this quarter's margin, then faces a major recall. Which stakeholder was initially exposed?","answer":"Customers","steps_vi":["Testing giảm làm tăng product safety risk đối với buyers.","Financial consequence có thể đến muộn dưới dạng lawsuits, recalls và lost trust."],"check":"Short-run profit differs from long-run value."},{"question_en":"A shareholder wants to maximize dividends while a bank requires liquidity reserves. Which two groups are in conflict?","answer":"Shareholders and lenders","steps_vi":["Equity holders muốn distribution còn creditors muốn giữ assets để bảo đảm debt service.","Covenant có thể quy định minimum liquidity hoặc limit dividends."],"check":"Priority claims matter."},{"question_en":"An enterprise employs 500 workers; 35 workers leave in a year and average employment is 500. Estimate workforce turnover rate.","answer":"7%","steps_vi":["Turnover=35/500×100%.","7% là chỉ báo human capital, không phải tự nó chứng minh workplace quality tốt hay xấu."],"check":"Illustrative supplemental metric."},{"question_en":"A minority investor discovers the founding family sells services to the firm at inflated prices. Who may benefit and who bears costs?","answer":"Controlling family benefits; minority shareholders bear value loss","steps_vi":["Related-party transaction làm transfer value ra khỏi public issuer.","Transparent arm's-length approval có thể giảm conflict."],"check":"Controlling owners are stakeholders with distinct incentives."},{"question_en":"A customer data breach triggers fines and customer attrition. Which stakeholders are directly affected?","answer":"Customers, regulators, and shareholders","steps_vi":["Customers mất privacy; regulator xử phạt; firm mất revenue/reputation.","External impact có thể chuyển thành quantifiable financial cost."],"check":"ESG risks can be financially material."},{"question_en":"An issuer improves energy efficiency and lowers utility bills. Can shareholder and stakeholder goals align?","answer":"Yes","steps_vi":["Environment hưởng lợi qua less resource use và shareholders hưởng lower operating expenses.","Tác động phụ thuộc cost đầu tư và expected savings."],"check":"Not all green projects have positive NPV."},{"question_en":"A board independently reviews management pay. Which relationship is being addressed?","answer":"Shareholders versus managers","steps_vi":["Board oversee executive incentives để hạn chế managers tối đa hóa private benefits.","Independent review có thể tăng alignment nhưng không loại hết agency costs."],"check":"Agency relationship needs monitoring."},{"question_en":"A local community opposes a new factory due to pollution concerns. Does the community qualify as a stakeholder despite owning no shares?","answer":"Yes","steps_vi":["Community chịu externalities từ operations dù không trực tiếp tài trợ vốn.","Regulatory response và protests có thể ảnh hưởng project approval."],"check":"Stakeholder beyond investors."},{"question_en":"A business pays all its bills but earns below shareholders' required return. Which stakeholder objective may still be unmet?","answer":"Equity owners' required financial return","steps_vi":["Legal/contractual obligations paid không bảo đảm project tạo economic profit cho shareholders.","Shareholder theory cần value creation lâu dài, không chỉ compliance."],"check":"Different claims create distinct objectives."},{"question_en":"A firm restructures working hours to retain skilled staff, accepting temporary lower profits. How should analysts assess it?","answer":"Compare long-term retention and productivity benefits with the near-term cost","steps_vi":["Chi phí ngắn hạn cần so với expected avoided turnover và output gains.","Stakeholder policy có thể tạo financial materiality, cần bằng chứng định lượng."],"check":"No automatic value uplift."},{"question_en":"A company increases charitable contributions but breaches a loan covenant. Which priority should not be ignored?","answer":"Contractual lender obligations","steps_vi":["Community objectives không xóa trách nhiệm thực hiện financial covenants.","Corporate stakeholder theory vẫn xem contractual claims và legal obligations là ràng buộc."],"check":"Stakeholder theory is not debt forgiveness."}],"questions":[{"stem_en":"Which group is not required to own stock to be a corporate stakeholder?","options":["Employees.","Common shareholders.","Preferred shareholders."],"correct":0,"why_vi":"Employees ảnh hưởng và chịu ảnh hưởng bởi operations dù không sở hữu equity.","trap_vi":"Stakeholders extend beyond security holders."},{"stem_en":"Shareholder theory most directly prioritizes:","options":["Balancing every preference equally at all times.","Maximizing long-term shareholder economic value within legal constraints.","Eliminating all nonshareholder interests."],"correct":1,"why_vi":"Shareholder theory đặt equity value làm objective trung tâm nhưng không miễn trừ contracts/laws.","trap_vi":"Legal obligations still apply."},{"stem_en":"Stakeholder theory expands management's focus to:","options":["Only existing lenders.","Only shareholders.","Multiple affected groups and their interests."],"correct":2,"why_vi":"Stakeholder approach xét society, workers, clients, creditors, environment và equity.","trap_vi":"Broader is not necessarily anti-profit."},{"stem_en":"A factory accident causes employee injury and costly shutdowns. Which statement is most accurate?","options":["Employees and investors may both face losses.","The issue is unrelated to firm performance.","Only employees are affected."],"correct":0,"why_vi":"Human safety failure có thể gây financial harm qua shutdown, fines, liability, reputation.","trap_vi":"Stakeholder outcomes can affect valuation."},{"stem_en":"Suppliers most often seek:","options":["Guaranteed stock price appreciation.","Timely payment for supplied goods and services.","Unrestricted power to appoint the CEO."],"correct":1,"why_vi":"Suppliers chịu receivable risk và cần consistent payment terms.","trap_vi":"Suppliers may be trade creditors."},{"stem_en":"A regulator is most concerned with:","options":["Immediate dividend maximization.","Management's private consumption.","Compliance with applicable law and market rules."],"correct":2,"why_vi":"Regulator thực thi rules về tax, labor, environment, market fairness.","trap_vi":"Government is not equivalent to shareholder."},{"stem_en":"Which governance body commonly oversees executive management?","options":["The board of directors.","Product customers.","The firm's trade suppliers."],"correct":0,"why_vi":"Board đại diện quyền quản trị của shareholders và monitor executives.","trap_vi":"Board does not usually supervise each transaction."},{"stem_en":"Employees generally value:","options":["Only a share split.","Workplace safety, pay, and career development.","Only the lender's recovery rate."],"correct":1,"why_vi":"Human capital và employee welfare là stakeholder objectives.","trap_vi":"Staff may care about issuer solvency too."},{"stem_en":"A company deliberately reduces customer privacy protections to save costs. The most immediate stakeholder concern is:","options":["Bond maturity shortening.","Tax shield reduction.","Customer data protection."],"correct":2,"why_vi":"Customer privacy là social exposure, có thể biến thành fines và lost loyalty.","trap_vi":"Qualitative harm can become measurable cost."},{"stem_en":"A local neighborhood impacted by industrial waste is:","options":["A stakeholder even without investment ownership.","Necessarily a senior secured creditor.","Outside all stakeholder definitions."],"correct":0,"why_vi":"Community chịu environmental externalities nên là stakeholder.","trap_vi":"Direct ownership is not required."},{"stem_en":"Controlling shareholders and minority holders may disagree over:","options":["Whether products have prices.","Related-party transactions and voting power.","Whether debt has a stated maturity."],"correct":1,"why_vi":"Control group có thể extract private benefits làm minority chịu value loss.","trap_vi":"Shareholders are not homogeneous."},{"stem_en":"An issuer delays all supplier payments to raise cash temporarily. The most likely trade-off is:","options":["Guaranteed lower long-term procurement costs.","Automatic improvement in credit rating.","Supplier financial stress and potential relationship damage."],"correct":2,"why_vi":"Kéo dài thời hạn thanh toán giữ tiền tại issuer, nhưng làm supplier phải tài trợ vốn lưu động lâu hơn và có thể yêu cầu giá cao hơn.","trap_vi":"Liquidity optimization has externalities."},{"stem_en":"Which statement best compares shareholder and stakeholder frameworks?","options":["They can align through long-run value creation.","They necessarily demand opposite outcomes in every decision.","Both ignore creditors."],"correct":0,"why_vi":"Better governance/safety/customer trust có thể tăng long-term value đồng thời lợi broader groups.","trap_vi":"Their priorities can still diverge."},{"stem_en":"A company's CFO proposes unsafe labor conditions to boost quarterly earnings. A stakeholder analysis would most likely:","options":["Ignore workers because they lack shares.","Consider worker safety and possible long-term costs.","Treat quarterly accounting earnings as the only outcome."],"correct":1,"why_vi":"Stakeholder lens nhìn human capital và potential financial materiality của injury/litigation.","trap_vi":"Immediate profit may hide contingent risk."},{"stem_en":"An independent director challenges management's excessive compensation. The primary conflict being mitigated is:","options":["Consumers versus regulators.","Suppliers versus communities.","Manager self-interest versus owner interests."],"correct":2,"why_vi":"Oversight chống private benefits of control/compensation.","trap_vi":"Agency monitoring is imperfect."},{"stem_en":"A bank insists on maintaining interest coverage before dividends. The bank is most directly protecting:","options":["Contractual lender recovery capacity.","Equity voting rights.","Employee training budgets."],"correct":0,"why_vi":"Banker giữ debt service cushion, nhất là ở leveraged issuer.","trap_vi":"Lenders have different incentives."},{"stem_en":"Which pair of stakeholders can both benefit from lower energy waste?","options":["Only competing firms and speculators.","Environment and shareholders.","Only bondholders and tax authorities."],"correct":1,"why_vi":"Efficiency vừa giảm resource consumption vừa có thể giảm energy costs.","trap_vi":"Verify project economics before assuming net benefit."},{"stem_en":"A company faces a boycott due to harmful products. The primary transmission to investors is through:","options":["A legal guarantee that bond prices rise.","An increase in share count automatically.","Potential lost sales, liabilities, and reputational damage."],"correct":2,"why_vi":"Customer/community concerns có thể ảnh hưởng cash flows và required returns.","trap_vi":"Financial effects are conditional."},{"stem_en":"A company's owners and executives differ about investment horizon. This is best described as:","options":["A potential agency conflict.","A currency arbitrage.","A cash conversion identity."],"correct":0,"why_vi":"Principal and agent có thể có risk/horizon incentives khác nhau.","trap_vi":"Stakeholder groups include management."},{"stem_en":"Compared with a shareholder-only focus, a broad stakeholder review most likely adds:","options":["Guaranteed agreement among all groups.","Community and employee impacts.","Exclusion of all financial claims."],"correct":1,"why_vi":"Stakeholder framework xét thêm nonfinancial groups và trade-offs.","trap_vi":"It does not erase shareholder return analysis."}],"cards":[{"front_en":"Explain: Definition of stakeholders","back_vi":"Stakeholders là cá nhân/nhóm có interests chịu ảnh hưởng hoặc tác động đến hoạt động và thành công của corporate issuer. Phạm vi rộng hơn shareholders và debt investors."},{"front_en":"Explain: Shareholder theory","back_vi":"Shareholder theory ưu tiên tạo financial value cho owners trong khuôn khổ nghĩa vụ pháp lý và các quy tắc, xem value creation là tiêu chí trung tâm."},{"front_en":"Explain: Stakeholder theory","back_vi":"Stakeholder theory yêu cầu management xét tới outcomes cho nhiều nhóm: creditors, staff, clients, suppliers, society và môi trường bên cạnh equity holders."},{"front_en":"Explain: Long-term alignment","back_vi":"Trả lương công bằng, giữ khách hàng và tuân thủ pháp luật có thể bảo vệ cash flows, reputation và shareholder value lâu dài."},{"front_en":"Explain: Trade-offs among claims","back_vi":"Nguồn cash của công ty hữu hạn, tăng dividend ngắn hạn có thể hạn chế liquidity cho creditors, worker investment hoặc suppliers, tạo đánh đổi."},{"front_en":"Explain: Common shareholders","back_vi":"Equity holders quan tâm total return, residual earnings, governance rights, business strategy và risk; một controlling shareholder có lợi ích khác minority holders."},{"front_en":"Explain: Debtholders and lenders","back_vi":"Creditors ưu tiên trả nợ đúng hạn, bảo toàn collateral, covenant compliance và downside risk; không hưởng toàn bộ upside vượt contracted claims."},{"front_en":"Explain: Board of directors","back_vi":"Board được shareholders bầu, oversee strategy, risk, manager appointment và integrity of reporting; board members cũng có fiduciary duties theo luật."},{"front_en":"Explain: Managers and executives","back_vi":"Management tìm compensation, career progression, performance rewards, discretion và job security; mục tiêu có thể lệch owners, tạo principal-agent conflict."},{"front_en":"Explain: Employees","back_vi":"Workers quan tâm stable wages, safety, benefits, training, equitable treatment và job security; turnover/labor disputes ảnh hưởng productivity."},{"front_en":"Explain: Customers","back_vi":"Customers muốn quality, fairness, safety, reliable supply và privacy of data; consumer trust là asset cạnh tranh dù không nhất thiết ghi nhận trên balance sheet."},{"front_en":"Explain: Suppliers","back_vi":"Suppliers quan tâm timely payment, predictable purchasing, credit quality và durable commercial relationships; họ có thể là creditors ngắn hạn qua trade payables."},{"front_en":"Explain: Governments and regulators","back_vi":"Governments quan tâm tax, labor/environmental compliance, competition và economic development; regulators có thể impose penalties và reporting obligations."},{"front_en":"Explain: Communities and society","back_vi":"Local community chịu ảnh hưởng từ employment, infrastructure, pollution, public health, resource use; loss of social license to operate có thể giảm giá trị issuer."},{"front_en":"Explain: Environment as affected interest","back_vi":"Natural resources, biodiversity, carbon emissions và waste có thể tạo exposure cho issuer dù môi trường không trực tiếp ký hợp đồng."},{"front_en":"Explain: Investor stakeholder spectrum","back_vi":"Một số investors ưu tiên financial materiality, một số đồng thời có ethical/impact goals; cần phân biệt objectives với actual financial consequences."},{"front_en":"Explain: Conflict: labor versus owners","back_vi":"Wage increases có thể nâng retention/morale, nhưng cũng tăng near-term cost và giảm profit nếu không tạo productivity offset."},{"front_en":"Explain: Conflict: suppliers versus liquidity","back_vi":"Kéo dài thời hạn phải trả có thể tăng issuer cash availability nhưng gây cash-flow pressure cho suppliers, thậm chí tăng purchasing price/risk."},{"front_en":"Explain: Conflict: customers versus margins","back_vi":"Giảm chất lượng để cắt cost có thể nâng short-run margin nhưng tạo recall, liability và reputational damage."},{"front_en":"Explain: Conflicts among shareholders","back_vi":"Controlling holders có thể thích transactions với affiliated parties, trong khi minority shareholders muốn arm's-length pricing và fair treatment."},{"front_en":"Explain: Risk sharing and governance","back_vi":"Contracts, independent directors, disclosure, compensation design, compliance và dialogue giúp phân bổ trách nhiệm và giảm agency conflicts."},{"front_en":"Explain: Stakeholder-specific information","back_vi":"Analysts dùng annual reports, proxy reports, sustainability data, customer retention, labor incidents, leverage ratios và public filings để hiểu stakeholder exposure."},{"front_en":"Explain: Economic obligations versus accounting liabilities","back_vi":"Một issuer có ảnh hưởng đến air/water quality, employee trust hoặc customer privacy mà chưa phải ghi recognized liability; economic consequence vẫn có thể material."},{"front_en":"Explain: Exam scenario mapping","back_vi":"Khi đọc case, xác định stakeholder bị tác động, claim/expectation chính, horizon và trade-off; chọn explanation dựa trên objective chứ không chỉ danh xưng."}]},{"id":"CFA26-03-02-LOS03","letter":"2.c","title_en":"Environmental, Social, and Governance Factors","outcome_en":"describe environmental, social, and governance factors of corporate issuers considered by investors","overview_vi":"Nhận diện E/S/G financially material theo ngành, phân biệt physical và transition climate risks, human capital/privacy, board independence và reporting; mô tả tác động đến cash flows, risk premium và valuation.","source":[{"id":"CFA Institute Curriculum 2026 — Corporate Issuers LM2","pages":"63–69 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading21","pages":"234–236 (physical PDF)"},{"id":"SAPP Corporate Issuers 2026 — Module2","pages":"57–59 (physical PDF)"}],"sections":[{"heading":"ESG overview","body":"ESG gồm environmental, social và governance factors có thể ảnh hưởng issuer risk, opportunities, expected cash flows và cost of capital. Analysts cần nhận diện material factors thay vì chỉ nhìn ESG label.","trap":"ESG disclosure does not by itself guarantee sustainability performance."},{"heading":"Financial materiality","body":"Một ESG issue là financially material nếu kỳ vọng ảnh hưởng đáng kể đến firm operations, value, financing costs hoặc long-term business model; tính material khác nhau theo industry/geography.","trap":"A minor issue is not equally material for every issuer."},{"heading":"Why ESG became measurable","body":"Regulation, taxes, changing consumer/investor preferences, climate effects, litigation và dữ liệu tốt hơn khiến nonfinancial outcomes có thể ước lượng thành earnings, capex, probability of loss.","trap":"Measurement can still be uncertain and incomplete."},{"heading":"Environmental themes","body":"Môi trường gồm GHG emissions, energy/water use, pollution, waste, natural-resource depletion, biodiversity và climate adaptation/mitigation; exposure khác nhau theo production process.","trap":"Not all companies have the same material environmental risks."},{"heading":"Climate physical risk","body":"Physical risk từ acute events (floods, storms, wildfire) hoặc chronic changes (drought, heat, sea level) phá hủy assets, disrupt supply chains và tăng insurance cost.","trap":"Physical risk is different from transition policy risk."},{"heading":"Climate transition risk","body":"Transition risk từ policy/carbon pricing, technological substitution và customer demand chuyển sang low-carbon products, làm existing plants/assets kém hữu ích.","trap":"A stranded asset is often a transition-risk example."},{"heading":"Stranded assets","body":"Stranded asset là asset không thể thu hồi expected economic value do thay đổi market/technology/regulation, ví dụ fossil fuel facility đóng sớm.","trap":"Stranding does not necessarily mean physical destruction."},{"heading":"GHG emissions scope categories","body":"Scope 1: direct controlled operations; Scope 2: indirect purchased energy; Scope 3: other value-chain emissions. Phạm vi và chất lượng data cần được đánh giá cẩn thận.","trap":"Scope labels are supplementary detail; reporting standards can change."},{"heading":"Water and resource dependence","body":"Water-intensive or mining firms có rủi ro từ scarcity, contamination và permitting, ảnh hưởng operating expense, capital investment và license to operate.","trap":"Environmental risk can be sector-specific."},{"heading":"Pollution and remediation","body":"Industrial spill có thể kéo theo cleanup cost, regulatory fines, civil compensation, production stoppage, credit downgrade và reputational damage.","trap":"A remediation obligation may crystallize after an incident."},{"heading":"Environmental opportunity","body":"Efficient processes, low-emission products, clean energy substitution hoặc recycling có thể tạo revenue growth và cost savings nếu investment economics có lợi.","trap":"Green labels do not prove positive NPV."},{"heading":"Social themes","body":"Social factors thường tập trung human capital, customer protection, community relations, product safety, labor standards, data privacy, diversity và supply chain labor practices.","trap":"Employee headcount alone is not a comprehensive social score."},{"heading":"Human capital risk","body":"Skills shortages, unsafe work, high turnover, poor training và labor disputes có thể tạo bottlenecks, higher cost và lower service quality.","trap":"Strong retention is context dependent."},{"heading":"Product and customer safety","body":"Product liability, unsafe medicine/food/vehicles, misleading marketing hoặc unreliable service ảnh hưởng trust, lawsuits và operating license.","trap":"Product recall effects may be both financial and social."},{"heading":"Data privacy and cybersecurity","body":"Mishandling personal data or breach làm mất customer trust, gián đoạn hoạt động, tạo fines và future spending; highly material đối với data-heavy firms.","trap":"Cybersecurity is not only an IT cost line."},{"heading":"Supply chain labor","body":"Procurement from abusive or unsafe suppliers tạo legal, reputational và disruption exposure cho issuer dù công nhân không trực tiếp được thuê.","trap":"Outsourcing does not eliminate all stakeholder impacts."},{"heading":"Community and social license","body":"Government approval alone đôi khi chưa đủ: community opposition hoặc conflict có thể delay project; cần xem social acceptance và grievance mechanisms.","trap":"Social license is an analytical concept, not always a formal legal license."},{"heading":"Governance themes","body":"Board composition, independence, shareholder rights, audit quality, executive compensation, risk controls, ethics, compliance và related-party transactions là governance factors.","trap":"Having a written code without enforcement is insufficient."},{"heading":"Board independence","body":"Independent directors có thể challenge managers và controlling owners; analysts xem composition, tenure, conflicts và actual effectiveness.","trap":"Independence label alone does not prove oversight quality."},{"heading":"Audit and disclosure","body":"Financial reporting integrity, independent audit và internal controls giúp giảm information risk; weak audit oversight làm earnings reliability thấp.","trap":"Clean audit opinions cannot eliminate all fraud risk."},{"heading":"Executive incentives","body":"Pay tied to short-term earnings/share price có thể encourage earnings management hoặc excessive risk, trong khi thoughtful long-term incentives có thể improve alignment.","trap":"Stock compensation does not guarantee good governance."},{"heading":"Corruption and bribery exposure","body":"Bribery làm tăng legal investigations, fines, procurement bans và trust erosion, có thể ảnh hưởng spreads và valuation sau khi công bố.","trap":"Governance harm can translate into cost-of-capital change."},{"heading":"Governance and share classes","body":"Dual-class shares hay controlling shareholders làm minority investor protection quan trọng; xem related-party conflicts và voting-right asymmetry.","trap":"Concentrated voting rights do not prove abuse but raise monitoring needs."},{"heading":"Sources for ESG analysis","body":"Annual reports, management disclosures, sustainability reports, proxy statements, audited financials, regulatory fines, third-party datasets và controversy records cần được triangulate.","trap":"A single vendor score is not definitive evidence."},{"heading":"ESG scores' limitations","body":"Ratings có thể khác nhau vì methods, boundaries, materiality, data gaps và weighting; analysts không nên coi điểm aggregate là dữ liệu thực nghiệm không thể tranh cãi.","trap":"Rating disagreement does not imply all ESG information is useless."},{"heading":"Cash flow transmission","body":"ESG exposure có thể ảnh hưởng volume, pricing, opex, capex, taxes, legal payments, terminal value và required return; valuation cần tránh double count cùng một loss.","trap":"Do not lower forecasts and raise discount rates for identical risk without thought."},{"heading":"Credit versus equity sensitivity","body":"ESG shocks có thể làm giảm buffer bảo vệ lenders và lower residual earnings cho equity; đòn bẩy và seniority làm kết quả khác nhau giữa securities.","trap":"Governance scandal need not affect all securities identically."},{"heading":"Greenwashing concern","body":"Marketing claim không có evidence đáng tin cậy có thể đánh lạc hướng investor; verify operational metrics và targets với underlying disclosures.","trap":"Promise is not realized outcome."},{"heading":"Exam materiality test","body":"Hỏi: exposure có thực sự liên quan industry? Risk có physical/transition/social/governance? Tác động đi qua cash flow hay required return? Is evidence independent?","trap":"Avoid picking an ESG category solely from a buzzword."}],"formulas":[{"name":"Environmental cost channel","expr":"ΔValue ≈ PV(Δcash flows) − additional risk-adjustment costs","meaning":"Minh họa link ESG đến valuation.","conditions":"Qualitative approximation, not mandatory official formula."},{"name":"Carbon tax cash cost","expr":"Carbon expense = taxable emissions × tax per unit","meaning":"Phí phát thải tác động operating expense.","conditions":"Coverage, tax credits and exemptions vary."},{"name":"GHG intensity","expr":"Emission intensity = emissions / unit revenue or output","meaning":"So sánh exposure qua sản lượng/quy mô.","conditions":"Need consistent denominator and scopes."},{"name":"Accident cost proxy","expr":"Expected annual accident loss = probability × estimated loss per incident","meaning":"Khung probability weighted losses.","conditions":"Estimates and dependencies uncertain."},{"name":"Risk-adjusted cash flow","expr":"Scenario-weighted forecast = Σ probability × scenario cash flow","meaning":"Đưa risks/opportunities vào expectation.","conditions":"Scenarios must be coherent and probabilities sum to one."},{"name":"Customer churn rate","expr":"Churn = customers lost / customers at start of period","meaning":"Supplemental social operating KPI.","conditions":"Check measurement period and cohort."},{"name":"Cyber incident expected exposure","expr":"Expected loss ≈ probability of breach × loss conditional on breach","meaning":"Định lượng sơ bộ downside social risk.","conditions":"Severity distribution may be heavy tailed."},{"name":"Governance cost channel","expr":"Required return rises when priced information/agency risk increases (all else equal)","meaning":"Quan hệ lý thuyết giữa governance và financing terms.","conditions":"Do not assert deterministic effects from a single event."}],"examples":[{"question_en":"A plant emits 50,000 taxable tonnes of CO2 equivalent and a carbon charge is $35 per tonne. Estimate annual tax cost.","answer":"$1.75 million","steps_vi":["Emission cost=50.000×35 USD.","$1,75m là expense illustrative, còn tax applicability depends on jurisdiction."],"check":"Supplemental scenario calculation."},{"question_en":"A firm emitted 20,000 tonnes for production of 400,000 units. Calculate emission intensity per unit.","answer":"0.05 tonnes per unit","steps_vi":["Cường độ phát thải=20.000/400.000=0,05 tấn mỗi sản phẩm, tức 50 kg trên mỗi đơn vị nếu cùng chuẩn đo lường.","0,05 tonnes (50 kg) per output unit; useful only with comparable definitions."],"check":"Check consistent scope."},{"question_en":"A facility has 3% annual probability of a flood causing $10 million of net economic loss. Calculate expected annual loss.","answer":"$300,000","steps_vi":["E[loss]≈0,03×10m.","300.000 USD expected annual exposure, không có nghĩa actual yearly loss equals that number."],"check":"Scenario expectation not guaranteed."},{"question_en":"A coal plant becomes uneconomic after carbon regulation although it is physically intact. What kind of risk caused stranding?","answer":"Transition risk","steps_vi":["Regulation/market pricing thay đổi economic value của asset.","Đây không phải direct storm damage/physical risk."],"check":"Stranded assets associated with transition."},{"question_en":"A coastal insurer sees increasing claims following more severe storms. Which climate risk is most direct?","answer":"Physical risk","steps_vi":["Storms làm actual physical damage và expected loss ratios tăng.","Premium/capital needs có thể tăng sau adverse experience."],"check":"Acute physical risk."},{"question_en":"A tech company loses personal data for one million customers and faces fines. Identify the leading ESG category.","answer":"Social","steps_vi":["Data privacy và customer protection thuộc social exposure; controls/governance cũng liên quan.","Phải xác định dominant issue thay vì cho rằng breach chỉ là environmental."],"check":"Multiple categories can overlap."},{"question_en":"A mining group has major water pollution. Which financial statement channels might be affected?","answer":"Cleanup expense, fines, reduced revenue and future capex","steps_vi":["Environmental harm có thể tạo remediation obligations, disrupted production, customer/community reaction.","Forecast both direct cost and lost production; avoid double count."],"check":"Materiality depends on exposure."},{"question_en":"An issuer reports a 2% cyber incident probability with $50 million conditional loss. Estimate simple expected loss.","answer":"$1 million","steps_vi":["0,02×50m=1m.","Đây là expected cost—not a prediction that loss is paid annually."],"check":"Simplified binary model."},{"question_en":"An investment with a new filtration system costs $2m and saves $600k annually for four years (zero discount for illustration). Is undiscounted aggregate saving greater than cost?","answer":"Yes: $2.4m versus $2m","steps_vi":["Tổng tiết kiệm=600k×4=$2,4m.","Chưa thể kết luận positive NPV thực nếu discount rate, residual costs và maintenance chưa xét."],"check":"Distinguish crude payback from discounted valuation."},{"question_en":"A company's employee turnover falls from 12% to 8% after a training initiative. What is the change in percentage points?","answer":"−4 percentage points","steps_vi":["Turnover giảm 12%−8%=4 percentage points.","Không nói reduction 4% khi mô tả absolute percentage-point difference."],"check":"Rates and points differ."},{"question_en":"An issuer is accused of bribery and subsequently loses public contracts. Identify the leading ESG dimension.","answer":"Governance","steps_vi":["Bribery thể hiện breakdown ethics/compliance và weak controls.","Legal/revenue effects làm issue financially material."],"check":"Governance not only board count."},{"question_en":"An analyst has two ESG vendors giving materially different overall scores to the same firm. What should the analyst do?","answer":"Investigate metric definitions, materiality and underlying evidence","steps_vi":["Ratings weights/sources khác nhau nên score disagreement là signal to reconcile drivers.","Không thể lấy average scores làm truth nếu missing data."],"check":"Aggregate scores differ by design."},{"question_en":"A firm faces two possible outcomes: 20% probability of a $4m regulatory fine and 80% of no fine. Estimate expected fine.","answer":"$800,000","steps_vi":["Expected cost=0,20×4m+0,80×0.","800.000 là scenario-weighted loss, not fixed liability unless recognition criteria met."],"check":"Expected loss differs from accounting accrual."},{"question_en":"A board has three independent directors among five members. What is the proportion independent?","answer":"60%","steps_vi":["3/5×100%=60%.","Số học alone không nói chắc board effectiveness; xét committee powers and conflicts."],"check":"Independence count is a starting point."}],"questions":[{"stem_en":"A coal facility loses value because carbon policy makes operations uneconomic. This is an example of:","options":["Transition risk.","Cybersecurity risk.","Physical climate risk."],"correct":0,"why_vi":"Policy shift tạo stranded assets dù physical plant còn nguyên.","trap_vi":"Do not confuse physical damage with transition."},{"stem_en":"Flooding destroys part of a coastal factory. This is most directly:","options":["A shareholder voting dispute.","Physical environmental risk.","Financial reporting manipulation."],"correct":1,"why_vi":"Flood gây thiệt hại vật lý và operational interruption.","trap_vi":"Acute physical risk."},{"stem_en":"Which ESG dimension most directly covers consumer data privacy?","options":["Governance only.","Environmental.","Social."],"correct":2,"why_vi":"Data handling tác động quyền lợi và trust của customers; weak governance cũng có thể contribute.","trap_vi":"Select dominant classification."},{"stem_en":"A company faces a large bribery investigation. The dominant ESG issue is:","options":["Governance.","Water scarcity.","Employee commute time."],"correct":0,"why_vi":"Corruption phản ánh ethics/compliance and governance controls.","trap_vi":"It can influence credit and equity risk."},{"stem_en":"An oil producer faces declining demand as electric transport grows. This is primarily:","options":["A capital structure identity.","Transition risk.","Flood physical risk."],"correct":1,"why_vi":"Technology/consumer shift làm fossil asset economics yếu hơn.","trap_vi":"Transition includes technology/market change."},{"stem_en":"Which factor is likely more material for a mining company than for a pure software services firm?","options":["User password security.","Board reporting quality.","Water contamination and remediation obligations."],"correct":2,"why_vi":"Mining trực tiếp chịu permit/water exposure lớn; software chịu data privacy more material.","trap_vi":"Industry context matters."},{"stem_en":"High employee turnover is most closely associated with:","options":["Human capital social risks.","Greenhouse gas scope only.","Foreign exchange intervention."],"correct":0,"why_vi":"Turnover ảnh hưởng training cost, knowledge retention và morale.","trap_vi":"Social can affect operating performance."},{"stem_en":"A company receives an excellent ESG label from one vendor, but fines and disclosures suggest unresolved environmental harm. The analyst should:","options":["Treat the label as conclusive.","Verify underlying operational data and controversy evidence.","Discard all data including audited reporting."],"correct":1,"why_vi":"Rating là signal không thay thế source evaluation và financially material exposure.","trap_vi":"Greenwashing and score methodology risk."},{"stem_en":"Which is the best interpretation of an ESG factor's materiality?","options":["It matters only if measured in tonnes.","It is equally material for all industries.","It may materially affect issuer value and risk in a specific context."],"correct":2,"why_vi":"Material ESG factor có expected financial/operational consequences đáng kể theo issuer.","trap_vi":"Context matters more than headline."},{"stem_en":"A company cuts energy use with no adverse effect on output. Its potential benefit can include:","options":["Lower operating cost and emissions.","Guaranteed permanent higher share price.","Elimination of all regulatory risks."],"correct":0,"why_vi":"Efficiency có thể giúp cả operating margin và environmental footprint.","trap_vi":"Calculate costs of initiative too."},{"stem_en":"A firm breaches customer privacy laws and pays fines. Which transmission to valuation is most direct?","options":["Automatic increase in face value of debt.","Lower cash flows through fines and potential customer losses.","Guaranteed lower required return."],"correct":1,"why_vi":"Fines, revenue loss, remediation spending làm expected future free cash flows giảm.","trap_vi":"Avoid double counting risk channels."},{"stem_en":"A governance scandal increases lenders' required risk premium. The firm is most likely to face:","options":["A guaranteed decline in borrowing cost.","Elimination of all interest obligations.","Potentially higher cost of debt."],"correct":2,"why_vi":"Information/reputation risk có thể dẫn tới higher spreads, refinance pressure.","trap_vi":"Outcome depends on actual repricing."},{"stem_en":"Which source is most useful for evaluating whether director oversight is credible?","options":["Board independence, committee disclosures and audit reports.","Only the issuer's advertising slogan.","Only the share ticker symbol."],"correct":0,"why_vi":"Governance analysis xét independent audit, committees, voting rights and controls.","trap_vi":"Labels without mechanism are weak evidence."},{"stem_en":"A supply chain contains suppliers using unsafe labor. This is most directly:","options":["Proof of immediate issuer default.","A potential social issue for the sourcing company.","Only a question of currency quoting."],"correct":1,"why_vi":"Supplier labor practices tác động reputation, operational continuity và legal compliance.","trap_vi":"Outsourcing does not remove exposure."},{"stem_en":"A security breach exposes patient information. What should an analyst most directly investigate?","options":["Only emissions intensity.","Only debt maturity.","Data protection controls and legal/customer exposure."],"correct":2,"why_vi":"Data privacy social risk và cybersecurity controls có thể materially affect valuation.","trap_vi":"Governance can also matter."},{"stem_en":"A company has annual emissions 15,000 tonnes and output 300,000 units. Emission intensity per unit is:","options":["0.05 tonnes.","20 tonnes.","5 tonnes."],"correct":0,"why_vi":"Cường độ phát thải mỗi đơn vị là 15.000/300.000=0,05 tấn; cần thống nhất scope và sản lượng làm mẫu số.","trap_vi":"Check denominator."},{"stem_en":"If an event has a 4% probability and loss if it occurs is $12 million, the simple expected loss is:","options":["$12 million.","$480,000.","$3 million."],"correct":1,"why_vi":"Expected loss=0,04×12 triệu=480.000 USD. Đây là giá trị kỳ vọng, không phải tổn thất chắc chắn xảy ra.","trap_vi":"Expected is not certain realized cost."},{"stem_en":"Governance factors most directly include:","options":["Ocean water temperature only.","Customers' number of gym visits.","Board independence and audit quality."],"correct":2,"why_vi":"Board, audit, incentive alignment, shareholder rights là governance.","trap_vi":"G can overlap with E/S exposures."},{"stem_en":"An analyst sees a dual-class issuer with concentrated superior voting rights. The most relevant governance concern is:","options":["Minority shareholder protection.","A mathematically guaranteed lower bond coupon.","No possibility of management discretion."],"correct":0,"why_vi":"Cấu trúc dual-class có thể tạo khoảng cách giữa quyền biểu quyết và tỷ lệ sở hữu kinh tế, vì vậy cần kiểm tra bảo vệ cổ đông thiểu số.","trap_vi":"Structure alone does not prove misconduct."},{"stem_en":"Which response best reflects careful ESG valuation?","options":["Assume every ESG initiative creates positive NPV.","Map material issues into forecast cash flows and risk assumptions without double counting.","Ignore ESG because it is nonfinancial."],"correct":1,"why_vi":"Analysts phải translate material risks/opportunities qua cash flow/discount rate và tránh tính trùng.","trap_vi":"Financial effects remain evidence-dependent."}],"cards":[{"front_en":"Explain: ESG overview","back_vi":"ESG gồm environmental, social và governance factors có thể ảnh hưởng issuer risk, opportunities, expected cash flows và cost of capital. Analysts cần nhận diện material factors thay vì chỉ nhìn ESG label."},{"front_en":"Explain: Financial materiality","back_vi":"Một ESG issue là financially material nếu kỳ vọng ảnh hưởng đáng kể đến firm operations, value, financing costs hoặc long-term business model; tính material khác nhau theo industry/geography."},{"front_en":"Explain: Why ESG became measurable","back_vi":"Regulation, taxes, changing consumer/investor preferences, climate effects, litigation và dữ liệu tốt hơn khiến nonfinancial outcomes có thể ước lượng thành earnings, capex, probability of loss."},{"front_en":"Explain: Environmental themes","back_vi":"Môi trường gồm GHG emissions, energy/water use, pollution, waste, natural-resource depletion, biodiversity và climate adaptation/mitigation; exposure khác nhau theo production process."},{"front_en":"Explain: Climate physical risk","back_vi":"Physical risk từ acute events (floods, storms, wildfire) hoặc chronic changes (drought, heat, sea level) phá hủy assets, disrupt supply chains và tăng insurance cost."},{"front_en":"Explain: Climate transition risk","back_vi":"Transition risk từ policy/carbon pricing, technological substitution và customer demand chuyển sang low-carbon products, làm existing plants/assets kém hữu ích."},{"front_en":"Explain: Stranded assets","back_vi":"Stranded asset là asset không thể thu hồi expected economic value do thay đổi market/technology/regulation, ví dụ fossil fuel facility đóng sớm."},{"front_en":"Explain: GHG emissions scope categories","back_vi":"Scope 1: direct controlled operations; Scope 2: indirect purchased energy; Scope 3: other value-chain emissions. Phạm vi và chất lượng data cần được đánh giá cẩn thận."},{"front_en":"Explain: Water and resource dependence","back_vi":"Water-intensive or mining firms có rủi ro từ scarcity, contamination và permitting, ảnh hưởng operating expense, capital investment và license to operate."},{"front_en":"Explain: Pollution and remediation","back_vi":"Industrial spill có thể kéo theo cleanup cost, regulatory fines, civil compensation, production stoppage, credit downgrade và reputational damage."},{"front_en":"Explain: Environmental opportunity","back_vi":"Efficient processes, low-emission products, clean energy substitution hoặc recycling có thể tạo revenue growth và cost savings nếu investment economics có lợi."},{"front_en":"Explain: Social themes","back_vi":"Social factors thường tập trung human capital, customer protection, community relations, product safety, labor standards, data privacy, diversity và supply chain labor practices."},{"front_en":"Explain: Human capital risk","back_vi":"Skills shortages, unsafe work, high turnover, poor training và labor disputes có thể tạo bottlenecks, higher cost và lower service quality."},{"front_en":"Explain: Product and customer safety","back_vi":"Product liability, unsafe medicine/food/vehicles, misleading marketing hoặc unreliable service ảnh hưởng trust, lawsuits và operating license."},{"front_en":"Explain: Data privacy and cybersecurity","back_vi":"Mishandling personal data or breach làm mất customer trust, gián đoạn hoạt động, tạo fines và future spending; highly material đối với data-heavy firms."},{"front_en":"Explain: Supply chain labor","back_vi":"Procurement from abusive or unsafe suppliers tạo legal, reputational và disruption exposure cho issuer dù công nhân không trực tiếp được thuê."},{"front_en":"Explain: Community and social license","back_vi":"Government approval alone đôi khi chưa đủ: community opposition hoặc conflict có thể delay project; cần xem social acceptance và grievance mechanisms."},{"front_en":"Explain: Governance themes","back_vi":"Board composition, independence, shareholder rights, audit quality, executive compensation, risk controls, ethics, compliance và related-party transactions là governance factors."},{"front_en":"Explain: Board independence","back_vi":"Independent directors có thể challenge managers và controlling owners; analysts xem composition, tenure, conflicts và actual effectiveness."},{"front_en":"Explain: Audit and disclosure","back_vi":"Financial reporting integrity, independent audit và internal controls giúp giảm information risk; weak audit oversight làm earnings reliability thấp."},{"front_en":"Explain: Executive incentives","back_vi":"Pay tied to short-term earnings/share price có thể encourage earnings management hoặc excessive risk, trong khi thoughtful long-term incentives có thể improve alignment."},{"front_en":"Explain: Corruption and bribery exposure","back_vi":"Bribery làm tăng legal investigations, fines, procurement bans và trust erosion, có thể ảnh hưởng spreads và valuation sau khi công bố."},{"front_en":"Explain: Governance and share classes","back_vi":"Dual-class shares hay controlling shareholders làm minority investor protection quan trọng; xem related-party conflicts và voting-right asymmetry."},{"front_en":"Explain: Sources for ESG analysis","back_vi":"Annual reports, management disclosures, sustainability reports, proxy statements, audited financials, regulatory fines, third-party datasets và controversy records cần được triangulate."},{"front_en":"Explain: ESG scores' limitations","back_vi":"Ratings có thể khác nhau vì methods, boundaries, materiality, data gaps và weighting; analysts không nên coi điểm aggregate là dữ liệu thực nghiệm không thể tranh cãi."},{"front_en":"Explain: Cash flow transmission","back_vi":"ESG exposure có thể ảnh hưởng volume, pricing, opex, capex, taxes, legal payments, terminal value và required return; valuation cần tránh double count cùng một loss."},{"front_en":"Explain: Credit versus equity sensitivity","back_vi":"ESG shocks có thể làm giảm buffer bảo vệ lenders và lower residual earnings cho equity; đòn bẩy và seniority làm kết quả khác nhau giữa securities."},{"front_en":"Explain: Greenwashing concern","back_vi":"Marketing claim không có evidence đáng tin cậy có thể đánh lạc hướng investor; verify operational metrics và targets với underlying disclosures."},{"front_en":"Explain: Exam materiality test","back_vi":"Hỏi: exposure có thực sự liên quan industry? Risk có physical/transition/social/governance? Tác động đi qua cash flow hay required return? Is evidence independent?"}]}]},{"module_id":"CFA26-03-03","module_title":"Corporate Governance: Conflicts, Mechanisms, Risks, and Benefits","subject":"Corporate Issuers","version":"2.1","language":"Vietnamese instruction with English CFA terms and exam questions","qa_status":"DETAILED_DRAFT_PENDING_INDEPENDENT_ACADEMIC_AUDIT","disclaimer_vi":"Được biên soạn độc lập dựa trên CFA Institute Curriculum 2026 Module 3, Kaplan Reading 22, slide Corporate Issuers. Tình huống và MCQ tự tạo, không sao chép nguyên văn bài tập có bản quyền. Các định lượng chỉ minh họa phụ trợ; câu hỏi vẫn cần kiểm định học thuật độc lập.","los":[{"id":"CFA26-03-03-LOS01","letter":"3.a","title_en":"Principal–Agent Relationships and Stakeholder Conflicts","outcome_en":"describe the principal-agent relationship and conflicts that may arise between stakeholder groups","overview_vi":"Giải thích principal–agent, information asymmetry, monitoring/agency costs; xung đột shareholders–managers, controlling–minority, lenders–equity và stakeholder groups; nhận diện debt overhang, risk shifting, executive incentives.","source":[{"id":"CFA Institute Curriculum 2026 — Corporate Issuers LM3","pages":"75–84 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading22","pages":"237–239 (physical PDF)"},{"id":"SAPP Corporate Issuers 2026 — Module3","pages":"64–72 (physical PDF)"}],"sections":[{"heading":"Principal–agent definition","body":"Principal ủy quyền cho agent hành động hoặc quản lý tài sản thay mình; agent được kỳ vọng đại diện lợi ích của principal nhưng có thể tối ưu hóa lợi ích riêng. Hợp đồng không phải điều kiện bắt buộc để agency relationship tồn tại.","trap":"Agent and principal are roles, not fixed people."},{"heading":"Ownership–control separation","body":"Shareholders sở hữu residual equity và bầu directors; directors chỉ định/giám sát managers, còn managers có quyền điều hành hàng ngày. Nhiều tầng ủy quyền tạo agency layers.","trap":"Owner and manager are not identical in listed companies."},{"heading":"Information asymmetry","body":"Agent thường biết chi tiết hoạt động hơn principal; thông tin bất cân xứng khiến monitoring kém hiệu quả và có thể tăng investor required return.","trap":"Private information does not necessarily imply misconduct."},{"heading":"Adverse selection versus moral hazard","body":"Adverse selection diễn ra trước giao dịch khi quality/risk của đối tác không quan sát rõ; moral hazard xuất hiện sau ký kết khi behavior của agent khó quan sát.","trap":"Do not confuse timing of informational problems."},{"heading":"Agency costs","body":"Agency costs gồm monitoring, bonding/incentive arrangements và residual loss khi agent không hoàn toàn hành động theo tối ưu của principal.","trap":"Monitoring has a cost and cannot ensure zero residual loss."},{"heading":"Manager entrenchment","body":"Managers có thể giữ quyền lực nhờ dispersed ownership, weak boards hoặc anti-takeover defenses; lợi ích cá nhân có thể xung đột shareholders.","trap":"Longevity in management is not by itself proof of entrenchment."},{"heading":"Executive perquisites","body":"Private benefits như travel xa xỉ, special services, oversized compensation có thể tiêu tiền của shareholders mà không tăng firm value tương ứng.","trap":"Compensation can be justified when tied to genuine performance."},{"heading":"Empire building","body":"Managers có thể mở rộng company size qua acquisitions dù NPV kém để tăng salary/prestige/career power.","trap":"Growth does not guarantee shareholder value."},{"heading":"Short-term versus long-term incentives","body":"Bonuses dựa vào quarterly EPS có thể khiến managers giảm maintenance/R&D hoặc tăng accounting earnings tạm thời, trái với maximization dài hạn.","trap":"Short-run earnings growth may harm intrinsic value."},{"heading":"Manager risk aversion","body":"Managers có phần lớn human capital gắn vào một employer nên có thể tránh dự án rủi ro nhưng NPV dương mà diversified shareholders thích.","trap":"Manager and shareholder risk exposures are different."},{"heading":"Equity-linked compensation dual effect","body":"Stock awards/options có thể align managers với equity owners nhưng cũng có thể tạo incentive tăng biến động hoặc làm loãng cổ đông.","trap":"Equity incentives do not automatically protect bondholders."},{"heading":"Shareholder board relationship","body":"Shareholders là principals khi elect board; directors phải monitor strategy, reporting và hiring; weak independence làm delegation kém hiệu quả.","trap":"Independent director label is not a guarantee of effectiveness."},{"heading":"Board manager relationship","body":"Board đóng vai principal đối với CEO; CEO là agent trong việc thực thi corporate strategy, cung cấp financial information cho board.","trap":"Board oversight should not be replaced by CEO unchecked discretion."},{"heading":"Controlling versus minority shareholders","body":"Majority hoặc controlling voting owners có thể ưu tiên related-party transactions, special dividends hoặc control benefits khiến minority chịu thiệt hại.","trap":"Shareholding majority does not necessarily equal all economic ownership."},{"heading":"Dual-class voting risk","body":"Superior-vote class có thể giữ managerial control với tỷ lệ cash-flow ownership nhỏ; điều này tạo khác biệt voting power và economic exposure.","trap":"Different share classes may have unequal voting rights."},{"heading":"Creditor versus shareholder incentives","body":"Debt investors nhận fixed claims, shareholders hưởng residual upside; khi công ty leveraged, shareholders có thể chọn projects khiến lender recovery giảm dù expected equity value tăng.","trap":"Lender incentives differ from residual holders."},{"heading":"Risk shifting / asset substitution","body":"Sau khi debt được phát hành, managers phục vụ equity có thể chuyển từ low-risk investment sang high-risk investment vì equity payoff có convexity.","trap":"Increased risk does not guarantee higher total firm value."},{"heading":"Debt overhang","body":"Lenders hưởng phần lớn value của future investment khi issuer near distress, khiến shareholders không muốn tài trợ positive-NPV project.","trap":"Underinvestment differs from excessive-risk investment."},{"heading":"Excessive dividend distributions","body":"Debt investors muốn cash/collateral còn shareholders muốn dividends/buybacks; distributions lớn có thể làm debt service kém an toàn.","trap":"Covenants can restrict dividends."},{"heading":"New debt dilution of existing creditors","body":"Issuing equal- or senior-ranking debt có thể làm existing lenders' recovery weaker; họ có thể yêu cầu negative pledge hoặc debt-incurrence tests.","trap":"Exact creditor priority depends on security and covenants."},{"heading":"Customers versus owners","body":"Cutting product quality/safety để cải thiện earnings có thể gây financial harm cho customers và future value của owners.","trap":"ESG and agency conflicts can overlap."},{"heading":"Employees versus owners","body":"Workforce có thể đòi higher wage/safe conditions trong khi management muốn lower costs; hợp tác hiệu quả có thể giảm turnover và nâng profitability.","trap":"Worker needs are not identical to manager pay preferences."},{"heading":"Suppliers versus company liquidity","body":"Issuer kéo dài payables có thể cải thiện short-term cash nhưng làm supplier mất liquidity, ảnh hưởng reliability và pricing về lâu dài.","trap":"Increasing DPO can create counterparty risk."},{"heading":"Corporate governance risk analysis","body":"Khi đánh giá agency problem, hỏi ai ủy quyền, ai nắm information/control, payoff và loss được phân bổ cho ai, mechanism nào có thể giảm incentive lệch.","trap":"Identifying a conflict does not establish fraud occurred."},{"heading":"Exam treatment of conflict cases","body":"Tách principal/agent, controlling/minority, creditor/shareholder; xem hợp đồng, voting power, pay design, short versus long term và nguồn dữ liệu độc lập.","trap":"Picking the party with the largest equity stake may miss the agency relationship."}],"formulas":[{"name":"Equity residual under debt","expr":"Equity value (simplified)=max(V−D,0)","meaning":"Convex residual payout liên quan đến incentive risk shifting.","conditions":"One-period single-debt-class abstraction."},{"name":"Manager option incentive","expr":"Payoff from a plain call option=max(S−K,0)","meaning":"Equity-option compensation có nonlinear upside.","conditions":"Illustrative and ignores vesting/expiry."},{"name":"Agency cost framework","expr":"Agency costs = monitoring + bonding + residual loss","meaning":"Phân rã chi phí do lệch mục tiêu agency.","conditions":"Conceptual identity; not all costs readily measured."},{"name":"Voting-control concentration","expr":"Voting power %=votes controlled/total votes×100%","meaning":"Phân biệt voting quyền kiểm soát với economic ownership.","conditions":"Multiple-class structures require vote weighting."},{"name":"Economic ownership fraction","expr":"Cash-flow ownership %=economic shares owned/total economic shares","meaning":"So sánh với voting rights.","conditions":"Different dividend classes complicate simple ratios."},{"name":"Related-party transfer","expr":"Economic loss to minority may arise from non-arm's-length transaction price","meaning":"Cơ chế transfer value.","conditions":"Requires evidence of actual terms; not deterministic."},{"name":"Debt payout intuition","expr":"Creditor repayment =min(V,D)","meaning":"Dạng payoff fixed debt trong mô hình đơn giản.","conditions":"Seniority not modeled."},{"name":"Risk alignment test","expr":"Who decides? Who benefits from upside? Who bears downside?","meaning":"Khung phân tích conflict case.","conditions":"Qualitative, not a numerical equation."}],"examples":[{"question_en":"A CEO earns bonuses based only on this quarter's EPS and cancels profitable long-term R&D. Identify the agency problem.","answer":"Short-termism in manager incentives","steps_vi":["CEO có incentive tối đa bonus quarterly, trong khi owners quan tâm long-run intrinsic value.","Performance measure thiếu horizon có thể dẫn đến underinvestment."],"check":"Incentive horizon is central."},{"question_en":"A controlling shareholder owns 42% of economic equity but 70% of votes via superior voting shares. What governance concern arises?","answer":"Disproportionate voting control over minority holders","steps_vi":["Voting rights > economic exposure làm control entrenchment và related-party decisions cần scrutiny.","Analyze voting and cash-flow rights separately."],"check":"Voting concentration isn't necessarily wrongdoing."},{"question_en":"An issuer has two share classes: founder shares have 10 votes each (1m shares); other shares have 1 vote each (5m shares). What is founder voting share?","answer":"66.67%","steps_vi":["Founder có 10 triệu phiếu, các cổ đông còn lại có 5 triệu; tổng 15 triệu phiếu biểu quyết.","Founder vote%=10/15≈66,67% although founder economic share is 1/6=16,67% if equal cash-flow rights."],"check":"Votes versus economic ownership."},{"question_en":"A manager refuses a positive-NPV but volatile project because dismissal risk would hurt their career. Which conflict is illustrated?","answer":"Manager risk aversion versus diversified shareholders","steps_vi":["Human capital manager tập trung tại one employer; dispersed investors can diversify.","Manager có thể underinvest dù expected shareholder value positive."],"check":"Avoid concluding all risky projects are good."},{"question_en":"A company near bankruptcy rejects a positive-NPV project because any benefit would mainly increase recovery of old creditors. Name the problem.","answer":"Debt overhang","steps_vi":["Equity phải bỏ new capital nhưng phần lớn value chảy vào repayment of existing debt.","This is underinvestment due to leverage."],"check":"Not risk shifting."},{"question_en":"After receiving a fixed-rate loan, management changes the asset portfolio toward speculative projects while leaving lenders without upside sharing. Name the conflict.","answer":"Asset substitution / risk shifting","steps_vi":["Equity hưởng convex upside, downside tăng có thể làm creditor recovery yếu.","Covenant có thể giới hạn investment risk."],"check":"Risk shifting differs from dividends."},{"question_en":"A board accepts a CEO's related-party transaction without asking for independent valuation. What oversight failure is most obvious?","answer":"Weak board monitoring and possible conflicts of interest","steps_vi":["Board nên bảo vệ fair terms giữa agent và owners.","No independent review khiến information asymmetry và self-dealing risk tăng."],"check":"Need evidence before concluding actual fraud."},{"question_en":"Executives take frequent luxury trips charged to the company without business justification. Which agency cost behavior is involved?","answer":"Excessive perquisites","steps_vi":["Managers nhận private benefits còn owners gánh cost.","Monitoring, disclosure và policies có thể mitigate."],"check":"Compensation is not always a perquisite."},{"question_en":"An activist investor campaigns to replace directors after years of poor capital allocation. Who is principal to the elected board?","answer":"Shareholders","steps_vi":["Shareholders bầu board như agents chịu trách nhiệm supervise company.","Activism là cơ chế owners yêu cầu accountability."],"check":"Board appoints managers."},{"question_en":"A firm issues new debt senior to existing unsecured lenders without protections. Who might face reduced recovery?","answer":"Existing unsecured lenders","steps_vi":["Claim mới có priority có thể divert assets from old lenders in distress.","Negative pledge and other debt covenants quản lý issue này."],"check":"Seniority drives recovery."},{"question_en":"Shareholder equity has $60 million of value over $40 million in debt at the firm's current $100 million value. If asset value rises to $120 million, what is the simplified equity payoff?","answer":"$80 million","steps_vi":["Equity payoff=max(120−40,0)=80m.","Debt remains 40m; equity nhận marginal upside of 20m."],"check":"Simplified one-class debt."},{"question_en":"Two managers independently report investment risk only to one another, with no board review. What underlying agency problem is intensified?","answer":"Information asymmetry with weak monitoring","steps_vi":["Board thiếu reliable risk reporting từ agent khiến oversight kém.","Independent audit và risk controls giúp giảm gap."],"check":"Do not assume transparency solely from managerial trust."}],"questions":[{"stem_en":"A principal–agent relationship most directly arises when:","options":["One party delegates tasks to another whose incentives may differ.","An exchange rate is fixed by treaty.","A firm uses only equity financing."],"correct":0,"why_vi":"Principal ủy quyền cho agent; conflict do incentives và information khác nhau.","trap_vi":"No formal written contract is always necessary."},{"stem_en":"Which group is typically the principal when shareholders elect directors?","options":["Suppliers.","Shareholders.","Employees."],"correct":1,"why_vi":"Board được shareholders bầu làm đại diện giám sát issuer, nên board đóng vai agent đối với shareholders.","trap_vi":"Board later becomes principal to managers."},{"stem_en":"A CEO has access to better current operating information than dispersed investors. This describes:","options":["Complete transparency.","A tax shield.","Information asymmetry."],"correct":2,"why_vi":"Agent có information advantage, làm monitoring khó.","trap_vi":"This is not necessarily fraud."},{"stem_en":"Managers pursue acquisitions to increase organizational size despite negative NPV. This is most consistent with:","options":["Empire building.","Optimal long-term capital allocation.","An increase in creditor seniority."],"correct":0,"why_vi":"Executives thích power/pay từ larger assets dù owners mất value.","trap_vi":"Scale is not automatically value."},{"stem_en":"A CFO delays necessary maintenance solely to reach an annual bonus target. This is an example of:","options":["Bond duration matching.","Short-term incentive misalignment.","A reduction of all stakeholder risks."],"correct":1,"why_vi":"Short-term compensation có thể induce long-term harm.","trap_vi":"Accounting profit need not reflect future cost."},{"stem_en":"Which action best illustrates manager entrenchment?","options":["Shareholders replace ineffective directors through a vote.","Auditors report material weaknesses.","Executives use governance defenses to resist accountability."],"correct":2,"why_vi":"Entrenchment giữ quyền lực agent bất chấp owners muốn thay đổi.","trap_vi":"Long executive tenure alone is insufficient proof."},{"stem_en":"Which factor tends to increase agency costs?","options":["Greater information asymmetry.","Clear executive performance metrics aligned with owners.","Reliable disclosure and independent oversight."],"correct":0,"why_vi":"Principal khó quan sát agent nên monitoring và residual loss tăng.","trap_vi":"Oversight can mitigate, not abolish."},{"stem_en":"A majority voting holder approves transactions benefiting an affiliated company at the expense of the issuer. The most direct conflict is:","options":["Lenders versus regulators only.","Controlling versus minority shareholders.","Employees versus customers only."],"correct":1,"why_vi":"Related-party self-dealing có thể transfer economic value khỏi minority investors.","trap_vi":"Two equity classes can have divergent incentives."},{"stem_en":"Dual-class shares with founder supervoting rights most directly create:","options":["Guaranteed equal voting for all shareholders.","Automatic default protection for creditors.","A possible gap between control and economic ownership."],"correct":2,"why_vi":"Voting rights có thể lớn hơn economic stake.","trap_vi":"Voting power concentration alone is not fraud."},{"stem_en":"A debt-laden company rejects a positive-NPV project because creditors capture most gains. This problem is:","options":["Debt overhang.","Product recall.","Risk shifting."],"correct":0,"why_vi":"Existing debt làm shareholders underinvest vì phần benefit đi cho creditors.","trap_vi":"Contrast with increasing asset volatility."},{"stem_en":"Changing to riskier projects after debt is issued can harm:","options":["Tax authorities only.","Existing lenders.","All shareholders only."],"correct":1,"why_vi":"Debt creditors chịu more default downside nhưng upside capped.","trap_vi":"Asset substitution problem."},{"stem_en":"A shareholder demands a large dividend that weakens loan collateral. Which group is most likely to oppose it?","options":["The receiving shareholders.","New retail customers only.","Existing lenders."],"correct":2,"why_vi":"Creditor muốn bảo vệ repayment capacity.","trap_vi":"Loan covenant may limit distributions."},{"stem_en":"A manager's career is tied to a single employer while diversified shareholders own many firms. The manager may:","options":["Prefer less project risk than shareholders.","Always choose the riskiest project.","Have identical risk exposure to investors."],"correct":0,"why_vi":"Undiversified human capital tạo risk aversion và potential underinvestment.","trap_vi":"Not all risk reduction is suboptimal."},{"stem_en":"Which is a common agency cost category?","options":["Cash discount on receivables.","Monitoring costs.","A bond coupon paid on schedule."],"correct":1,"why_vi":"Agency cost gồm monitoring, bonding, residual loss.","trap_vi":"Monitoring is not free."},{"stem_en":"Which approach most directly addresses information asymmetry?","options":["Hiding related-party transactions.","Eliminating all board meetings.","Independent reporting and disclosure."],"correct":2,"why_vi":"External disclosure và audit làm principal hiểu operations hơn.","trap_vi":"Disclosures still need verification."},{"stem_en":"If the founder owns 20% of equal economic shares but has 60% of votes, the founder has:","options":["Greater voting control than economic ownership.","Equal voting and cash-flow rights.","No ability to influence the board."],"correct":0,"why_vi":"Founder sở hữu 20% lợi ích kinh tế nhưng có 60% phiếu biểu quyết; tỷ lệ kiểm soát vượt phần chịu rủi ro kinh tế.","trap_vi":"Check the specific share-class rights."},{"stem_en":"A stock-option bonus can sometimes encourage executives to:","options":["Guarantee dividend payments.","Increase asset risk to enhance option value.","Eliminate all asymmetric payoffs."],"correct":1,"why_vi":"Convex option payoff có thể favor volatility and increase creditor concerns.","trap_vi":"Options can also align management with equity."},{"stem_en":"The most appropriate first step in identifying a stakeholder conflict is to:","options":["Assume all shareholders have equal interests.","Ignore lender covenants.","Map who controls decisions and who bears outcomes."],"correct":2,"why_vi":"Decision-maker, payoffs, downside và information xác định agency conflicts.","trap_vi":"Do not infer motives solely from labels."},{"stem_en":"Which conflict is most likely for suppliers?","options":["Delayed payment that improves buyer liquidity but harms supplier cash flows.","A CEO appointed by the board.","An increase in one-year bond duration."],"correct":0,"why_vi":"Supplier có receivables nên cash delay ảnh hưởng họ trực tiếp.","trap_vi":"Trade credit has costs."},{"stem_en":"An investment manager is paid more when the firm's EPS rises, even if risk rises sharply. What should an analyst investigate?","options":["Only the firm's office area.","Incentive design and risk-taking behavior.","Only the currency of coupon payments."],"correct":1,"why_vi":"Compensation metric có thể encourage risk/short-term accounting trade-off.","trap_vi":"Earnings alone can miss risk."}],"cards":[{"front_en":"Explain: Principal–agent definition","back_vi":"Principal ủy quyền cho agent hành động hoặc quản lý tài sản thay mình; agent được kỳ vọng đại diện lợi ích của principal nhưng có thể tối ưu hóa lợi ích riêng. Hợp đồng không phải điều kiện bắt buộc để agency relationship tồn tại."},{"front_en":"Explain: Ownership–control separation","back_vi":"Shareholders sở hữu residual equity và bầu directors; directors chỉ định/giám sát managers, còn managers có quyền điều hành hàng ngày. Nhiều tầng ủy quyền tạo agency layers."},{"front_en":"Explain: Information asymmetry","back_vi":"Agent thường biết chi tiết hoạt động hơn principal; thông tin bất cân xứng khiến monitoring kém hiệu quả và có thể tăng investor required return."},{"front_en":"Explain: Adverse selection versus moral hazard","back_vi":"Adverse selection diễn ra trước giao dịch khi quality/risk của đối tác không quan sát rõ; moral hazard xuất hiện sau ký kết khi behavior của agent khó quan sát."},{"front_en":"Explain: Agency costs","back_vi":"Agency costs gồm monitoring, bonding/incentive arrangements và residual loss khi agent không hoàn toàn hành động theo tối ưu của principal."},{"front_en":"Explain: Manager entrenchment","back_vi":"Managers có thể giữ quyền lực nhờ dispersed ownership, weak boards hoặc anti-takeover defenses; lợi ích cá nhân có thể xung đột shareholders."},{"front_en":"Explain: Executive perquisites","back_vi":"Private benefits như travel xa xỉ, special services, oversized compensation có thể tiêu tiền của shareholders mà không tăng firm value tương ứng."},{"front_en":"Explain: Empire building","back_vi":"Managers có thể mở rộng company size qua acquisitions dù NPV kém để tăng salary/prestige/career power."},{"front_en":"Explain: Short-term versus long-term incentives","back_vi":"Bonuses dựa vào quarterly EPS có thể khiến managers giảm maintenance/R&D hoặc tăng accounting earnings tạm thời, trái với maximization dài hạn."},{"front_en":"Explain: Manager risk aversion","back_vi":"Managers có phần lớn human capital gắn vào một employer nên có thể tránh dự án rủi ro nhưng NPV dương mà diversified shareholders thích."},{"front_en":"Explain: Equity-linked compensation dual effect","back_vi":"Stock awards/options có thể align managers với equity owners nhưng cũng có thể tạo incentive tăng biến động hoặc làm loãng cổ đông."},{"front_en":"Explain: Shareholder board relationship","back_vi":"Shareholders là principals khi elect board; directors phải monitor strategy, reporting và hiring; weak independence làm delegation kém hiệu quả."},{"front_en":"Explain: Board manager relationship","back_vi":"Board đóng vai principal đối với CEO; CEO là agent trong việc thực thi corporate strategy, cung cấp financial information cho board."},{"front_en":"Explain: Controlling versus minority shareholders","back_vi":"Majority hoặc controlling voting owners có thể ưu tiên related-party transactions, special dividends hoặc control benefits khiến minority chịu thiệt hại."},{"front_en":"Explain: Dual-class voting risk","back_vi":"Superior-vote class có thể giữ managerial control với tỷ lệ cash-flow ownership nhỏ; điều này tạo khác biệt voting power và economic exposure."},{"front_en":"Explain: Creditor versus shareholder incentives","back_vi":"Debt investors nhận fixed claims, shareholders hưởng residual upside; khi công ty leveraged, shareholders có thể chọn projects khiến lender recovery giảm dù expected equity value tăng."},{"front_en":"Explain: Risk shifting / asset substitution","back_vi":"Sau khi debt được phát hành, managers phục vụ equity có thể chuyển từ low-risk investment sang high-risk investment vì equity payoff có convexity."},{"front_en":"Explain: Debt overhang","back_vi":"Lenders hưởng phần lớn value của future investment khi issuer near distress, khiến shareholders không muốn tài trợ positive-NPV project."},{"front_en":"Explain: Excessive dividend distributions","back_vi":"Debt investors muốn cash/collateral còn shareholders muốn dividends/buybacks; distributions lớn có thể làm debt service kém an toàn."},{"front_en":"Explain: New debt dilution of existing creditors","back_vi":"Issuing equal- or senior-ranking debt có thể làm existing lenders' recovery weaker; họ có thể yêu cầu negative pledge hoặc debt-incurrence tests."},{"front_en":"Explain: Customers versus owners","back_vi":"Cutting product quality/safety để cải thiện earnings có thể gây financial harm cho customers và future value của owners."},{"front_en":"Explain: Employees versus owners","back_vi":"Workforce có thể đòi higher wage/safe conditions trong khi management muốn lower costs; hợp tác hiệu quả có thể giảm turnover và nâng profitability."},{"front_en":"Explain: Suppliers versus company liquidity","back_vi":"Issuer kéo dài payables có thể cải thiện short-term cash nhưng làm supplier mất liquidity, ảnh hưởng reliability và pricing về lâu dài."},{"front_en":"Explain: Corporate governance risk analysis","back_vi":"Khi đánh giá agency problem, hỏi ai ủy quyền, ai nắm information/control, payoff và loss được phân bổ cho ai, mechanism nào có thể giảm incentive lệch."},{"front_en":"Explain: Exam treatment of conflict cases","back_vi":"Tách principal/agent, controlling/minority, creditor/shareholder; xem hợp đồng, voting power, pay design, short versus long term và nguồn dữ liệu độc lập."}]},{"id":"CFA26-03-03-LOS02","letter":"3.b","title_en":"Corporate Governance Mechanisms and Stakeholder Management","outcome_en":"describe corporate governance and mechanisms to manage stakeholder relationships and mitigate associated risks","overview_vi":"Khung governance nội bộ và bên ngoài: reporting, AGM/EGM, shareholder voting/proxy/activism, takeover defenses, creditor covenants, board committees, compensation, employees, regulators và governance codes.","source":[{"id":"CFA Institute Curriculum 2026 — Corporate Issuers LM3","pages":"84–93 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading22","pages":"239–242 (physical PDF)"},{"id":"SAPP Corporate Issuers 2026 — Module3","pages":"73–87 (physical PDF)"}],"sections":[{"heading":"Corporate governance framework","body":"Corporate governance là hệ thống rules, oversight, checks/balances và incentives nhằm điều hành issuer có trách nhiệm và quản lý stakeholder conflicts.","trap":"Governance is more than a written ethics policy."},{"heading":"Internal and external mechanisms","body":"Cơ chế nội bộ gồm board committees, internal controls, disclosure, compensation design và risk policies. Cơ chế bên ngoài gồm laws, exchange listing rules, auditors, activist investors, creditor enforcement và takeover market.","trap":"Mechanisms are complementary, not substitutes."},{"heading":"Transparency and reporting","body":"Regular financial disclosures, related-party disclosures và material-event reporting giúp outside stakeholders đánh giá performance, risk và management integrity.","trap":"Disclosure volume is not the same as quality."},{"heading":"Annual general meeting (AGM)","body":"AGM cho shareholders hỏi board/management, approve ordinary resolutions, elect directors và vote on important matters according to jurisdiction.","trap":"Not every strategic choice is voted on by shareholders."},{"heading":"Extraordinary general meeting (EGM)","body":"EGM được triệu tập cho special/urgent resolutions hoặc tại yêu cầu hợp lệ của qualified shareholders; cơ chế trao quyền kiểm soát giữa hai AGM.","trap":"Thresholds differ by local company law."},{"heading":"Proxy voting","body":"Shareholder không dự họp trực tiếp có thể ủy quyền bỏ phiếu cho representative/proxy; cơ chế này rất quan trọng với dispersed ownership.","trap":"A proxy is authority to vote, not ownership transfer."},{"heading":"Proxy contest","body":"Dissident group kêu gọi shareholders ủy quyền vote để thay directors hay thay policy, tạo sức ép lên incumbent management.","trap":"Proxy contest differs from a normal annual proxy collection."},{"heading":"Shareholder activism","body":"Activists mua hoặc nắm sizable stake nhằm thúc đẩy board change, strategy, capital allocation hoặc payout modifications; có thể tăng accountability nhưng gây costs/disputes.","trap":"Activism is not invariably value creating."},{"heading":"Voting rights and special resolutions","body":"Ordinary vs special resolutions có voting thresholds khác nhau theo jurisdiction/articles; special matters như constitutional change hoặc merger cần enhanced approval.","trap":"Do not assume universal 50% or 75% across countries."},{"heading":"Preemptive rights","body":"Existing shareholders có quyền mua proportional new shares để tránh dilution khi issuer raise fresh equity, tùy securities law và issuance terms.","trap":"Rights may be waived or absent."},{"heading":"Takeovers and market for corporate control","body":"Takeover possibility tạo disciplinary pressure nếu underperformance làm company undervalued; tender offers/mergers có thể thay managers.","trap":"A takeover is not always beneficial to all stakeholders."},{"heading":"Staggered board","body":"Chỉ một phần board được bầu lại mỗi năm, làm hostile acquirer khó thay entire board ngay; có thể tạo stability hoặc entrenchment.","trap":"Classifying directors does not automatically protect minority owners."},{"heading":"Shareholder rights plan / poison pill","body":"Rights plan có thể khiến aggressive bidder chịu dilution/cost nếu vượt ownership threshold; tăng takeover defense và bargaining power của incumbent board.","trap":"Poison pill can protect negotiations or entrench managers."},{"heading":"One-tier board","body":"Directors (including inside/independent) ở một board quản lý oversight; executive functions được phân chia theo legal framework.","trap":"One-tier is not automatically less independent than two-tier."},{"heading":"Two-tier board","body":"Management board điều hành, supervisory board oversee; jurisdictions có thể yêu cầu worker representatives, reducing direct management overlap.","trap":"Legal details vary by country."},{"heading":"Independent directors","body":"Directors không có significant ties to management/controlling holders giúp review executive actions và reduce conflicts; effectiveness còn phụ thuộc skills, incentives, information.","trap":"Formal independence can be superficial."},{"heading":"Audit committee","body":"Audit committee oversee financial reporting, internal control, external auditor independence/quality và reporting integrity.","trap":"Committee does not replace external auditor's work."},{"heading":"Compensation/remuneration committee","body":"Committee design executive pay, targets, clawbacks và risk-adjusted performance; cần gắn horizon với shareholder outcomes.","trap":"Paying in stock alone does not solve risk shifting."},{"heading":"Nominating/governance committee","body":"Committee propose director slate, review board skills/succession và governance policies, often independence standards.","trap":"Nomination can still be influenced by controlling owners."},{"heading":"Risk committee and controls","body":"Risk oversight, internal control và compliance functions identify/monitor operational, market, legal and reputational exposures; board needs escalation reports.","trap":"A risk policy without implementation is insufficient."},{"heading":"Whistleblower channels","body":"Confidential reporting/anti-retaliation giúp phát hiện fraud và safety/compliance problems trước khi losses nghiêm trọng.","trap":"Whistleblowers need protections to be effective."},{"heading":"Creditor covenants","body":"Financial and negative covenants có thể require coverage/collateral, restrict dividends/new debt, trigger reporting or acceleration on breach.","trap":"A covenant gives contractual rights, not routine ownership votes."},{"heading":"Debt collateral and security","body":"Collateral grant lien vào specific assets, improving creditor recovery and discipline.","trap":"Secured debt priority depends on legal perfection and insolvency rules."},{"heading":"Employee voice and unions","body":"Collective bargaining, works councils hoặc board representation tùy jurisdiction tạo mechanism để nhân viên negotiate conditions và report risks.","trap":"Worker representation is not universal."},{"heading":"Regulatory and exchange requirements","body":"Corporate/securities laws, mandatory audits, anti-bribery rules, listing standards và governance codes create external accountability.","trap":"Compliance floor is not identical across countries."},{"heading":"Comply-or-explain approach","body":"Một số governance codes yêu cầu issuer follow recommended practices hoặc giải thích deviations; analyst cần đánh giá explanation thay vì chỉ count compliance.","trap":"Departure may be legitimate if transparently justified."},{"heading":"Corporate policies and culture","body":"Codes of conduct, conflict-of-interest policies, approval thresholds, training, independent review và sanctions ảnh hưởng real decision quality.","trap":"A printed code alone does not imply enforcement."},{"heading":"Corporate governance program evaluation","body":"Xét governance objectives, disclosure integrity, board independence/skills, incentives, stakeholder engagement, creditor safeguards và evidence from controversies.","trap":"One-off score cannot replace a holistic review."}],"formulas":[{"name":"Voting majority illustration","expr":"Approval fraction = supporting eligible votes / votes cast","meaning":"Cách mô tả voting outcome.","conditions":"Quorum and special thresholds jurisdiction dependent."},{"name":"Board independence ratio","expr":"Independent directors / total directors ×100%","meaning":"Một proxy cho oversight structure.","conditions":"Not an overall governance quality score."},{"name":"Insider voting percentage","expr":"Votes controlled by insiders / all voting rights ×100%","meaning":"Đánh giá concentrated control.","conditions":"Share classes and agreements affect rights."},{"name":"Ownership dilution after issuance","expr":"Existing ownership = old holding / (old shares + new shares)","meaning":"Rationale for preemptive rights.","conditions":"Assumes same-class shares and no subscriptions."},{"name":"Loan covenant headroom","expr":"Headroom = actual metric − minimum covenant threshold","meaning":"Illustrative cushion for minimum coverage.","conditions":"Reverse comparison for max leverage covenant."},{"name":"Debt-to-equity limit","expr":"Actual D/E compared with maximum allowed ratio","meaning":"Một financial covenant example.","conditions":"Legal covenant definitions may differ from book ratios."},{"name":"Audit reporting chain","expr":"Audit committee → board → shareholders, with independent auditor providing assurance","meaning":"Khung giám sát reporting.","conditions":"Illustrative communication hierarchy."},{"name":"Governance control chain","expr":"Shareholders elect board → board oversees management → management executes","meaning":"Khung principal-agent controls.","conditions":"Board systems vary by jurisdiction."}],"examples":[{"question_en":"A corporation has 9 directors, 6 independent. What percentage are independent?","answer":"66.67%","steps_vi":["Independent fraction=6/9×100%.","66,67% là structural indicator, chưa đủ chứng minh strong governance."],"check":"Independent designation must be credible."},{"question_en":"A creditor requires interest coverage of at least 3.0×. The issuer reports 3.8×. What is the coverage headroom?","answer":"0.8×","steps_vi":["Coverage headroom=actual−minimum=3,8−3=0,8 lần.","Điều kiện covenant hiện được đáp ứng trong mô hình này."],"check":"Covenant definitions and test periods matter."},{"question_en":"An issuer has maximum covenant D/E of 1.2× and current D/E of 1.35×. Is the simple maximum leverage covenant met?","answer":"No","steps_vi":["1,35>1,20 nên vượt maximum.","Lender có thể yêu cầu remedies/waiver theo contract, không tự động liquidation ngay."],"check":"Check permitted cure terms."},{"question_en":"A founder owns 100,000 of 500,000 equal shares. The company issues 250,000 new shares and founder purchases none. New ownership is?","answer":"13.33%","steps_vi":["Founder vẫn sở hữu 100.000 shares, tổng cổ phiếu mới là 750.000; tỷ lệ còn 100/750=13,33%.","Ownership=100/750=13,33%; preemptive rights could allow proportional purchase if offered."],"check":"Share dilution is mathematical, not necessarily value loss."},{"question_en":"Shareholders want to replace directors through an organized vote campaign. Identify the mechanism.","answer":"Proxy contest","steps_vi":["Dissidents kêu gọi proxy votes để thay board members.","Không phải creditor default covenant."],"check":"Proxy differs from a takeover bid."},{"question_en":"An issuer's CEO is investigated for suspected misconduct; an independent board committee reviews evidence and potential conflicts. Which governance objective does this best serve?","answer":"Independent oversight","steps_vi":["Oversight giảm information asymmetry/management self-review.","Review cần documented evidence, ability to escalate và independent legal/audit advice."],"check":"Committee labels are not enough."},{"question_en":"A bank wants to limit dividends when cash coverage is weak. What contractual tool is most direct?","answer":"Restrictive covenant","steps_vi":["Covenant hạn chế distribution trước khi lender được bảo vệ.","Rights arise from loan agreement."],"check":"Debt holders need not elect all directors."},{"question_en":"An activist investor wants an immediate special shareholder vote on a major transaction. What meeting may be requested under applicable rules?","answer":"Extraordinary general meeting","steps_vi":["EGM tổ chức ngoài AGM regular schedule để xem resolution cụ thể.","Investor cần thỏa legal thresholds."],"check":"No universal calling threshold."},{"question_en":"A company uses a rights plan that makes acquisition more expensive once a hostile investor crosses a threshold. What is the defense?","answer":"Poison pill","steps_vi":["Shareholder rights plan tạo dilution/cost với bidder vượt threshold.","Có thể tạo negotiation leverage hoặc incumbent entrenchment."],"check":"Defense is not necessarily good or bad."},{"question_en":"A firm has a 12-person board; 4 seats rotate off each year. What board structure is illustrated?","answer":"Staggered board","steps_vi":["Board chia classes, directors không cùng reelect annually.","Điều này làm replacement full board chậm hơn."],"check":"Rules on class terms vary."},{"question_en":"A company lists executive pay in an annual proxy filing. Which governance mechanism is highlighted?","answer":"Reporting and transparency","steps_vi":["Investors có thông tin để đánh giá alignment của pay với risk/returns.","Disclosure alone does not prove compensation is appropriate."],"check":"Material information must be reliable."},{"question_en":"An employee reports accounting manipulation through a confidential hotline without retaliation. Which mechanism is used?","answer":"Whistleblower protection","steps_vi":["Kênh report giúp audit committee/board phát hiện misconduct.","Anti-retaliation tăng khả năng employees report promptly."],"check":"Confidentiality matters."},{"question_en":"A shareholder cannot attend an annual meeting and authorizes someone else to vote. What is that authorization?","answer":"Proxy","steps_vi":["Proxy-holder thực hiện quyền vote theo authority, không nhận ownership of shares.","Ủy quyền đúng phạm vi và luật áp dụng."],"check":"Not a stock transfer."},{"question_en":"A regulated firm follows most voluntary governance code recommendations but explains one deviation with evidence. What approach is this?","answer":"Comply or explain","steps_vi":["Analyst nên xét rationale của deviation và outcome, không chỉ đếm số tick.","Local rules may impose mandatory practices outside code."],"check":"Not carte blanche to ignore law."}],"questions":[{"stem_en":"An independent audit committee most directly oversees:","options":["Financial reporting and audit integrity.","Currency intervention by the central bank.","Product marketing strategy only."],"correct":0,"why_vi":"Audit committee chịu oversight reporting, controls, external auditor independence.","trap_vi":"It does not replace auditor judgment."},{"stem_en":"The compensation committee primarily monitors:","options":["Foreign exchange regimes.","Directors' and executives' pay incentives.","Only supplier credit limits."],"correct":1,"why_vi":"Pay policy và performance target ảnh hưởng agency alignment.","trap_vi":"Stock awards can have risk incentives."},{"stem_en":"An issuer has a staggered board. This structure most likely:","options":["Eliminates the CEO's responsibilities.","Allows replacing all directors at every AGM.","Slows the replacement of all board members at one vote."],"correct":2,"why_vi":"Classified/staggered terms chỉ rotate subset each year, making quick takeover harder.","trap_vi":"It can support stability or entrenchment."},{"stem_en":"A poison-pill rights plan typically:","options":["Makes certain hostile acquisitions more expensive.","Guarantees no future shareholder dilution.","Automatically improves product quality."],"correct":0,"why_vi":"Rights plan làm bidder có nguy cơ chịu dilution hoặc phải bỏ thêm chi phí khi vượt ngưỡng sở hữu, từ đó tăng takeover cost.","trap_vi":"Evaluate actual interests and context."},{"stem_en":"A bank limits dividend distributions in a loan contract. The mechanism is:","options":["A labor union election.","A debt covenant.","A shareholder proxy contest."],"correct":1,"why_vi":"Covenant là điều khoản trong hợp đồng vay, nhằm bảo vệ khả năng trả nợ, collateral hoặc liquidity của issuer.","trap_vi":"Covenants do not require lender equity ownership."},{"stem_en":"The mechanism most directly allowing an absent shareholder to vote is:","options":["Creditor collateralization.","Management stock options.","Proxy voting."],"correct":2,"why_vi":"Proxy cho phép người được ủy quyền thực hiện phiếu biểu quyết thay cổ đông; ownership của shares không chuyển giao.","trap_vi":"Not a change in beneficial ownership."},{"stem_en":"A dissident shareholder seeks to replace incumbent directors by soliciting votes. This is:","options":["Proxy contest.","Interest tax shield.","A takeover arbitrage guarantee."],"correct":0,"why_vi":"Trong proxy contest, nhóm dissident kêu gọi ủy quyền bỏ phiếu cho slate directors khác để thay đổi board và accountability.","trap_vi":"Contest uses voting rights."},{"stem_en":"An annual general meeting is most directly a forum for:","options":["Payment of every supplier invoice.","Ordinary shareholder voting and oversight matters.","A central bank policy decision."],"correct":1,"why_vi":"AGM là cuộc họp thường niên để shareholders giám sát board, bỏ phiếu bầu directors và resolutions theo điều lệ.","trap_vi":"Not all board operations require shareholder vote."},{"stem_en":"A meeting convened outside the annual schedule to approve an extraordinary resolution is:","options":["A normal supplier negotiation.","A bond coupon.","An EGM."],"correct":2,"why_vi":"EGM xử lý special matters within law/bylaws.","trap_vi":"Calling threshold varies."},{"stem_en":"Which party most often elects a public company's directors?","options":["Voting shareholders.","All lenders without exception.","The firm's major customers."],"correct":0,"why_vi":"Voting shareholders bầu directors, còn board có trách nhiệm appoint và oversee management.","trap_vi":"Supervoting classes can alter voting power."},{"stem_en":"Which committee is most likely responsible for proposing board nominees?","options":["Marketing department.","Nominating/governance committee.","Credit sales committee only."],"correct":1,"why_vi":"Nominating/governance committee đề xuất nhân sự board, xem xét expertise, independence và governance policies.","trap_vi":"Final vote may rest with shareholders."},{"stem_en":"A credible whistleblower channel most directly improves:","options":["A guarantee of revenue growth.","Elimination of legal obligations.","Detection and escalation of misconduct."],"correct":2,"why_vi":"Whistleblower channel cho phép nhân viên báo cáo gian lận hoặc rủi ro an toàn và cần bảo vệ chống retaliation.","trap_vi":"Must have independent follow-up."},{"stem_en":"A two-tier board generally separates:","options":["Management and supervisory bodies.","Debt and equity markets permanently.","Audited and unaudited revenue streams."],"correct":0,"why_vi":"Two-tier board tách management board thực thi vận hành với supervisory board giám sát, giảm trùng lặp vai trò.","trap_vi":"Actual legal practice varies."},{"stem_en":"Which is the best measure of governance effectiveness?","options":["Existence of a code of conduct alone.","Actual monitoring, disclosure quality and enforcement.","Number of pages in an annual report only."],"correct":1,"why_vi":"Governance hiệu quả đòi hỏi thực thi controls, oversight, incentives và credible reporting; không chỉ có văn bản quy định.","trap_vi":"Formal structures can fail."},{"stem_en":"An issuer with 8 directors including 6 independent has an independence proportion of:","options":["133%.","25%.","75%."],"correct":2,"why_vi":"Có 6 trong 8 directors independent, tỷ trọng là 6/8×100%=75%; số lượng chỉ là tiêu chí bước đầu.","trap_vi":"Count alone does not establish effectiveness."},{"stem_en":"A loan requires minimum EBIT/interest of 4.0; actual ratio is 3.5. The firm:","options":["Has breached the stated minimum in the simple comparison.","Has 0.5 excess coverage headroom.","Automatically has positive shareholder return."],"correct":0,"why_vi":"3,5<4,0 nên không đạt test covenant.","trap_vi":"Waivers/cure are contractual matters."},{"stem_en":"A company allows shareholders to buy new shares proportionally before outsiders. This protects:","options":["Dividend tax exemption.","Preemptive rights.","Cash pooling only."],"correct":1,"why_vi":"Rights giúp existing holders avoid dilution of ownership if exercised.","trap_vi":"Rights availability depends on market rules."},{"stem_en":"A takeover bidder encounters a shareholder rights plan. The most direct potential effect is:","options":["Elimination of minority shareholders.","A legal requirement that price equals book equity.","Higher acquisition costs."],"correct":2,"why_vi":"Poison pill làm bidder phải pay more/dilute under trigger terms.","trap_vi":"Board may misuse or legitimately use defenses."},{"stem_en":"Which governance feature best addresses related-party deals?","options":["Independent approval and detailed disclosure.","Hidden negotiations with insiders.","Higher manager travel allowances."],"correct":0,"why_vi":"Conflict of interest cần scrutiny về arm's-length terms.","trap_vi":"Not every related-party deal is improper."},{"stem_en":"A board sets risk limits and receives internal compliance reports. The primary mechanism is:","options":["Currency market speculation.","Risk oversight and internal controls.","A dividend stock split."],"correct":1,"why_vi":"Monitoring/control giúp board challenge managers and prevent harm.","trap_vi":"Policies need escalation and enforcement."}],"cards":[{"front_en":"Explain: Corporate governance framework","back_vi":"Corporate governance là hệ thống rules, oversight, checks/balances và incentives nhằm điều hành issuer có trách nhiệm và quản lý stakeholder conflicts."},{"front_en":"Explain: Internal and external mechanisms","back_vi":"Cơ chế nội bộ gồm board committees, internal controls, disclosure, compensation design và risk policies. Cơ chế bên ngoài gồm laws, exchange listing rules, auditors, activist investors, creditor enforcement và takeover market."},{"front_en":"Explain: Transparency and reporting","back_vi":"Regular financial disclosures, related-party disclosures và material-event reporting giúp outside stakeholders đánh giá performance, risk và management integrity."},{"front_en":"Explain: Annual general meeting (AGM)","back_vi":"AGM cho shareholders hỏi board/management, approve ordinary resolutions, elect directors và vote on important matters according to jurisdiction."},{"front_en":"Explain: Extraordinary general meeting (EGM)","back_vi":"EGM được triệu tập cho special/urgent resolutions hoặc tại yêu cầu hợp lệ của qualified shareholders; cơ chế trao quyền kiểm soát giữa hai AGM."},{"front_en":"Explain: Proxy voting","back_vi":"Shareholder không dự họp trực tiếp có thể ủy quyền bỏ phiếu cho representative/proxy; cơ chế này rất quan trọng với dispersed ownership."},{"front_en":"Explain: Proxy contest","back_vi":"Dissident group kêu gọi shareholders ủy quyền vote để thay directors hay thay policy, tạo sức ép lên incumbent management."},{"front_en":"Explain: Shareholder activism","back_vi":"Activists mua hoặc nắm sizable stake nhằm thúc đẩy board change, strategy, capital allocation hoặc payout modifications; có thể tăng accountability nhưng gây costs/disputes."},{"front_en":"Explain: Voting rights and special resolutions","back_vi":"Ordinary vs special resolutions có voting thresholds khác nhau theo jurisdiction/articles; special matters như constitutional change hoặc merger cần enhanced approval."},{"front_en":"Explain: Preemptive rights","back_vi":"Existing shareholders có quyền mua proportional new shares để tránh dilution khi issuer raise fresh equity, tùy securities law và issuance terms."},{"front_en":"Explain: Takeovers and market for corporate control","back_vi":"Takeover possibility tạo disciplinary pressure nếu underperformance làm company undervalued; tender offers/mergers có thể thay managers."},{"front_en":"Explain: Staggered board","back_vi":"Chỉ một phần board được bầu lại mỗi năm, làm hostile acquirer khó thay entire board ngay; có thể tạo stability hoặc entrenchment."},{"front_en":"Explain: Shareholder rights plan / poison pill","back_vi":"Rights plan có thể khiến aggressive bidder chịu dilution/cost nếu vượt ownership threshold; tăng takeover defense và bargaining power của incumbent board."},{"front_en":"Explain: One-tier board","back_vi":"Directors (including inside/independent) ở một board quản lý oversight; executive functions được phân chia theo legal framework."},{"front_en":"Explain: Two-tier board","back_vi":"Management board điều hành, supervisory board oversee; jurisdictions có thể yêu cầu worker representatives, reducing direct management overlap."},{"front_en":"Explain: Independent directors","back_vi":"Directors không có significant ties to management/controlling holders giúp review executive actions và reduce conflicts; effectiveness còn phụ thuộc skills, incentives, information."},{"front_en":"Explain: Audit committee","back_vi":"Audit committee oversee financial reporting, internal control, external auditor independence/quality và reporting integrity."},{"front_en":"Explain: Compensation/remuneration committee","back_vi":"Committee design executive pay, targets, clawbacks và risk-adjusted performance; cần gắn horizon với shareholder outcomes."},{"front_en":"Explain: Nominating/governance committee","back_vi":"Committee propose director slate, review board skills/succession và governance policies, often independence standards."},{"front_en":"Explain: Risk committee and controls","back_vi":"Risk oversight, internal control và compliance functions identify/monitor operational, market, legal and reputational exposures; board needs escalation reports."},{"front_en":"Explain: Whistleblower channels","back_vi":"Confidential reporting/anti-retaliation giúp phát hiện fraud và safety/compliance problems trước khi losses nghiêm trọng."},{"front_en":"Explain: Creditor covenants","back_vi":"Financial and negative covenants có thể require coverage/collateral, restrict dividends/new debt, trigger reporting or acceleration on breach."},{"front_en":"Explain: Debt collateral and security","back_vi":"Collateral grant lien vào specific assets, improving creditor recovery and discipline."},{"front_en":"Explain: Employee voice and unions","back_vi":"Collective bargaining, works councils hoặc board representation tùy jurisdiction tạo mechanism để nhân viên negotiate conditions và report risks."},{"front_en":"Explain: Regulatory and exchange requirements","back_vi":"Corporate/securities laws, mandatory audits, anti-bribery rules, listing standards và governance codes create external accountability."},{"front_en":"Explain: Comply-or-explain approach","back_vi":"Một số governance codes yêu cầu issuer follow recommended practices hoặc giải thích deviations; analyst cần đánh giá explanation thay vì chỉ count compliance."},{"front_en":"Explain: Corporate policies and culture","back_vi":"Codes of conduct, conflict-of-interest policies, approval thresholds, training, independent review và sanctions ảnh hưởng real decision quality."},{"front_en":"Explain: Corporate governance program evaluation","back_vi":"Xét governance objectives, disclosure integrity, board independence/skills, incentives, stakeholder engagement, creditor safeguards và evidence from controversies."}]},{"id":"CFA26-03-03-LOS03","letter":"3.c","title_en":"Risks of Weak Governance and Benefits of Effective Governance","outcome_en":"describe potential risks of poor corporate governance and stakeholder management and benefits of effective corporate governance and stakeholder management","overview_vi":"Liên kết weak controls đến fraud, litigation, underinvestment, costly funding, reputation và operating failures; phân tích lợi ích của effective governance đối với performance, trust, cost of capital và long-run resilience.","source":[{"id":"CFA Institute Curriculum 2026 — Corporate Issuers LM3","pages":"93–99 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading22","pages":"242–244 (physical PDF)"},{"id":"SAPP Corporate Issuers 2026 — Module3","pages":"88–92 (physical PDF)"}],"sections":[{"heading":"Weak governance overview","body":"Weak governance khiến decision power ít được kiểm soát, thông tin sai lệch, stakeholder conflicts tích tụ và rủi ro mất value tăng. Outcomes phụ thuộc context, không phải every weakness always leads to scandal.","trap":"Correlation is not automatic causation."},{"heading":"Fraud and misreporting risk","body":"Audit committee yếu, CEO dominance hoặc unreliable internal controls có thể dẫn tới false financial statements, concealment of liabilities và legal investigations.","trap":"A clean-looking earnings series is not proof of accurate reporting."},{"heading":"Misallocation of capital","body":"Poor challenge to management khiến overexpansion, overpriced acquisitions và negative-NPV projects; owners may pay for executives' empire building.","trap":"More investment is not necessarily value creation."},{"heading":"Excessive compensation","body":"Pay structures không gắn long-term value có thể chuyển rent từ owners sang management hoặc encourage short-term risk taking.","trap":"High pay alone is not automatically abusive."},{"heading":"Related-party abuse","body":"Controlling shareholders chuyển value qua private affiliated entities bằng non-arm's-length transactions, khiến minority equity diluted economically.","trap":"Analyze actual terms and approvals."},{"heading":"Stakeholder neglect","body":"Inadequate labor safety, customer protection, product testing, supplier ethics hoặc environmental compliance có thể gây production loss và sanctions.","trap":"Stakeholder injury and shareholder cost can overlap."},{"heading":"Legal and regulatory cost","body":"Corporate misconduct có thể gây fines, damages, license withdrawal, deferred projects và financing restrictions.","trap":"Financial effect depends on penalties and reputation."},{"heading":"Operational inefficiency","body":"Lack of controls tạo procurement waste, employee turnover, supply disruptions và weak execution.","trap":"Governance quality is not measured by one ratio alone."},{"heading":"Reputation and trust","body":"Investor/customer confidence mất có thể làm orders giảm, staff departures tăng, investor risk premium cao hơn; intangible confidence khó đo trực tiếp nhưng có thể material.","trap":"Reputation and brand marketing are not interchangeable."},{"heading":"Financing cost effect","body":"Khi perceived governance/information risk cao, lenders và equity investors có thể yêu cầu higher expected returns, khiến debt/equity financing expensive.","trap":"Spreads and valuation also depend on business fundamentals."},{"heading":"Liquidity/access to capital","body":"Quality disclosures và strong governance có thể mở rộng investor base, cải thiện availability of outside financing; scandal có thể làm thị trường đóng lại trong lúc cần vốn.","trap":"Transparency does not guarantee funding during crises."},{"heading":"Creditor rating and covenant effects","body":"Governance failures có thể khiến credit agencies revise rating/outlook, lenders tighten covenants hoặc require collateral, tùy loss severity.","trap":"Not every controversy triggers an actual downgrade."},{"heading":"Unreliable valuation inputs","body":"Earnings manipulation làm investment analysts overestimate free cash flow, growth hoặc underestimate liabilities; weak reporting reduces valuation confidence.","trap":"Watch both financial and nonfinancial information."},{"heading":"Governance risk and fraud example","body":"Trường hợp healthcare technology Theranos được CFAI dùng minh họa oversight kém, board thiếu expertise và whistleblower concerns không được xử lý hiệu quả.","trap":"Case details are historical educational examples, not a generalization to all startups."},{"heading":"Environmental compliance example","body":"CFAI sử dụng Volkswagen emissions scandal để cho thấy compliance failure, regulatory penalties và trust damage có thể gây ảnh hưởng đáng kể đến issuer.","trap":"Do not infer every employee or director had the same knowledge."},{"heading":"Strong board supervision","body":"Independent, competent board có thể challenge strategy, monitor risk/appetite, review CEO compensation và replace failed leadership.","trap":"Independent status without expertise/access may be ineffective."},{"heading":"Sound disclosure and audits","body":"Credible financial statements, independent audits, internal controls và transparent risk reporting reduce information asymmetry and can improve confidence.","trap":"Reporting does not replace economic analysis."},{"heading":"Aligned incentives","body":"Multi-year risk-adjusted pay, clawbacks, share-ownership requirements và transparent assessment giảm temptation manipulate quarterly measures.","trap":"Any compensation scheme can create new incentives."},{"heading":"Stakeholder engagement benefits","body":"Early consultation với regulators, workers, customers, communities và suppliers có thể prevent litigation/disruption và preserve social license to operate.","trap":"Engagement without concrete remediation is insufficient."},{"heading":"Improved operating efficiency","body":"Transparent accountability, standardized controls và timely escalation có thể reduce waste and fraud loss, increase execution quality và improve operating margins.","trap":"Benefit size is firm-specific."},{"heading":"Better strategic decision-making","body":"Independent challenge, diversified board skills và risk review giúp avoid value-destructive acquisitions hoặc overconcentration.","trap":"Board diversity alone is not a proof of better decisions."},{"heading":"Lower perceived investment risk","body":"Giảm uncertainty về reported results và protection of stakeholder claims có thể lower risk premium and increase valuation, all else equal.","trap":"Cannot promise a particular share-price increase."},{"heading":"Greater long-run resilience","body":"Governance culture khuyến khích reporting issues early, dự phòng rủi ro và sửa errors trước khi khủng hoảng, giúp preserve reputation/cash flows.","trap":"Resilience is a qualitative outcome, not a guarantee."},{"heading":"Analyst evaluation practice","body":"Xem governance structure, track record, incident history, reporting/audit quality, board skills, related-party dealings, compensation policy và regulator actions.","trap":"A glossy ESG report is not substitute for evidence."},{"heading":"Risk-benefit matrix","body":"So sánh effectiveness of monitoring với probability/severity of management failures; benefits đo qua avoided costs, access to capital, cash-flow stability và value.","trap":"Avoid double counting the same governance benefit twice."},{"heading":"Exam conclusion rule","body":"Chọn answer phản ánh cả risks of poor governance lẫn benefits of strong: reputation, operating efficiency, capital access, cost of capital, financial reporting reliability.","trap":"Do not claim strong governance eliminates risk completely."}],"formulas":[{"name":"Governance expected loss proxy","expr":"Expected governance loss ≈ incident probability × loss severity","meaning":"Khung risk management minh họa.","conditions":"Author example, not mandatory CFAI official formula."},{"name":"Cost of debt comparison","expr":"Annual debt interest = principal × financing rate","meaning":"Minh họa higher spread khi risk rises.","conditions":"Ignore taxes and changing principal for illustration."},{"name":"Capital cost difference","expr":"Extra annual interest = debt principal × spread increase","meaning":"Chi phí tăng do lender risk premium.","conditions":"One-period simple approximation."},{"name":"Operating margin","expr":"Operating margin = operating profit / revenue","meaning":"Liên hệ operating efficiency và controls.","conditions":"Use consistent accounting definitions."},{"name":"Fraud loss ratio","expr":"Loss ratio = loss incurred / relevant revenue or assets","meaning":"Scale governance incident impact.","conditions":"Supplemental metric, not standardized governance score."},{"name":"Equity value after shock","expr":"Equity value change ≈ change in PV of expected FCFE discounted appropriately","meaning":"Dòng cash-flow effect trong valuation.","conditions":"Need specify horizon and discount assumptions; no mechanical percentage."},{"name":"Risk priority framework","expr":"Risk priority ≈ probability × financial impact","meaning":"Sắp xếp governance vulnerabilities.","conditions":"Qualitative screening; probabilities may not be observable."},{"name":"Reporting credibility chain","expr":"Strong controls → reliable financial reporting → lower information risk (all else equal)","meaning":"Khung causal analysis.","conditions":"Other issuer risks continue to matter."}],"examples":[{"question_en":"A governance scandal increases a firm's borrowing spread by 150 basis points on $200 million of refinanced debt. Estimate additional annual simple interest.","answer":"$3 million","steps_vi":["150 bps=1,5 percentage points=0,015; 200m×0,015.","Extra interest≈3m USD/year trước tax, nếu toàn bộ khoản vay repriced."],"check":"Funding cost example."},{"question_en":"An issuer has a 5% annual probability of a compliance event that would cost $8 million. Calculate simple expected annual loss.","answer":"$400,000","steps_vi":["Expected annual loss=5%×8 triệu=400.000 USD, là kỳ vọng xác suất chứ không phải năm nào cũng chịu đúng khoản này.","400k USD is expected risk cost, not certain annual payment."],"check":"Simplified binary event."},{"question_en":"A board identifies a cyber issue and prevention reduces incident probability from 10% to 3%; loss severity would be $4m. What is expected loss reduction?","answer":"$280,000","steps_vi":["Trước kiểm soát expected loss=10%×4 triệu=400.000 USD; sau kiểm soát=3%×4 triệu=120.000 USD.","Expected reduction=280k USD, before expense of prevention."],"check":"Need compare investment cost separately."},{"question_en":"A company's revenue is $100m and operating profit grows from $8m to $12m after better procurement controls. What is the operating margin change?","answer":"From 8% to 12%, up 4 percentage points","steps_vi":["Margins=8/100 and 12/100.","Improvement 4 pp; không khẳng định toàn bộ change chỉ do governance nếu không có evidence."],"check":"Attribution requires care."},{"question_en":"A company has $150m of variable-rate debt and its risk spread falls 80 bps after governance improvements, all else equal. What is annual interest saving?","answer":"$1.2 million","steps_vi":["80 bps tương đương 0,8%; tiết kiệm lãi dự kiến=150 triệu×0,008=1,2 triệu USD mỗi năm nếu khoản nợ được repriced.","Estimated 1,2m USD interest saving if fully repriced, not guaranteed market outcome."],"check":"Assumed spread change given."},{"question_en":"An issuer with weak reporting has persistent related-party deals lacking independent approval. What investor concern is most direct?","answer":"Potential diversion of value from minority owners","steps_vi":["Connected-party terms có thể không arm's length, leading to wealth transfer.","Investigate facts, disclosures and voting approvals."],"check":"Weak governance is a red flag, not proof."},{"question_en":"A startup board lacks relevant scientific expertise and ignores independent test warnings. What risk is particularly high?","answer":"Failure to challenge management claims","steps_vi":["Board thiếu competence độc lập để verify assertions, làm operational/fraud risk tăng.","Oversight needs expertise and credible evidence."],"check":"Illustrative generalization from governance cases."},{"question_en":"An automaker is penalized for noncompliance with environmental testing rules. Identify main consequence channels.","answer":"Legal fines, reputational harm and future compliance costs","steps_vi":["Vi phạm có thể gây civil/regulatory loss và giảm consumer trust.","Scenarios và actual impact phải kiểm tra theo evidence."],"check":"Environmental and governance can overlap."},{"question_en":"A company issues bonds when investors demand 6% rather than 4.5% due to higher perceived governance risk. On $40m of new debt, how much extra annual interest?","answer":"$600,000","steps_vi":["Spread=1,5%=0,015; 40m×0,015=600k.","Khoản tăng chỉ dựa trên assumed rate difference, không phải universal ESG impact."],"check":"Financing cost channel."},{"question_en":"A strong audit committee catches an incorrect revenue recognition policy before statements are issued. What benefit is most direct?","answer":"More reliable financial reporting and less information risk","steps_vi":["Prevented misstatement improves transparency to outside investors.","Lợi ích là quality of data và reduced sanctions risk; exact valuation effect uncertain."],"check":"Audits cannot eliminate all error."},{"question_en":"A manager pursues a large acquisition mainly to grow personal influence, despite negative estimated NPV. What governance failure is highlighted?","answer":"Weak oversight of capital allocation","steps_vi":["Board cần scrutinize acquisition economics thay vì approve executive empire building.","Good governance emphasizes risk-adjusted value."],"check":"Large size is not value creation."},{"question_en":"A firm has operating profit $18m and revenue $150m. What is its operating margin?","answer":"12%","steps_vi":["18/150×100=12%.","Ratio is operating profitability, chỉ là một indicator trong governance effectiveness assessment."],"check":"No direct causality implied."},{"question_en":"An issuer's compliance risk falls but it incurs greater audit and reporting expense. How should management evaluate the change?","answer":"Compare ongoing control cost with expected reduction in risk losses and financing benefits","steps_vi":["Strong governance có costs nhưng cũng có benefits từ fewer incidents và more credible finance.","Decision cần expected net value, không mặc định mọi controls đáng giá vô hạn."],"check":"Avoid zero-cost governance assumption."}],"questions":[{"stem_en":"Poor corporate governance is most likely to increase:","options":["The risk of misreporting and costly stakeholder conflicts.","The certainty of accurate valuations.","Guarantee of investor returns."],"correct":0,"why_vi":"Weak oversight làm agency conflicts, fraud, legal/reputation loss more likely.","trap_vi":"Avoid guaranteed outcomes."},{"stem_en":"Effective corporate governance can potentially lower:","options":["The legal requirement to pay taxes.","Investors' perceived information risk and financing costs.","Every possible business risk to zero."],"correct":1,"why_vi":"Kiểm soát và disclosure đáng tin cậy có thể giảm bất định thông tin, làm investors yêu cầu risk premium thấp hơn, nếu các yếu tố khác không đổi.","trap_vi":"Other business risks remain."},{"stem_en":"An overpaid CEO pursues negative-NPV mergers without board challenge. This is most likely:","options":["Optimal investment by definition.","A dividend-arbitrage strategy.","A governance failure and agency problem."],"correct":2,"why_vi":"Empire building và weak oversight có thể destroy shareholder value.","trap_vi":"Growth is not synonymous with value."},{"stem_en":"A board suppresses audit findings of overstated revenue. The greatest direct concern is:","options":["Integrity of financial reporting.","Exchange-rate bid–ask spreads.","The dividend tax rate only."],"correct":0,"why_vi":"Che giấu audit findings làm financial statements kém tin cậy, sai lệch định giá và tăng litigation risk.","trap_vi":"This may create legal exposure."},{"stem_en":"Strong whistleblower protections are most directly useful for:","options":["Setting monetary policy.","Escalating misconduct before it grows.","Eliminating all operational expenses."],"correct":1,"why_vi":"Confidential channels và anti-retaliation help detect fraud/compliance risk.","trap_vi":"Follow-up and independence still matter."},{"stem_en":"A company experiences a sharp rise in regulatory fines after weak compliance controls. This primarily reflects:","options":["Guaranteed low cost of capital.","No impact on operating cash flows.","A possible governance cost."],"correct":2,"why_vi":"Regulatory fines làm giảm cash flows hiện tại và có thể tăng compliance costs hoặc rủi ro kiện tụng về sau.","trap_vi":"Financial effects depend on severity."},{"stem_en":"Compared with opaque reporting, credible audited reporting is likely to:","options":["Reduce information asymmetry for outside investors.","Eliminate competitive risk.","Guarantee no restatements ever."],"correct":0,"why_vi":"Independent assurance và transparency cải thiện investor information quality.","trap_vi":"Audit is reasonable not absolute assurance."},{"stem_en":"An executive compensation scheme includes multi-year risk-adjusted targets. It is designed to:","options":["Guarantee that no manager leaves.","Better align managers with long-run owner interests.","Increase incentives for immediate accounting manipulation."],"correct":1,"why_vi":"Mục tiêu thưởng theo nhiều năm và có điều chỉnh rủi ro giúp giảm động cơ thao túng lợi nhuận quý để nhận bonus.","trap_vi":"Design and enforcement matter."},{"stem_en":"After a major governance controversy, bond spreads widen. This most directly indicates:","options":["The issuer has become risk-free.","The board automatically loses all votes.","Lenders demand more compensation for perceived risk."],"correct":2,"why_vi":"Spread cao hơn phản ánh lenders đòi compensation cao hơn cho risk cảm nhận, làm refinancing cost tăng.","trap_vi":"Other market factors can contribute."},{"stem_en":"A firm has debt of $100m; the credit spread rises by 100 basis points on new financing. Approximate additional annual interest is:","options":["$1 million.","$10 million.","$100,000."],"correct":0,"why_vi":"100 basis points=1%; nếu 100 triệu USD nợ được áp lãi mới, chi phí tăng khoảng 100m×1%=1 triệu USD/năm.","trap_vi":"Only if all $100m is repriced/issued."},{"stem_en":"Which characteristic of an effective board is most important?","options":["Unlimited executive discretion.","Independence, relevant expertise and willingness to challenge management.","An absence of recorded meetings."],"correct":1,"why_vi":"Board cần adequate information, competence và independent judgment.","trap_vi":"Checklist labels alone insufficient."},{"stem_en":"A large loss arising from environmental noncompliance can be connected to:","options":["Only currency risk.","No stakeholder issues.","Both governance weaknesses and environmental exposure."],"correct":2,"why_vi":"Compliance failure thuộc governance và event có environmental costs.","trap_vi":"E, S and G can overlap."},{"stem_en":"A company has never published key related-party transactions. What is a reasonable analyst response?","options":["Investigate reporting quality and conflicts of interest.","Assume the company is fraud-free.","Guarantee minority shareholder protection."],"correct":0,"why_vi":"Related-party transactions thiếu minh bạch có thể chuyển giá trị khỏi minority owners; analyst cần điều tra terms và approvals.","trap_vi":"Lack of disclosure is not automatic evidence of loss."},{"stem_en":"One benefit of strong stakeholder management is:","options":["Elimination of dividend decisions.","Lower probability of costly labor, customer or community disputes.","A guarantee that all competing interests are identical."],"correct":1,"why_vi":"Early engagement improves risk identification và continuity.","trap_vi":"Cannot prevent all disputes."},{"stem_en":"Poor management of suppliers is most likely to cause:","options":["An automatic reduction in all leverage.","Guaranteed faster payments from customers.","Operational disruptions and higher procurement costs."],"correct":2,"why_vi":"Supplier instability có thể gây delays, shortages, repair of relationship.","trap_vi":"Stakeholder management affects operations."},{"stem_en":"The case of a company ignoring critical safety or product-test warnings best illustrates:","options":["Weak board oversight and risk escalation.","Successful independent monitoring.","Zero operational risk."],"correct":0,"why_vi":"Management claims phải được independently checked để hạn chế costly harm.","trap_vi":"Do not simply accept persuasive founders."},{"stem_en":"Which outcome is least likely to be a benefit of effective governance?","options":["Better control of agency conflicts.","Guaranteed positive returns under all market conditions.","More credible disclosures."],"correct":1,"why_vi":"Governance tốt không loại bỏ toàn bộ market, operational hoặc credit risks, nên không thể đảm bảo lợi nhuận dương mọi trạng thái.","trap_vi":"Avoid guarantees."},{"stem_en":"A company has strong financial controls but poor customer-safety oversight. The most reasonable interpretation is:","options":["Strong accounting controls make customer harms impossible.","Disclosure is irrelevant.","Governance quality should be assessed across several functions."],"correct":2,"why_vi":"Governance không chỉ audit; product/operational risk also needs monitoring.","trap_vi":"One good committee doesn't assure all controls."},{"stem_en":"A company improves risk management and reduces expected annual incident losses. The most likely financial benefit is:","options":["Greater expected operating cash flows, other things equal.","An automatic increase in bond principal due.","Elimination of employee wages."],"correct":0,"why_vi":"Giảm sự cố có thể tăng expected future cash flows, nhưng phải trừ chi phí thiết lập và duy trì kiểm soát.","trap_vi":"Do not infer realized outcomes mechanically."},{"stem_en":"Which factor is most likely to support investor confidence?","options":["Unlimited manager perquisites.","Reliable reporting plus independent oversight.","Persistent concealment of losses."],"correct":1,"why_vi":"Audit integrity và credible board monitoring reduce information risk.","trap_vi":"Investor confidence is conditional."}],"cards":[{"front_en":"Explain: Weak governance overview","back_vi":"Weak governance khiến decision power ít được kiểm soát, thông tin sai lệch, stakeholder conflicts tích tụ và rủi ro mất value tăng. Outcomes phụ thuộc context, không phải every weakness always leads to scandal."},{"front_en":"Explain: Fraud and misreporting risk","back_vi":"Audit committee yếu, CEO dominance hoặc unreliable internal controls có thể dẫn tới false financial statements, concealment of liabilities và legal investigations."},{"front_en":"Explain: Misallocation of capital","back_vi":"Poor challenge to management khiến overexpansion, overpriced acquisitions và negative-NPV projects; owners may pay for executives' empire building."},{"front_en":"Explain: Excessive compensation","back_vi":"Pay structures không gắn long-term value có thể chuyển rent từ owners sang management hoặc encourage short-term risk taking."},{"front_en":"Explain: Related-party abuse","back_vi":"Controlling shareholders chuyển value qua private affiliated entities bằng non-arm's-length transactions, khiến minority equity diluted economically."},{"front_en":"Explain: Stakeholder neglect","back_vi":"Inadequate labor safety, customer protection, product testing, supplier ethics hoặc environmental compliance có thể gây production loss và sanctions."},{"front_en":"Explain: Legal and regulatory cost","back_vi":"Corporate misconduct có thể gây fines, damages, license withdrawal, deferred projects và financing restrictions."},{"front_en":"Explain: Operational inefficiency","back_vi":"Lack of controls tạo procurement waste, employee turnover, supply disruptions và weak execution."},{"front_en":"Explain: Reputation and trust","back_vi":"Investor/customer confidence mất có thể làm orders giảm, staff departures tăng, investor risk premium cao hơn; intangible confidence khó đo trực tiếp nhưng có thể material."},{"front_en":"Explain: Financing cost effect","back_vi":"Khi perceived governance/information risk cao, lenders và equity investors có thể yêu cầu higher expected returns, khiến debt/equity financing expensive."},{"front_en":"Explain: Liquidity/access to capital","back_vi":"Quality disclosures và strong governance có thể mở rộng investor base, cải thiện availability of outside financing; scandal có thể làm thị trường đóng lại trong lúc cần vốn."},{"front_en":"Explain: Creditor rating and covenant effects","back_vi":"Governance failures có thể khiến credit agencies revise rating/outlook, lenders tighten covenants hoặc require collateral, tùy loss severity."},{"front_en":"Explain: Unreliable valuation inputs","back_vi":"Earnings manipulation làm investment analysts overestimate free cash flow, growth hoặc underestimate liabilities; weak reporting reduces valuation confidence."},{"front_en":"Explain: Governance risk and fraud example","back_vi":"Trường hợp healthcare technology Theranos được CFAI dùng minh họa oversight kém, board thiếu expertise và whistleblower concerns không được xử lý hiệu quả."},{"front_en":"Explain: Environmental compliance example","back_vi":"CFAI sử dụng Volkswagen emissions scandal để cho thấy compliance failure, regulatory penalties và trust damage có thể gây ảnh hưởng đáng kể đến issuer."},{"front_en":"Explain: Strong board supervision","back_vi":"Independent, competent board có thể challenge strategy, monitor risk/appetite, review CEO compensation và replace failed leadership."},{"front_en":"Explain: Sound disclosure and audits","back_vi":"Credible financial statements, independent audits, internal controls và transparent risk reporting reduce information asymmetry and can improve confidence."},{"front_en":"Explain: Aligned incentives","back_vi":"Multi-year risk-adjusted pay, clawbacks, share-ownership requirements và transparent assessment giảm temptation manipulate quarterly measures."},{"front_en":"Explain: Stakeholder engagement benefits","back_vi":"Early consultation với regulators, workers, customers, communities và suppliers có thể prevent litigation/disruption và preserve social license to operate."},{"front_en":"Explain: Improved operating efficiency","back_vi":"Transparent accountability, standardized controls và timely escalation có thể reduce waste and fraud loss, increase execution quality và improve operating margins."},{"front_en":"Explain: Better strategic decision-making","back_vi":"Independent challenge, diversified board skills và risk review giúp avoid value-destructive acquisitions hoặc overconcentration."},{"front_en":"Explain: Lower perceived investment risk","back_vi":"Giảm uncertainty về reported results và protection of stakeholder claims có thể lower risk premium and increase valuation, all else equal."},{"front_en":"Explain: Greater long-run resilience","back_vi":"Governance culture khuyến khích reporting issues early, dự phòng rủi ro và sửa errors trước khi khủng hoảng, giúp preserve reputation/cash flows."},{"front_en":"Explain: Analyst evaluation practice","back_vi":"Xem governance structure, track record, incident history, reporting/audit quality, board skills, related-party dealings, compensation policy và regulator actions."},{"front_en":"Explain: Risk-benefit matrix","back_vi":"So sánh effectiveness of monitoring với probability/severity of management failures; benefits đo qua avoided costs, access to capital, cash-flow stability và value."},{"front_en":"Explain: Exam conclusion rule","back_vi":"Chọn answer phản ánh cả risks of poor governance lẫn benefits of strong: reputation, operating efficiency, capital access, cost of capital, financial reporting reliability."}]}]},{"module_id":"CFA26-03-04","module_title":"Working Capital and Liquidity","subject":"Corporate Issuers","version":"2.2","language":"Vietnamese teaching, English CFA terms and English exam questions","qa_status":"DETAILED_DRAFT_PENDING_INDEPENDENT_ACADEMIC_AUDIT","disclaimer_vi":"Ba LOS CFAI 2026 CI Module4 đã đối chiếu trang nguồn, và biên soạn ví dụ/MCQ mới hoàn toàn. Có những khung phụ trợ cho quản lý liquidity ngoài trọng tâm tính toán CFAI. Chưa nghiệm thu độc lập toàn bộ câu hỏi; không xem tỷ số đơn lẻ là chứng cứ thanh khoản đủ.","los":[{"id":"CFA26-03-04-LOS01","letter":"4.a","title_en":"Cash Conversion Cycle and Working Capital","outcome_en":"explain the cash conversion cycle and compare issuers’ cash conversion cycles","overview_vi":"Từ inventory → credit sale → receivables → cash, tính days inventory on hand (DIO), days sales outstanding (DSO), days payables outstanding (DPO) và cash conversion cycle (CCC). Phân biệt total và operating net working capital, các yếu tố rút ngắn/kéo dài kỳ chuyển đổi tiền mặt.","source":[{"id":"CFA Institute Curriculum 2026 — Corporate Issuers LM4","pages":"105–119 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading23","pages":"245–247 (physical PDF)"},{"id":"SAPP Corporate Issuers 2026 — Module4","pages":"99–112 (physical PDF)"}],"sections":[{"heading":"Operating cycle mechanics","body":"Doanh nghiệp mua materials, giữ inventory, bán goods/services, rồi thu receivables. Revenue và expense được ghi nhận theo accrual trước/sau cash flows, tạo nhu cầu tài trợ current assets.","trap":"Sales recognition does not automatically equal cash receipt."},{"heading":"Trade receivables","body":"Accounts receivable xuất hiện khi giao hàng/dịch vụ theo credit terms; được xóa khi khách thanh toán hoặc write-off.","trap":"Receivables may not all collect at book value."},{"heading":"Inventory timing","body":"Inventory là goods/materials held for production/sale, chiếm cash trước khi trở thành COGS. Slow turnover tạo inventory carrying cost và risk of obsolescence.","trap":"Inventory is recorded at cost conventions, not always sales price."},{"heading":"Accounts payable timing","body":"Accounts payable phát sinh khi issuer nhận goods/services nhưng chưa trả suppliers; trade credit tài trợ một phần operating cycle.","trap":"Extending payables can harm supplier relationships."},{"heading":"Cash conversion cycle definition","body":"CCC là số ngày giữa lúc chi cash cho suppliers và lúc nhận cash từ customers trong vòng operating cycle thông thường.","trap":"Negative CCC is possible."},{"heading":"Days inventory on hand","body":"DIO/DOH cho biết bình quân inventory được giữ bao lâu trước bán; tính từ average inventory và COGS.","trap":"Use COGS, not revenue, in denominator."},{"heading":"Days sales outstanding","body":"DSO đo số ngày trung bình phải thu chưa thu tiền sau credit sales; tính average receivables / revenue (hoặc net credit sales nếu có) × days.","trap":"Compare credit-sale definition across firms."},{"heading":"Days payables outstanding","body":"DPO đo số ngày trung bình issuer trì hoãn trả suppliers; tính average payables / COGS × days trong đơn giản hóa.","trap":"Purchases can be more accurate denominator when disclosed."},{"heading":"CCC identity","body":"CCC=DIO+DSO−DPO. DIO/DSO tăng làm CCC dài hơn; DPO tăng làm CCC ngắn hơn, nếu các yếu tố khác không đổi.","trap":"DPO carries a negative sign."},{"heading":"Operating cycle versus CCC","body":"Operating cycle=DIO+DSO từ inventory tới cash; CCC trừ DPO vì supplier financing làm rút ngắn thời gian firm tự bỏ tiền.","trap":"Do not subtract DPO when asked for operating cycle."},{"heading":"Negative CCC meaning","body":"CCC âm khi suppliers được trả sau khi cash từ customers đã vào; khách tài trợ turnover nhanh và trade payable dài có thể tạo cấu trúc này.","trap":"Negative CCC is not inherently bad or good without supplier context."},{"heading":"Working capital: total","body":"Total working capital trong cách dùng CFAI module này = current assets − current liabilities; cũng thường được gọi là net working capital trong FSA, nên phải nêu rõ convention.","trap":"Terminology is context-dependent."},{"heading":"Operating net working capital: CFAI","body":"Net working capital theo CFAI Corporate Issuers LM4 loại cash, marketable securities ở current assets và loại short-term/current debt ở current liabilities. Công thức: (CA − cash − marketable securities) − (CL − interest-bearing short-term debt).","trap":"Do not conflate with broad current assets minus current liabilities."},{"heading":"Operating NWC components","body":"Thành phần thường là accounts receivable + inventory + prepaid expenses − accounts payable − accrued liabilities, với các khoản operating khác khi có.","trap":"Exclude cash and interest-bearing current debt in the CFAI CI net definition."},{"heading":"Working capital to sales","body":"NWC/sales chuẩn hóa theo quy mô để so sánh issuers; cao có thể do inventory cần dài ngày hoặc collection yếu.","trap":"A high ratio can reflect business model, not necessarily inefficiency."},{"heading":"Average balance convention","body":"DSO/DIO/DPO thường dùng average beginning/end balance, với revenue/COGS theo cả kỳ; nếu chỉ dùng year-end balance cần disclose.","trap":"Seasonal firms may need monthly averages."},{"heading":"365 versus 360-day convention","body":"Một số exams/books dùng 365, một số 360 hoặc 90 cho quý. Chỉ dùng số ngày đề cung cấp và giữ nhất quán giữa các ratios.","trap":"Calendar basis can create small numeric differences."},{"heading":"Drivers that shorten CCC","body":"Accelerate collection, optimize inventory turnover, negotiate longer supplier terms sẽ giảm CCC; không phải thay đổi nào cũng miễn phí.","trap":"Tight credit may reduce sales."},{"heading":"Drivers that lengthen CCC","body":"Looser customer credit, safety stock hoặc early supplier payment khiến cash phải tài trợ lâu hơn, nếu các yếu tố khác không đổi.","trap":"Early payment may earn valuable discounts."},{"heading":"Inventory management tradeoff","body":"Just-in-time giảm DIO và cash tied-up nhưng tăng risk of supply shortage khi supply chain gián đoạn.","trap":"Lower DIO is not automatically optimal."},{"heading":"Receivables policy tradeoff","body":"Credit discount/tighter collection có thể giảm DSO nhưng mất gross margin hoặc sales volume; cần đánh giá benefit net.","trap":"Faster DSO can be achieved by costly discounts."},{"heading":"Supplier credit tradeoff","body":"DPO cao hỗ trợ liquidity nhưng có thể mất early-pay discount, đe dọa relationship và làm prices tăng.","trap":"DPO should not be increased without considering costs."},{"heading":"Industry model differences","body":"Retail cash sales thường DSO thấp, service firms ít inventory; aged products/makers có DIO cao; cross-industry CCC comparison cần context.","trap":"Do not interpret identical CCC as identical risk across industries."},{"heading":"Seasonality and comparability","body":"Year-end balances có thể chưa đại diện peak working capital; monthly/quarterly trends, revenue growth và supplier terms cần được kiểm tra.","trap":"A single CCC snapshot may mislead."},{"heading":"CCC and financing need","body":"CCC càng dài, issuer thường cần nhiều funds tài trợ inventory/AR trước khi thu cash, other things equal; ngắn có thể giải phóng cash.","trap":"Increases in sales can raise absolute working capital needs even with stable days ratios."},{"heading":"CCC and liquidity are not identical","body":"CCC là operating-timing metric; công ty có CCC thấp vẫn có thể thiếu cash nếu debt maturities lớn, funding access yếu hoặc operating losses.","trap":"Analyze liquidity ratios and funding separately."},{"heading":"Analyst CCC checklist","body":"Xác định sales/COGS đúng mẫu số, average balances, period days, operating vs cash cycle, sign của DPO, industry reason và financing cost.","trap":"Resist comparing CCC across dissimilar business models without adjustments."}],"formulas":[{"name":"Average receivables","expr":"Average A/R=(opening receivables+closing receivables)/2","meaning":"Balance dùng cho DSO.","conditions":"Simple two-point approximation; seasonality matters."},{"name":"Average inventory","expr":"Average inventory=(opening inventory+closing inventory)/2","meaning":"Balance dùng cho DIO.","conditions":"Matching period to COGS required."},{"name":"Average payables","expr":"Average A/P=(opening payables+closing payables)/2","meaning":"Balance dùng cho DPO.","conditions":"Supplier purchases are alternative denominator."},{"name":"Days sales outstanding","expr":"DSO=(average A/R / revenue)×days","meaning":"Số ngày collection bình quân.","conditions":"Use net credit sales if specified, otherwise revenue proxy."},{"name":"Days inventory on hand","expr":"DIO=(average inventory / cost of goods sold)×days","meaning":"Số ngày giữ hàng.","conditions":"Use COGS, not revenue."},{"name":"Days payable outstanding","expr":"DPO=(average A/P / COGS)×days","meaning":"Số ngày trả suppliers.","conditions":"COGS proxy in module; purchases may be preferable."},{"name":"Cash conversion cycle","expr":"CCC=DIO+DSO−DPO","meaning":"Thời gian cash bị tài trợ.","conditions":"Negative values valid."},{"name":"Operating cycle","expr":"OC=DIO+DSO","meaning":"Thời gian inventory-to-collection.","conditions":"Does not subtract supplier credit."},{"name":"Total working capital (CFAI CI)","expr":"TWC=current assets−current liabilities","meaning":"Quan hệ tài sản/nợ ngắn hạn.","conditions":"Elsewhere may be called net working capital."},{"name":"Operating NWC (CFAI CI)","expr":"NWC=(CA−cash−marketable securities)−(CL−short-term/current debt)","meaning":"Operating capital invested.","conditions":"Check components on statement."},{"name":"Operating NWC detail","expr":"NWC≈A/R+inventory+prepaids−A/P−accrued expenses","meaning":"Working capital excluding financing accounts.","conditions":"May include other operating accounts."},{"name":"Net working capital to sales","expr":"NWC margin=NWC / annual sales","meaning":"Scale normalization.","conditions":"Sales denominator may be low/negative in distressed firm."},{"name":"CCC change decomposition","expr":"ΔCCC=ΔDIO+ΔDSO−ΔDPO","meaning":"Phân tích nguyên nhân thay đổi.","conditions":"All days measures use comparable periods."},{"name":"DIO turnover relation","expr":"Inventory turnover=COGS/average inventory; DIO=days/turnover","meaning":"Link activity ratio to days.","conditions":"Not directly 1/DSO or DPO."},{"name":"DSO turnover relation","expr":"Receivables turnover=sales/average receivables; DSO=days/turnover","meaning":"Link collection and receivables.","conditions":"Net credit sales can matter."},{"name":"DPO turnover relation","expr":"Payables turnover≈COGS/average payables; DPO=days/turnover","meaning":"Short-term supplier terms.","conditions":"Purchases denominator often more precise."}],"examples":[{"question_en":"A retailer has DIO 50 days, DSO 10 days, and DPO 45 days. Compute its CCC.","answer":"15 days","steps_vi":["CCC=DIO+DSO−DPO=50+10−45.","Cash tied in operating cycle là 15 ngày trong average flow."],"check":"Subtract DPO."},{"question_en":"A firm has DIO 25, DSO 6, DPO 42. Compute CCC.","answer":"−11 days","steps_vi":["CCC=25+6−42=−11.","Cash collected before supplier payment on average; không phải firm tự động mất khả năng thanh toán."],"check":"Negative CCC is valid."},{"question_en":"Average inventory is $30m, annual COGS is $180m and a 360-day year is used. Compute DIO.","answer":"60 days","steps_vi":["DIO=30/180×360=60.","Mẫu số COGS chứ không phải revenue."],"check":"Annual basis must match."},{"question_en":"Average receivables are $12m, revenue is $144m and days=360. Compute DSO.","answer":"30 days","steps_vi":["DSO=12/144×360=30.","Doanh nghiệp thu tiền bình quân khoảng 30 ngày sau sale."],"check":"Compare with customer terms."},{"question_en":"Average payables are $18m, COGS is $216m and days=360. Compute DPO.","answer":"30 days","steps_vi":["DPO=18/216×360=30.","Trade credit hỗ trợ chiếm dụng vốn từ suppliers 30 ngày bình quân."],"check":"Supplier denominator proxy."},{"question_en":"A firm has DIO 40, DSO 32, DPO 36. Compute operating cycle and CCC.","answer":"Operating cycle 72 days; CCC 36 days","steps_vi":["OC=40+32=72; CCC=72−36=36.","Không trừ DPO khi hỏi operating cycle."],"check":"Distinguish concepts."},{"question_en":"Receivables are $6m at beginning and $10m at end. Calculate average A/R.","answer":"$8 million","steps_vi":["Average=(6+10)/2=8 triệu USD.","DSO dùng average AR nếu không có thông tin tốt hơn."],"check":"Two-point average may miss seasonality."},{"question_en":"A firm has current assets $140m and current liabilities $95m. Compute total working capital in CFAI CI convention.","answer":"$45 million","steps_vi":["TWC=CA−CL=140−95.","45 triệu USD."],"check":"Terminology convention matters."},{"question_en":"An issuer has A/R $30m, inventory $40m, prepaids $5m, A/P $20m, accrued expenses $10m. Calculate operating NWC.","answer":"$45 million","steps_vi":["Operating NWC=30+40+5−20−10.","45 triệu USD; cash and short-term bank debt không nằm trong mô hình operating NWC."],"check":"Correct account inclusion."},{"question_en":"An issuer has current assets $180m including cash $20m and marketable securities $10m, and current liabilities $120m including interest-bearing short-term debt $30m. Calculate operating NWC.","answer":"$60 million","steps_vi":["Operating assets=180−20−10=150; operating liabilities=120−30=90.","NWC=150−90=60m, khác broad TWC=60m trong tình huống trùng số này."],"check":"The two definitions can coincide accidentally."},{"question_en":"An issuer's DIO falls from 55 to 40 and DSO rises from 20 to 30; DPO unchanged. Compute change in CCC.","answer":"−5 days","steps_vi":["ΔCCC=(40−55)+(30−20)−0.","−15+10=−5 ngày: overall CCC ngắn hơn."],"check":"Analyze components not one metric."},{"question_en":"A firm has NWC $25m and annual sales $250m. Compute NWC to sales ratio.","answer":"10%","steps_vi":["25/250×100=10%.","Scale-based comparison cần industry context."],"check":"Relative rather than absolute level."},{"question_en":"Beginning inventory $16m and ending inventory $24m, annual COGS $100m, days=365. DIO is closest to?","answer":"73 days","steps_vi":["Average inventory=(16+24)/2=20m.","DIO=20/100×365=73 ngày."],"check":"Do not use ending balance alone."},{"question_en":"A distributor collects customers immediately, holds inventory 20 days, and pays suppliers 35 days later. Estimate CCC.","answer":"−15 days","steps_vi":["Nếu bán thu tiền ngay, DSO xấp xỉ 0; vì thế CCC = 20 + 0 − 35 = −15 ngày.","Doanh nghiệp có thể thu tiền của khách trước khi phải thanh toán nhà cung cấp."],"check":"Assumes prompt cash collection."},{"question_en":"A company's CCC increases from 25 to 50 days with sales unchanged. What happens to working capital financing need, other things equal?","answer":"It typically increases","steps_vi":["Cash tài trợ inventory/AR tồn lâu hơn trước khi nhận customer payment.","Financing need normally rises unless other structural changes offset."],"check":"Direction not exact amount."},{"question_en":"A firm wants to reduce CCC by 12 days without changing DIO or DSO. By how many days should DPO change?","answer":"Increase by 12 days","steps_vi":["ΔCCC=−ΔDPO khi hai thành phần khác fixed.","DPO tăng 12 làm CCC giảm 12, nhưng phải xét supplier financing cost."],"check":"Trade credit not always free."}],"questions":[{"stem_en":"A company has DIO 35, DSO 25, and DPO 40. Its CCC is:","options":["20 days.","100 days.","60 days."],"correct":0,"why_vi":"CCC=35+25−40=20 ngày.","trap_vi":"DPO is subtracted."},{"stem_en":"Which ratio uses cost of goods sold rather than sales as its typical denominator?","options":["Days sales outstanding.","Days inventory on hand.","A/R turnover."],"correct":1,"why_vi":"DIO = bình quân hàng tồn kho / COGS × số ngày trong kỳ; mẫu số dùng giá vốn, không phải doanh thu.","trap_vi":"Inventory relates to goods sold cost."},{"stem_en":"Which change most directly reduces CCC, all else equal?","options":["Higher DIO.","Higher DSO.","Higher DPO."],"correct":2,"why_vi":"CCC=DIO+DSO−DPO, nên DPO tăng làm CCC giảm.","trap_vi":"Supplier finance may be costly."},{"stem_en":"A firm collects customer payments before suppliers are paid. Its CCC may be:","options":["Equal to its annual interest rate.","Negative.","Necessarily positive."],"correct":1,"why_vi":"Negative CCC khi DPO lớn hơn DIO+DSO.","trap_vi":"Not equivalent to negative cash balance."},{"stem_en":"The operating cycle is calculated as:","options":["DIO+DSO−DPO.","DPO−DSO.","DIO+DSO."],"correct":2,"why_vi":"Operating cycle chưa trừ trade credit.","trap_vi":"CCC subtracts DPO."},{"stem_en":"Which action is most likely to lengthen CCC?","options":["More safety inventory with unchanged sales.","Longer supplier payment terms.","Tighter collection standards."],"correct":0,"why_vi":"Inventory giữ lâu hơn làm DIO tăng và CCC tăng.","trap_vi":"Inventory buffers may reduce stockouts."},{"stem_en":"An issuer reports average A/R $15m and annual sales $180m using 360 days. DSO equals:","options":["45 days.","10 days.","30 days."],"correct":2,"why_vi":"DSO = 15/180 × 360 = 30 ngày; đây là thời gian thu tiền bình quân.","trap_vi":"Sales denominator."},{"stem_en":"If DIO=60, DSO=20, and DPO=90, CCC is:","options":["−10 days.","170 days.","10 days."],"correct":0,"why_vi":"CCC = 60 + 20 − 90 = −10 ngày, nghĩa là tiền về trước hạn thanh toán cho nhà cung cấp.","trap_vi":"Negative is valid."},{"stem_en":"A lower DSO most directly indicates:","options":["Lower trade creditor payment frequency.","Faster receivables collection.","Slower inventory turnover."],"correct":1,"why_vi":"DSO đo cash collection delay from credit sales.","trap_vi":"DSO is not inventory days."},{"stem_en":"With annual COGS $240m, average payables $20m and 360 days, DPO is:","options":["30 days.","90 days.","60 days."],"correct":0,"why_vi":"DPO = 20/240 × 360 = 30 ngày; doanh nghiệp bình quân mất 30 ngày để thanh toán.","trap_vi":"Payables numerator."},{"stem_en":"CFAI CI operating net working capital typically excludes:","options":["Accounts receivable and inventory.","Cash, marketable securities and short-term debt.","Accounts payable and accrued expenses."],"correct":1,"why_vi":"Operating NWC tách financing/liquidity accounts khỏi operating current assets/liabilities.","trap_vi":"Contrast total WC."},{"stem_en":"An issuer has current assets $130m and current liabilities $90m. Its total WC is:","options":["$40m.","$220m.","−$40m."],"correct":0,"why_vi":"Total working capital = 130 − 90 = 40 triệu USD theo cách dùng của module.","trap_vi":"Broad CA less CL."},{"stem_en":"A 12-day increase in DPO, with DIO and DSO unchanged, changes CCC by:","options":["No change.","−12 days.","+12 days."],"correct":1,"why_vi":"ΔCCC=−ΔDPO, nên CCC giảm 12 ngày.","trap_vi":"Check sign."},{"stem_en":"Compared with 365 days, using 360 days consistently in turnover-day computations usually:","options":["Always doubles DSO.","Prevents CCC from being negative.","Produces slightly smaller days values."],"correct":2,"why_vi":"Formula nhân days, nên dùng 360 cho value thấp hơn 365, all else equal.","trap_vi":"Use specified convention."},{"stem_en":"Which can explain a high DIO without poor management?","options":["A zero inventory balance.","A regulated or aged-inventory business model.","All customers pay in cash."],"correct":1,"why_vi":"Aging product/regulated safety stock làm inventory cần giữ lâu; context matters.","trap_vi":"Industry comparison vital."},{"stem_en":"A firm reduces DIO by 5 days and DSO by 7 days, while DPO is unchanged. Its CCC:","options":["Does not change.","Increases by 12 days.","Decreases by 12 days."],"correct":2,"why_vi":"Mức thay đổi CCC = −5 −7 −0 = −12 ngày; giảm thời gian tồn kho và phải thu đều làm CCC giảm.","trap_vi":"Independent changes add."},{"stem_en":"If sales increase rapidly and CCC stays unchanged, absolute working capital may:","options":["Still increase with higher operating volume.","Always drop to zero.","Necessarily become negative."],"correct":0,"why_vi":"Nhu cầu vốn lưu động tuyệt đối vẫn tăng khi doanh thu và khoản phải thu/hàng tồn kho tăng, dù số ngày CCC không đổi.","trap_vi":"Days metrics do not measure dollar amount directly."},{"stem_en":"An issuer with negative CCC is necessarily:","options":["In breach of all debt covenants.","Unable to pay its liabilities.","Receiving funds from customers before average supplier payments."],"correct":2,"why_vi":"Negative CCC liên quan timing của receipts vs supplier payments, không tự xác định solvency.","trap_vi":"Require additional liquidity assessment."},{"stem_en":"Which balance is usually averaged when calculating DSO?","options":["Accounts receivable.","Retained earnings.","Long-term debt."],"correct":0,"why_vi":"DSO dùng average A/R.","trap_vi":"Period alignment."},{"stem_en":"What is the best way to compare CCC across two issuers?","options":["Compare the number without considering business models.","Use consistent accounting definitions and industry context.","Assume longer CCC always means financial distress."],"correct":1,"why_vi":"Industry, seasonality, terms và period conventions affect CCC comparability.","trap_vi":"Use more than one metric."}],"cards":[{"front_en":"Explain: Operating cycle mechanics","back_vi":"Doanh nghiệp mua materials, giữ inventory, bán goods/services, rồi thu receivables. Revenue và expense được ghi nhận theo accrual trước/sau cash flows, tạo nhu cầu tài trợ current assets."},{"front_en":"Explain: Trade receivables","back_vi":"Accounts receivable xuất hiện khi giao hàng/dịch vụ theo credit terms; được xóa khi khách thanh toán hoặc write-off."},{"front_en":"Explain: Inventory timing","back_vi":"Inventory là goods/materials held for production/sale, chiếm cash trước khi trở thành COGS. Slow turnover tạo inventory carrying cost và risk of obsolescence."},{"front_en":"Explain: Accounts payable timing","back_vi":"Accounts payable phát sinh khi issuer nhận goods/services nhưng chưa trả suppliers; trade credit tài trợ một phần operating cycle."},{"front_en":"Explain: Cash conversion cycle definition","back_vi":"CCC là số ngày giữa lúc chi cash cho suppliers và lúc nhận cash từ customers trong vòng operating cycle thông thường."},{"front_en":"Explain: Days inventory on hand","back_vi":"DIO/DOH cho biết bình quân inventory được giữ bao lâu trước bán; tính từ average inventory và COGS."},{"front_en":"Explain: Days sales outstanding","back_vi":"DSO đo số ngày trung bình phải thu chưa thu tiền sau credit sales; tính average receivables / revenue (hoặc net credit sales nếu có) × days."},{"front_en":"Explain: Days payables outstanding","back_vi":"DPO đo số ngày trung bình issuer trì hoãn trả suppliers; tính average payables / COGS × days trong đơn giản hóa."},{"front_en":"Explain: CCC identity","back_vi":"CCC=DIO+DSO−DPO. DIO/DSO tăng làm CCC dài hơn; DPO tăng làm CCC ngắn hơn, nếu các yếu tố khác không đổi."},{"front_en":"Explain: Operating cycle versus CCC","back_vi":"Operating cycle=DIO+DSO từ inventory tới cash; CCC trừ DPO vì supplier financing làm rút ngắn thời gian firm tự bỏ tiền."},{"front_en":"Explain: Negative CCC meaning","back_vi":"CCC âm khi suppliers được trả sau khi cash từ customers đã vào; khách tài trợ turnover nhanh và trade payable dài có thể tạo cấu trúc này."},{"front_en":"Explain: Working capital: total","back_vi":"Total working capital trong cách dùng CFAI module này = current assets − current liabilities; cũng thường được gọi là net working capital trong FSA, nên phải nêu rõ convention."},{"front_en":"Explain: Operating net working capital: CFAI","back_vi":"Net working capital theo CFAI CI LM4 = (current assets − cash − marketable securities) − (current liabilities − short-term/current debt)."},{"front_en":"Explain: Operating NWC components","back_vi":"Thành phần thường là accounts receivable + inventory + prepaid expenses − accounts payable − accrued liabilities, với các khoản operating khác khi có."},{"front_en":"Explain: Working capital to sales","back_vi":"NWC/sales chuẩn hóa theo quy mô để so sánh issuers; cao có thể do inventory cần dài ngày hoặc collection yếu."},{"front_en":"Explain: Average balance convention","back_vi":"DSO/DIO/DPO thường dùng average beginning/end balance, với revenue/COGS theo cả kỳ; nếu chỉ dùng year-end balance cần disclose."},{"front_en":"Explain: 365 versus 360-day convention","back_vi":"Một số exams/books dùng 365, một số 360 hoặc 90 cho quý. Chỉ dùng số ngày đề cung cấp và giữ nhất quán giữa các ratios."},{"front_en":"Explain: Drivers that shorten CCC","back_vi":"Accelerate collection, optimize inventory turnover, negotiate longer supplier terms sẽ giảm CCC; không phải thay đổi nào cũng miễn phí."},{"front_en":"Explain: Drivers that lengthen CCC","back_vi":"Looser customer credit, safety stock hoặc early supplier payment khiến cash phải tài trợ lâu hơn, nếu các yếu tố khác không đổi."},{"front_en":"Explain: Inventory management tradeoff","back_vi":"Just-in-time giảm DIO và cash tied-up nhưng tăng risk of supply shortage khi supply chain gián đoạn."},{"front_en":"Explain: Receivables policy tradeoff","back_vi":"Credit discount/tighter collection có thể giảm DSO nhưng mất gross margin hoặc sales volume; cần đánh giá benefit net."},{"front_en":"Explain: Supplier credit tradeoff","back_vi":"DPO cao hỗ trợ liquidity nhưng có thể mất early-pay discount, đe dọa relationship và làm prices tăng."},{"front_en":"Explain: Industry model differences","back_vi":"Retail cash sales thường DSO thấp, service firms ít inventory; aged products/makers có DIO cao; cross-industry CCC comparison cần context."},{"front_en":"Explain: Seasonality and comparability","back_vi":"Year-end balances có thể chưa đại diện peak working capital; monthly/quarterly trends, revenue growth và supplier terms cần được kiểm tra."},{"front_en":"Explain: CCC and financing need","back_vi":"CCC càng dài, issuer thường cần nhiều funds tài trợ inventory/AR trước khi thu cash, other things equal; ngắn có thể giải phóng cash."},{"front_en":"Explain: CCC and liquidity are not identical","back_vi":"CCC là operating-timing metric; công ty có CCC thấp vẫn có thể thiếu cash nếu debt maturities lớn, funding access yếu hoặc operating losses."},{"front_en":"Explain: Analyst CCC checklist","back_vi":"Xác định sales/COGS đúng mẫu số, average balances, period days, operating vs cash cycle, sign của DPO, industry reason và financing cost."}]},{"id":"CFA26-03-04-LOS02","letter":"4.b","title_en":"Liquidity Sources, Risks, and Financial Ratios","outcome_en":"explain liquidity and compare issuers’ liquidity levels","overview_vi":"Định nghĩa asset liquidity và issuer liquidity; primary/secondary funding, liquidation cost, operating cash flow/free cash flow, drags/pulls và các tỷ số current/quick/cash. Nêu cách đọc các tỷ số mâu thuẫn với nhau.","source":[{"id":"CFA Institute Curriculum 2026 — Corporate Issuers LM4","pages":"120–130 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading23","pages":"247–249 (physical PDF)"},{"id":"SAPP Corporate Issuers 2026 — Module4","pages":"113–123 (physical PDF)"}],"sections":[{"heading":"Asset liquidity","body":"Một asset liquid khi có thể chuyển thành cash nhanh với ít price concession/transaction cost; cash liquid nhất, marketable instruments thường liquid hơn inventory.","trap":"Liquid on paper does not guarantee executable market depth."},{"heading":"Liability liquidity","body":"Short-term payable due trong vài ngày gây immediate cash need hơn lease payment xa; timing of obligations là một phần liquidity analysis.","trap":"Balance amount alone is insufficient."},{"heading":"Issuer liquidity","body":"Khả năng issuer đáp ứng short-term obligations khi đến hạn, xét available cash, asset convertibility, operating inflows, funding access và maturity profile.","trap":"Profitability does not guarantee near-term liquidity."},{"heading":"Liquidity versus solvency","body":"Liquidity thiếu cash đúng thời điểm; insolvency là tài sản không đủ đáp ứng nghĩa vụ hoặc distress theo luật/financing. Một firm solvent vẫn có thể liquidity crisis.","trap":"Do not equate accounting profits with cash available."},{"heading":"Primary source: cash and securities","body":"Cash balances và easily saleable marketable instruments là readily accessible primary liquidity; vẫn cần xét restrictions/fees.","trap":"Restricted cash may not be freely available."},{"heading":"Primary source: operating cash flow","body":"Cash flow generated from recurring business là primary sustainable long-run funding source; losses hoặc growth strain có thể làm CFO âm.","trap":"Reported accounting NI is not CFO."},{"heading":"Primary source: borrowing","body":"Bank credit line, short-term debt và supplier trade credit cung cấp funds nhưng tạo future repayment obligations; funding availability depends on credit risk.","trap":"Borrowing is not free cash generation."},{"heading":"CFO: statement of cash flows","body":"CFO phản ánh cash paid/received từ core operations theo classification applicable; trong CFAI module, includes interest received/paid as presented.","trap":"Cash flow classification can vary by reporting standards."},{"heading":"Free cash flow in CI module","body":"FCF simplified = CFO − capital investments in long-term assets, khái niệm cash available after reinvestment; FCFF/FCFE definitions trong valuation có thể điều chỉnh lãi vay.","trap":"Do not substitute this for all formal FCFF models."},{"heading":"Secondary: suspend dividends","body":"Giữ lại cash bằng giảm distributions có thể hỗ trợ funding ngắn hạn, nhưng ảnh hưởng investor expectations và dividend clientele.","trap":"Dividends to common shareholders are usually discretionary."},{"heading":"Secondary: delay capex","body":"Dừng/lùi capex giúp cash immediate, nhưng có thể hại productive capacity/long-run value.","trap":"Avoid assuming capex postponement is costless."},{"heading":"Secondary: issue equity","body":"New share issuance raise cash nhưng có dilution, fees, time to market và unfavorable pricing in distress.","trap":"Selling existing holders' shares does not fund issuer."},{"heading":"Secondary: renegotiate obligations","body":"Refinance near-term debt, extend leases, renegotiate covenants/payables giúp delay cash outflows, nhưng creditors có thể demand compensation.","trap":"Agreement required; unilateral nonpayment risks default."},{"heading":"Secondary: asset sale","body":"Selling inventories, receivables, property hoặc subsidiary chuyển assets thành cash nhưng có transaction fees và sale-at-discount losses.","trap":"Forced-sale price may be below fair value."},{"heading":"Secondary: restructuring","body":"Bankruptcy protection và reorganization là extreme measures to stabilize obligations/capital structure, thường mất valuation flexibility và credit trust.","trap":"Not a normal first-choice liquidity source."},{"heading":"Liquidity liquidation costs","body":"Net proceeds=estimated fair value−selling fees−market discount; nhiều sources cần xét net amounts để plan funding.","trap":"Gross proceeds overstate cash available."},{"heading":"Liquidity drag","body":"Drag khi cash inflows bị trì hoãn hay unavailable: overdue receivables, obsolete inventory, restricted borrowing availability.","trap":"Drag relates primarily to weak/delayed receipts."},{"heading":"Liquidity pull","body":"Pull khi cash outflows accelerate: suppliers shorten trade credit, immediate payroll/tax expenses hoặc faster payments before receipts.","trap":"Pull is not just low sales revenue."},{"heading":"Borrowing constraints classification","body":"CFAI liệt kê credit tightening/borrowing constraints như drag: planned inflows from funding không đến đúng hạn.","trap":"Other authors may classify intuitively differently; follow CFAI framing."},{"heading":"Current ratio","body":"Current ratio=all current assets/current liabilities; inventory/prepaid có thể nâng chỉ số dù chưa chuyển thành cash dễ dàng.","trap":"Higher current ratio is not always greater true liquidity."},{"heading":"Quick ratio","body":"Quick=(cash+short-term marketable instruments+receivables)/current liabilities; loại inventory và prepaids khỏi numerator.","trap":"Receivables still require collection."},{"heading":"Cash ratio","body":"Cash ratio=(cash+short-term marketable instruments)/current liabilities; conservative nhất nếu current asset components đều không âm.","trap":"Cash ratio alone ignores future operating cash flows/credit lines."},{"heading":"Ratio ordering","body":"Với assets thông thường không âm: cash ratio ≤ quick ratio ≤ current ratio do numerator tăng dần và CL chung.","trap":"Equality possible if excluded balances are zero."},{"heading":"Conflicting signals","body":"Current ratio tăng do buildup inventory nhưng cash/quick ratios giảm cho thấy overall liquidity không nhất thiết tốt lên; xem numerator composition.","trap":"Choose conservative metric if question explicitly asks most liquid coverage."},{"heading":"CFO versus accounting profit","body":"Profit cao có thể đi cùng CFO thấp do revenue chưa collect hoặc inventory tăng. Cash available cho debt service phụ thuộc operations và financing timing.","trap":"Accrual revenue is not cash receipt."},{"heading":"Liquidity ratios across industries","body":"Retailers có quick inventory turnover và cash sale khác construction/manufacturers; các ratios nên so theo peer/seasonality/maturity schedule.","trap":"A uniform current-ratio threshold is simplistic."},{"heading":"Liquidation ranking","body":"Selling marketable securities thường rẻ/nhanh hơn selling special-use assets or subsidiary; thứ tự funding cần xét availability/cost/strategic value.","trap":"Actual markets can freeze in stress."},{"heading":"Stress liquidity planning","body":"Forecast cash due dates, alternative funding commitments, covenant headroom, contingency lines và operational buffers để tránh fire sales.","trap":"An undrawn credit line may be conditional."},{"heading":"Analyst assessment order","body":"Kiểm tra cash & marketable securities → quick assets → CFO and FCF → debt maturity/refinancing → secondary assets and sale discount.","trap":"Strong profitability alone is not sufficient."}],"formulas":[{"name":"Current ratio","expr":"Current ratio=Current assets / Current liabilities","meaning":"Broad near-term balance-sheet measure.","conditions":"Current assets can be illiquid."},{"name":"Quick ratio","expr":"Quick=(cash+marketable instruments+receivables)/current liabilities","meaning":"Ability to cover obligations without inventory disposal.","conditions":"Requires collectable receivables."},{"name":"Cash ratio","expr":"Cash ratio=(cash+marketable securities)/current liabilities","meaning":"Strictest of three ratios.","conditions":"May be below 1 despite robust CFO."},{"name":"Ratio ordering","expr":"Cash ratio ≤ quick ratio ≤ current ratio","meaning":"Under nonnegative included current assets.","conditions":"Same CL denominator."},{"name":"CFO simplified","expr":"CFO=cash customer receipts+other operating receipts−operating payments−taxes−interest paid (as CFAI CI module presents)","meaning":"Operating cash-flow concept.","conditions":"Reporting frameworks can differ in interest classification."},{"name":"Simplified FCF","expr":"Free cash flow=CFO−investment in long-term assets","meaning":"Cash remaining after capital expenditures.","conditions":"Definition differs from FCFF/FCFE in Equity."},{"name":"Net asset liquidation proceeds","expr":"Net proceeds=fair value×(1−liquidation cost rate)","meaning":"Available cash after fees/price loss.","conditions":"Rate applies to fair value."},{"name":"Total liquidation costs","expr":"Total cost=Σ fair value_i×cost rate_i","meaning":"Selling/restructuring loss in crisis.","conditions":"Percentages must be decimal."},{"name":"Total net proceeds","expr":"Total net=Σ fair value_i×(1−cost_i)","meaning":"Funding raised by multiple asset sales.","conditions":"Exclude tax if not specified."},{"name":"Liquidity gap","expr":"Funding shortfall=max(cash obligations−available liquidity,0)","meaning":"Short-term cash gap.","conditions":"Conceptual planning metric."},{"name":"CFO margin","expr":"CFO / revenue","meaning":"Supplemental measure cash generated per sales.","conditions":"Industry/seasonality matters."},{"name":"Cash to short-term debt","expr":"Cash and marketable investments / near-term debt maturities","meaning":"Focused maturity cushion.","conditions":"Not identical to CFAI standard cash ratio."},{"name":"Liquidation discount equivalent","expr":"Haircut rate=1−net proceeds/fair value","meaning":"Back out sale discount.","conditions":"Exclude taxes unless specified."},{"name":"Debt maturity ladder","expr":"Cash obligations by payment date versus available cash by date","meaning":"Stress-test timing.","conditions":"Conceptual tool, not a scalar ratio."},{"name":"Quick minus cash ratio","expr":"(A/R) / current liabilities","meaning":"Contribution of receivables to liquidity ratios.","conditions":"Assuming quick numerator includes A/R as above."},{"name":"Current minus quick","expr":"(inventory+other excluded current assets)/current liabilities","meaning":"Shows illiquid current asset contribution.","conditions":"Excluded assets include prepaids, etc."}],"examples":[{"question_en":"An issuer has cash $20m, marketable securities $10m, A/R $30m, inventory $50m, prepaid costs $5m, and current liabilities $50m. Find cash, quick, and current ratios.","answer":"0.60; 1.20; 2.30","steps_vi":["Cash ratio=(20+10)/50=0,60. Quick=(20+10+30)/50=1,20.","Current assets=115; current ratio=115/50=2,30; inventory chưa chắc quickly saleable."],"check":"Denominators equal."},{"question_en":"An issuer has cash $15m, short-term investments $5m, receivables $40m, inventories $60m, and current liabilities $80m. Calculate quick ratio.","answer":"0.75","steps_vi":["Quick=(15+5+40)/80=60/80.","Quick ratio=0,75; cần collections hoặc borrowing để cover remaining obligations."],"check":"Inventory excluded."},{"question_en":"An issuer has current assets $150m and current liabilities $75m. Compute current ratio.","answer":"2.00","steps_vi":["Current ratio=150/75=2,0.","Chỉ số cao không chứng minh toàn bộ assets convertible into cash immediately."],"check":"Review composition."},{"question_en":"A firm has cash $12m, marketable securities $8m, and current liabilities $100m. Compute cash ratio.","answer":"0.20","steps_vi":["Cash ratio=(12+8)/100=0,20.","Cash-only near-term coverage thấp, cần xét operational inflows/credit."],"check":"Current cash not total current assets."},{"question_en":"A firm reports CFO $120m and capital investment $70m. Compute simplified free cash flow.","answer":"$50 million","steps_vi":["FCF=CFO−long-term capex=120−70.","Đây là simplified FCF từ module, không đồng nhất mọi FCFF formula."],"check":"Capital investments cash amount given."},{"question_en":"A firm may sell equipment valued $40m at a 15% forced-sale haircut. Estimate net cash raised.","answer":"$34 million","steps_vi":["Chi phí bán gấp = 40 × 15% = 6 triệu USD.","Tiền thu ròng = 40 − 6 = 34 triệu USD."],"check":"Fair value assumed."},{"question_en":"A firm sells a $20m marketable security with a 1% fee and $10m receivables at a 12% discount. Find combined net proceeds.","answer":"$28.6 million","steps_vi":["Securities net=20×0,99=19,8m; A/R net=10×0,88=8,8m.","Tổng 28,6 triệu USD, liquidity cost 1,4m."],"check":"Do not sum gross value."},{"question_en":"A firm's receivables increase sharply while cash stays unchanged; what generally happens to current and cash ratios if liabilities unchanged?","answer":"Current ratio may rise; cash ratio is unchanged","steps_vi":["A/R tăng được tính vào current numerator nhưng cash numerator không đổi.","Cash ratio phản ánh conservative immediate coverage."],"check":"Check amounts and current-liability changes."},{"question_en":"An issuer faces overdue customers and suppliers demanding earlier payments. Identify drag and pull.","answer":"Overdue receivables: drag; earlier supplier payment: pull","steps_vi":["Drag = delayed cash inflow; pull = accelerated cash outflow.","Hai yếu tố cùng làm liquidity gap lớn hơn."],"check":"Categorize by timing of cash flows."},{"question_en":"An issuer has current assets $220m and current liabilities $110m, but most CA consists of obsolete inventory. Is a current ratio of 2 sufficient to conclude strong liquidity?","answer":"No","steps_vi":["Current ratio=2, nhưng obsolete inventory có thể phải sell at steep discount.","Cần quick/cash ratio, CFO và payment calendar."],"check":"Composition matters."},{"question_en":"A firm needs $25m immediately; cash+marketable available are $18m. Find simple liquidity gap.","answer":"$7 million","steps_vi":["Shortfall=max(25−18,0)=7m.","Cần sử dụng credit line, sale assets hoặc other funding, trong mô hình giả định."],"check":"Availability of credit uncertain."},{"question_en":"Cash $10m, ST investments $10m, receivables $30m, inventory $70m, other current assets $10m, CL $100m. Compare ratios.","answer":"Cash 0.20; quick 0.50; current 1.30","steps_vi":["Cash=(10+10)/100=0,2; quick=(10+10+30)/100=0,5.","Current=(10+10+30+70+10)/100=1,3; broad ratio khá cao dù near-cash coverage yếu."],"check":"Ratio order."},{"question_en":"An issuer has $50m asset fair value and $44m net sale proceeds. Calculate liquidation haircut percentage.","answer":"12%","steps_vi":["Haircut=1−44/50=0,12.","Haircut bao gồm price concessions/fees theo giả định."],"check":"Net, not gross."},{"question_en":"A firm has cash ratio 0.40 and quick ratio 1.10, current liabilities $100m. What receivables are implied, assuming quick includes only cash, marketable instruments, and A/R?","answer":"$70 million","steps_vi":["Chênh lệch quick ratio − cash ratio = 1,10 − 0,40 = 0,70.","Khoản phải thu suy ra = 0,70 × 100 triệu USD = 70 triệu USD."],"check":"Assumes same CL and numerator definitions."},{"question_en":"A firm has net income $50m but CFO is negative $20m due to receivables growth. Can it rely on accounting profit alone to meet short-term bills?","answer":"No","steps_vi":["Earnings theo accrual có thể chưa thu cash; liquidity needs near-term cash.","CFO âm chỉ ra challenge funding dù net income dương."],"check":"Earnings do not equal cash."},{"question_en":"A $10m inventory holding would require a 30% emergency discount to sell. What net proceeds would be expected?","answer":"$7 million","steps_vi":["Tiền thu từ bán tồn kho = 10 × (1 − 0,30) = 7 triệu USD.","Giảm giá thanh lý 3 triệu USD; do đó tồn kho kém thanh khoản hơn tiền mặt."],"check":"Fire sale risk."},{"question_en":"Two firms have equal current ratios, but A has $50m in cash and B has $50m in very slow inventory. Which is more immediately liquid, holding all else equal?","answer":"Firm A","steps_vi":["Tiền mặt có thể chi trả ngay; tồn kho chậm luân chuyển phải trải qua khâu bán và có thể giảm giá.","Cùng current ratio không đảm bảo cùng khả năng thanh toán tức thời."],"check":"Assess asset liquidity."}],"questions":[{"stem_en":"An issuer has current assets $120m and CL $60m. Its current ratio is:","options":["2.0.","0.5.","60.0."],"correct":0,"why_vi":"Current ratio = 120/60 = 2,0 lần; lấy tổng tài sản ngắn hạn chia nợ ngắn hạn.","trap_vi":"CA divided by CL."},{"stem_en":"Which asset is usually most liquid?","options":["Inventory awaiting sale.","Cash.","Special-purpose machinery."],"correct":1,"why_vi":"Tiền mặt có thể sử dụng ngay; tồn kho và máy móc cần bán mới chuyển thành tiền và có thể bị chiết khấu.","trap_vi":"Liquidity and profitability differ."},{"stem_en":"A firm's quick ratio numerator usually excludes:","options":["Cash.","Marketable short-term securities.","Inventory."],"correct":2,"why_vi":"Quick ratio gồm tiền, chứng khoán ngắn hạn và khoản phải thu; loại tồn kho vì cần thời gian bán.","trap_vi":"Prepaids also excluded."},{"stem_en":"A firm with cash $25m, marketable securities $5m and CL $100m has cash ratio:","options":["0.30.","1.00.","3.00."],"correct":0,"why_vi":"Cash ratio = (25+5)/100 = 0,30 lần; không đưa khoản phải thu hay tồn kho vào tử số.","trap_vi":"Excludes receivables/inventory."},{"stem_en":"Which of the following is typically a primary liquidity source?","options":["Issuing new equity in an emergency.","Operating cash flow.","Delaying strategic capital investment."],"correct":1,"why_vi":"Dòng tiền hoạt động lặp lại (CFO) là nguồn thanh khoản chính giúp doanh nghiệp thực hiện nghĩa vụ.","trap_vi":"Equity issue/capex delay secondary in CFAI classification."},{"stem_en":"Which action is a secondary liquidity source?","options":["Cash already on hand.","Normal operating cash receipts.","Renegotiating debt maturities."],"correct":2,"why_vi":"Tái cấu trúc kỳ hạn nợ là nguồn thanh khoản thứ cấp vì cần đàm phán, không xuất hiện thường xuyên.","trap_vi":"Can impose fees/conditions."},{"stem_en":"A company sells an asset worth $30m at a 20% discount. Net proceeds are:","options":["$24m.","$6m.","$36m."],"correct":0,"why_vi":"Tiền thu ròng = 30×(1−0,20)=24 triệu USD; thiệt hại thanh lý là 6 triệu USD.","trap_vi":"Liquidity haircut reduces funds."},{"stem_en":"A drag on liquidity most directly describes:","options":["Taxes paid a month early.","Customer collections arriving later than expected.","Supplier bills being accelerated."],"correct":1,"why_vi":"Liquidity drag xảy ra khi dòng tiền vào chậm hoặc giảm, như khách hàng trả chậm khoản phải thu.","trap_vi":"Pull accelerates outflows."},{"stem_en":"Which event is a liquidity pull?","options":["Marketable securities become easier to sell.","Credit sales are collected promptly.","Suppliers shorten trade credit terms."],"correct":2,"why_vi":"Khi nhà cung cấp đòi trả sớm hơn, tiền ra nhanh hơn: đó là liquidity pull.","trap_vi":"Pull not drag."},{"stem_en":"An issuer's current ratio rises because obsolete inventory accumulates. The most reasonable conclusion is:","options":["The ratio may mask deteriorating asset quality.","Credit risk disappears.","Liquidity definitely improves."],"correct":0,"why_vi":"Tồn kho khó bán nên current ratio có thể che giấu rủi ro; cần thêm quick ratio, cash ratio và CFO.","trap_vi":"Composition matters."},{"stem_en":"Which ordering generally applies to cash, quick and current ratios?","options":["Quick ≤ cash ≤ current.","Cash ≤ quick ≤ current.","Current ≤ quick ≤ cash."],"correct":1,"why_vi":"Với cùng mẫu số nợ ngắn hạn, tử số được mở rộng dần: cash ≤ quick ≤ current.","trap_vi":"Assuming ordinary nonnegative items."},{"stem_en":"A company has $80m CFO and $50m investment in long-term assets. Simplified FCF is:","options":["$130m.","$50m.","$30m."],"correct":2,"why_vi":"FCF đơn giản = CFO − capex = 80 − 50 = 30 triệu USD.","trap_vi":"Note definition."},{"stem_en":"A company's net income is positive but operating cash flow negative. This most likely means:","options":["Accrual earnings do not necessarily provide near-term cash.","No new financing could ever be raised.","Profitability automatically covers all obligations."],"correct":0,"why_vi":"Lợi nhuận hạch toán có thể chưa thành tiền vì các biến động vốn lưu động, đặc biệt tăng khoản phải thu.","trap_vi":"Analyze cash timing."},{"stem_en":"A company has current assets $150m, CL $100m, and quick assets $60m. Quick ratio is:","options":["1.50.","0.60.","0.40."],"correct":1,"why_vi":"Quick ratio = 60/100 = 0,60; chỉ dùng các quick assets đã cho.","trap_vi":"Do not use total CA."},{"stem_en":"Liquidation cost of a fair value $50m asset at 12% is:","options":["$44m.","$5m.","$6m."],"correct":2,"why_vi":"Chi phí thanh lý = 50×12%=6 triệu USD, nên tiền thu ròng bằng 44 triệu USD.","trap_vi":"Differentiate cost vs net."},{"stem_en":"An issuer raises funds by selling a subsidiary at a steep discount. This is generally:","options":["A secondary, potentially costly liquidity source.","Guaranteed growth capex funding without loss.","A routine primary operating cash inflow."],"correct":0,"why_vi":"Bán công ty con có thể đem lại tiền nhưng làm mất tài sản chiến lược và bị giảm giá khi cần bán gấp.","trap_vi":"Source classification."},{"stem_en":"If a borrowing constraint cuts off expected credit line funds, the CFAI framework treats this primarily as:","options":["Guaranteed liquidity improvement.","Liquidity drag.","Liquidity pull only."],"correct":1,"why_vi":"Borrowing constraint làm nguồn cash inflow dự kiến không tới.","trap_vi":"Follow CFAI definition."},{"stem_en":"An issuer has cash ratio 0.2, quick 0.9, current 1.8. Its asset composition most likely includes:","options":["No receivables or inventory.","Cash sufficient for all CL.","Material less-liquid assets such as inventory."],"correct":2,"why_vi":"Chênh lệch current và quick lớn cho thấy inventory/prepaid có tỷ trọng lớn.","trap_vi":"Composition matters."},{"stem_en":"A firm needs $12m of near-term liquidity but has immediately available cash $9m. Funding gap is:","options":["$3m.","$9m.","$21m."],"correct":0,"why_vi":"Thiếu hụt thanh khoản = max(12−9,0)=3 triệu USD cần nguồn tài trợ bổ sung.","trap_vi":"More assets may be converted at cost."},{"stem_en":"A 15% forced sale discount on $40m equipment implies net proceeds:","options":["$40m.","$34m.","$6m."],"correct":1,"why_vi":"Tiền thu sau chiết khấu = 40×0,85 = 34 triệu USD.","trap_vi":"Price concession is 6m."},{"stem_en":"Which ratio is the most conservative near-term balance-sheet liquidity measure among these three?","options":["Current ratio.","Quick ratio.","Cash ratio."],"correct":2,"why_vi":"Cash ratio chỉ tính tiền và chứng khoán ngắn hạn; khoản phải thu hoặc tồn kho không thuộc tử số.","trap_vi":"Does not capture future cash generation."},{"stem_en":"Which item most directly shortens the time between a cash sale and cash collection?","options":["A cash sale typically has DSO close to zero.","A high inventory aging period.","Longer payable days."],"correct":0,"why_vi":"Nếu khách trả ngay, công ty không có độ trễ thu tiền từ trade receivables.","trap_vi":"Trade processing time may differ."},{"stem_en":"Which action may strengthen near-term liquidity but impair long-term competitiveness?","options":["Maintaining appropriate emergency cash.","Delaying productive capital investments.","Collecting receivables owed."],"correct":1,"why_vi":"Hoãn đầu tư vốn giúp giữ tiền hiện tại nhưng có thể làm giảm năng lực sản xuất và doanh thu tương lai.","trap_vi":"Consider opportunity cost."},{"stem_en":"Why can two issuers with identical current ratios have different financial risk?","options":["All current assets have identical liquidity.","Reporting standards eliminate business model differences.","Asset liquidity, maturity timing, and access to funding may differ."],"correct":2,"why_vi":"Cash composition, future cash flow và refinancing determine real liquidity beyond a broad ratio.","trap_vi":"Ratio is only a snapshot."}],"cards":[{"front_en":"Explain: Asset liquidity","back_vi":"Một asset liquid khi có thể chuyển thành cash nhanh với ít price concession/transaction cost; cash liquid nhất, marketable instruments thường liquid hơn inventory."},{"front_en":"Explain: Liability liquidity","back_vi":"Short-term payable due trong vài ngày gây immediate cash need hơn lease payment xa; timing of obligations là một phần liquidity analysis."},{"front_en":"Explain: Issuer liquidity","back_vi":"Khả năng issuer đáp ứng short-term obligations khi đến hạn, xét available cash, asset convertibility, operating inflows, funding access và maturity profile."},{"front_en":"Explain: Liquidity versus solvency","back_vi":"Liquidity thiếu cash đúng thời điểm; insolvency là tài sản không đủ đáp ứng nghĩa vụ hoặc distress theo luật/financing. Một firm solvent vẫn có thể liquidity crisis."},{"front_en":"Explain: Primary source: cash and securities","back_vi":"Cash balances và easily saleable marketable instruments là readily accessible primary liquidity; vẫn cần xét restrictions/fees."},{"front_en":"Explain: Primary source: operating cash flow","back_vi":"Cash flow generated from recurring business là primary sustainable long-run funding source; losses hoặc growth strain có thể làm CFO âm."},{"front_en":"Explain: Primary source: borrowing","back_vi":"Bank credit line, short-term debt và supplier trade credit cung cấp funds nhưng tạo future repayment obligations; funding availability depends on credit risk."},{"front_en":"Explain: CFO: statement of cash flows","back_vi":"CFO phản ánh cash paid/received từ core operations theo classification applicable; trong CFAI module, includes interest received/paid as presented."},{"front_en":"Explain: Free cash flow in CI module","back_vi":"FCF simplified = CFO − capital investments in long-term assets, khái niệm cash available after reinvestment; FCFF/FCFE definitions trong valuation có thể điều chỉnh lãi vay."},{"front_en":"Explain: Secondary: suspend dividends","back_vi":"Giữ lại cash bằng giảm distributions có thể hỗ trợ funding ngắn hạn, nhưng ảnh hưởng investor expectations và dividend clientele."},{"front_en":"Explain: Secondary: delay capex","back_vi":"Dừng/lùi capex giúp cash immediate, nhưng có thể hại productive capacity/long-run value."},{"front_en":"Explain: Secondary: issue equity","back_vi":"New share issuance raise cash nhưng có dilution, fees, time to market và unfavorable pricing in distress."},{"front_en":"Explain: Secondary: renegotiate obligations","back_vi":"Refinance near-term debt, extend leases, renegotiate covenants/payables giúp delay cash outflows, nhưng creditors có thể demand compensation."},{"front_en":"Explain: Secondary: asset sale","back_vi":"Selling inventories, receivables, property hoặc subsidiary chuyển assets thành cash nhưng có transaction fees và sale-at-discount losses."},{"front_en":"Explain: Secondary: restructuring","back_vi":"Bankruptcy protection và reorganization là extreme measures to stabilize obligations/capital structure, thường mất valuation flexibility và credit trust."},{"front_en":"Explain: Liquidity liquidation costs","back_vi":"Net proceeds=estimated fair value−selling fees−market discount; nhiều sources cần xét net amounts để plan funding."},{"front_en":"Explain: Liquidity drag","back_vi":"Drag khi cash inflows bị trì hoãn hay unavailable: overdue receivables, obsolete inventory, restricted borrowing availability."},{"front_en":"Explain: Liquidity pull","back_vi":"Pull khi cash outflows accelerate: suppliers shorten trade credit, immediate payroll/tax expenses hoặc faster payments before receipts."},{"front_en":"Explain: Borrowing constraints classification","back_vi":"CFAI liệt kê credit tightening/borrowing constraints như drag: planned inflows from funding không đến đúng hạn."},{"front_en":"Explain: Current ratio","back_vi":"Current ratio=all current assets/current liabilities; inventory/prepaid có thể nâng chỉ số dù chưa chuyển thành cash dễ dàng."},{"front_en":"Explain: Quick ratio","back_vi":"Quick=(cash+short-term marketable instruments+receivables)/current liabilities; loại inventory và prepaids khỏi numerator."},{"front_en":"Explain: Cash ratio","back_vi":"Cash ratio=(cash+short-term marketable instruments)/current liabilities; conservative nhất nếu current asset components đều không âm."},{"front_en":"Explain: Ratio ordering","back_vi":"Với assets thông thường không âm: cash ratio ≤ quick ratio ≤ current ratio do numerator tăng dần và CL chung."},{"front_en":"Explain: Conflicting signals","back_vi":"Current ratio tăng do buildup inventory nhưng cash/quick ratios giảm cho thấy overall liquidity không nhất thiết tốt lên; xem numerator composition."},{"front_en":"Explain: CFO versus accounting profit","back_vi":"Profit cao có thể đi cùng CFO thấp do revenue chưa collect hoặc inventory tăng. Cash available cho debt service phụ thuộc operations và financing timing."},{"front_en":"Explain: Liquidity ratios across industries","back_vi":"Retailers có quick inventory turnover và cash sale khác construction/manufacturers; các ratios nên so theo peer/seasonality/maturity schedule."},{"front_en":"Explain: Liquidation ranking","back_vi":"Selling marketable securities thường rẻ/nhanh hơn selling special-use assets or subsidiary; thứ tự funding cần xét availability/cost/strategic value."},{"front_en":"Explain: Stress liquidity planning","back_vi":"Forecast cash due dates, alternative funding commitments, covenant headroom, contingency lines và operational buffers để tránh fire sales."},{"front_en":"Explain: Analyst assessment order","back_vi":"Kiểm tra cash & marketable securities → quick assets → CFO and FCF → debt maturity/refinancing → secondary assets and sale discount."}]},{"id":"CFA26-03-04-LOS03","letter":"4.c","title_en":"Working Capital and Liquidity Management Strategies","outcome_en":"describe issuers’ objectives and compare methods for managing working capital and liquidity","overview_vi":"Mục tiêu cân bằng cash availability và invested capital, phân biệt permanent/variable current assets và conservative, aggressive, moderate/matching funding. Quản lý inventory, trade credit, seasonal funding, lines of credit, discounts và liquidity contingency.","source":[{"id":"CFA Institute Curriculum 2026 — Corporate Issuers LM4","pages":"131–139 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading23","pages":"249–253 (physical PDF)"},{"id":"SAPP Corporate Issuers 2026 — Module4","pages":"123–134 (physical PDF)"}],"sections":[{"heading":"Value-focused working capital objective","body":"Quản lý WC nhằm tối đa value với đủ cash trả short-term liabilities; tránh overinvestment cash/inventory/AR nhưng cũng không đẩy issuer vào financial distress.","trap":"Lowest current assets possible is not always optimal."},{"heading":"Permanent current assets","body":"Nhu cầu base level inventory, receivables và cash duy trì liên tục để vận hành doanh nghiệp ngay trong mùa thấp.","trap":"Permanent is an operating floor, not long-term fixed assets."},{"heading":"Variable current assets","body":"Extra working capital do seasonal peaks, promotion, growth hoặc unexpected demand; thường biến động theo revenue.","trap":"Seasonal financing should match duration when possible."},{"heading":"Working capital investment sizing","body":"Forecast sales, credit terms, inventory days và payable policies để estimate dollars of current assets/liabilities; tăng doanh thu thường cần thêm vốn.","trap":"CCC alone cannot predict absolute cash needs."},{"heading":"Conservative strategy basics","body":"Giữ nhiều cash/safety inventory và funded current assets bằng relatively more long-term financing, giảm refinancing risk nhưng có higher carry/financing cost.","trap":"Not automatically superior for shareholder return."},{"heading":"Conservative strategy advantages","body":"Cushion chống credit-market disruption, inventory shortages và unexpected demand; stable funding thích hợp early-stage/uncertain access.","trap":"Higher buffers create opportunity costs."},{"heading":"Conservative strategy disadvantages","body":"Cash/inventory carrying costs và costly long-term funding làm reduce returns if overused.","trap":"Safety has a price."},{"heading":"Aggressive strategy basics","body":"Giảm excess current assets và dùng nhiều short-term debt để finance current capital; potentially lower cost và higher return nhưng liquidity/refinancing risk lớn.","trap":"Cheap short-term debt can reset at higher rates."},{"heading":"Aggressive strategy advantages","body":"Giảm vốn lưu động được đầu tư bình quân có thể giúp tăng hiệu quả vốn và ROIC khi các điều kiện vận hành ổn định, nhưng cần xét stockouts và chi phí rủi ro.","trap":"Must account for losses from stockouts or delinquent customers."},{"heading":"Aggressive strategy disadvantages","body":"Rollover/refinancing exposure, sensitivity to interest-rate spikes và operational disruptions; stress market access may disappear.","trap":"Profitability does not guarantee refinancing."},{"heading":"Moderate matching strategy","body":"Long-term financing cho permanent current assets và short-term funding cho variable/seasonal needs; cân bằng cost với liquidity protection.","trap":"Matching does not eliminate credit risk."},{"heading":"Conservative versus aggressive on yield curve","body":"Long-term financing often higher cost than short-term; chi phí thực thay đổi theo yield curve và issuer credit.","trap":"An inverted curve can invalidate simple cost comparisons."},{"heading":"Inventory policy: safety stock","body":"Safety stock giảm nguy cơ stockouts nhưng tăng DIO, storage/obsolescence, insurance costs.","trap":"Optimal buffer depends on supply/demand volatility."},{"heading":"Inventory policy: JIT","body":"Just-in-time giảm inventory/cash tied-up nhưng tăng exposure khi suppliers delay hoặc demand spikes.","trap":"JIT not universally appropriate for fragile supply chains."},{"heading":"Accounts receivable: credit terms","body":"More generous credit có thể raise sales nhưng tăng DSO, bad debt và billing cost. Tighter policy giảm AR nhưng có thể lose customers.","trap":"Credit sales must be evaluated by net economic profit."},{"heading":"Early payment discounts to customers","body":"Cash discount tăng tốc collection nhưng giảm effective selling price; đánh giá incremental financing saved so với lost margin.","trap":"Discount may be expensive for modest acceleration."},{"heading":"Payables and supplier discounts","body":"Chậm trả suppliers tăng DPO, nhưng mất early-payment discount có implicit financing cost; tính effective annual cost trước quyết định.","trap":"A 2% discount over 20 days can have high annualized cost."},{"heading":"Trade credit terms 2/10 net 30","body":"Nếu trả trong 10 ngày được discount 2%; phải trả full invoice trong 30 ngày. Bỏ discount giống vay khoảng 98 để trả thêm 2 trong 20 ngày.","trap":"The implied periodic cost uses discount/(1−discount)."},{"heading":"Short-term funding sources","body":"Bank lines, overdrafts, commercial paper, asset-backed borrowing, trade credit, factoring và securitization tùy size, credit quality và legal environment.","trap":"Not every issuer can tap commercial paper markets."},{"heading":"Committed versus uncommitted lines","body":"Committed facility thường có contractual access subject conditions, uncommitted line bank có thể withdraw; commitment fee/covenants tạo tradeoff.","trap":"Committed does not mean no covenants or conditions."},{"heading":"Commercial paper","body":"Short-term unsecured debt thường dành cho large/high-credit issuers, exposed to rollover market conditions.","trap":"Access is not universal for small/weak borrowers."},{"heading":"Receivables factoring","body":"Bán A/R cho factor để nhận cash sớm, có discount/fees và recourse/nonrecourse differences.","trap":"Sale price can be below face; risk transfer terms vary."},{"heading":"Asset-based borrowing","body":"Pledge receivables/inventory làm collateral for loan, improving liquidity without direct sale nhưng tạo repayment/pledge restrictions.","trap":"Collateral can deteriorate and borrowing base may shrink."},{"heading":"Liquidity funding decision","body":"Khi chọn nguồn tài trợ, xem xét tổng chi phí gồm phí, kỳ hạn, khả năng tiếp cận, tốc độ giải ngân, ràng buộc pháp lý, tài sản bảo đảm, credit rating và tác động vận hành; không chỉ nhìn lãi suất niêm yết.","trap":"Cheapest stated rate can have hidden conditions."},{"heading":"Early warning indicators","body":"DSO slippage, declining cash/quick ratios, falling CFO, covenant pressure, credit line cuts và stock obsolescence báo liquidity weakness.","trap":"Signs require context; do not infer default solely from one ratio."},{"heading":"Contingency liquidity plan","body":"Cash forecasts, diversified facilities, liquid securities, risk limits, supplier/customer escalation và backup funding needed for stresses.","trap":"Reliance on one revolving line is concentrated risk."},{"heading":"Crisis response hierarchy","body":"Ưu tiên cash holdings/operating cash/committed funding, xét sale cost/strategic consequences của secondary sources nếu needed.","trap":"In a crisis timing may dominate nominal cost."},{"heading":"Growth versus liquidity","body":"Growth có thể cần tăng inventory, A/R và capex dù profitable; liquidity forecast phải anticipate cash gap trước khi sales convert to cash.","trap":"Rapid growth can create cash strain."},{"heading":"Analyst strategy comparison","body":"Tổng hợp chiến lược: conservative duy trì đệm tài sản ngắn hạn và dùng nhiều vốn dài hạn; aggressive giữ đệm mỏng và dùng nhiều nợ ngắn hạn; moderate/matching ghép thời hạn tài trợ với tính thường trực/mùa vụ. Lựa chọn theo chu kỳ sống và rủi ro kinh doanh.","trap":"Do not choose a strategy solely from current ratio."}],"formulas":[{"name":"Permanent versus variable WC","expr":"Required current assets = base/permanent component + seasonal/variable component","meaning":"Forecast working capital.","conditions":"Conceptual split may be estimated."},{"name":"Moderate funding match","expr":"Long-term funds cover permanent WC; short-term funds cover seasonal WC","meaning":"Duration matching framework.","conditions":"Refinancing/asset duration remain imperfect."},{"name":"Effective implicit trade credit cost","expr":"Periodic cost = discount/(1−discount)","meaning":"Cost of forgoing early-pay cash discount.","conditions":"Assumes payment at the end of net term."},{"name":"Trade credit annualized simple","expr":"Simple annual cost≈[d/(1−d)]×[365/(net days−discount days)]","meaning":"Approx annualized opportunity cost.","conditions":"Annual convention / credit terms must match."},{"name":"Trade credit effective annual","expr":"Effective annual cost=[1+d/(1−d)]^(365/(net−discount days))−1","meaning":"Compounded implied borrowing rate.","conditions":"Assumes repeated comparable terms all year."},{"name":"Inventory investment","expr":"Extra inventory cash ≈ additional inventory units×unit cost","meaning":"Working capital cash tied-up.","conditions":"Ignore financing cost and obsolescence."},{"name":"Accounts receivable investment","expr":"Additional A/R≈increase in credit sales/day×DSO + existing sales/day×increase in DSO","meaning":"Decompose credit growth and collection delay.","conditions":"Approximation, may need cross-term for simultaneous changes."},{"name":"Collection days reduction","expr":"Δfunds released≈daily credit sales×days reduced","meaning":"Cash released by shorter DSO.","conditions":"Assumes stable sales and collected at book value."},{"name":"Carrying cost","expr":"Annual WC carry cost≈average financed WC×financing rate","meaning":"Opportunity/interest cost.","conditions":"Simplified, excludes stockouts/credit losses."},{"name":"Factoring cash","expr":"Net factoring proceeds=receivable face×(1−fee/discount rate)","meaning":"Liquidity from sale A/R.","conditions":"Real deals may have retention reserves and recourse."},{"name":"Cash gap forecast","expr":"Cumulative future cash=initial cash+receipts−payments","meaning":"Liquidity scheduling.","conditions":"Timing and committed funding should be modeled."},{"name":"Working capital turnover","expr":"Sales / average operating NWC","meaning":"Capital efficiency indicator.","conditions":"Negative NWC makes ratio hard to interpret."}],"examples":[{"question_en":"A firm has $50m permanent WC and $20m seasonal WC. Under a moderate matching strategy, how should it broadly finance them?","answer":"Long-term funding for $50m; short-term funding for $20m","steps_vi":["Base current assets cần nguồn vốn dài hạn ổn định; seasonal demand có thể dùng short-term funds.","Matching duration giúp giảm rollover of permanent needs."],"check":"Simple duration matching."},{"question_en":"An issuer has trade terms 2/10 net 30. What is the approximate simple annualized cost of foregoing the discount using 365 days?","answer":"37.24%","steps_vi":["Chi phí mỗi kỳ 20 ngày = 0,02/0,98 = 2,0408%.","Lãi đơn quy năm ≈ 0,020408 × 365/20 = 37,24%; trả chậm có chi phí ngầm rất cao."],"check":"Not equivalent to effective compounded annual."},{"question_en":"For 2/10 net 30, what is approximate effective annual cost of foregoing discount?","answer":"44.59%","steps_vi":["Hệ số tiền phải trả sau 20 ngày so với trả sớm là 1/0,98.","Lãi suất hiệu dụng năm = (1/0,98)^(365/20) − 1 ≈ 44,59%, khác phép quy đổi lãi đơn."],"check":"Check annual convention."},{"question_en":"A firm with stable credit sales $1m per day reduces DSO from 50 to 42 days. Estimate receivables cash released.","answer":"$8 million","steps_vi":["Thời gian thu tiền giảm từ 50 xuống 42 ngày, tức giảm 8 ngày.","Tổng vốn giải phóng ≈ 1 triệu USD/ngày × 8 ngày = 8 triệu USD khi doanh số không đổi."],"check":"Assumes no change in default/price."},{"question_en":"A company raises inventory by $3m to avoid stockouts. Annual financing cost is 8%. Estimate yearly carry cost.","answer":"$240,000","steps_vi":["Chi phí tài trợ cho 3 triệu USD tồn kho bổ sung = 3 triệu × 8% = 240.000 USD/năm.","Cần so sánh với lợi ích giảm mất doanh thu/lợi nhuận do hết hàng."],"check":"Excludes warehouse costs."},{"question_en":"An issuer sells $25m receivables at a 3% factoring discount. Estimate immediate proceeds.","answer":"$24.25 million","steps_vi":["Phí chiết khấu factoring = 25 triệu × 3% = 0,75 triệu USD.","Tiền thu tức thời = 25 − 0,75 = 24,25 triệu USD; điều kiện truy đòi cũng quan trọng."],"check":"Face versus net."},{"question_en":"A firm begins with $12m cash, expects $30m receipts and $38m payments next month. Forecast ending cash.","answer":"$4 million","steps_vi":["Số dư tiền cuối tháng = 12 + 30 − 38 = 4 triệu USD.","Dù dương, doanh nghiệp vẫn cần đệm thanh khoản vì thời điểm chi trả có thể đến trước thu tiền."],"check":"Timing within month may create interim shortfalls."},{"question_en":"An early-stage firm cannot reliably refinance short-term loans. Which WC strategy is likely to provide more financing stability?","answer":"Conservative","steps_vi":["Conservative dùng nhiều permanent financing, larger cushions, giảm rollover risk.","Higher cost can be rational in uncertain credit access."],"check":"Not guaranteed optimal for every firm."},{"question_en":"A stable large company funds seasonal receivables using a short-term bank facility while permanent WC uses long-term funds. Identify the policy.","answer":"Moderate / matching","steps_vi":["Nhu cầu biến động theo mùa được tài trợ bằng vay ngắn hạn, còn phần cơ bản bằng vốn dài hạn.","Chiến lược matching cân đối chi phí duy trì vốn và nguy cơ tái cấp vốn."],"check":"Mixed funding."},{"question_en":"A company holds minimal cash/inventory and relies on short-term debt for core operating assets. Identify its WC stance.","answer":"Aggressive","steps_vi":["Lean buffers và short-term funding giảm carrying cost, tăng liquidity risk.","Rollover disruption can harm operations."],"check":"Do not confuse aggressive with growth strategy."},{"question_en":"A supplier offers a 2% discount for payment on day 10 instead of day 30 on a $1m invoice. How much discount is forgone if paid on day 30?","answer":"$20,000","steps_vi":["Chiết khấu 2% của hóa đơn 1 triệu USD = 20.000 USD.","Trả ngày 10 chỉ tốn 980.000 USD, trả ngày 30 tốn 1 triệu USD; chi phí kéo dài 20 ngày là 20.000 USD."],"check":"Effective financing cost uses 980k denominator."},{"question_en":"A customer will pay a $100k invoice 20 days earlier if given 1% discount. What cash discount cost is incurred?","answer":"$1,000","steps_vi":["Chi phí chiết khấu khách hàng = 100.000 × 1% = 1.000 USD.","So sánh chi phí này với tiết kiệm tài trợ 20 ngày và lợi ích giảm nguy cơ không thu được nợ."],"check":"Not necessarily economic value positive."},{"question_en":"A firm's permanent WC requirement is $40m, seasonal $15m. Conservative funding is proposed at $55m long-term. Is this consistent with the policy?","answer":"Yes","steps_vi":["Nguồn vốn dài hạn bao phủ cả nhu cầu thường trực và mùa vụ, làm tăng độ ổn định vốn.","Đổi lại, doanh nghiệp thường chịu chi phí giữ vốn cao hơn."],"check":"Simple strategy illustration."},{"question_en":"A business has cost of funds 6% and carries $10m extra liquid assets year-round. Approximate annual opportunity cost.","answer":"$600,000","steps_vi":["Chi phí cơ hội vốn lưu động dư thừa = 10 triệu × 6% = 600.000 USD/năm.","Doanh nghiệp có thể vẫn cần đệm tiền vì rủi ro thanh khoản."],"check":"Simplified financing proxy."},{"question_en":"A firm uses a commercial paper program but its credit spreads rise and market access freezes. Which WC funding risk materializes?","answer":"Rollover/refinancing risk","steps_vi":["Doanh nghiệp không thể gia hạn phát hành thương phiếu khi thị trường đóng băng hoặc spread tăng.","Cần dự phòng nguồn vốn cam kết khác để xử lý rủi ro tái cấp vốn."],"check":"Commercial paper not a stable perpetual capital source."},{"question_en":"If a 3% customer discount accelerates collection by one week, is it necessarily optimal?","answer":"No","steps_vi":["Chi phí giảm giá có thể vượt lợi ích tiết kiệm chi phí tài trợ và làm thay đổi hành vi khách hàng.","Phải đánh giá lợi nhuận biên, rủi ro nợ xấu và giá trị thời gian của dòng tiền."],"check":"No one-size-fits-all credit terms."}],"questions":[{"stem_en":"Which WC strategy generally relies more on long-term financing and larger current-asset buffers?","options":["Conservative.","Aggressive.","Matching only."],"correct":0,"why_vi":"Conservative giữ liquidity cushion và tránh rollover of permanent current assets.","trap_vi":"This has costs."},{"stem_en":"An issuer finances permanent WC with long-term debt and seasonal WC with short-term borrowing. This is:","options":["Aggressive.","Moderate/matching.","A liquidation strategy."],"correct":1,"why_vi":"Chiến lược matching tài trợ nhu cầu thường trực bằng nguồn dài hạn và phần mùa vụ bằng nguồn ngắn hạn.","trap_vi":"Risks persist."},{"stem_en":"An aggressive WC approach is most likely to:","options":["Hold large excess cash with all long-term funding.","Avoid all liquidity pressure.","Use lean current assets and more short-term funding."],"correct":2,"why_vi":"Aggressive working capital policy giảm vốn bị giữ nhưng tăng nguy cơ thiếu hàng và rủi ro tái cấp vốn.","trap_vi":"Lower cost not guaranteed."},{"stem_en":"Which trade credit terms offer a 2% discount if paid by day 10 and full payment by day 30?","options":["2/10 net 30.","10/2 net 30.","30/10 net 2."],"correct":0,"why_vi":"Điều khoản 2/10 net 30 nghĩa là giảm giá 2% khi trả trước/ngày 10, nếu không thì trả đủ vào ngày 30.","trap_vi":"Check payment date."},{"stem_en":"For 2/10 net 30, how many days of extra supplier credit are obtained by foregoing discount?","options":["10 days.","20 days.","30 days."],"correct":1,"why_vi":"Thanh toán vào ngày 30 thay vì ngày 10 giúp kéo dài tín dụng nhà cung cấp thêm 20 ngày.","trap_vi":"Rate derived using 20 days."},{"stem_en":"The periodic implicit cost of foregoing a 2% cash discount is closest to:","options":["2.00%.","0.02%.","2.04%."],"correct":2,"why_vi":"Chi phí vay ngầm mỗi kỳ = 0,02/0,98 = 2,0408% trên khoản tiền có thể thanh toán sớm.","trap_vi":"Divide by amount funded, not full face."},{"stem_en":"A firm with $2m daily credit sales reduces DSO by 5 days. Estimate cash released:","options":["$10m.","$0.4m.","$2.5m."],"correct":0,"why_vi":"Dòng tiền giải phóng = doanh số tín dụng 2 triệu USD/ngày × 5 ngày = 10 triệu USD.","trap_vi":"Assumes steady daily credit sales."},{"stem_en":"A supplier demands full payment earlier than previously. The likely effect is:","options":["Increased issuer liquidity.","Increased near-term cash funding need.","Guaranteed lower inventory."],"correct":1,"why_vi":"Kỳ hạn thanh toán ngắn hơn làm DPO giảm, kéo dài CCC và tăng nhu cầu tài trợ bằng tiền.","trap_vi":"Supplier credit has implicit cost."},{"stem_en":"Which is a potential benefit of higher safety stock?","options":["Lower storage cost.","Elimination of supplier default risk.","Reduced stockout probability."],"correct":2,"why_vi":"Tồn kho dự phòng giúp tránh hết hàng nhưng làm tăng chi phí lưu kho, tài trợ và lỗi thời.","trap_vi":"Trade-off not free."},{"stem_en":"A company moves to JIT inventory management. Its main expected benefit is:","options":["Less inventory cash tied up.","Higher DIO unconditionally.","Guaranteed zero supply disruptions."],"correct":0,"why_vi":"Just-in-time giảm hàng tồn kho bình quân và nhu cầu vốn khi chuỗi cung ứng hoạt động ổn định.","trap_vi":"Supply-chain resilience trade-off."},{"stem_en":"Offering more generous customer credit usually tends to:","options":["Shorten DSO automatically.","Increase A/R funding needs.","Eliminate bad debts."],"correct":1,"why_vi":"Nới điều khoản tín dụng có thể tăng doanh thu nhưng cũng tăng khoản phải thu và số ngày DSO.","trap_vi":"Evaluate incremental profitability."},{"stem_en":"A company has 5/10 net 60 supplier terms. Forgoing a 5% discount is most directly equivalent to:","options":["A zero-cost 50-day extension.","A guaranteed tax benefit.","Implicit financing at a potentially high rate."],"correct":2,"why_vi":"Trả chậm đồng nghĩa mất chiết khấu mua hàng; đó là chi phí tài trợ ngầm của trade credit.","trap_vi":"Compute cost using d/(1−d)."},{"stem_en":"Which WC policy has greatest exposure to short-term refinancing under otherwise comparable conditions?","options":["Aggressive.","Conservative.","Fully long-term funded."],"correct":0,"why_vi":"Dùng nợ ngắn hạn cho cả tài sản lưu động thường trực làm tăng rủi ro rollover/refinancing.","trap_vi":"Funding maturity matters."},{"stem_en":"Which firm might rationally choose conservative WC policy?","options":["A firm with perfectly stable cheap short-term access and no shocks, necessarily.","A young firm with uncertain credit access.","A firm with unlimited costless refinancing."],"correct":1,"why_vi":"Doanh nghiệp mới, khả năng tiếp cận vốn bất ổn có thể chọn giữ đệm thanh khoản lớn dù tốn kém.","trap_vi":"Conditional, not universal."},{"stem_en":"A committed credit line normally differs from an uncommitted line because it:","options":["Is always free of covenants.","Can never be suspended for any reason.","Has contractual availability subject to terms."],"correct":2,"why_vi":"Hạn mức tín dụng cam kết cải thiện khả năng tiếp cận tiền với các điều khoản, phí và covenant đã thỏa thuận.","trap_vi":"Conditions still matter."},{"stem_en":"Commercial paper is most accessible to:","options":["Large issuers with strong credit quality.","Every unprofitable startup on equal terms.","Only equity shareholders."],"correct":0,"why_vi":"Thương phiếu là nguồn vay không bảo đảm ngắn hạn, đòi hỏi uy tín và khả năng tiếp cận thị trường.","trap_vi":"Market disruptions can close access."},{"stem_en":"Selling receivables at a discount to obtain immediate funds is:","options":["An ordinary stock split.","Factoring.","A poison-pill defense."],"correct":1,"why_vi":"Factoring bán khoản phải thu để thu tiền sớm nhưng phải trừ phí; cần xem quyền truy đòi.","trap_vi":"Sale versus pledged collateral distinction."},{"stem_en":"A bank lends against a company's inventory collateral. This is:","options":["Equity crowdfunding.","Dividend reinvestment.","Asset-based borrowing."],"correct":2,"why_vi":"Vay cầm cố hàng tồn kho/khoản phải thu tạo thanh khoản nhưng làm phát sinh nghĩa vụ nợ.","trap_vi":"Collateral eligibility can change."},{"stem_en":"A firm has $10m in excess working assets and an 8% annual cost of capital. Annual carry cost is:","options":["$800,000.","$80,000.","$8m."],"correct":0,"why_vi":"Chi phí tài trợ một năm = 10 triệu × 8% = 800.000 USD, chưa tính các chi phí khác.","trap_vi":"Not automatically optimal to remove buffer."},{"stem_en":"The primary objective of managing liquidity is:","options":["Minimizing all cash balances, regardless of risk.","Maximizing value while meeting operational and debt cash requirements.","Maximizing DSO indefinitely."],"correct":1,"why_vi":"Cân bằng profitability và enough liquidity, not extremes.","trap_vi":"Financial distress matters."},{"stem_en":"During rapid growth, a profitable issuer can encounter a liquidity shortage because:","options":["More sales eliminate receivables.","Payables automatically finance all inventory.","Receivables and inventory may grow faster than cash collection."],"correct":2,"why_vi":"Quy mô hoạt động tăng sẽ làm nhu cầu tài trợ tài sản ngắn hạn tăng ngay cả khi có lợi nhuận kế toán.","trap_vi":"Forecast cash timing."},{"stem_en":"If a company pays suppliers later to raise DPO, the analyst should also assess:","options":["Lost discounts and supplier relationships.","Only the firm's ticker symbol.","Whether revenue is stated in millions."],"correct":0,"why_vi":"Kéo dài thanh toán suppliers có thể mất discount và ảnh hưởng sự ổn định của chuỗi cung ứng.","trap_vi":"DPO is not free."},{"stem_en":"A firm has permanent current assets $25m and seasonal needs $10m. Under matched funding, long-term capital should broadly cover:","options":["Only $10m.","About $25m.","All $35m necessarily."],"correct":1,"why_vi":"Matching policy dùng vốn dài hạn cho nhu cầu vốn lưu động nền tảng và vốn ngắn hạn cho nhu cầu mùa vụ.","trap_vi":"Simplified strategy model."},{"stem_en":"Which is the most comprehensive short-term funding decision framework?","options":["Nominal interest rate alone.","Number of employees only.","All-in cost, availability, tenor, covenants, collateral and operational impact."],"correct":2,"why_vi":"Funding choices phải xem liquidity terms, legal restrictions và cost tổng.","trap_vi":"Cheapest quote not always best."}],"cards":[{"front_en":"Explain: Value-focused working capital objective","back_vi":"Quản lý WC nhằm tối đa value với đủ cash trả short-term liabilities; tránh overinvestment cash/inventory/AR nhưng cũng không đẩy issuer vào financial distress."},{"front_en":"Explain: Permanent current assets","back_vi":"Nhu cầu base level inventory, receivables và cash duy trì liên tục để vận hành doanh nghiệp ngay trong mùa thấp."},{"front_en":"Explain: Variable current assets","back_vi":"Extra working capital do seasonal peaks, promotion, growth hoặc unexpected demand; thường biến động theo revenue."},{"front_en":"Explain: Working capital investment sizing","back_vi":"Forecast sales, credit terms, inventory days và payable policies để estimate dollars of current assets/liabilities; tăng doanh thu thường cần thêm vốn."},{"front_en":"Explain: Conservative strategy basics","back_vi":"Giữ nhiều cash/safety inventory và funded current assets bằng relatively more long-term financing, giảm refinancing risk nhưng có higher carry/financing cost."},{"front_en":"Explain: Conservative strategy advantages","back_vi":"Cushion chống credit-market disruption, inventory shortages và unexpected demand; stable funding thích hợp early-stage/uncertain access."},{"front_en":"Explain: Conservative strategy disadvantages","back_vi":"Cash/inventory carrying costs và costly long-term funding làm reduce returns if overused."},{"front_en":"Explain: Aggressive strategy basics","back_vi":"Giảm excess current assets và dùng nhiều short-term debt để finance current capital; potentially lower cost và higher return nhưng liquidity/refinancing risk lớn."},{"front_en":"Explain: Aggressive strategy advantages","back_vi":"Lower average invested WC, potentially higher ROIC/efficiency trong stable conditions."},{"front_en":"Explain: Aggressive strategy disadvantages","back_vi":"Rollover/refinancing exposure, sensitivity to interest-rate spikes và operational disruptions; stress market access may disappear."},{"front_en":"Explain: Moderate matching strategy","back_vi":"Long-term financing cho permanent current assets và short-term funding cho variable/seasonal needs; cân bằng cost với liquidity protection."},{"front_en":"Explain: Conservative versus aggressive on yield curve","back_vi":"Long-term financing often higher cost than short-term; chi phí thực thay đổi theo yield curve và issuer credit."},{"front_en":"Explain: Inventory policy: safety stock","back_vi":"Safety stock giảm nguy cơ stockouts nhưng tăng DIO, storage/obsolescence, insurance costs."},{"front_en":"Explain: Inventory policy: JIT","back_vi":"Just-in-time giảm inventory/cash tied-up nhưng tăng exposure khi suppliers delay hoặc demand spikes."},{"front_en":"Explain: Accounts receivable: credit terms","back_vi":"More generous credit có thể raise sales nhưng tăng DSO, bad debt và billing cost. Tighter policy giảm AR nhưng có thể lose customers."},{"front_en":"Explain: Early payment discounts to customers","back_vi":"Cash discount tăng tốc collection nhưng giảm effective selling price; đánh giá incremental financing saved so với lost margin."},{"front_en":"Explain: Payables and supplier discounts","back_vi":"Chậm trả suppliers tăng DPO, nhưng mất early-payment discount có implicit financing cost; tính effective annual cost trước quyết định."},{"front_en":"Explain: Trade credit terms 2/10 net 30","back_vi":"Nếu trả trong 10 ngày được discount 2%; phải trả full invoice trong 30 ngày. Bỏ discount giống vay khoảng 98 để trả thêm 2 trong 20 ngày."},{"front_en":"Explain: Short-term funding sources","back_vi":"Bank lines, overdrafts, commercial paper, asset-backed borrowing, trade credit, factoring và securitization tùy size, credit quality và legal environment."},{"front_en":"Explain: Committed versus uncommitted lines","back_vi":"Committed facility thường có contractual access subject conditions, uncommitted line bank có thể withdraw; commitment fee/covenants tạo tradeoff."},{"front_en":"Explain: Commercial paper","back_vi":"Short-term unsecured debt thường dành cho large/high-credit issuers, exposed to rollover market conditions."},{"front_en":"Explain: Receivables factoring","back_vi":"Bán A/R cho factor để nhận cash sớm, có discount/fees và recourse/nonrecourse differences."},{"front_en":"Explain: Asset-based borrowing","back_vi":"Pledge receivables/inventory làm collateral for loan, improving liquidity without direct sale nhưng tạo repayment/pledge restrictions."},{"front_en":"Explain: Liquidity funding decision","back_vi":"Xem all-in cost, term, availability, speed, legal restrictions, collateral, credit rating and operational effect; not only nominal quoted rate."},{"front_en":"Explain: Early warning indicators","back_vi":"DSO slippage, declining cash/quick ratios, falling CFO, covenant pressure, credit line cuts và stock obsolescence báo liquidity weakness."},{"front_en":"Explain: Contingency liquidity plan","back_vi":"Cash forecasts, diversified facilities, liquid securities, risk limits, supplier/customer escalation và backup funding needed for stresses."},{"front_en":"Explain: Crisis response hierarchy","back_vi":"Ưu tiên cash holdings/operating cash/committed funding, xét sale cost/strategic consequences của secondary sources nếu needed."},{"front_en":"Explain: Growth versus liquidity","back_vi":"Growth có thể cần tăng inventory, A/R và capex dù profitable; liquidity forecast phải anticipate cash gap trước khi sales convert to cash."},{"front_en":"Explain: Analyst strategy comparison","back_vi":"Conservative = high buffers/more long term, aggressive = lean buffers/more short term, moderate = duration matching. Evaluate risk–return fit to issuer lifecycle and business model."}]}]},{"module_id":"CFA26-03-05","module_title":"Capital Investments and Capital Allocation","subject":"Corporate Issuers","version":"2.3","language":"Vietnamese teaching with English CFA terms and original English MCQs","qa_status":"DETAILED_DRAFT_PENDING_FULL_ACADEMIC_REVIEW","disclaimer_vi":"Đầy đủ bốn LOS CFAI 2026 CI Module5 theo nguồn, với học liệu và ví dụ/câu hỏi biên soạn riêng. Đây là bản thảo chưa có xác nhận kiểm toán học thuật độc lập toàn diện. Cần đặc biệt lưu ý NPV/IRR, ROIC và quyền chọn thực khi giải bài thi.","los":[{"id":"CFA26-03-05-LOS01","letter":"5.a","title_en":"Types of Capital Investments","outcome_en":"describe types of capital investments","overview_vi":"Phân biệt going concern/maintenance, regulatory/compliance, expansion of existing business và new lines of business. Giải thích động cơ, mức độ rủi ro, dòng tiền, đặc điểm tài trợ, khấu hao và giới hạn khi dùng depreciation làm maintenance capex proxy.","source":[{"id":"CFA Institute Curriculum 2026 — Corporate Issuers LM5","pages":"143–153 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading24","pages":"253–256 (physical PDF)"},{"id":"SAPP Corporate Issuers 2026 — Module5","pages":"135–141 (physical PDF)"}],"sections":[{"heading":"Capital investment purpose","body":"Capital investment là việc cam kết nguồn lực vào tài sản/dự án tạo lợi ích dài hạn; khác với working capital dùng cho hoạt động ngắn hạn.","trap":"A cash outlay is not automatically a value-creating investment."},{"heading":"Long-lived tangible assets","body":"Nhà xưởng, thiết bị, hệ thống CNTT phục vụ nhiều kỳ; giá trị được phân bổ dần qua depreciation và cần bảo trì/thay thế.","trap":"Depreciation is an accounting expense, not a period cash outflow."},{"heading":"Intangible investment","body":"R&D, phần mềm, patents và năng lực tổ chức có thể tạo giá trị dài hạn; cách ghi nhận chi phí/capitalization phụ thuộc chuẩn mực.","trap":"Some value-creating spending is expensed rather than capitalized."},{"heading":"Four broad categories","body":"CFAI phân nhóm: going concern, regulatory/compliance, expansion of existing business, new lines of business and other. Hai nhóm đầu thiên về maintain; hai nhóm sau về growth.","trap":"Do not classify every replacement as growth capex."},{"heading":"Going concern definition","body":"Going concern/maintenance capex nhằm giữ năng lực hoạt động, thay thế tài sản hết vòng đời và duy trì quy mô kinh doanh hiện tại.","trap":"Maintenance can still improve efficiency."},{"heading":"Going concern examples","body":"Thay máy bơm cũ, cập nhật server, sửa đường ống, bảo trì dây chuyền là hoạt động duy trì.","trap":"Newer equipment does not automatically mean a new business line."},{"heading":"Efficiency improvements","body":"Nâng cấp thiết bị để giảm điện, giảm phế phẩm hoặc tăng hiệu suất vận hành hiện hữu có thể thuộc going concern nếu mục tiêu là duy trì/cải tiến hoạt động sẵn có.","trap":"Classification follows strategic purpose."},{"heading":"Maintenance risk profile","body":"Rủi ro maintenance thường thấp hơn hoạt động kinh doanh mới do công ty có lịch sử vận hành và dự báo nhu cầu tương đối rõ.","trap":"Low risk is relative, not risk-free."},{"heading":"Match funding assets","body":"Tài trợ tài sản dài hạn bằng vốn có kỳ hạn tương ứng giúp tránh rollover risk; kỳ hạn nợ quá dài cũng có thể đắt hoặc gây chi phí mua lại nợ.","trap":"Asset life and debt maturity need not be identical but should be considered jointly."},{"heading":"Maintenance capex disclosure","body":"Doanh nghiệp không phải lúc nào cũng công bố riêng maintenance và growth capex, khiến nhà phân tích phải ước tính.","trap":"Reported capex includes multiple strategic purposes."},{"heading":"Depreciation as maintenance proxy","body":"D&A đôi khi được dùng làm proxy cho maintenance capex nhưng khác biệt do inflation, historical cost, replacement costs, asset lives và intangible investment.","trap":"Depreciation is not a reliable identity for maintenance spending."},{"heading":"Regulatory/compliance definition","body":"Dự án compliance đáp ứng luật, tiêu chuẩn an toàn, môi trường hoặc yêu cầu giám sát; có thể không có doanh thu trực tiếp.","trap":"Negative standalone operating cash flow does not imply the firm can legally avoid spending."},{"heading":"Compliance examples","body":"Nâng cấp kiểm soát chống rửa tiền, hệ thống xử lý khí thải, công nghệ an toàn nhà máy hoặc báo cáo dữ liệu theo quy định.","trap":"Compare avoidance of fines/loss of operating license."},{"heading":"Compliance strategic effect","body":"Quy định mới có thể tăng chi phí, nhưng cũng tạo rào cản gia nhập và bảo vệ các doanh nghiệp đáp ứng quy định tốt.","trap":"Compliance implications vary by incumbent and newcomer."},{"heading":"Expansion of existing business","body":"Mở rộng quy mô sản xuất, kênh phân phối, thị trường địa lý hoặc phạm vi sản phẩm dựa trên năng lực đang có.","trap":"Growth capex differs from normal replacement of worn-out capacity."},{"heading":"Expansion size","body":"Tăng sản lượng hiện có mà ít đổi công nghệ/khách hàng là expansion in size (scale).","trap":"Scale expansion still exposes demand risk."},{"heading":"Expansion scope","body":"Dùng năng lực hiện có để phục vụ nhóm khách mới hoặc vùng thị trường mới là mở rộng scope.","trap":"Related diversification is not always a new line of business."},{"heading":"R&D and acquisitions within core","body":"Chi cho R&D, acquisition trong ngành liên quan có thể là expansion hiện hữu thay vì một ngành hoàn toàn mới.","trap":"R&D expenditure accounting may not match classification of economic investment."},{"heading":"Expansion risk profile","body":"Dự án growth mang rủi ro demand, execution, cạnh tranh, integration và chi phí vốn; phụ thuộc khả năng dự báo sales và margins.","trap":"Higher forecast revenue is not proof of positive NPV."},{"heading":"Financing expansion","body":"Doanh nghiệp tăng trưởng chưa có track record có thể phụ thuộc equity, trong khi công ty trưởng thành có thể tiếp cận debt cho dự án tương tự.","trap":"Choice depends on issuer credit quality and risk, not one fixed rule."},{"heading":"New lines of business","body":"Đầu tư vào ngành, công nghệ hoặc mô hình gần như chưa liên quan đến năng lực cốt lõi; thường có mức bất định cao nhất.","trap":"A related geographic expansion is often not a completely new line."},{"heading":"New venture challenges","body":"Nhập ngành mới làm công ty thiếu thông tin về khách hàng, vận hành và đối thủ; acquisitions ngoài ngành có thêm risk of overpayment.","trap":"Diversification does not eliminate execution risk."},{"heading":"Capital allocation comparison","body":"Dự án maintenance có dòng tiền phần lớn từ tránh gián đoạn; growth dựa trên upside incremental sales; compliance từ tránh mất quyền hoạt động; new line dựa trên thị trường/công nghệ mới.","trap":"Compare cash flows including opportunity costs and strategic constraints."},{"heading":"Strategic investment versus accounting expense","body":"Cách hạch toán (capex hay opex) không quyết định một khoản chi có tạo giá trị; cần xem kỳ hạn và incremental cash flows.","trap":"EPS change is not NPV."},{"heading":"Analyst classification checklist","body":"Xác định dự án giữ quy mô, bắt buộc tuân thủ, mở rộng lõi hay ngành mới; sau đó đánh giá funding tenor, growth/risk, D&A proxy và management execution.","trap":"Category labels are analytical, not a stand-alone accept/reject rule."}],"formulas":[{"name":"Maintenance expenditure proxy","expr":"Maintenance capex ≈ annual depreciation and amortization (rough estimate only)","meaning":"Chỉ dùng khi không có disclosure, cần điều chỉnh cho giá thay thế và vòng đời.","conditions":"NOT an official exact identity and can be materially misleading."},{"name":"Total capital expenditures","expr":"Capex_total = capex_maintenance + capex_expansion + capex_compliance + capex_other","meaning":"Phân loại theo mục đích khi có thông tin nội bộ.","conditions":"Illustrative decomposition, not a published reporting requirement."},{"name":"After-tax efficiency saving","expr":"Incremental annual saving after tax ≈ pre-tax operating cost saving×(1−tax rate)","meaning":"Đo lợi ích hoạt động khi thay máy tiết kiệm chi phí.","conditions":"Ignore incremental depreciation tax shield unless separately stated."},{"name":"Asset financing maturity gap","expr":"Maturity gap = asset useful life − funding maturity","meaning":"Kiểm tra mismatch tạo rollover risk cho vốn tài trợ tài sản.","conditions":"Diagnostic illustration, not compulsory CFAI formula."},{"name":"Expansion revenue projection","expr":"Incremental sales ≈ incremental units×unit selling price","meaning":"Nêu cơ sở sales growth khi làm dự án expansion.","conditions":"Use margin and tax to convert to cash flow."},{"name":"Savings payback proxy","expr":"Simple payback ≈ initial cost / stable annual cash savings","meaning":"So sánh thô các dự án tiết kiệm chi phí.","conditions":"Payback ignores discounting and is not the main CFAI LM5 decision rule."},{"name":"Replacement cost gap","expr":"Replacement cost gap ≈ actual replacement capex − historical annual depreciation","meaning":"Chỉ ra inflation/technology khiến D&A proxy lệch.","conditions":"D&A may not be a maintenance spending estimate."},{"name":"Incremental investment NPV","expr":"NPV = −initial cash investment + discounted incremental after-tax future cash flows","meaning":"Cùng nguyên tắc capital allocation áp dụng mọi loại dự án.","conditions":"Requires risk-appropriate hurdle rate and cash-flow forecast."},{"name":"Expected regulatory loss avoided","expr":"Expected avoided loss ≈ probability of penalty/loss-of-license×loss magnitude","meaning":"Minh họa một phần lợi ích compliance.","conditions":"Enforcement and strategic effects are not exhausted by expected fines."}],"examples":[{"question_en":"A utility replaces an aging transformer to maintain its current electricity service. Classify the investment.","answer":"Going concern/maintenance","steps_vi":["Mục đích là duy trì công suất và phục vụ hiện tại bằng thiết bị thay thế.","Không phải expansion vì không có thị trường hay công suất mới trong đề."],"check":"Replacement purpose."},{"question_en":"A bank installs a transaction-monitoring platform solely to satisfy a new anti-money-laundering requirement. Classify it.","answer":"Regulatory/compliance","steps_vi":["Đầu tư nhằm đáp ứng yêu cầu giám sát pháp lý, không cần tạo doanh thu trực tiếp.","Việc bắt buộc phải làm phân biệt compliance với dự án tùy chọn."],"check":"Legal obligation."},{"question_en":"A beverage issuer doubles the capacity of an existing product line in a familiar market. What category?","answer":"Expansion of existing business — size","steps_vi":["Tăng công suất của sản phẩm đang có là mở rộng scale.","Không tự động là new lines dù số tiền đầu tư lớn."],"check":"Business scale."},{"question_en":"A retailer enters a new province using its existing logistics and product range. How should it generally be classified?","answer":"Expansion of existing business — scope","steps_vi":["Mở sang khu vực mới nhờ năng lực hiện hữu là mở rộng scope.","Chỉ khi vào ngành chưa liên quan mới xét new lines."],"check":"Geographic expansion."},{"question_en":"A utility invests in a new pharmaceutical R&D venture unrelated to its core energy operations. What type?","answer":"New line of business","steps_vi":["Công ty bước vào công nghệ và tập khách hàng ngoài lĩnh vực năng lượng.","Rủi ro thông tin, triển khai và thị trường thường cao hơn maintenance."],"check":"Unrelated diversification."},{"question_en":"A firm reports annual D&A $60m and capex $90m. An analyst uses D&A as estimated maintenance. Estimate growth/other capex residual.","answer":"$30 million (proxy only)","steps_vi":["Theo proxy, phần còn lại = capex 90 − D&A 60 = 30 triệu USD.","Đây không phải xác nhận maintenance thực tế đúng 60 triệu USD."],"check":"Replacement prices can differ from book cost."},{"question_en":"An old machine cost $2m but now costs $3m to replace. Depreciation last year was $0.2m. Does D&A necessarily fund replacement?","answer":"No","steps_vi":["Khấu hao dựa trên historical accounting values, trong khi giá thay thế hiện tại đã tăng.","Chi phí thay mới và lịch thay thế không trùng khấu hao năm."],"check":"Inflation/obsolescence."},{"question_en":"A manufacturer invests $5m to save $1m pre-tax annual operating expense; tax rate 25%. Compute annual after-tax saving before depreciation effects.","answer":"$0.75 million","steps_vi":["Tiết kiệm sau thuế giả định = 1×(1−0,25)=0,75 triệu USD/năm.","Phải cộng tác động thuế của depreciation nếu đề yêu cầu NPV đầy đủ."],"check":"Simplified operating benefit."},{"question_en":"An issuer finances a 25-year power plant by a 1-year revolving loan. Identify the main risk.","answer":"Rollover/refinancing risk","steps_vi":["Nhu cầu vay lại thường xuyên trong khi tài sản còn tạo dòng tiền nhiều năm.","Lãi suất và khả năng tiếp cận khoản vay tương lai không chắc chắn."],"check":"Maturity mismatch."},{"question_en":"A firm finances a short-lived computer system with a very long bond and plans early repayment. Identify a potential cost.","answer":"Long-term borrowing and early retirement cost","steps_vi":["Vay quá dài có thể chịu coupon cao và chi phí mua lại nợ khi không cần nữa.","Không phải dài hạn càng nhiều càng luôn tối ưu."],"check":"Financing match."},{"question_en":"A company builds an emissions scrubber that has no extra sales but prevents closure of a facility. Is a zero-revenue project automatically inappropriate?","answer":"No","steps_vi":["Khoản đầu tư bảo vệ quyền vận hành, tránh đóng cửa, fines và tác động danh tiếng.","NPV phải so sánh phương án có dự án với không thực hiện."],"check":"Avoidance value."},{"question_en":"A mature issuer acquires a small competitor in its own industry to expand product coverage. How is the project generally categorized?","answer":"Expansion within existing business","steps_vi":["Acquisition trong cùng core business có mục đích mở rộng năng lực/scope.","Cần kiểm tra giá mua, integration và incremental cash flows."],"check":"Related acquisition."},{"question_en":"A firm builds a completely unrelated cryptocurrency-mining operation. Classify the risk relative to normal maintenance.","answer":"New line; typically greater uncertainty","steps_vi":["Hoạt động mới có economics và operations chưa quen thuộc, rủi ro dự báo cao.","Không coi lợi ích diversification là đảm bảo dự án có NPV dương."],"check":"Unrelated sector."},{"question_en":"Annual capex is $140m: $70m maintenance, $20m compliance and $50m expansion. Compute the proportion classified as maintaining the business.","answer":"64.29%","steps_vi":["Các khoản duy trì gồm maintenance+compliance=90 triệu USD.","Tỷ lệ = 90/140 ≈64,29%; phân nhóm dùng mục đích dự án đã cho."],"check":"Compliance as maintenance category."},{"question_en":"A growth project creates $10m yearly revenue at 20% operating cash margin before taxes. Approximate annual pre-tax operating cash contribution.","answer":"$2 million","steps_vi":["Doanh thu tăng 10 triệu × margin 20%=2 triệu USD trước thuế.","Cần trừ capex, thuế, vốn lưu động và discounting khi tính NPV."],"check":"Sales is not cash profit."}],"questions":[{"stem_en":"Which investment most clearly qualifies as a going-concern project?","options":["Replacement of existing server hardware.","Acquisition of an unrelated chemical company.","Entry into a new national market."],"correct":0,"why_vi":"Thay server để duy trì hoạt động hiện hữu là maintenance/going concern.","trap_vi":"New assets do not necessarily mean growth."},{"stem_en":"Which project is primarily a regulatory/compliance investment?","options":["Opening another store.","Installing legally required pollution controls.","Developing an unrelated product category."],"correct":1,"why_vi":"Hệ thống kiểm soát ô nhiễm theo luật là compliance bắt buộc.","trap_vi":"Revenue is not essential for classification."},{"stem_en":"An acquisition of a company in an unrelated industry is generally classified as:","options":["Maintenance.","Regulatory compliance.","A new line of business."],"correct":2,"why_vi":"Acquisition ngoài core industry thuộc nhóm new lines với rủi ro integration/overpayment.","trap_vi":"Classification follows purpose and scope."},{"stem_en":"An issuer doubles the output of an established factory to meet growing demand. This is most likely:","options":["Expansion in size.","Going-concern replacement only.","Regulatory compliance."],"correct":0,"why_vi":"Tăng quy mô hoạt động hiện có là expansion in size.","trap_vi":"Added scale, not necessarily new line."},{"stem_en":"Which category often involves the highest uncertainty because of unfamiliar markets or technologies?","options":["Going concern.","New lines of business.","Mandatory compliance."],"correct":1,"why_vi":"Ngành/công nghệ chưa quen thuộc làm dự báo rủi ro và valuation bất định hơn.","trap_vi":"Relative, not guaranteed ranking for every project."},{"stem_en":"An issuer upgrades a process to comply with new safety standards. Its main category is:","options":["Expansion in scope.","An unrelated venture.","Regulatory/compliance."],"correct":2,"why_vi":"Chuẩn an toàn bắt buộc là compliance capital spending.","trap_vi":"Does not require positive direct revenue."},{"stem_en":"Depreciation and amortization are used as a proxy for maintenance capex mainly because:","options":["Separate maintenance capex may not be disclosed.","They are always equal to current replacement cost.","All capex is maintenance."],"correct":0,"why_vi":"Khi thiếu công bố riêng, D&A là proxy nhưng phụ thuộc giá lịch sử và tuổi thọ.","trap_vi":"Do not treat proxy as an identity."},{"stem_en":"Which circumstance most weakens D&A as an estimate of replacement capex?","options":["Stable replacement prices.","Sharp increases in replacement equipment prices.","Stable equipment utilization."],"correct":1,"why_vi":"Inflation và thay đổi giá công nghệ làm maintenance capex thực tế lệch khấu hao.","trap_vi":"Historical cost issue."},{"stem_en":"A firm funds a 30-year operating asset entirely with one-year debt. The most immediate financing concern is:","options":["No risk because the project is long lived.","Only stock market liquidity.","Refinancing uncertainty."],"correct":2,"why_vi":"Nợ ngắn hạn phải đảo nợ nhiều lần trong suốt vòng đời tài sản.","trap_vi":"Match funding reduces rollover exposure."},{"stem_en":"A firm invests in upgrading its current distribution center to reduce electricity use. The project is most likely:","options":["Going concern/efficiency improvement.","Unrelated new line.","Pure financial portfolio trading."],"correct":0,"why_vi":"Cải tiến hiệu suất cơ sở hiện có thuộc going concern nếu không mở rộng ngành.","trap_vi":"Purpose matters."},{"stem_en":"Which is a typical expansion-of-business project?","options":["Repairing a roof to keep the current store open.","Entering a new geographic market with existing products.","Paying back a short-term loan."],"correct":1,"why_vi":"Mở rộng vùng thị trường bằng sản phẩm hiện có thuộc expansion.","trap_vi":"Geographic scope."},{"stem_en":"What is a common risk of entering a new line of business?","options":["Guaranteed higher ROI.","Guaranteed stable demand.","Lack of operating expertise."],"correct":2,"why_vi":"Thiếu hiểu biết về khách hàng/công nghệ/đối thủ là nguồn rủi ro.","trap_vi":"Not all diversification adds value."},{"stem_en":"For analysts, maintenance capex compared with growth capex is generally:","options":["Hard to distinguish from disclosure alone.","Always reported separately under IFRS.","Unrelated to cash flow analysis."],"correct":0,"why_vi":"Công ty không nhất thiết tách maintenance và expansion trong báo cáo capex.","trap_vi":"Reporting limitations."},{"stem_en":"A company has capex $90m and D&A $60m. The residual after using D&A as a maintenance proxy is closest to:","options":["$150m.","$30m.","$60m."],"correct":1,"why_vi":"Khoản còn lại theo cách proxy =90−60=30 triệu USD; không chứng minh chi tiêu growth thực tế.","trap_vi":"Proxy caveat."},{"stem_en":"A new production line within an existing product category is primarily:","options":["Compliance.","Maintenance of old equipment.","Existing-business expansion."],"correct":2,"why_vi":"Dây chuyền mới tăng năng lực sản phẩm lõi thuộc expansion.","trap_vi":"Product category and capacity."},{"stem_en":"The main point of matching debt maturities with asset lives is to:","options":["Reduce refinancing mismatch risk.","Guarantee a positive project NPV.","Avoid all interest costs."],"correct":0,"why_vi":"Phù hợp kỳ hạn nguồn vốn và thời gian khai thác tài sản giảm rủi ro rollover.","trap_vi":"Debt maturity not a standalone investment rule."},{"stem_en":"Which project is usually the most mandatory from a legal perspective?","options":["Optional geographic expansion.","Pollution-control installation required by law.","Unrelated technology acquisition."],"correct":1,"why_vi":"Doanh nghiệp có thể phải đầu tư compliance để tránh phạt hoặc ngừng hoạt động.","trap_vi":"Mandatory decision context."},{"stem_en":"Investment in new product R&D within the core industry is most likely:","options":["Going-concern capex only.","A loan repayment.","Expansion of the existing business."],"correct":2,"why_vi":"R&D trong lĩnh vực lõi giúp mở rộng scope/sản phẩm.","trap_vi":"Accounting expense does not change economic classification."},{"stem_en":"A firm evaluates a compliance project with no new revenue. The strongest reason not to reject it solely for zero revenue is:","options":["Its value may come from preventing shutdown or penalties.","Compliance always increases EPS.","Tax rules guarantee a positive NPV."],"correct":0,"why_vi":"Giá trị có thể là tránh tổn thất do không đáp ứng yêu cầu pháp lý.","trap_vi":"Compare against the no-project alternative."},{"stem_en":"Which investment would generally be classified as expansion in scope rather than scale?","options":["Replacing a worn-out pump.","Offering current capabilities to a new customer group.","Changing an insurance premium payment date."],"correct":1,"why_vi":"Mở rộng scope là dùng năng lực hiện có cho nhóm khách/sản phẩm/thị trường khác.","trap_vi":"Scale is capacity of existing activities."},{"stem_en":"What does a high reported capex-to-depreciation ratio necessarily prove?","options":["That all capex is maintenance.","That every project has positive NPV.","None of those conclusions."],"correct":2,"why_vi":"Capex/D&A cao không cho biết tách chính xác maintenance, growth hay compliance.","trap_vi":"Ratio needs context."},{"stem_en":"A company replacing worn IT infrastructure with similar-capacity new servers most likely undertakes:","options":["A going-concern investment.","An unrelated acquisition.","Expansion into a new industry."],"correct":0,"why_vi":"Tái đầu tư để giữ chức năng hoạt động hiện hữu là going concern.","trap_vi":"Capacity may be similar."}],"cards":[{"front_en":"Explain: Capital investment purpose","back_vi":"Capital investment là việc cam kết nguồn lực vào tài sản/dự án tạo lợi ích dài hạn; khác với working capital dùng cho hoạt động ngắn hạn."},{"front_en":"Explain: Long-lived tangible assets","back_vi":"Nhà xưởng, thiết bị, hệ thống CNTT phục vụ nhiều kỳ; giá trị được phân bổ dần qua depreciation và cần bảo trì/thay thế."},{"front_en":"Explain: Intangible investment","back_vi":"R&D, phần mềm, patents và năng lực tổ chức có thể tạo giá trị dài hạn; cách ghi nhận chi phí/capitalization phụ thuộc chuẩn mực."},{"front_en":"Explain: Four broad categories","back_vi":"CFAI phân nhóm: going concern, regulatory/compliance, expansion of existing business, new lines of business and other. Hai nhóm đầu thiên về maintain; hai nhóm sau về growth."},{"front_en":"Explain: Going concern definition","back_vi":"Going concern/maintenance capex nhằm giữ năng lực hoạt động, thay thế tài sản hết vòng đời và duy trì quy mô kinh doanh hiện tại."},{"front_en":"Explain: Going concern examples","back_vi":"Thay máy bơm cũ, cập nhật server, sửa đường ống, bảo trì dây chuyền là hoạt động duy trì."},{"front_en":"Explain: Efficiency improvements","back_vi":"Nâng cấp thiết bị để giảm điện, giảm phế phẩm hoặc tăng hiệu suất vận hành hiện hữu có thể thuộc going concern nếu mục tiêu là duy trì/cải tiến hoạt động sẵn có."},{"front_en":"Explain: Maintenance risk profile","back_vi":"Rủi ro maintenance thường thấp hơn hoạt động kinh doanh mới do công ty có lịch sử vận hành và dự báo nhu cầu tương đối rõ."},{"front_en":"Explain: Match funding assets","back_vi":"Tài trợ tài sản dài hạn bằng vốn có kỳ hạn tương ứng giúp tránh rollover risk; kỳ hạn nợ quá dài cũng có thể đắt hoặc gây chi phí mua lại nợ."},{"front_en":"Explain: Maintenance capex disclosure","back_vi":"Doanh nghiệp không phải lúc nào cũng công bố riêng maintenance và growth capex, khiến nhà phân tích phải ước tính."},{"front_en":"Explain: Depreciation as maintenance proxy","back_vi":"D&A đôi khi được dùng làm proxy cho maintenance capex nhưng khác biệt do inflation, historical cost, replacement costs, asset lives và intangible investment."},{"front_en":"Explain: Regulatory/compliance definition","back_vi":"Dự án compliance đáp ứng luật, tiêu chuẩn an toàn, môi trường hoặc yêu cầu giám sát; có thể không có doanh thu trực tiếp."},{"front_en":"Explain: Compliance examples","back_vi":"Nâng cấp kiểm soát chống rửa tiền, hệ thống xử lý khí thải, công nghệ an toàn nhà máy hoặc báo cáo dữ liệu theo quy định."},{"front_en":"Explain: Compliance strategic effect","back_vi":"Quy định mới có thể tăng chi phí, nhưng cũng tạo rào cản gia nhập và bảo vệ các doanh nghiệp đáp ứng quy định tốt."},{"front_en":"Explain: Expansion of existing business","back_vi":"Mở rộng quy mô sản xuất, kênh phân phối, thị trường địa lý hoặc phạm vi sản phẩm dựa trên năng lực đang có."},{"front_en":"Explain: Expansion size","back_vi":"Tăng sản lượng hiện có mà ít đổi công nghệ/khách hàng là expansion in size (scale)."},{"front_en":"Explain: Expansion scope","back_vi":"Dùng năng lực hiện có để phục vụ nhóm khách mới hoặc vùng thị trường mới là mở rộng scope."},{"front_en":"Explain: R&D and acquisitions within core","back_vi":"Chi cho R&D, acquisition trong ngành liên quan có thể là expansion hiện hữu thay vì một ngành hoàn toàn mới."},{"front_en":"Explain: Expansion risk profile","back_vi":"Dự án growth mang rủi ro demand, execution, cạnh tranh, integration và chi phí vốn; phụ thuộc khả năng dự báo sales và margins."},{"front_en":"Explain: Financing expansion","back_vi":"Doanh nghiệp tăng trưởng chưa có track record có thể phụ thuộc equity, trong khi công ty trưởng thành có thể tiếp cận debt cho dự án tương tự."},{"front_en":"Explain: New lines of business","back_vi":"Đầu tư vào ngành, công nghệ hoặc mô hình gần như chưa liên quan đến năng lực cốt lõi; thường có mức bất định cao nhất."},{"front_en":"Explain: New venture challenges","back_vi":"Nhập ngành mới làm công ty thiếu thông tin về khách hàng, vận hành và đối thủ; acquisitions ngoài ngành có thêm risk of overpayment."},{"front_en":"Explain: Capital allocation comparison","back_vi":"Dự án maintenance có dòng tiền phần lớn từ tránh gián đoạn; growth dựa trên upside incremental sales; compliance từ tránh mất quyền hoạt động; new line dựa trên thị trường/công nghệ mới."},{"front_en":"Explain: Strategic investment versus accounting expense","back_vi":"Cách hạch toán (capex hay opex) không quyết định một khoản chi có tạo giá trị; cần xem kỳ hạn và incremental cash flows."},{"front_en":"Explain: Analyst classification checklist","back_vi":"Xác định dự án giữ quy mô, bắt buộc tuân thủ, mở rộng lõi hay ngành mới; sau đó đánh giá funding tenor, growth/risk, D&A proxy và management execution."}]},{"id":"CFA26-03-05-LOS02","letter":"5.b","title_en":"Capital Allocation, NPV, IRR, and ROIC","outcome_en":"describe the capital allocation process, calculate net present value (NPV), internal rate of return (IRR), and return on invested capital (ROIC), and contrast their use in capital allocation","overview_vi":"Đủ bốn bước capital allocation; định giá after-tax incremental cash flows, NPV/IRR decision rules, irregular cash-flow dates, multiple IRRs, mutually exclusive projects, ROIC tính từ after-tax operating profit và average long-term liabilities plus equity, khác NPV/IRR.","source":[{"id":"CFA Institute Curriculum 2026 — Corporate Issuers LM5","pages":"154–165 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading24","pages":"255–260 (physical PDF)"},{"id":"SAPP Corporate Issuers 2026 — Module5","pages":"142–174 (physical PDF)"}],"sections":[{"heading":"Capital allocation objective","body":"Management và board phân bổ vốn để tối đa hóa giá trị kinh tế cho cổ đông bằng những dự án tạo return vượt opportunity cost trên cùng mức rủi ro.","trap":"High accounting earnings do not necessarily create shareholder value."},{"heading":"Stage 1 idea generation","body":"Thu thập ý tưởng dự án từ operations, khách hàng, nhà quản lý, innovation và consultants; cần hiểu capabilities và competitive position.","trap":"A plentiful idea pipeline is not a substitute for analysis."},{"heading":"Stage 2 investment analysis","body":"Ước lượng after-tax cash flows, amount, timing, duration, uncertainty, project risk và discount rate; thực hiện NPV/IRR.","trap":"Treat each project's cash flows as incremental rather than total firm sales."},{"heading":"Stage 3 planning/prioritization","body":"Khi vốn và năng lực triển khai hữu hạn, chọn danh mục dự án phù hợp mục tiêu và đem lại giá trị ròng tốt nhất; xét mutually exclusive và capital rationing.","trap":"Higher IRR need not imply higher dollar value added."},{"heading":"Stage 4 monitoring/post review","body":"Đối chiếu cash flows thực tế với forecast, cập nhật assumptions và điều chỉnh/abandon/expand sau khi triển khai.","trap":"A project approval is not the end of management responsibility."},{"heading":"Hurdle rate opportunity cost","body":"Required return r phản ánh return có thể kiếm được trên tài sản khác có rủi ro tương đương; không tự động bằng risk-free rate.","trap":"Internally generated cash is not free financing."},{"heading":"Incremental after-tax cash flow","body":"NPV sử dụng dòng tiền sau thuế phát sinh thêm do dự án, gồm capex, operating inflows/outflows, working-capital impacts và terminal value khi liên quan.","trap":"Accounting net income is not the same as free cash flow."},{"heading":"NPV definition","body":"NPV là hiện giá của tất cả dòng tiền sau thuế dự án, gồm vốn ra tại t=0; cho biết dự án làm tăng/giảm giá trị bao nhiêu tiền.","trap":"A positive NPV measures dollars, not a rate."},{"heading":"NPV accept/reject","body":"Với dự án độc lập: NPV>0 tạo giá trị, NPV<0 làm mất giá trị; NPV=0 vừa đạt hurdle nhưng không có biên an toàn dự báo.","trap":"Financing/strategic constraints may make NPV≥0 necessary but not sufficient."},{"heading":"Time value of money","body":"Mỗi dòng tiền ở t được chiết khấu bằng (1+r)^t; dòng tiền xa có PV nhỏ hơn khi r dương.","trap":"Do not discount t0 a second time."},{"heading":"NPV spreadsheet convention","body":"Excel/Sheets NPV(rate,CF1,CF2,...) chiết khấu CF đầu vào về t1, nên CF0 phải cộng bên ngoài.","trap":"NPV(rate,CF0,CF1...) is often one-period shifted."},{"heading":"Irregular cash flows","body":"Khi dòng tiền phát sinh ở thời điểm không đều hoặc có t=1,5 năm, dùng fractional exponent hoặc XNPV với ngày chính xác.","trap":"Ordinary NPV assumes equal periods."},{"heading":"IRR definition","body":"IRR là rate làm NPV=0 với chuỗi dòng tiền dự án; so sánh IRR với hurdle r nếu dòng tiền quy ước chỉ đổi dấu một lần.","trap":"IRR is not the same as required market return."},{"heading":"IRR decision rule","body":"Dự án độc lập conventional CF: IRR≥r thì về lý thuyết có thể nhận; IRR<r thì không.","trap":"Multiple sign changes may create ambiguous IRRs."},{"heading":"IRR spreadsheet convention","body":"IRR(values) thường cho các kỳ cách đều, bao gồm CF0 trong mảng; XIRR(values,dates) dành cho các ngày không đều.","trap":"IRR syntax differs from NPV's treatment of t0."},{"heading":"IRR reinvestment assumption","body":"Khi dùng IRR để diễn giải geometric realized return, giả định interim cash flows được tái đầu tư ở IRR; NPV đánh giá cơ hội tái đầu tư theo hurdle r.","trap":"High project IRR can be unrealistic to reinvest at."},{"heading":"Multiple IRR problem","body":"Dòng tiền thay đổi dấu hơn một lần có thể tạo nhiều nghiệm IRR; trong trường hợp đó ưu tiên NPV tại hurdle r.","trap":"Spreadsheets may return only one of several IRRs."},{"heading":"No IRR / pathological cash flow","body":"Chuỗi chỉ toàn dòng tiền dương hoặc chỉ toàn âm không có IRR hữu ích cho quyết định; NPV tại r vẫn xác định được.","trap":"Not every set of cash flows has a meaningful IRR."},{"heading":"Mutually exclusive ranking","body":"Khi chỉ chọn một trong hai dự án và chúng khác size/timing, có thể IRR cao hơn nhưng NPV thấp hơn; chọn dự án có NPV cao nhất trong các phương án khả thi.","trap":"IRR is a percentage, not monetary wealth added."},{"heading":"Capital scale effect","body":"Dự án nhỏ IRR 30% có thể chỉ tạo $1m, còn dự án lớn IRR 15% tạo $20m; NPV mới thể hiện giá trị dollar.","trap":"Higher percentage return does not always win."},{"heading":"ROIC company-level concept","body":"ROIC so sánh after-tax operating profit (NOPAT) với average invested capital dùng trong hoạt động; khác với project cash-flow NPV và IRR.","trap":"ROIC from consolidated statements is not project IRR."},{"heading":"CFAI denominator convention","body":"CFAI CI LM5 trình bày average invested capital = average long-term liabilities + equity capital; cần theo định nghĩa này khi làm câu tương ứng.","trap":"Do not accidentally include operating trade payables unless question defines another convention."},{"heading":"NOPAT computation","body":"NOPAT = operating income (EBIT)×(1−tax rate) nếu dữ liệu thuế phù hợp; đây là profit đo hoạt động trước cấu trúc tài trợ.","trap":"Interest expense is not deducted from EBIT in NOPAT."},{"heading":"Average invested capital","body":"Dùng bình quân đầu/cuối kỳ của long-term liabilities và equity thay vì chỉ balance ngày cuối, để khớp profit cả kỳ.","trap":"Read capital definition given in the question."},{"heading":"ROIC profitability test","body":"ROIC > required return trong dài hạn có thể là dấu hiệu hoạt động sử dụng vốn hiệu quả; nhưng ROIC kỳ quá khứ không thay NPV của dự án tương lai.","trap":"One year ROIC is not proof future investment worth."},{"heading":"ROIC decomposition","body":"ROIC = (NOPAT/Sales) × (Sales/Average invested capital), tức biên lợi nhuận hoạt động sau thuế nhân với số vòng quay vốn; cần cùng định nghĩa NOPAT và vốn.","trap":"High margin can coexist with low ROIC if turnover is weak."},{"heading":"NPV vs IRR vs ROIC information","body":"NPV/IRR cần dự báo cash flows dự án và hurdle rate, thường có thông tin nội bộ; ROIC có thể tính từ báo cáo tài chính công khai.","trap":"External analysts usually cannot audit all project NPVs."},{"heading":"ROIC interpretation limitations","body":"ROIC có thể chịu ảnh hưởng book values, depreciation, cấu trúc vốn, các dự án cũ và cách phân bổ lợi nhuận; phải so sánh ngành/thời gian.","trap":"Accounting ratios cannot substitute forward-looking project value."},{"heading":"Economic reinvestment costs","body":"Lợi nhuận giữ lại (CFO) có opportunity cost như equity capital vì có thể trả về cổ đông; không được giả định r=0.","trap":"No new share issuance does not make investment funds free."},{"heading":"Cash flow timing and value","body":"Cùng một tổng tiền dự kiến, nhận sớm hơn làm NPV cao hơn nếu r dương; back-loaded cash flows nhạy với r lớn hơn.","trap":"Timing is as important as the total dollars."},{"heading":"Analyst capital allocation checklist","body":"Xác định CF0/timing, after-tax incremental CF, r theo risk, NPV/IRR limitations, ROIC trend và post-investment accountability.","trap":"Always disclose rounding and rate/period conventions."}],"formulas":[{"name":"NPV multi-period","expr":"NPV=Σ[t=0..T] CF_t/(1+r)^t","meaning":"Giá trị gia tăng tính bằng currency.","conditions":"CF are after-tax incremental cash flows and r is risk-appropriate."},{"name":"NPV two-year","expr":"NPV=CF0+CF1/(1+r)+CF2/(1+r)^2","meaning":"Tiện tính ví dụ dự án hai năm.","conditions":"End-of-year timing."},{"name":"PV one future cash flow","expr":"PV=CF_T/(1+r)^T","meaning":"Chiết khấu một khoản tiền tương lai.","conditions":"r and time periods aligned."},{"name":"Hurdle decision","expr":"Accept if NPV≥0; reject if NPV<0","meaning":"Quy tắc cơ bản cho dự án độc lập khả thi.","conditions":"No room for error at exactly zero NPV."},{"name":"IRR equation","expr":"0=Σ[t=0..T] CF_t/(1+IRR)^t","meaning":"IRR là nghiệm r làm NPV bằng không.","conditions":"May be multiple/no roots when unconventional CF pattern."},{"name":"One-year IRR","expr":"IRR=CF1/(-CF0)−1","meaning":"Dự án chỉ chi tại t0 rồi thu một khoản tại t1.","conditions":"CF0<0 and CF1>0."},{"name":"Two-year single-terminal IRR","expr":"IRR=(CF2/(-CF0))^(1/2)−1","meaning":"Tỷ suất hòa vốn khi chỉ nhận tiền ở năm 2.","conditions":"No intervening cash flows."},{"name":"PV of annuity","expr":"PV=C×[1−(1+r)^(-n)]/r","meaning":"Hiện giá dòng tiền đều C cuối mỗi kỳ.","conditions":"r>0, equally spaced cash flows."},{"name":"XNPV fractional year","expr":"NPV=Σ CF_t/(1+r)^(days_since_start/365)","meaning":"Dòng tiền theo ngày không đều.","conditions":"Use actual day count and date conventions."},{"name":"Average invested capital","expr":"Avg IC=[(LT liabilities+equity)_start+(LT liabilities+equity)_end]/2","meaning":"Vốn bình quân theo CFAI CI LM5.","conditions":"Definitions may vary outside this context."},{"name":"NOPAT","expr":"NOPAT=EBIT×(1−tax rate)","meaning":"Lợi nhuận sau thuế từ hoạt động để tính ROIC.","conditions":"Simplified treatment for given tax rate."},{"name":"ROIC","expr":"ROIC=NOPAT / Avg invested capital","meaning":"Hiệu quả lợi nhuận trên vốn đầu tư bình quân.","conditions":"Accounting ratio not a project cash return."},{"name":"ROIC decomposition","expr":"ROIC=(NOPAT/Sales)×(Sales/Avg IC)","meaning":"After-tax operating margin × invested capital turnover.","conditions":"Same NOPAT and capital basis in both components."},{"name":"Incremental operating cash flow","expr":"Incremental operating CF≈(ΔRevenue−ΔCashCosts)×(1−T)+Tax depreciation shield","meaning":"Chuyển doanh thu/cost thành dòng tiền sau thuế.","conditions":"Working capital, terminal effects and project tax rules additionally matter."},{"name":"Depreciation tax shield","expr":"Annual depreciation tax shield≈Depreciation×Tax rate","meaning":"Khấu hao giảm nghĩa vụ thuế khi taxable income đủ.","conditions":"Tax law and income constraints apply."},{"name":"Project cash flow after WC","expr":"CF_t,project≈after-tax operating cash_t−capital spending_t−ΔNWC_t","meaning":"Bao gồm dòng tiền bị giữ trong vốn lưu động.","conditions":"Must also add WC release at terminal period when justified."},{"name":"Project NPV difference","expr":"Value advantage=NPV_A−NPV_B","meaning":"Chọn dự án giá trị cao hơn khi mutually exclusive.","conditions":"Compare at same valid hurdle and under mutually exclusive constraint."},{"name":"Required return by risk","expr":"Project hurdle=risk-adjusted required return of comparable investment","meaning":"Tỷ lệ chiết khấu theo mức rủi ro, không mặc định risk-free.","conditions":"Project-specific risk can differ from issuer WACC."},{"name":"Simple capital turnover","expr":"Invested capital turnover=Sales/Avg IC","meaning":"Một thành phần tạo nên ROIC.","conditions":"Average balances convention."},{"name":"Accounting return spread","expr":"ROIC − required return","meaning":"Khoảng cách giữa hiệu quả kế toán và opportunity cost.","conditions":"Spread is a diagnostic, not equivalent to NPV."},{"name":"NPV Excel convention","expr":"Excel/Sheets: NPV(rate,CF1,...,CFT)+CF0","meaning":"Tránh chiết khấu sai CF0.","conditions":"First argument assumes CF1 at t1."},{"name":"IRR Excel convention","expr":"Excel/Sheets: IRR(CF0,CF1,...,CFT)","meaning":"Trình bày đúng chuỗi kể cả CF0.","conditions":"Equal-period spacing; use XIRR if irregular."}],"examples":[{"question_en":"An independent project costs $100m now and returns $115m one year later. Required return 10%. Find NPV.","answer":"$4.55 million","steps_vi":["NPV=−100+115/1,10=4,545m USD.","NPV dương nên dự án tạo thêm giá trị nếu forecast và hurdle hợp lý."],"check":"Rounded to two decimals."},{"question_en":"A project costs $100m today and pays $121m at the end of Year 2 only. What is IRR?","answer":"10%","steps_vi":["IRR=(121/100)^(1/2)−1=0,10.","Đây là geometric rate cho hai năm; không dùng 21% là IRR năm."],"check":"Two periods."},{"question_en":"A project pays CF0=-$100m, CF1=$50m, CF2=$70m. At r=10%, calculate NPV.","answer":"$3.31 million","steps_vi":["NPV=−100+50/1,10+70/1,10².","Kết quả 3,3058m USD, dự án có NPV dương."],"check":"Two-year end-of-period flows."},{"question_en":"An issuer will receive $60m in each of Years 1 and 2 after $100m investment. At r=10%, find NPV.","answer":"$4.13 million","steps_vi":["NPV=−100+60/1,10+60/1,10².","NPV≈4,132m USD; discount mỗi khoản theo năm tương ứng."],"check":"Two periods."},{"question_en":"A $100m investment produces a single cash receipt $120m at Year 1. Find IRR.","answer":"20%","steps_vi":["Giải phương trình 0=−100+120/(1+IRR).","IRR=120/100−1=20%, không cần Excel."],"check":"One-period conventional CF."},{"question_en":"An investment requires $100m now and yields $110m one year later. At required rate 10%, decide.","answer":"NPV = $0; marginally acceptable","steps_vi":["NPV=−100+110/1,10=0.","Chỉ vừa đạt hurdle nên không có dự phòng cho forecast error."],"check":"NPV=0 decision nuance."},{"question_en":"An investment costs $100m and pays $95m one year later. Required return 5%. Calculate NPV.","answer":"−$9.52 million","steps_vi":["NPV=−100+95/1,05=−9,5238m USD.","Do âm, dự án giảm giá trị theo assumptions đã cho."],"check":"Rounded."},{"question_en":"A project yields $40m after one year and $80m after two years, with initial cost $100m and r=10%. Find NPV.","answer":"$2.48 million","steps_vi":["NPV=−100+40/1,10+80/1,10².","NPV≈2,4793m USD; cộng PV thay vì cộng dòng tiền danh nghĩa."],"check":"Approximation."},{"question_en":"A firm has after-tax operating profit $18m and average invested capital $150m. Compute ROIC.","answer":"12%","steps_vi":["ROIC=18/150×100%=12%.","Đây là tỷ suất lợi nhuận hoạt động sau thuế trên vốn bình quân."],"check":"Company-level ratio."},{"question_en":"EBIT is $20m, tax rate 25%, and average invested capital $150m. Calculate ROIC.","answer":"10%","steps_vi":["NOPAT=20×0,75=15m; ROIC=15/150=10%.","Không trừ interest expense khi tính EBIT→NOPAT theo định nghĩa."],"check":"Given tax approximation."},{"question_en":"A company has long-term liabilities and equity of $100m at start and $120m at end. NOPAT $16.5m. Compute ROIC.","answer":"15%","steps_vi":["Average capital=(100+120)/2=110m.","ROIC=16,5/110=15%, không chỉ dùng mẫu số cuối kỳ."],"check":"Average long-term liabilities + equity."},{"question_en":"A firm has after-tax operating margin 12% and invested capital turnover 1.5×. What ROIC does the decomposition imply?","answer":"18%","steps_vi":["ROIC=0,12×1,5=0,18.","Hai doanh nghiệp khác asset turnover có thể khác ROIC dù margin giống nhau."],"check":"Same capital basis."},{"question_en":"A company has sales $200m, NOPAT $20m, and average invested capital $250m. Compute margin, turnover, ROIC.","answer":"10%; 0.80×; 8%","steps_vi":["Biên hoạt động sau thuế = 20/200 = 10%; số vòng quay vốn = 200/250 = 0,80 lần.","ROIC=10%×0,80=8%; hiệu quả kế toán chịu tác động cả margin và capital turnover."],"check":"Three linked outputs."},{"question_en":"A project has after-tax CF $55m payable in exactly 1.5 years and costs $50m now. Discount rate 10%. Is NPV positive?","answer":"No; NPV approximately −$2.33 million","steps_vi":["Với khoản tiền 55 triệu USD ở đúng 1,5 năm, NPV=−50+55/(1,10)^1,5.","Kết quả ≈−2,3269 triệu USD, làm tròn −2,33 triệu USD; dùng số mũ thời gian chính xác."],"check":"Fractional-year discounting."},{"question_en":"A project costs $30m and generates a $40m cash inflow at Year 2 only. Find IRR.","answer":"Approximately 15.47%","steps_vi":["IRR=sqrt(40/30)−1≈15,47%.","Dòng tiền sau 2 năm cần lấy căn bậc hai khi quy về rate mỗi năm."],"check":"Two years."},{"question_en":"Two mutually exclusive projects have IRRs of 35% and 18%, but NPVs $2m and $15m at the same risk-adjusted hurdle. Which adds more value?","answer":"Project with NPV $15m","steps_vi":["Khi chỉ chọn một, NPV đo mức tăng giá trị tiền tệ.","IRR cao hơn không nhất thiết tăng wealth nhiều hơn."],"check":"Mutually exclusive criterion."},{"question_en":"A project has cash flows −$100 at t0, +$230 at t1, −$132 at t2. How many distinct positive IRRs are there?","answer":"Two: 10% and 20%","steps_vi":["Phương trình −100+230/(1+r)−132/(1+r)^2=0.","Có nghiệm r=10%,20%; sign changes nhiều lần làm IRR thiếu duy nhất."],"check":"Use NPV instead."},{"question_en":"A company receives after-tax operating profit $12m and has average capital $160m. Compare ROIC with a 9% required return.","answer":"ROIC 7.50%; below hurdle","steps_vi":["ROIC=12/160=7,50%.","Mức thấp hơn hurdle là dấu hiệu nên xem xét hiệu quả, không tự động bác mọi dự án tương lai."],"check":"Historical not forward-looking."},{"question_en":"A firm has $10m annual EBIT and tax rate 30%. Calculate NOPAT.","answer":"$7 million","steps_vi":["NOPAT=10×(1−0,30)=7m.","Khác net income nếu công ty có interest/other non-operating items."],"check":"Operating tax assumption."},{"question_en":"A company has sales $400m, after-tax operating margin 5%, and capital turnover 2.0×. Calculate ROIC.","answer":"10%","steps_vi":["ROIC=5%×2,0=10%.","Tỷ lệ hiệu quả vốn có thể cao dù operating margin thấp."],"check":"Sales/capital link."},{"question_en":"A project yields CF0=−$100m, CF1=$50m, CF2=$70m. What should be entered into Excel NPV at 10%?","answer":"=NPV(10%,50,70)−100","steps_vi":["NPV function chiết khấu CF1 và CF2; CF0 cộng bên ngoài.","Nếu nhập CF0 bên trong NPV sẽ dịch sai một kỳ."],"check":"Spreadsheet convention."},{"question_en":"An issuer wants to compute IRR for cash flows −$50m, $30m, $30m at evenly spaced years. Which spreadsheet inputs?","answer":"=IRR(−50,30,30)","steps_vi":["IRR array bao gồm CF0 đầu tiên, khác NPV.","Số kỳ phải đều nhau."],"check":"IRR syntax."},{"question_en":"A project has two possible future payoffs but the analyst knows only historic ROIC. Can the analyst compute an authoritative project IRR?","answer":"No","steps_vi":["Project IRR cần chuỗi dòng tiền dự kiến theo thời gian; ROIC toàn công ty là chỉ số kế toán từ dữ liệu tổng hợp.","Không thay forecast project IRR bằng ROIC historical."],"check":"Different information."},{"question_en":"A company has $200m incremental project capex today, then $130m each in Years 1 and 2. Required return 10%. Compute NPV.","answer":"$25.62 million","steps_vi":["NPV=−200+130/1,1+130/1,1².","Giá trị ≈25,62m dương, dù capex ban đầu rất lớn."],"check":"End-year CF."},{"question_en":"An issuer earns $30m NOPAT with long-term debt+equity $280m at year start and $320m at year end. Compute ROIC.","answer":"10%","steps_vi":["Capital bình quân=(280+320)/2=300m.","ROIC=30/300=10%."],"check":"CFAI CI invested capital convention."},{"question_en":"A project is expected to return $110 after one year for a $100 investment. Which hurdle leads to NPV exactly zero?","answer":"10%","steps_vi":["IRR=110/100−1=10%; tại r=10%, NPV=0.","IRR chính là hurdle hòa vốn của dòng tiền."],"check":"Conventional one-year case."}],"questions":[{"stem_en":"An independent capital project has NPV of +$4m at its required rate. The project most likely:","options":["Increases shareholder value by $4m.","Has an IRR of exactly 4%.","Generates $4m net accounting income every year."],"correct":0,"why_vi":"NPV là số tiền giá trị hiện tại ròng tăng thêm, không phải % hoặc annual earnings.","trap_vi":"Dollar versus rate."},{"stem_en":"Which stage comes immediately after idea generation in capital allocation?","options":["Post-investment review.","Investment analysis.","Planning and prioritization."],"correct":1,"why_vi":"Trình tự CFAI: idea → investment analysis → planning/prioritization → post-review.","trap_vi":"Recognize stage order."},{"stem_en":"A positive project NPV means:","options":["IRR must equal risk-free rate.","Accounting ROIC must increase in Year 1.","Present value of expected benefits exceeds project cost."],"correct":2,"why_vi":"NPV dương khi PV future net cash flows lớn hơn dòng tiền đầu tư theo r đã chọn.","trap_vi":"Cash flows and discount rate required."},{"stem_en":"Under an ordinary conventional cash flow pattern, which IRR rule is appropriate?","options":["Accept if IRR exceeds the risk-appropriate hurdle.","Accept if IRR is below zero.","Accept if IRR exceeds the risk-free rate irrespective of risk."],"correct":0,"why_vi":"So sánh IRR với required return của dự án cùng mức rủi ro.","trap_vi":"Hurdle can be above risk-free."},{"stem_en":"Which measure is expressed in currency rather than a percentage?","options":["IRR.","NPV.","ROIC."],"correct":1,"why_vi":"NPV đo giá trị thêm tính bằng USD/EUR; IRR/ROIC là rates.","trap_vi":"Size/timing differences matter."},{"stem_en":"A company can choose only one of two projects. Project A has higher IRR; Project B has higher NPV. At valid comparable hurdles the preferred project is generally:","options":["Project A.","Neither could be considered.","Project B."],"correct":2,"why_vi":"Khi mutually exclusive, ưu tiên dự án đem lại NPV cao hơn.","trap_vi":"NPV adds more dollar value."},{"stem_en":"The IRR of a conventional one-year project with CF0=−100 and CF1=120 is:","options":["20%.","10%.","120%."],"correct":0,"why_vi":"IRR =120/100−1=20%; vốn đầu kỳ 100 và tiền thu năm sau 120.","trap_vi":"Do not confuse gross return multiple with IRR."},{"stem_en":"At the project's required discount rate, NPV is exactly zero. The investment:","options":["Definitely destroys value.","Earns exactly the required expected rate before forecast risk.","Necessarily has no future cash flows."],"correct":1,"why_vi":"NPV=0 nghĩa là dự kiến vừa đủ bù opportunity cost, chưa có biên an toàn.","trap_vi":"Forecast can be wrong."},{"stem_en":"A project has cash flows −100, +230, −132 in three consecutive periods. Which method is most reliable for accept/reject?","options":["IRR because it is always unique.","Historical ROIC.","NPV evaluated at the required rate."],"correct":2,"why_vi":"Dòng tiền đổi dấu nhiều lần có thể tạo nhiều IRR; NPV nhất quán hơn.","trap_vi":"Multiple IRRs."},{"stem_en":"In a spreadsheet, which convention avoids misplacing time-zero cash flow for NPV?","options":["Add CF0 separately to NPV(rate,CF1,...).","Include CF0 as the first discounted future flow.","Use sales instead of cash flow."],"correct":0,"why_vi":"Excel/Sheets NPV function mặc định giá trị đầu vào đầu tiên ở t1.","trap_vi":"No extra discount on t0."},{"stem_en":"For cash flows dated irregularly, the appropriate spreadsheet calculation is:","options":["Ordinary IRR with equal spacing assumed.","XIRR/XNPV using dates.","Simple annual sales growth."],"correct":1,"why_vi":"XIRR/XNPV cho phép ngày phát sinh không đều.","trap_vi":"Match date fraction."},{"stem_en":"Which assumption about IRR can make it misleading as a realized geometric project return?","options":["Discount cash flows at the same hurdle as NPV.","Ignore the initial investment.","Reinvest interim cash flows at IRR."],"correct":2,"why_vi":"Khi lãi tái đầu tư thực tế khác IRR, realized geometric rate có thể khác.","trap_vi":"Reinvestment assumption."},{"stem_en":"The return on invested capital (ROIC) is calculated using:","options":["After-tax operating profit over average invested capital.","Net sales over ending current liabilities.","Gross revenue over share price."],"correct":0,"why_vi":"ROIC = NOPAT / vốn đầu tư bình quân; đây là chỉ số kế toán của hoạt động kinh doanh.","trap_vi":"Company-level accounting ratio."},{"stem_en":"For CFAI Corporate Issuers LM5, invested capital is measured using:","options":["Inventories plus receivables only.","Average long-term liabilities plus equity.","Operating revenue plus market value of debt."],"correct":1,"why_vi":"Theo module, mẫu số là vốn dài hạn và equity bình quân.","trap_vi":"Context-specific convention."},{"stem_en":"An issuer has EBIT $20m, tax rate 25%, average invested capital $150m. Its ROIC is:","options":["7.5%.","13.33%.","10%."],"correct":2,"why_vi":"NOPAT=20×0,75=15 triệu USD, nên ROIC=15/150=10%.","trap_vi":"Do not use EBIT before tax."},{"stem_en":"Which combination decomposes ROIC?","options":["After-tax operating margin × capital turnover.","Gross margin × P/E.","Debt ratio × interest coverage."],"correct":0,"why_vi":"ROIC=(NOPAT/Sales)×(Sales/Avg invested capital), tức margin hoạt động sau thuế × vòng quay vốn.","trap_vi":"Denominators cancel."},{"stem_en":"Compared with project NPV and IRR, company ROIC is more readily available to outside analysts because it:","options":["Needs precise internal project forecasts.","Can be calculated from consolidated accounts.","Always predicts future project cash flows."],"correct":1,"why_vi":"BCTC cho dữ liệu vốn/lợi nhuận hoạt động nhưng không có forecasts từng project.","trap_vi":"ROIC is backward-looking."},{"stem_en":"A high profit margin firm can still have low ROIC if:","options":["Tax is always zero.","Every project has a negative IRR.","Invested capital turnover is very low."],"correct":2,"why_vi":"ROIC=margin×turnover nên quay vòng vốn yếu làm ROIC thấp.","trap_vi":"Asset efficiency matters."},{"stem_en":"Which rate is appropriate for discounting project after-tax cash flows?","options":["The required rate on investments of similar risk.","Always the government bill yield.","Always zero for retained earnings."],"correct":0,"why_vi":"Discount rate phải phản ánh opportunity cost có rủi ro tương tự.","trap_vi":"Internal financing is not free."},{"stem_en":"A firm discounts future cash flows at 10% instead of 20%, all else equal, NPV of a conventional future-positive-cash-flow project will generally:","options":["Fall.","Rise.","Be invariant."],"correct":1,"why_vi":"Với CF tương lai dương, r thấp làm hiện giá lớn hơn nên NPV tăng.","trap_vi":"Sign pattern matters."},{"stem_en":"ROIC of 9% for last year and hurdle 11% for a new project implies:","options":["The new project definitely has negative NPV.","No project could be undertaken.","Historical ROIC alone cannot establish new project NPV."],"correct":2,"why_vi":"ROIC quá khứ là tín hiệu hiệu quả công ty, không phải chuỗi CF mới.","trap_vi":"Different decision measures."},{"stem_en":"A project costs $100m and returns $121m at the end of Year 2. What is its IRR?","options":["10%.","21%.","11%."],"correct":0,"why_vi":"Lãi suất IRR hai năm=(121/100)^(1/2)−1=10% mỗi năm.","trap_vi":"Annualize across two years."},{"stem_en":"A project's NPV is negative but accounting earnings are positive. Which conclusion is most supported?","options":["Earnings guarantee positive investor wealth.","The project does not earn its risk-adjusted opportunity cost.","The project's cash receipts are all zero."],"correct":1,"why_vi":"Cash flows sau chiết khấu không bù được đầu tư theo hurdle.","trap_vi":"Earnings not NPV."},{"stem_en":"The main role of monitoring and post-investment review is:","options":["To avoid recording all depreciation.","To eliminate future uncertainty permanently.","To compare realized outcomes with original forecasts and adjust."],"correct":2,"why_vi":"Review theo dõi dự báo, nhận diện sai lệch và điều chỉnh dự án.","trap_vi":"Capital allocation is iterative."},{"stem_en":"A project with IRR of 12% and hurdle 15% under conventional cash flows most likely has:","options":["Negative NPV.","Positive NPV.","Exactly zero NPV."],"correct":0,"why_vi":"Khi IRR thấp hơn required return, NPV tại hurdle âm.","trap_vi":"Applies to conventional CF."},{"stem_en":"An issuer's after-tax operating profit is $16m and invested capital is $200m. Its ROIC is:","options":["12%.","8%.","20%."],"correct":1,"why_vi":"ROIC=16/200=8% trên vốn đầu tư bình quân.","trap_vi":"Average capital definition."},{"stem_en":"Which of the following would most directly change ROIC while leaving operating margin unchanged?","options":["A 1-for-1 split of shares.","A change in P/E without operating effects.","A change in invested capital turnover."],"correct":2,"why_vi":"ROIC=margin×turnover; quay vòng vốn thay đổi làm ROIC thay đổi.","trap_vi":"Market multiples are not ROIC."}],"cards":[{"front_en":"Explain: Capital allocation objective","back_vi":"Management và board phân bổ vốn để tối đa hóa giá trị kinh tế cho cổ đông bằng những dự án tạo return vượt opportunity cost trên cùng mức rủi ro."},{"front_en":"Explain: Stage 1 idea generation","back_vi":"Thu thập ý tưởng dự án từ operations, khách hàng, nhà quản lý, innovation và consultants; cần hiểu capabilities và competitive position."},{"front_en":"Explain: Stage 2 investment analysis","back_vi":"Ước lượng after-tax cash flows, amount, timing, duration, uncertainty, project risk và discount rate; thực hiện NPV/IRR."},{"front_en":"Explain: Stage 3 planning/prioritization","back_vi":"Khi vốn và năng lực triển khai hữu hạn, chọn danh mục dự án phù hợp mục tiêu và đem lại giá trị ròng tốt nhất; xét mutually exclusive và capital rationing."},{"front_en":"Explain: Stage 4 monitoring/post review","back_vi":"Đối chiếu cash flows thực tế với forecast, cập nhật assumptions và điều chỉnh/abandon/expand sau khi triển khai."},{"front_en":"Explain: Hurdle rate opportunity cost","back_vi":"Required return r phản ánh return có thể kiếm được trên tài sản khác có rủi ro tương đương; không tự động bằng risk-free rate."},{"front_en":"Explain: Incremental after-tax cash flow","back_vi":"NPV sử dụng dòng tiền sau thuế phát sinh thêm do dự án, gồm capex, operating inflows/outflows, working-capital impacts và terminal value khi liên quan."},{"front_en":"Explain: NPV definition","back_vi":"NPV là hiện giá của tất cả dòng tiền sau thuế dự án, gồm vốn ra tại t=0; cho biết dự án làm tăng/giảm giá trị bao nhiêu tiền."},{"front_en":"Explain: NPV accept/reject","back_vi":"Với dự án độc lập: NPV>0 tạo giá trị, NPV<0 làm mất giá trị; NPV=0 vừa đạt hurdle nhưng không có biên an toàn dự báo."},{"front_en":"Explain: Time value of money","back_vi":"Mỗi dòng tiền ở t được chiết khấu bằng (1+r)^t; dòng tiền xa có PV nhỏ hơn khi r dương."},{"front_en":"Explain: NPV spreadsheet convention","back_vi":"Excel/Sheets NPV(rate,CF1,CF2,...) chiết khấu CF đầu vào về t1, nên CF0 phải cộng bên ngoài."},{"front_en":"Explain: Irregular cash flows","back_vi":"Khi dòng tiền phát sinh ở thời điểm không đều hoặc có t=1,5 năm, dùng fractional exponent hoặc XNPV với ngày chính xác."},{"front_en":"Explain: IRR definition","back_vi":"IRR là rate làm NPV=0 với chuỗi dòng tiền dự án; so sánh IRR với hurdle r nếu dòng tiền quy ước chỉ đổi dấu một lần."},{"front_en":"Explain: IRR decision rule","back_vi":"Dự án độc lập conventional CF: IRR≥r thì về lý thuyết có thể nhận; IRR<r thì không."},{"front_en":"Explain: IRR spreadsheet convention","back_vi":"IRR(values) thường cho các kỳ cách đều, bao gồm CF0 trong mảng; XIRR(values,dates) dành cho các ngày không đều."},{"front_en":"Explain: IRR reinvestment assumption","back_vi":"Khi dùng IRR để diễn giải geometric realized return, giả định interim cash flows được tái đầu tư ở IRR; NPV đánh giá cơ hội tái đầu tư theo hurdle r."},{"front_en":"Explain: Multiple IRR problem","back_vi":"Dòng tiền thay đổi dấu hơn một lần có thể tạo nhiều nghiệm IRR; trong trường hợp đó ưu tiên NPV tại hurdle r."},{"front_en":"Explain: No IRR / pathological cash flow","back_vi":"Chuỗi chỉ toàn dòng tiền dương hoặc chỉ toàn âm không có IRR hữu ích cho quyết định; NPV tại r vẫn xác định được."},{"front_en":"Explain: Mutually exclusive ranking","back_vi":"Khi chỉ chọn một trong hai dự án và chúng khác size/timing, có thể IRR cao hơn nhưng NPV thấp hơn; chọn dự án có NPV cao nhất trong các phương án khả thi."},{"front_en":"Explain: Capital scale effect","back_vi":"Dự án nhỏ IRR 30% có thể chỉ tạo $1m, còn dự án lớn IRR 15% tạo $20m; NPV mới thể hiện giá trị dollar."},{"front_en":"Explain: ROIC company-level concept","back_vi":"ROIC so sánh after-tax operating profit (NOPAT) với average invested capital dùng trong hoạt động; khác với project cash-flow NPV và IRR."},{"front_en":"Explain: CFAI denominator convention","back_vi":"CFAI CI LM5 trình bày average invested capital = average long-term liabilities + equity capital; cần theo định nghĩa này khi làm câu tương ứng."},{"front_en":"Explain: NOPAT computation","back_vi":"NOPAT = operating income (EBIT)×(1−tax rate) nếu dữ liệu thuế phù hợp; đây là profit đo hoạt động trước cấu trúc tài trợ."},{"front_en":"Explain: Average invested capital","back_vi":"Dùng bình quân đầu/cuối kỳ của long-term liabilities và equity thay vì chỉ balance ngày cuối, để khớp profit cả kỳ."},{"front_en":"Explain: ROIC profitability test","back_vi":"ROIC > required return trong dài hạn có thể là dấu hiệu hoạt động sử dụng vốn hiệu quả; nhưng ROIC kỳ quá khứ không thay NPV của dự án tương lai."},{"front_en":"Explain: ROIC decomposition","back_vi":"ROIC = (after-tax operating profit / sales) × (sales / average invested capital): operating profit margin × capital turnover."},{"front_en":"Explain: NPV vs IRR vs ROIC information","back_vi":"NPV/IRR cần dự báo cash flows dự án và hurdle rate, thường có thông tin nội bộ; ROIC có thể tính từ báo cáo tài chính công khai."},{"front_en":"Explain: ROIC interpretation limitations","back_vi":"ROIC có thể chịu ảnh hưởng book values, depreciation, cấu trúc vốn, các dự án cũ và cách phân bổ lợi nhuận; phải so sánh ngành/thời gian."},{"front_en":"Explain: Economic reinvestment costs","back_vi":"Lợi nhuận giữ lại (CFO) có opportunity cost như equity capital vì có thể trả về cổ đông; không được giả định r=0."},{"front_en":"Explain: Cash flow timing and value","back_vi":"Cùng một tổng tiền dự kiến, nhận sớm hơn làm NPV cao hơn nếu r dương; back-loaded cash flows nhạy với r lớn hơn."},{"front_en":"Explain: Analyst capital allocation checklist","back_vi":"Xác định CF0/timing, after-tax incremental CF, r theo risk, NPV/IRR limitations, ROIC trend và post-investment accountability."}]},{"id":"CFA26-03-05-LOS03","letter":"5.c","title_en":"Capital Allocation Principles and Common Pitfalls","outcome_en":"describe principles of capital allocation and common capital allocation pitfalls","overview_vi":"Nhấn mạnh after-tax incremental cash flows, sunk/opportunity costs, cannibalization, thuế và thời điểm dòng tiền; phân biệt cognitive forecasting errors với behavioral biases, lãi suất thực/danh nghĩa, chi phí vốn nội sinh và EPS-driven underinvestment.","source":[{"id":"CFA Institute Curriculum 2026 — Corporate Issuers LM5","pages":"166–171 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading24","pages":"259–261 (physical PDF)"},{"id":"SAPP Corporate Issuers 2026 — Module5","pages":"175–181 (physical PDF)"}],"sections":[{"heading":"Principle: after-tax cash flows","body":"Phân tích capex trên dòng tiền sau thuế, không dùng revenues, net accounting earnings hay lợi nhuận trước thuế một cách trực tiếp.","trap":"Taxes and cash accounting matter."},{"heading":"Noncash depreciation and tax","body":"Depreciation làm giảm taxable profit nên có depreciation tax shield dù bản thân depreciation không phải cash payment năm đó.","trap":"Do not subtract depreciation twice from free cash flows."},{"heading":"Principle: incremental only","body":"Chỉ tính cash flows khác biệt giữa hai trạng thái có dự án và không làm dự án.","trap":"Total firm cash flow is not incremental project cash flow."},{"heading":"Sunk costs excluded","body":"Chi phí đã phát sinh dù chọn hay không chọn dự án không đổi, nên không là cash flow gia tăng.","trap":"Just because an expense appears in project paperwork does not mean it belongs in NPV."},{"heading":"Opportunity costs included","body":"Nếu dùng nhà kho/đất/nguồn lực có thể cho thuê/bán, phải tính lợi ích tốt nhất bị từ bỏ do chọn dự án.","trap":"No new invoice does not mean zero economic cost."},{"heading":"Cannibalization included","body":"Dự án mới làm giảm doanh thu sản phẩm cũ, phần mất lợi nhuận là cash flow âm gia tăng cần tính.","trap":"Do not count only new product sales."},{"heading":"Synergies included","body":"Tiết kiệm vận hành hoặc tăng sales ở sản phẩm khác do dự án mới cũng thuộc incremental cash flows nếu có bằng chứng.","trap":"Only benefits caused by the project are incremental."},{"heading":"Financing costs and discounting","body":"Rủi ro dự án được phản ánh qua required return phù hợp, tránh vừa trừ toàn bộ interest vừa discount FCF tại WACC gây double count theo quy ước.","trap":"Financing approach must match cash-flow definition."},{"heading":"Principle: cash-flow timing","body":"Cùng lượng tiền nhưng về sớm hơn có PV lớn hơn tại positive r; timing và phân kỳ chi ra cần dự báo chính xác.","trap":"NPV uses when cash arrives, not accounting recognition date."},{"heading":"Working capital cash effects","body":"Dự án tăng inventory/receivables thường làm giảm cash đầu kỳ; khi kết thúc, vốn lưu động được giải phóng có thể cộng vào terminal CF.","trap":"Book profits miss working-capital timing."},{"heading":"Salvage and termination","body":"Thu hồi tài sản/giá trị bán cuối kỳ và thuế liên quan thuộc terminal incremental CF; dự báo phải nhất quán.","trap":"Salvage may be taxed depending on tax basis."},{"heading":"Nominal versus real consistency","body":"Nominal CF có inflation phải dùng nominal discount rate; real CF đã loại inflation phải dùng real rate.","trap":"Mixing real CF with nominal rates usually biases NPV."},{"heading":"Actual inflation uncertainty","body":"Kể cả mô hình dùng real cash flows/real rates, inflation thực tế khác kỳ vọng vẫn ảnh hưởng input prices, output prices và cash flows.","trap":"Real analysis does not make the firm immune to inflation."},{"heading":"Cognitive errors","body":"Sai dự báo, phép tính hoặc lựa chọn assumptions/hurdle (forecast error, cost estimates, competitor response) là lỗi nhận thức/phân tích có thể kiểm chứng.","trap":"Not every bad outcome proves a behavioral bias."},{"heading":"Overoptimistic cash-flow forecasts","body":"Đánh giá demand quá cao, chi phí thấp, chậm tiến độ hoặc không tính cạnh tranh làm NPV ước lượng cao sai.","trap":"Project risk requires downside scenarios and post audits."},{"heading":"Ignoring competitor response","body":"Giá bán/lợi nhuận tăng có thể kéo đối thủ gia nhập, giảm thị phần; nên dự báo phản ứng cạnh tranh trong CF.","trap":"Base case with no competitive response can overstate value."},{"heading":"Underestimating corporate overhead","body":"Phân bổ thời gian quản lý, IT support, compliance và indirect costs không đúng có thể làm lợi nhuận dự án bị thổi phồng.","trap":"Allocate genuinely incremental costs, not arbitrary sunk overhead."},{"heading":"Ignoring cost of retained earnings","body":"Tiền do hoạt động giữ lại có opportunity cost đối với cổ đông vì có thể trả dưới dạng dividend, nên dùng discount rate theo rủi ro dự án.","trap":"CFO funding is not free."},{"heading":"Nominal-real error","body":"Dùng CF danh nghĩa với real discount rate làm NPV thường bị thổi lên trong inflation dương đối với dòng tiền dương tương lai.","trap":"Match nominal to nominal."},{"heading":"Behavioral bias: inertia","body":"Management có thể neo ngân sách capex năm mới vào năm trước thay vì NPV/strategic need của từng dự án.","trap":"Stable spending can be rational but should be justified."},{"heading":"Anchoring to past budgets","body":"Đầu tư lặp lại theo % hay số tiền cũ, ít điều chỉnh dù ROI của segment đi xuống, cần phân tích phản biện.","trap":"Historical budget is not an opportunity-cost hurdle."},{"heading":"Behavioral bias: EPS focus","body":"Ưu tiên EPS/net income/ROE ngắn hạn khiến management bỏ lỡ dự án positive-NPV nhưng giảm earnings kế toán ban đầu.","trap":"A buyback boosting EPS is not proof of superior value creation."},{"heading":"Agency incentives and underinvestment","body":"Nếu compensation thưởng EPS hoặc margin ngắn hạn, management có động cơ trì hoãn R&D/capex dù triển vọng dài hạn tốt.","trap":"Governance design shapes capital allocation outcomes."},{"heading":"Overinvestment/empire building","body":"Ban quản lý muốn mở rộng quy mô/địa vị có thể đầu tư dự án NPV âm hoặc M&A đắt giá.","trap":"Growth in assets is not shareholder wealth creation."},{"heading":"Post-investment review as discipline","body":"So sánh dự báo với thực tế, đánh giá nguyên nhân lỗi, cơ chế sửa và phân bổ vốn cho kỳ tiếp theo.","trap":"Review is important even when the project was initially positive NPV."},{"heading":"Inflation and relative prices","body":"Inflation không đồng đều: giá nguyên liệu đầu vào và sản phẩm đầu ra thay đổi khác nhau, nên margin và tax CF thay đổi.","trap":"Simply applying a uniform inflation factor to every line may mislead."},{"heading":"Risk-adjusted required return","body":"Dự án khác mức rủi ro cần required rate khác; sử dụng risk-free hoặc WACC toàn công ty bất chấp rủi ro có thể ra quyết định sai.","trap":"A lower rate makes marginal projects look better."},{"heading":"Principles checklist","body":"Kiểm tra after-tax incremental CF, sunk vs opportunity, cannibalization/synergies, WC/tax, inflation basis, timing, r và quản trị quyết định.","trap":"Review both cognitive errors and behavioral incentives."}],"formulas":[{"name":"Incremental CF principle","expr":"Incremental CF=CF(with project)−CF(without project)","meaning":"Chuẩn so sánh quyết định đầu tư.","conditions":"Cash flows must be after-tax and time-specific."},{"name":"Sunk cost rule","expr":"Incremental impact of sunk cost=0","meaning":"Chi phí quá khứ không thay đổi theo quyết định hiện tại.","conditions":"If not recoverable or decision-dependent."},{"name":"Opportunity cost","expr":"Economic project cost includes foregone best alternative after-tax CF","meaning":"Giá trị sử dụng nguồn lực hiện có có thể không xuất hiện trên hóa đơn.","conditions":"Estimate feasible alternative net proceeds."},{"name":"Cannibalization","expr":"Project incremental revenue=New revenue−Lost existing-product revenue","meaning":"Nhận diện ảnh hưởng tiêu cực lên hoạt động sẵn có.","conditions":"Compare net contribution rather than gross sales if margins differ."},{"name":"Synergy after tax","expr":"After-tax synergy≈cash cost savings×(1−tax rate)","meaning":"Lợi ích lan tỏa sang hoạt động khác.","conditions":"Depreciation/other tax effects separately."},{"name":"Depreciation shield","expr":"Depreciation tax shield=tax rate×deductible depreciation","meaning":"Khấu hao giảm thuế.","conditions":"Requires taxable income and deductible asset basis."},{"name":"Incremental FCF simple","expr":"Project FCF≈(Incremental EBIT×(1−T))+Depreciation−Capex−ΔNWC","meaning":"Đưa tác động thuế và cash investing vào NPV.","conditions":"Salvage/taxes and other items may be needed."},{"name":"Terminal working-capital recovery","expr":"CF_terminal includes release of investment in NWC","meaning":"Khoản vốn lưu động giải phóng khi đóng dự án.","conditions":"Must be truly collectible."},{"name":"Nominal real Fisher","expr":"1+nominal rate=(1+real rate)×(1+expected inflation)","meaning":"Liên hệ discount rate danh nghĩa và thực.","conditions":"Rates per same period; expected inflation for valuation."},{"name":"Approximate Fisher","expr":"Nominal rate≈real rate+expected inflation","meaning":"Xấp xỉ khi mức lãi suất và lạm phát nhỏ.","conditions":"Exact cross-product omitted."},{"name":"Nominal CF adjustment","expr":"Nominal future CF≈Real CF×(1+inflation)^t","meaning":"Chuyển real→nominal khi inflation đồng đều.","conditions":"Individual project inputs may move at different inflation rates."},{"name":"NPV with inflation","expr":"NPV_nominal=Σ nominal_CF_t/(1+r_nominal)^t","meaning":"Ghép đúng nominal flows và rates.","conditions":"Taxes require nominal cash-flow forecast."},{"name":"NPV consistency","expr":"NPV_real=Σ real_CF_t/(1+r_real)^t","meaning":"Cùng kết quả lý thuyết nếu chuyển đổi nhất quán.","conditions":"Consistency requires proper cash-flow conversion."},{"name":"Net incremental cannibalization","expr":"Loss=Lost old sales×old contribution margin","meaning":"Chỉ tính phần margin mất do dự án mới.","conditions":"Not all gross old revenue is lost economic contribution."}],"examples":[{"question_en":"A firm already spent $2m on an unrefundable market survey before choosing whether to launch. Include the $2m in today's project NPV?","answer":"No; sunk cost","steps_vi":["Khảo sát đã trả và không thu hồi dù quyết định thế nào.","Không đưa chi phí chìm vào incremental CF tại thời điểm lựa chọn."],"check":"Time of decision matters."},{"question_en":"A project uses company land that could be sold today for $5m net. Is the land free?","answer":"No; include $5m opportunity cost","steps_vi":["Nếu chọn dự án sẽ từ bỏ 5 triệu USD tiền bán ròng có thể thu ngay.","Không có chi tiền mới không đồng nghĩa cost=0."],"check":"Tax-adjusted net proceeds if relevant."},{"question_en":"A new product generates $20m sales but reduces existing product sales by $4m. What is net incremental sales?","answer":"$16 million","steps_vi":["Phần incremental revenue =20−4=16 triệu USD.","NPV đầy đủ cần contribution margins/taxes cho từng dòng."],"check":"Gross sales not total cash contribution."},{"question_en":"A project saves $3m pre-tax expenses per year, tax rate 30%, no other differences. Estimate after-tax savings.","answer":"$2.1 million","steps_vi":["Lợi ích sau thuế =3×(1−0,30)=2,1 triệu USD.","Nếu có depreciation tax shield thì cần cộng riêng."],"check":"Simplified tax."},{"question_en":"Annual tax-deductible depreciation on a new asset is $4m, tax rate 25%. Compute depreciation tax shield.","answer":"$1 million","steps_vi":["Lá chắn thuế =4×0,25=1 triệu USD/năm.","Khấu hao là chi phí phi tiền mặt nhưng giảm thuế tiền mặt."],"check":"Taxable income assumed sufficient."},{"question_en":"An issuer will recover $8m working capital at project termination. How should this affect terminal CF?","answer":"Add $8 million cash inflow","steps_vi":["Vốn bị giữ trong inventories/receivables được thu hồi cuối dự án.","Cộng vào terminal CF nếu thực sự có thể chuyển thành tiền."],"check":"Do not ignore recovery."},{"question_en":"A firm has real required return 4% and expected inflation 3%. Compute exact nominal required return.","answer":"7.12%","steps_vi":["Fisher: (1,04×1,03)−1=7,12%.","Không cộng giản đơn 4+3 nếu đề yêu cầu chính xác."],"check":"Same period."},{"question_en":"An analyst discounts nominal cash flows at a real interest rate while inflation is positive. What is the likely effect for positive future CF?","answer":"NPV is overstated","steps_vi":["Real rate thấp hơn nominal nên mẫu số chiết khấu quá nhỏ.","Dùng nominal CF với nominal r để tránh sai lệch."],"check":"Assume conventional positive future CF."},{"question_en":"An issuer has EBIT increment $10m, tax 25%, annual depreciation $2m and no capex or NWC change in the year. Estimate annual project operating cash flow.","answer":"$9.5 million","steps_vi":["FCF vận hành =10×0,75+2=9,5m nếu EBIT đã tính khấu hao 2m.","Không trừ depreciation lần nữa vì đó là noncash expense."],"check":"EBIT after depreciation."},{"question_en":"A $2m pre-tax annual cost saving with 25% tax is expected for three years. What is annual after-tax incremental saving?","answer":"$1.5 million","steps_vi":["Tiết kiệm sau thuế =2×(1−0,25)=1,5m/năm.","Có thể discount từng năm bằng hurdle phù hợp."],"check":"No price growth."},{"question_en":"Management's capex budget remains $100m despite steadily declining ROIC. Which bias should be investigated?","answer":"Inertia / anchoring","steps_vi":["Budget neo theo kỳ trước thay vì giá trị dự án được tạo.","Không kết luận sai hoàn toàn nếu chưa kiểm tra nhu cầu duy trì tài sản."],"check":"Examine trend and rationale."},{"question_en":"Managers reject a high-NPV project because it lowers next-year EPS. Name the likely pitfall.","answer":"EPS-driven behavioral bias","steps_vi":["Tập trung chỉ tiêu earnings ngắn hạn có thể gây underinvestment và bỏ lỡ shareholder value.","Cần xét cơ chế thưởng và horizon."],"check":"Short term metrics."},{"question_en":"An issuer uses cash generated internally for a risky project and sets required return to 0%. Is that justified?","answer":"No","steps_vi":["Retained cash có thể phân phối cho cổ đông, do đó chịu opportunity cost.","Dự án cần chiết khấu tại required return theo risk, không phải 0%."],"check":"Source of capital does not erase opportunity cost."},{"question_en":"A new factory raises old-unit revenue by $6m due to shared distribution gains. Is this effect relevant to the project?","answer":"Yes; positive synergy","steps_vi":["Lợi ích phụ thuộc vào việc làm dự án nên là incremental cash flow dương.","Cần tính sau thuế và theo thời điểm thích hợp."],"check":"Broader firm effects."},{"question_en":"The real year-2 CF is $100m and cumulative expected inflation is 10% over two years. What nominal year-2 CF is equivalent?","answer":"$110 million","steps_vi":["Khi tỷ số giá kỳ gốc→kỳ 2 tăng 10%, nominal CF tương ứng 100×1,10=110m.","Không nhân (1,10)^2 lần nữa vì đề đã cho cumulative inflation."],"check":"Cumulative versus annual inflation."},{"question_en":"An issuer has a negative incremental NPV project but predicts higher net income. Which objective should dominate?","answer":"Value creation / positive NPV","steps_vi":["Earnings tăng không chứng minh dự án bù được cost of capital.","Dùng after-tax cash flows và risk-adjusted hurdle."],"check":"Accounting bias."},{"question_en":"A project has NPV $12m excluding lost contribution from an existing product of $15m PV. What is adjusted NPV?","answer":"−$3 million","steps_vi":["Phần mất cash contribution phải trừ 12−15=−3m.","Nếu không điều chỉnh cannibalization sẽ phê duyệt sai."],"check":"Incremental negative effect."},{"question_en":"A project has total capex today $50m, but cash recovered from sale of old equipment is $8m net today. What is net initial cash outflow?","answer":"$42 million","steps_vi":["Initial incremental outflow =50−8=42m.","Chỉ trừ tiền bán equipment ròng sau các khoản thuế/phí có liên quan."],"check":"Cash proceeds at t0."}],"questions":[{"stem_en":"Which cost should generally be excluded when computing incremental project NPV?","options":["Previously incurred nonrecoverable market study expense.","Future incremental wages caused by the project.","Future foregone rental income from a used property."],"correct":0,"why_vi":"Chi phí khảo sát đã chi bất kể quyết định là sunk cost.","trap_vi":"Future incremental/opportunity costs count."},{"stem_en":"A company uses owned land that could be rented to another party. The foregone rental income is:","options":["A sunk cost.","An opportunity cost of the project.","A financing cash inflow."],"correct":1,"why_vi":"Tiền thuê mất đi vì dùng đất cho dự án là cash flow cơ hội.","trap_vi":"No accounting expense needed."},{"stem_en":"A new product steals sales from an existing product. The loss in the existing product's contribution is:","options":["Never relevant.","A pure financing cost.","An incremental negative cash flow."],"correct":2,"why_vi":"Cannibalization làm giảm CF nếu có dự án so với không có.","trap_vi":"Count whole-firm effects."},{"stem_en":"For NPV, management should generally use:","options":["Incremental after-tax cash flows.","Accounting revenue alone.","Past sunk costs only."],"correct":0,"why_vi":"CFAI yêu cầu dòng tiền sau thuế tăng thêm.","trap_vi":"Cash not earnings."},{"stem_en":"Depreciation is relevant to project NPV principally because it:","options":["Is an annual cash purchase of machinery.","Creates a tax shield if deductible.","Eliminates future inflation risk."],"correct":1,"why_vi":"Khấu hao làm giảm taxable income và tiền thuế phải trả dù bản thân noncash.","trap_vi":"Avoid double counting."},{"stem_en":"Which treatment of inflation is consistent?","options":["Nominal cash flows with real discount rate.","Real cash flows with nominal discount rate.","Nominal cash flows with nominal discount rate."],"correct":2,"why_vi":"Ghép cùng đơn vị giá trị tiền tệ để NPV không sai lệch.","trap_vi":"Match rate/flow definitions."},{"stem_en":"A firm's expected inflation is 3% and real required return 4%. Exact nominal return is:","options":["7.12%.","7.00%.","1.00%."],"correct":0,"why_vi":"Theo Fisher, lãi suất danh nghĩa chính xác =1,04×1,03−1=7,12%, cao hơn phép cộng gần đúng 7,00%.","trap_vi":"Exact vs approximate."},{"stem_en":"A firm holds a large retained earnings balance. The cost of capital for investing it is:","options":["Zero because no securities are issued.","The opportunity cost of similarly risky shareholder investment.","Always the bank rate."],"correct":1,"why_vi":"Lợi nhuận giữ lại thuộc vốn của cổ đông và có cost of equity/opportunity cost.","trap_vi":"Internal cash is not free."},{"stem_en":"An annual capex budget closely copied from the previous year despite falling ROIC may indicate:","options":["A one-time sunk cost.","A mandatory valuation convention.","Capital allocation inertia."],"correct":2,"why_vi":"Inertia/anchoring vào ngân sách quá khứ cần xem xét.","trap_vi":"Historical path dependency."},{"stem_en":"A project with positive NPV reduces EPS during the first year. Which conclusion is most appropriate?","options":["It may still create value for shareholders.","Its NPV must be negative.","The firm should necessarily repurchase shares instead."],"correct":0,"why_vi":"Accounting EPS và NPV có mục tiêu khác nhau; nên xét giá trị dài hạn.","trap_vi":"Earnings focus pitfall."},{"stem_en":"Under an incremental cash-flow approach, the correct baseline is:","options":["With project minus yesterday's revenue.","With project minus without project.","Pre-tax sales minus tax credits only."],"correct":1,"why_vi":"So sánh hai kịch bản có và không có dự án.","trap_vi":"Counterfactual analysis."},{"stem_en":"A company expects to release $15m of NWC at the end of a project. This is:","options":["Irrelevant because NWC is accounting only.","A sunk cost.","A terminal cash inflow."],"correct":2,"why_vi":"Khoản vốn lưu động thu hồi là tiền vào cuối dự án.","trap_vi":"Include only when realizable."},{"stem_en":"Which is most clearly a cognitive forecasting error?","options":["Underestimating competitor responses.","Rewarding executives solely on EPS.","Copying last year's budget out of habit."],"correct":0,"why_vi":"Bỏ qua phản ứng cạnh tranh làm sai dự báo doanh thu/margin.","trap_vi":"Cognitive vs behavioral."},{"stem_en":"Which example best reflects a behavioral bias?","options":["A spreadsheet sums the wrong range.","Management rejects a positive-NPV project to protect this year's EPS bonus.","A tax rate is typed incorrectly."],"correct":1,"why_vi":"Incentive focus on EPS ngắn hạn gây lệch quyết định.","trap_vi":"Not merely a calculation mistake."},{"stem_en":"An investor notices that capex is rising while ROIC has been declining for several years. The best immediate analyst action is:","options":["Conclude every new project is bad.","Ignore management's decisions.","Scrutinize the rationale and post-investment results."],"correct":2,"why_vi":"Cần phản biện hiệu quả dùng vốn và inertia, không vội kết luận không có dự án tốt.","trap_vi":"Trend investigation."},{"stem_en":"Which cash-flow attribute has the largest direct relevance to NPV among the choices?","options":["Timing of after-tax incremental cash receipts.","Stock ticker alphabetic order.","Number of board committee names."],"correct":0,"why_vi":"PV của dòng tiền phụ thuộc thời điểm nhận và discount rate.","trap_vi":"Time value."},{"stem_en":"A project increases sales at a different division as a direct result of the project. This additional margin is:","options":["A sunk cost.","A positive incremental synergy.","Always an indirect noncash benefit."],"correct":1,"why_vi":"Dòng tiền khác biệt do dự án tạo ra phải được tính kể cả ở division khác.","trap_vi":"Firm-wide spillovers."},{"stem_en":"When assessing a real-cash-flow forecast, a firm should generally apply:","options":["The nominal required return in all cases.","A zero discount rate.","The corresponding real required return."],"correct":2,"why_vi":"Real CF đi với real hurdle nếu conversion nhất quán.","trap_vi":"Match rate basis."},{"stem_en":"In deciding between a new project and no new project, an expense that was already paid before today is:","options":["Typically irrelevant if nonrecoverable.","A future operating cash outflow.","Always part of CF0."],"correct":0,"why_vi":"Sunk expense không đổi dù chọn quyết định nào.","trap_vi":"Avoid sunk-cost fallacy."},{"stem_en":"In a conventional project model, a depreciation tax shield generally:","options":["Decreases after-tax project cash flows.","Increases after-tax project cash flows.","Changes cash flows only when assets are sold."],"correct":1,"why_vi":"Depreciation tax shield làm giảm tiền thuế và tăng cash after tax trong kỳ có lợi nhuận chịu thuế.","trap_vi":"Tax eligibility needed."},{"stem_en":"An issuer has project cash flows in nominal dollars that grow with inflation. Discounting them at a real rate will generally:","options":["Understate NPV for positive future CF.","Have no impact.","Overstate NPV for positive future CF."],"correct":2,"why_vi":"Lãi suất thực thấp hơn nominal làm PV bị tính quá cao.","trap_vi":"Sign and inflation assumptions matter."},{"stem_en":"A capital project that increases NPV but depresses year-one ROE is best described as:","options":["Potentially economically desirable despite near-term accounting dilution.","Necessarily value destroying.","Always a regulatory project."],"correct":0,"why_vi":"ROE năm đầu không đo phần giá trị dài hạn của incremental CF.","trap_vi":"Long-run shareholder wealth."},{"stem_en":"Which management practice best guards against repeated forecast mistakes?","options":["Avoiding comparisons with past projections.","Conducting post-investment reviews.","Replacing all cash flow analysis with EPS."],"correct":1,"why_vi":"So sánh actual vs forecast tạo feedback và sửa quyết định tiếp theo.","trap_vi":"Monitoring discipline."},{"stem_en":"The most likely consequence of overlooking future cleanup costs of a project is:","options":["Underestimating project NPV.","No valuation impact.","Overstating project NPV."],"correct":2,"why_vi":"Chi phí tương lai không tính vào mô hình khiến dòng tiền ròng dự phóng quá cao.","trap_vi":"Include all incremental obligations."}],"cards":[{"front_en":"Explain: Principle: after-tax cash flows","back_vi":"Phân tích capex trên dòng tiền sau thuế, không dùng revenues, net accounting earnings hay lợi nhuận trước thuế một cách trực tiếp."},{"front_en":"Explain: Noncash depreciation and tax","back_vi":"Depreciation làm giảm taxable profit nên có depreciation tax shield dù bản thân depreciation không phải cash payment năm đó."},{"front_en":"Explain: Principle: incremental only","back_vi":"Chỉ tính cash flows khác biệt giữa hai trạng thái có dự án và không làm dự án."},{"front_en":"Explain: Sunk costs excluded","back_vi":"Chi phí đã phát sinh dù chọn hay không chọn dự án không đổi, nên không là cash flow gia tăng."},{"front_en":"Explain: Opportunity costs included","back_vi":"Nếu dùng nhà kho/đất/nguồn lực có thể cho thuê/bán, phải tính lợi ích tốt nhất bị từ bỏ do chọn dự án."},{"front_en":"Explain: Cannibalization included","back_vi":"Dự án mới làm giảm doanh thu sản phẩm cũ, phần mất lợi nhuận là cash flow âm gia tăng cần tính."},{"front_en":"Explain: Synergies included","back_vi":"Tiết kiệm vận hành hoặc tăng sales ở sản phẩm khác do dự án mới cũng thuộc incremental cash flows nếu có bằng chứng."},{"front_en":"Explain: Financing costs and discounting","back_vi":"Rủi ro dự án được phản ánh qua required return phù hợp, tránh vừa trừ toàn bộ interest vừa discount FCF tại WACC gây double count theo quy ước."},{"front_en":"Explain: Principle: cash-flow timing","back_vi":"Cùng lượng tiền nhưng về sớm hơn có PV lớn hơn tại positive r; timing và phân kỳ chi ra cần dự báo chính xác."},{"front_en":"Explain: Working capital cash effects","back_vi":"Dự án tăng inventory/receivables thường làm giảm cash đầu kỳ; khi kết thúc, vốn lưu động được giải phóng có thể cộng vào terminal CF."},{"front_en":"Explain: Salvage and termination","back_vi":"Thu hồi tài sản/giá trị bán cuối kỳ và thuế liên quan thuộc terminal incremental CF; dự báo phải nhất quán."},{"front_en":"Explain: Nominal versus real consistency","back_vi":"Nominal CF có inflation phải dùng nominal discount rate; real CF đã loại inflation phải dùng real rate."},{"front_en":"Explain: Actual inflation uncertainty","back_vi":"Kể cả mô hình dùng real cash flows/real rates, inflation thực tế khác kỳ vọng vẫn ảnh hưởng input prices, output prices và cash flows."},{"front_en":"Explain: Cognitive errors","back_vi":"Sai dự báo, phép tính hoặc lựa chọn assumptions/hurdle (forecast error, cost estimates, competitor response) là lỗi nhận thức/phân tích có thể kiểm chứng."},{"front_en":"Explain: Overoptimistic cash-flow forecasts","back_vi":"Đánh giá demand quá cao, chi phí thấp, chậm tiến độ hoặc không tính cạnh tranh làm NPV ước lượng cao sai."},{"front_en":"Explain: Ignoring competitor response","back_vi":"Giá bán/lợi nhuận tăng có thể kéo đối thủ gia nhập, giảm thị phần; nên dự báo phản ứng cạnh tranh trong CF."},{"front_en":"Explain: Underestimating corporate overhead","back_vi":"Phân bổ thời gian quản lý, IT support, compliance và indirect costs không đúng có thể làm lợi nhuận dự án bị thổi phồng."},{"front_en":"Explain: Ignoring cost of retained earnings","back_vi":"Tiền do hoạt động giữ lại có opportunity cost đối với cổ đông vì có thể trả dưới dạng dividend, nên dùng discount rate theo rủi ro dự án."},{"front_en":"Explain: Nominal-real error","back_vi":"Dùng CF danh nghĩa với real discount rate làm NPV thường bị thổi lên trong inflation dương đối với dòng tiền dương tương lai."},{"front_en":"Explain: Behavioral bias: inertia","back_vi":"Management có thể neo ngân sách capex năm mới vào năm trước thay vì NPV/strategic need của từng dự án."},{"front_en":"Explain: Anchoring to past budgets","back_vi":"Đầu tư lặp lại theo % hay số tiền cũ, ít điều chỉnh dù ROI của segment đi xuống, cần phân tích phản biện."},{"front_en":"Explain: Behavioral bias: EPS focus","back_vi":"Ưu tiên EPS/net income/ROE ngắn hạn khiến management bỏ lỡ dự án positive-NPV nhưng giảm earnings kế toán ban đầu."},{"front_en":"Explain: Agency incentives and underinvestment","back_vi":"Nếu compensation thưởng EPS hoặc margin ngắn hạn, management có động cơ trì hoãn R&D/capex dù triển vọng dài hạn tốt."},{"front_en":"Explain: Overinvestment/empire building","back_vi":"Ban quản lý muốn mở rộng quy mô/địa vị có thể đầu tư dự án NPV âm hoặc M&A đắt giá."},{"front_en":"Explain: Post-investment review as discipline","back_vi":"So sánh dự báo với thực tế, đánh giá nguyên nhân lỗi, cơ chế sửa và phân bổ vốn cho kỳ tiếp theo."},{"front_en":"Explain: Inflation and relative prices","back_vi":"Inflation không đồng đều: giá nguyên liệu đầu vào và sản phẩm đầu ra thay đổi khác nhau, nên margin và tax CF thay đổi."},{"front_en":"Explain: Risk-adjusted required return","back_vi":"Dự án khác mức rủi ro cần required rate khác; sử dụng risk-free hoặc WACC toàn công ty bất chấp rủi ro có thể ra quyết định sai."},{"front_en":"Explain: Principles checklist","back_vi":"Kiểm tra after-tax incremental CF, sunk vs opportunity, cannibalization/synergies, WC/tax, inflation basis, timing, r và quản trị quyết định."}]},{"id":"CFA26-03-05-LOS04","letter":"5.d","title_en":"Real Options in Capital Investments","outcome_en":"describe types of real options relevant to capital investments","overview_vi":"Phân loại timing, sizing (abandonment/expansion), flexibility (pricing/production) và fundamental options. Giải thích quyền nhưng không phải nghĩa vụ, decision tree với xác suất điều kiện, giá trị tăng thêm của managerial flexibility và giới hạn của option-pricing models.","source":[{"id":"CFA Institute Curriculum 2026 — Corporate Issuers LM5","pages":"171–176 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading24","pages":"260–263 (physical PDF)"},{"id":"SAPP Corporate Issuers 2026 — Module5","pages":"182–195 (physical PDF)"}],"sections":[{"heading":"Real option definition","body":"Real option là quyền quản lý được hành động hoặc không hành động trong tương lai khi có thêm thông tin về dự án/tài sản thực.","trap":"A real option is not a traded financial call or put."},{"heading":"Right, not obligation","body":"Khác với cam kết bất biến, real options cho phép management chỉ thực hiện hành động nếu làm tăng giá trị tại thời điểm quyết định.","trap":"Future action should not be automatic."},{"heading":"Why flexibility creates value","body":"Điều chỉnh theo thông tin mới có thể tránh downside hoặc nắm upside tốt hơn NPV dự án cố định ban đầu.","trap":"An option with significant acquisition cost may still be uneconomical."},{"heading":"Timing option: defer","body":"Có thể trì hoãn capex để quan sát demand, prices, technology hoặc regulatory outcomes; đánh đổi là bỏ lỡ cash flows giai đoạn sớm.","trap":"Waiting is not always optimal when first-mover advantage matters."},{"heading":"Timing option: staged investment","body":"Chi vốn theo các giai đoạn: chi nhỏ hôm nay để có quyền mở rộng sau khi thử nghiệm thành công.","trap":"A first-stage project may be valuable as a platform option."},{"heading":"Sizing option family","body":"Quyền thay đổi quy mô: expansion (growth) khi thuận lợi và abandonment/shrink khi kết quả xấu.","trap":"Do not confuse option category with the initial project type."},{"heading":"Abandonment option","body":"Nếu bán/thu hồi tài sản đem lại nhiều hơn PV của tiếp tục vận hành, management nên cân nhắc dừng dự án.","trap":"Compare after-tax salvage with continuing value at the exercise date."},{"heading":"Abandonment decision","body":"Tại thời điểm t, chọn max(salvage value, PV continuation CF); option protects the downside.","trap":"Sunk prior expenditures should not drive the exercise decision."},{"heading":"Expansion/growth option","body":"Nếu nhu cầu cao, công ty có thể đầu tư bổ sung để tăng công suất/thị phần, chỉ khi incremental expansion NPV dương.","trap":"Growth is not automatic if added project cash flows are inadequate."},{"heading":"Contraction/downsizing option","body":"Khi demand thấp, doanh nghiệp có thể đóng một ca/một phân xưởng để giảm chi phí; đây là dạng sizing flexibility.","trap":"Contraction savings must exceed costs to exercise."},{"heading":"Flexibility option family","body":"Thay đổi phương thức vận hành thay vì quy mô: điều chỉnh pricing, production mix, overtime, nguyên liệu hoặc công nghệ khi điều kiện đổi.","trap":"Operational flexibility has constraints and costs."},{"heading":"Price-setting option","body":"Khi capacity không tăng được nhưng demand cao, management có thể tăng giá có chọn lọc để tăng contribution nếu elasticity cho phép.","trap":"Price increases can reduce quantity demanded."},{"heading":"Production flexibility option","body":"Chuyển vật liệu, lịch máy, ca làm thêm, nguồn cung hoặc output mix theo giá/demand tạo quyền điều chỉnh cash flows.","trap":"Overtime and switching costs matter."},{"heading":"Input switching example","body":"Nhà máy có thể dùng điện/gas tùy giá; khả năng đổi input là operational flexibility option nếu có thiết bị và hợp đồng phù hợp.","trap":"Technological feasibility required."},{"heading":"Fundamental option","body":"Giá trị của dự án phụ thuộc biến cố ngoài control như giá dầu, quặng, công nghệ hay thành công R&D; management chọn hành động theo trạng thái thế giới.","trap":"Real options do not hedge commodity prices the same way financial derivatives do."},{"heading":"Commodity-based option","body":"Nhà khai thác chỉ mở mỏ khi giá hàng hóa đủ cao, có quyền chờ hoặc bỏ dự án khi giá thấp.","trap":"Operating rights and licenses may expire while waiting."},{"heading":"R&D platform option","body":"Dự án nghiên cứu nhỏ tạo quyền phát triển sản phẩm nếu thử nghiệm thành công, không cam kết toàn bộ vốn từ ban đầu.","trap":"Research-stage costs and failure probability must be modeled."},{"heading":"Traditional NPV without flexibility","body":"NPV cố định đánh giá chuỗi hành động không thay đổi; khi có quyền điều chỉnh, đây có thể là lower bound cho dự án với quyền miễn phí hữu ích.","trap":"If option costs more than its value, adjusted NPV can be worse."},{"heading":"NPV with option cost and value","body":"NPV điều chỉnh = NPV cố định − incremental option cost + option value; mỗi khoản cần chiết khấu cùng time basis.","trap":"Never count the option's expected extra cash flows twice."},{"heading":"Decision tree approach","body":"Mô hình hóa quyết định, sự kiện, xác suất điều kiện, chi phí và cash flows theo từng thời điểm; discount expected state-contingent payoffs.","trap":"Probabilities must sum to 1 at each event node."},{"heading":"Conditional probabilities","body":"Khi xảy ra failure 40%, xác suất conditional sale 30% dẫn đến joint probability 0,4×0,3=12%.","trap":"Do not use conditional 30% as unconditional 30%."},{"heading":"Timing of payoff","body":"Nếu salvage t2 và success t1, discount theo 2 và 1 kỳ riêng; nếu cùng t1 mới dùng cùng exponent.","trap":"Misplacing payoffs inflates NPV."},{"heading":"Evaluate abandonment","body":"Chọn salvage net after tax so với PV of continuation at decision date, không so sánh với CF0 vốn đã chi.","trap":"Sunk-cost fallacy at option exercise."},{"heading":"Option value and uncertainty","body":"Khi cơ hội thích ứng tăng, flexibility có thể hữu ích đặc biệt dưới uncertainty; nhưng estimating option probabilities/values là khó.","trap":"Higher uncertainty is not sufficient to prove every option valuable."},{"heading":"Option pricing model limits","body":"Các tham số nhiều khi không quan sát được (trạng thái, thời gian, exercise conditions); mô hình phức tạp không đảm bảo accuracy cao hơn decision trees.","trap":"Do not assert complex option pricing is inherently most accurate."},{"heading":"Real versus financial options","body":"Quyền thay đổi dự án thực khác với mua option tài chính để hedging giá; commodity price risk có thể hedged bằng derivatives riêng.","trap":"Physical project flexibility is not a trading strategy."},{"heading":"Option type exam classification","body":"Đối chiếu nhanh: trì hoãn thuộc timing; mở rộng hay từ bỏ thuộc sizing; đổi giá, đổi ca sản xuất hoặc nguyên liệu thuộc flexibility; giá mỏ và R&D contingent thuộc fundamental. Một dự án thực tế có thể chứa nhiều quyền.","trap":"Real situations can involve multiple option types simultaneously."},{"heading":"Integrated investment decision","body":"Xác định basic NPV, timing of information, rights/costs, conditional future actions, joint probabilities, after-tax CF rồi so sánh adjusted NPV với 0.","trap":"Source limitations and managerial incentives remain relevant."}],"formulas":[{"name":"Real option adjusted NPV","expr":"NPV_with_options=NPV_without_options−incremental_option_cost+option_value","meaning":"Đo thay đổi giá trị nhờ quyền linh hoạt.","conditions":"All terms discounted to same valuation date."},{"name":"Decision tree expected payoff","expr":"E(CF_t)=Σ_s P(s)×CF_t(s)","meaning":"Trung bình cash flows theo trạng thái ở cùng thời điểm t.","conditions":"Mutually exclusive exhaustive outcomes."},{"name":"Two-stage joint probability","expr":"P(A∩B)=P(A)×P(B|A)","meaning":"Xác suất unconditional của nhánh thứ hai.","conditions":"Conditional probability is not unconditional probability."},{"name":"Option tree NPV","expr":"NPV=CF0+Σ_t E(CF_t)/(1+r)^t","meaning":"Tổng hiện giá after-tax state-contingent CF.","conditions":"Risk-adjusted discount rate appropriate for assumptions."},{"name":"Abandonment exercise","expr":"Exercise abandon if net salvage value>PV(continuation CF at decision date)","meaning":"Dừng khi giá trị thu hồi lớn hơn tiếp tục.","conditions":"Include costs/taxes of selling."},{"name":"Growth option exercise","expr":"Exercise expand if incremental expansion NPV at decision date>0","meaning":"Bỏ vốn thêm khi PV incremental payoff > cost.","conditions":"Project-specific risk needed."},{"name":"Production flexibility net benefit","expr":"Flexibility benefit≈extra contribution−switching/overtime cost","meaning":"Dòng tiền tăng thêm nhờ đổi cách vận hành.","conditions":"Illustrative, can vary by state."},{"name":"Real option incremental value","expr":"Option benefit=NPV_with_flexibility−NPV_fixed (before incremental option cost)","meaning":"Đo upside tránh downside trước phí lựa chọn.","conditions":"Must use matching scenario assumptions."},{"name":"PV future salvage","expr":"PV_today(salvage at t)=salvage/(1+r)^t","meaning":"Discount giá trị bán/thu hồi từ tương lai.","conditions":"Cash after tax and sale costs."},{"name":"PV expected option payoff","expr":"PV_option=Σ_s P(s)×payoff_s/(1+r)^t","meaning":"Minh họa quyền contingent theo xác suất.","conditions":"Linear expected CF valuation may miss option risk adjustments."},{"name":"Best decision at node","expr":"Value_node=max(value_continue,value_abandon,value_expand_net)","meaning":"Quyền chọn phương án tốt nhất tại trạng thái biết được.","conditions":"Use comparable PV at same node and exclude impossible alternatives."},{"name":"Simple option cost-benefit","expr":"Net option benefit=PV(incremental option cash effects)−PV(option cost)","meaning":"Kiểm tra real option đáng mua hay không.","conditions":"Beware sunk costs and double count."},{"name":"Failure-state salvage contribution","expr":"E(salvage at t)=P(failure)×salvage_if_failure","meaning":"Thêm dòng tiền bảo vệ downside.","conditions":"Only if salvage sale feasible."},{"name":"Option value by state","expr":"E[max(X,0)]≥max(E[X],0) (when defined)","meaning":"Quyền hành động theo thông tin không tệ hơn cam kết cố định nếu miễn phí và không bị ràng buộc.","conditions":"Illustrative general option intuition; not mandatory CFAI formula."}],"examples":[{"question_en":"An issuer can delay building a plant for one year to learn whether demand grows. Identify the real option.","answer":"Timing / deferral option","steps_vi":["Công ty giữ quyền chờ thông tin mới trước khi bỏ vốn.","Lợi ích thông tin phải cân với dòng tiền bỏ lỡ khi trì hoãn."],"check":"Do not equate waiting with guaranteed improvement."},{"question_en":"A mining firm may sell a project for $30m in a downturn instead of continuing. What type of real option?","answer":"Abandonment (sizing) option","steps_vi":["Quyền từ bỏ khi kết quả xấu để thu tiền bán tài sản.","So với PV tiếp tục vận hành tại ngày lựa chọn."],"check":"Salvage must be realizable."},{"question_en":"An issuer may double production if product demand unexpectedly rises. Identify option type.","answer":"Expansion/growth (sizing) option","steps_vi":["Công ty chỉ mở rộng khi demand mạnh và cash flows gia tăng đủ bù vốn bỏ thêm.","Quyền mở rộng không phải nghĩa vụ."],"check":"State contingent."},{"question_en":"A manufacturer can switch between natural gas and electricity as input depending on prices. Classify option.","answer":"Production-flexibility option","steps_vi":["Quyền đổi input làm giảm cash costs khi tương quan giá thay đổi.","Cần tính switching costs và công nghệ cho phép."],"check":"Operating flexibility."},{"question_en":"A refinery can raise price when demand exceeds available capacity. Identify real option.","answer":"Price-setting flexibility option","steps_vi":["Thay đổi pricing có thể tăng contribution mà không tăng capacity.","Phải xem demand elasticity/competition."],"check":"Not an expansion option."},{"question_en":"A company pays $10m for pilot research, and invests $100m more only if the pilot works. What is the structure?","answer":"Staged R&D / fundamental option","steps_vi":["Vốn thử nghiệm mua quyền nghiên cứu tiếp khi tín hiệu tích cực.","Tránh cam kết toàn bộ vốn trước khi biết kết quả."],"check":"Not a guaranteed outcome."},{"question_en":"A project costs $100m and pays $150m with probability 60%, zero otherwise after one year. Required return 10%. Calculate fixed-strategy NPV.","answer":"−$18.18 million","steps_vi":["Expected CF1=0,6×150+0,4×0=90m.","NPV=−100+90/1,1=−18,18m; chưa xét quyền linh hoạt."],"check":"Time t1 only."},{"question_en":"In the previous project, management could instead salvage $70m after failure at Year 1, with no option fee. What is flexible NPV?","answer":"$7.27 million","steps_vi":["Expected CF1=0,6×150+0,4×70=118m.","NPV=−100+118/1,1=7,27m; quyền salvage giúp NPV chuyển dương."],"check":"Same-period salvage."},{"question_en":"The previous project can buy the salvage option for $5m today. Compute adjusted NPV including option cost.","answer":"$2.27 million","steps_vi":["NPV flexible trước phí=7,2727m; trừ phí option 5m tại t0.","NPV điều chỉnh=2,27m, vẫn dương."],"check":"Do not subtract fee twice."},{"question_en":"At a decision date, a project can be sold for $40m net or continued for PV of $30m. Which decision maximizes value?","answer":"Abandon/sell","steps_vi":["Bán đem về 40m > PV tiếp tục 30m tại cùng thời điểm.","Initial project cost đã sunk, không chi phối lựa chọn này."],"check":"Compare same date."},{"question_en":"At Year 2 an expansion costs $25m and brings incremental future CF with PV at Year 2 of $37m. Exercise?","answer":"Yes; net value +$12m at Year 2","steps_vi":["Expansion incremental NPV=37−25=12m>0 tại ngày quyết định.","Có thể phải chiết khấu 12m về ngày hôm nay cho total project value."],"check":"Timing."},{"question_en":"A project has static NPV $8m, an option costs $3m today and its estimated PV is $12m. Compute option-adjusted NPV.","answer":"$17 million","steps_vi":["Điều chỉnh =8−3+12=17m.","Phải chắc $12m là option value chưa được tính trong NPV nền."],"check":"Avoid double counting."},{"question_en":"A failure has probability 40%; conditional probability of selling the plant after failure is 30%. Find unconditional joint probability.","answer":"12%","steps_vi":["Joint P=failure×P(sale|failure)=0,4×0,3=0,12.","Không dùng 30% như joint probability của toàn dự án."],"check":"Conditional probability."},{"question_en":"A project costs $80m now, and returns $110m at Year 1 if successful with probability 70%, or $30m if failed with probability 30%. At r=10%, find NPV.","answer":"−$1.82 million","steps_vi":["E(CF1)=0,7×110+0,3×30=86m.","NPV=−80+86/1,1=−1,82m; dự báo theo xác suất."],"check":"Weighted outcomes."},{"question_en":"The project in the preceding example can instead abandon to recover $50m on failure at Year 1. Compute revised NPV.","answer":"$3.64 million","steps_vi":["E(CF1)=0,7×110+0,3×50=92m.","NPV mới=−80+92/1,1=3,64m, nếu salvage không mất phí."],"check":"Changed failure branch."},{"question_en":"A project has a possible cash payoff $20m at Year 2 if an event with joint probability 25% occurs, otherwise zero. At 10%, calculate expected PV of this branch.","answer":"$4.13 million","steps_vi":["Expected CF2=0,25×20=5m; PV=5/1,1².","Giá trị≈4,13m, không chiết khấu theo 1 năm."],"check":"Year2 timing."},{"question_en":"Management can expand only if market profit improves; else it keeps current capacity. Does the expansion right necessarily create a loss if it has zero cost?","answer":"No","steps_vi":["Quyền không bắt buộc nên management có thể không mở rộng ở trạng thái xấu.","Giá trị tăng thêm không âm trong mô hình quyền miễn phí và không ràng buộc."],"check":"Exercise only when beneficial."},{"question_en":"A company may abandon a mine if commodity prices collapse. Is this identical to buying a financial put option on oil?","answer":"No","steps_vi":["Quyền ngừng dự án thực khác với derivative traded để hedging price risk.","Real option liên quan điều chỉnh asset/operations, không trực tiếp khóa giá hàng hóa."],"check":"Real versus financial option."},{"question_en":"An analyst builds a complex Black–Scholes-like model for a project with unobservable exercise probabilities. Is it guaranteed more accurate than a decision tree?","answer":"No","steps_vi":["Thiếu tham số quan sát làm kết quả model-dependent, phức tạp hơn không đảm bảo accuracy.","CFAI khuyến nghị xem độ tin cậy inputs."],"check":"Estimation uncertainty."},{"question_en":"A failed launch has probability 50%. Conditional on failure, management can redeploy equipment with probability 40%. Calculate probability of failure and redeployment jointly.","answer":"20%","steps_vi":["P(failure∩redeploy)=0,5×0,4=0,20.","Joint 20% nhỏ hơn conditional 40% do phải xảy ra failure trước."],"check":"Conditional branching."}],"questions":[{"stem_en":"A firm's right to delay a capital outlay is a:","options":["Timing option.","Production flexibility option.","Pure debt covenant."],"correct":0,"why_vi":"Quyền trì hoãn đầu tư để chờ thông tin là timing/deferral.","trap_vi":"Waiting has opportunity cost."},{"stem_en":"An issuer can shut down and sell a weak project. Which type of real option does it exercise?","options":["Price-setting option.","Abandonment option.","Foreign exchange option."],"correct":1,"why_vi":"Bỏ dự án và thu hồi salvage là sizing/abandonment option.","trap_vi":"Not a traded put."},{"stem_en":"If demand is strong, a company may add a second production line; if demand is weak, it does nothing. This is a:","options":["Pure financial forward.","Mandatory compliance investment.","Expansion option."],"correct":2,"why_vi":"Quyền mở rộng conditional theo demand là growth/sizing option.","trap_vi":"No obligation to exercise."},{"stem_en":"A company can change product mix when relative margins change. This is:","options":["Production-flexibility option.","Abandonment option only.","Risk-free bond investment."],"correct":0,"why_vi":"Đổi output mix là operational/production flexibility.","trap_vi":"Switching costs can matter."},{"stem_en":"For a commodity-dependent project, the right to invest only when commodity prices are high is most closely a:","options":["Retained earnings policy.","Fundamental real option.","Trade receivables policy."],"correct":1,"why_vi":"Giá trị mỏ/công trình phụ thuộc commodity price; quyền quyết định theo trạng thái thuộc fundamental option.","trap_vi":"Not automatically a futures hedge."},{"stem_en":"Which is a defining characteristic of a real option?","options":["A compulsory future investment.","A guaranteed increase in EPS.","A right, not an obligation, to change the project."],"correct":2,"why_vi":"Option tạo quyền chủ động khi conditions được biết, management có thể không exercise.","trap_vi":"Flexibility contingent on states."},{"stem_en":"A project's base NPV is $10m. Option cost is $2m and option value is $8m. Adjusted NPV is:","options":["$16m.","$4m.","$20m."],"correct":0,"why_vi":"NPV adjusted=10−2+8=16m; dùng cùng valuation date.","trap_vi":"Avoid double counting."},{"stem_en":"A project with a valuable abandonment option most directly:","options":["Guarantees every scenario is profitable.","Limits losses in some adverse scenarios.","Eliminates initial capex."],"correct":1,"why_vi":"Có thể bán/đóng dự án khi continuing value thấp, bảo vệ downside.","trap_vi":"Salvage not certain."},{"stem_en":"If a plant can be sold for $50m net but continuing cash flows have PV $30m at the decision date, the most valuable action is:","options":["Continue regardless.","Invest further without analysis.","Sell/abandon the plant."],"correct":2,"why_vi":"Bán 50m > PV tiếp tục 30m nên lựa chọn từ bỏ tốt hơn.","trap_vi":"Prior sunk cost irrelevant."},{"stem_en":"The main benefit of deferral is typically:","options":["Information gained before irreversible investment.","Guaranteed first-mover revenue.","Removal of all future risks."],"correct":0,"why_vi":"Chờ giúp có thêm thông tin demand/technology trước khi cam kết vốn.","trap_vi":"Delaying sacrifices early returns."},{"stem_en":"Which formula captures the probability of a joint event in a sequential decision tree?","options":["P(A)+P(B|A).","P(A)×P(B|A).","P(A)/P(B|A)."],"correct":1,"why_vi":"Nhánh sau có điều kiện nên joint probability là tích hai xác suất.","trap_vi":"Conditional versus unconditional."},{"stem_en":"A failed launch occurs with 40% probability, and asset sale occurs with 30% conditional probability given failure. Joint probability is:","options":["30%.","70%.","12%."],"correct":2,"why_vi":"Xác suất chung =0,4×0,3=12%, không phải xác suất có điều kiện 30%.","trap_vi":"Multiply conditional chance."},{"stem_en":"An asset's expected Year 1 payoff is $110m with probability 70%, or $30m otherwise. Expected payoff is:","options":["$86m.","$140m.","$77m."],"correct":0,"why_vi":"Tiền kỳ vọng =0,7×110+0,3×30=86 triệu USD, dùng probabilities cho các nhánh loại trừ nhau.","trap_vi":"Exhaustive outcome weights."},{"stem_en":"In decision-tree NPV, a cash flow at Year 2 should normally be discounted by:","options":["(1+r) only.","(1+r)^2.","No discounting if probability weighted."],"correct":1,"why_vi":"Dòng tiền ở t2 có hai kỳ chiết khấu; probability weighting không thay discount time.","trap_vi":"Date convention."},{"stem_en":"Which option allows management to add shifts or change raw materials without increasing permanent production capacity?","options":["Timing option.","Abandonment option.","Production flexibility option."],"correct":2,"why_vi":"Điều chỉnh ca làm/nguyên liệu là operational flexibility.","trap_vi":"Capacity constraints remain."},{"stem_en":"How is real-option value most often reflected in project NPV?","options":["Add estimated option value and subtract its incremental cost.","Replace after-tax cash flows with gross revenue.","Set discount rates to zero."],"correct":0,"why_vi":"Giá trị quyền linh hoạt cộng vào NPV nền, chi phí mua/giữ option trừ ra.","trap_vi":"Avoid double count."},{"stem_en":"An analyst claims financial puts and project abandonment options are the same because both have a negative outlook. The strongest correction is:","options":["They always use identical contract terms.","Real options change real activities, while financial options are derivative contracts.","Both eliminate market risk entirely."],"correct":1,"why_vi":"Abandonment liên quan quyết định thực, financial put là công cụ tài chính.","trap_vi":"Underlying differs."},{"stem_en":"When an option's exercise probabilities are not observable, a very complex valuation model:","options":["Is necessarily exact.","Never can be used.","May still produce unreliable estimates."],"correct":2,"why_vi":"Nhiều inputs ước lượng khiến model uncertainty cao.","trap_vi":"Complexity not accuracy."},{"stem_en":"A firm's ability to increase its product price when demand exceeds fixed capacity is a:","options":["Price-setting flexibility option.","Growth-by-acquisition option.","Abandonment option."],"correct":0,"why_vi":"Điều chỉnh giá để quản lý nhu cầu/biên lợi nhuận là price-setting flexibility.","trap_vi":"Depends on elasticity."},{"stem_en":"A pilot research project gives management the right to invest in product launch only if tests succeed. This is most clearly:","options":["A required bond repayment.","A staged R&D/fundamental option.","A sunk cost that must be repeated."],"correct":1,"why_vi":"Thử nghiệm mua quyền quyết định phát triển tiếp sau khi có thông tin.","trap_vi":"Subsequent investment conditional."},{"stem_en":"A project with positive fixed-strategy NPV has a free real option whose exercise is discretionary and can only improve payoffs. The fixed NPV is generally:","options":["Higher than flexible NPV by construction.","Unrelated to the ability to abandon.","A lower bound on flexible NPV."],"correct":2,"why_vi":"Quyền miễn phí không bắt buộc nên downside tránh được, không làm NPV giảm trong assumptions.","trap_vi":"Options with cost differ."},{"stem_en":"What action best characterizes the sizing category of real options?","options":["Expanding or abandoning a project.","Changing customer payment days only.","Switching interest rates on a loan."],"correct":0,"why_vi":"Sizing bao gồm tăng quy mô và từ bỏ/thu hẹp dự án.","trap_vi":"Not all flexibility is resizing."},{"stem_en":"For a free abandonment option, the expected value in failure states typically becomes:","options":["Lower because an option must be exercised.","At least as high as continuing without flexibility.","Necessarily zero."],"correct":1,"why_vi":"Tại mỗi failure state management có thể chọn max(salvage,continue).","trap_vi":"Salvage feasibility assumed."},{"stem_en":"A project has a negative base NPV but positive NPV after including a well-valued real option. Which statement is best?","options":["Reject always based on the base calculation.","Assume no option costs are required.","The project may become acceptable after adjustment."],"correct":2,"why_vi":"Với thông tin và option cost/benefit hợp lý, NPV adjusted dương có thể biện minh đầu tư.","trap_vi":"Review assumptions."},{"stem_en":"The purpose of a decision tree in evaluating real options is to:","options":["Represent sequential choices, conditional outcomes and cash-flow timing.","Guarantee management's ability to predict prices.","Remove the need for discounting."],"correct":0,"why_vi":"Cây quyết định gắn state probabilities, quyết định và thời điểm CF để tính NPV.","trap_vi":"Model remains probabilistic."}],"cards":[{"front_en":"Explain: Real option definition","back_vi":"Real option là quyền quản lý được hành động hoặc không hành động trong tương lai khi có thêm thông tin về dự án/tài sản thực."},{"front_en":"Explain: Right, not obligation","back_vi":"Khác với cam kết bất biến, real options cho phép management chỉ thực hiện hành động nếu làm tăng giá trị tại thời điểm quyết định."},{"front_en":"Explain: Why flexibility creates value","back_vi":"Điều chỉnh theo thông tin mới có thể tránh downside hoặc nắm upside tốt hơn NPV dự án cố định ban đầu."},{"front_en":"Explain: Timing option: defer","back_vi":"Có thể trì hoãn capex để quan sát demand, prices, technology hoặc regulatory outcomes; đánh đổi là bỏ lỡ cash flows giai đoạn sớm."},{"front_en":"Explain: Timing option: staged investment","back_vi":"Chi vốn theo các giai đoạn: chi nhỏ hôm nay để có quyền mở rộng sau khi thử nghiệm thành công."},{"front_en":"Explain: Sizing option family","back_vi":"Quyền thay đổi quy mô: expansion (growth) khi thuận lợi và abandonment/shrink khi kết quả xấu."},{"front_en":"Explain: Abandonment option","back_vi":"Nếu bán/thu hồi tài sản đem lại nhiều hơn PV của tiếp tục vận hành, management nên cân nhắc dừng dự án."},{"front_en":"Explain: Abandonment decision","back_vi":"Tại thời điểm t, chọn max(salvage value, PV continuation CF); option protects the downside."},{"front_en":"Explain: Expansion/growth option","back_vi":"Nếu nhu cầu cao, công ty có thể đầu tư bổ sung để tăng công suất/thị phần, chỉ khi incremental expansion NPV dương."},{"front_en":"Explain: Contraction/downsizing option","back_vi":"Khi demand thấp, doanh nghiệp có thể đóng một ca/một phân xưởng để giảm chi phí; đây là dạng sizing flexibility."},{"front_en":"Explain: Flexibility option family","back_vi":"Thay đổi phương thức vận hành thay vì quy mô: điều chỉnh pricing, production mix, overtime, nguyên liệu hoặc công nghệ khi điều kiện đổi."},{"front_en":"Explain: Price-setting option","back_vi":"Khi capacity không tăng được nhưng demand cao, management có thể tăng giá có chọn lọc để tăng contribution nếu elasticity cho phép."},{"front_en":"Explain: Production flexibility option","back_vi":"Chuyển vật liệu, lịch máy, ca làm thêm, nguồn cung hoặc output mix theo giá/demand tạo quyền điều chỉnh cash flows."},{"front_en":"Explain: Input switching example","back_vi":"Nhà máy có thể dùng điện/gas tùy giá; khả năng đổi input là operational flexibility option nếu có thiết bị và hợp đồng phù hợp."},{"front_en":"Explain: Fundamental option","back_vi":"Giá trị của dự án phụ thuộc biến cố ngoài control như giá dầu, quặng, công nghệ hay thành công R&D; management chọn hành động theo trạng thái thế giới."},{"front_en":"Explain: Commodity-based option","back_vi":"Nhà khai thác chỉ mở mỏ khi giá hàng hóa đủ cao, có quyền chờ hoặc bỏ dự án khi giá thấp."},{"front_en":"Explain: R&D platform option","back_vi":"Dự án nghiên cứu nhỏ tạo quyền phát triển sản phẩm nếu thử nghiệm thành công, không cam kết toàn bộ vốn từ ban đầu."},{"front_en":"Explain: Traditional NPV without flexibility","back_vi":"NPV cố định đánh giá chuỗi hành động không thay đổi; khi có quyền điều chỉnh, đây có thể là lower bound cho dự án với quyền miễn phí hữu ích."},{"front_en":"Explain: NPV with option cost and value","back_vi":"NPV điều chỉnh = NPV cố định − incremental option cost + option value; mỗi khoản cần chiết khấu cùng time basis."},{"front_en":"Explain: Decision tree approach","back_vi":"Mô hình hóa quyết định, sự kiện, xác suất điều kiện, chi phí và cash flows theo từng thời điểm; discount expected state-contingent payoffs."},{"front_en":"Explain: Conditional probabilities","back_vi":"Khi xảy ra failure 40%, xác suất conditional sale 30% dẫn đến joint probability 0,4×0,3=12%."},{"front_en":"Explain: Timing of payoff","back_vi":"Nếu salvage t2 và success t1, discount theo 2 và 1 kỳ riêng; nếu cùng t1 mới dùng cùng exponent."},{"front_en":"Explain: Evaluate abandonment","back_vi":"Chọn salvage net after tax so với PV of continuation at decision date, không so sánh với CF0 vốn đã chi."},{"front_en":"Explain: Option value and uncertainty","back_vi":"Khi cơ hội thích ứng tăng, flexibility có thể hữu ích đặc biệt dưới uncertainty; nhưng estimating option probabilities/values là khó."},{"front_en":"Explain: Option pricing model limits","back_vi":"Các tham số nhiều khi không quan sát được (trạng thái, thời gian, exercise conditions); mô hình phức tạp không đảm bảo accuracy cao hơn decision trees."},{"front_en":"Explain: Real versus financial options","back_vi":"Quyền thay đổi dự án thực khác với mua option tài chính để hedging giá; commodity price risk có thể hedged bằng derivatives riêng."},{"front_en":"Explain: Option type exam classification","back_vi":"Defer=timing; expand/abandon=size; price/production shift=flexibility; mine/R&D conditional payoff=fundamental."},{"front_en":"Explain: Integrated investment decision","back_vi":"Xác định basic NPV, timing of information, rights/costs, conditional future actions, joint probabilities, after-tax CF rồi so sánh adjusted NPV với 0."}]}]},{"module_id":"CFA26-03-06","module_title":"Capital Structure","subject":"Corporate Issuers","sources":"CFAI Corporate Issuers 2026, Kaplan Book1 2026, SAPP Slide Corporate 2026","los":[{"id":"CFA26-03-06-LOS01","letter":"6.a","title_en":"Weighted-Average Cost of Capital (WACC)","outcome_en":"calculate and interpret the weighted-average cost of capital for a company","overview_vi":"Tính WACC theo cost of debt trước/sau thuế, cost of equity, market/target weights và tax rate; nhận biết mối liên hệ giữa expected investor return, credit risk, share prices, lease debt và project hurdle rate.","source":[{"id":"CFA Institute Curriculum 2026 — Corporate Issuers LM6","pages":"181–188 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading25","pages":"263–267 (physical PDF)"},{"id":"SAPP Corporate Issuers 2026 — Module6","pages":"208–227 (physical PDF)"}],"sections":[{"heading":"Cost of capital as opportunity cost","body":"Cost of capital là required return của nhà cung cấp vốn khi đầu tư vào issuer có mức rủi ro phù hợp, dùng để đánh giá đầu tư.","trap":"A firm's actual coupon is not necessarily its current cost of borrowing."},{"heading":"Debt investor versus equity investor","body":"Debt thường có nghĩa vụ trả lãi/gốc, quyền ưu tiên trước equity khi thanh lý; equity chịu residual risk cao hơn nên required return thường cao hơn.","trap":"Risk order can vary with unusual securities but basic principle holds."},{"heading":"Debt pretax required return","body":"rd là return required hiện tại trên nợ có rủi ro tương đương; thường được ước lượng từ YTM/current debt market rates, không chỉ coupon lịch sử.","trap":"Coupon rate differs from yield when price differs from par."},{"heading":"Tax deductibility of interest","body":"Nếu interest được khấu trừ thuế, chi phí debt sau thuế = rd(1−T) với marginal corporate tax rate.","trap":"Do not apply tax shield to cost of equity."},{"heading":"Equity required return","body":"re là return expected by equity investors given risk; có thể ước lượng bằng CAPM hoặc mô hình khác nếu có dữ liệu.","trap":"Equity capital is not free because no contractual coupon."},{"heading":"WACC basic definition","body":"WACC là average required return của tất cả nguồn capital, weighted by proportions, và debt adjusted for deductibility.","trap":"All weights should sum to 100%."},{"heading":"WACC two-component","body":"Với debt/equity: WACC=wd×rd×(1−T)+we×re; preferred stock nếu có dùng weight/cost riêng.","trap":"Preferred stock not necessarily tax deductible."},{"heading":"Market weights","body":"Market value của debt/equity phản ánh cơ cấu giá thị trường hiện tại khi tính WACC; book weights có thể khác đáng kể.","trap":"Do not substitute balance sheet book equity for market value if market weights requested."},{"heading":"Target weights","body":"Management có thể dùng target mix cho capital planning, nhất là khi market values biến động mạnh; phải biết đề yêu cầu current versus target.","trap":"Target structure may be stated in book-value terms."},{"heading":"Market value of equity","body":"MV_equity=shares outstanding×current share price; không nhất thiết bằng share capital+retained earnings trên sổ sách.","trap":"Count shares not book capital for market weights."},{"heading":"Market value of debt","body":"MV_debt là PV hiện tại của debt CF hoặc market price×face units; có thể khác par/book value.","trap":"Yield, price and coupon are distinct."},{"heading":"Debt weight","body":"Trọng số debt theo giá thị trường = Market D/(Market D+Market E), điều chỉnh mẫu số nếu có preferred stock.","trap":"Check definition of total capitalization."},{"heading":"Equity weight","body":"Trọng số equity theo giá thị trường = Market E/(Market D+Market E), nếu issuer chỉ có debt và equity.","trap":"1−wd when two financing classes only."},{"heading":"Marginal tax rate","body":"Đối với future cost of financing, dùng tax rate thích hợp trong các assumptions của đề; thực tế tax shield có thể bị hạn chế.","trap":"Tax deductibility is conditional on profitability/tax law."},{"heading":"Interpret WACC","body":"WACC 9% nghĩa là blended expected required return của financing providers theo giả định; không đảm bảo issuer earned 9%.","trap":"WACC is cost of financing, not realized ROIC."},{"heading":"WACC as project hurdle","body":"Có thể dùng WACC cho project có risk gần tương tự issuer; project risk khác cần hurdle điều chỉnh.","trap":"Company WACC is not always the right discount rate for all projects."},{"heading":"Debt tax rate effect","body":"Khi rd và weights cố định, marginal tax rate tăng khiến after-tax rd và WACC giảm nếu debt deductible.","trap":"Higher taxes do not necessarily make overall firm more valuable in real world."},{"heading":"Leases and capital funding","body":"Quyền sử dụng máy bay/bất động sản qua leases có tính chất debt-like vì tạo nghĩa vụ fixed payments; cần xem ghi nhận và leverage.","trap":"Lease liability treatment in analysis depends on context."},{"heading":"Floating rate debt risk","body":"Cost of debt có thể tăng khi benchmark rate tăng và issuer refinances; floating-rate debt phản ứng nhanh.","trap":"Old coupon does not guarantee future borrowing rates."},{"heading":"Credit spread and debt yield","body":"Market rate risk-free component + credit spread (simplified) phản ánh compensation cho default/liquidity/term risks.","trap":"Spread can widen even when base rate is unchanged."},{"heading":"WACC sensitivity to weight","body":"Dịch tỷ trọng debt sang equity có thể thay blended cost, nhưng re/rd có thể cũng đổi vì leverage risk.","trap":"Never treat component costs as fixed at any debt amount."},{"heading":"Book-versus-market distinction","body":"Giá thị trường của equity biến động làm weights thay đổi dù vốn sổ sách không đổi; ghi rõ dùng vốn thị trường hay mục tiêu.","trap":"Different conventions give different WACC."},{"heading":"Project financing and business risk","body":"Dự án có operating cash-flow volatility cao cần hurdle tương ứng cao; cost of debt/equity phản ánh issuer's risks.","trap":"Low WACC alone does not justify riskier expansion."},{"heading":"Financing costs versus cash flow definition","body":"Khi chiết khấu FCFF tại WACC, không trừ interest expense khỏi FCFF thêm lần nữa; nếu FCFE dùng re.","trap":"Avoid double counting financing costs."},{"heading":"Analyst WACC checklist","body":"Xác định debt/equity market values, current rd, re, marginal T, tax deductibility, target policy và project risk.","trap":"Verify whether an instrument is debt or equity."}],"formulas":[{"name":"After-tax debt cost","expr":"rd_after=rd_pre×(1−T)","meaning":"Lợi ích thuế của interest đối với issuer.","conditions":"Interest deductible and marginal T appropriate."},{"name":"WACC debt/equity","expr":"WACC=wd×rd×(1−T)+we×re","meaning":"Weighted funding opportunity cost.","conditions":"Sum weights=1, pre-tax rd."},{"name":"Debt market weight","expr":"wd=D_mkt/(D_mkt+E_mkt)","meaning":"Trọng số nợ thị trường.","conditions":"Include only relevant capital providers."},{"name":"Equity market weight","expr":"we=E_mkt/(D_mkt+E_mkt)","meaning":"Trọng số equity thị trường.","conditions":"Use shares×price for listed equity."},{"name":"Equity market value","expr":"E_mkt=shares outstanding×market share price","meaning":"Tử số trọng số equity thị trường.","conditions":"Number of shares and price same currency."},{"name":"Par debt market value","expr":"D_mkt=bond price as % par×total face amount","meaning":"Quy đổi giá debt khi trái phiếu giao dịch khác par.","conditions":"If coupon different, price might not equal book."},{"name":"Risk-free plus credit spread","expr":"rd≈risk-free benchmark+debt credit spread","meaning":"Ước lượng đơn giản borrowing cost.","conditions":"Maturity and spread basis aligned."},{"name":"Equity residual weight","expr":"we=1−wd","meaning":"Dùng khi chỉ có debt/equity.","conditions":"No preferred or other capital class."},{"name":"WACC with preferred","expr":"WACC=wd rd(1−T)+we re+wp rp","meaning":"Mở rộng nếu phát hành preferred.","conditions":"Preferred dividends generally not tax deductible."},{"name":"Marginal WACC tax effect","expr":"ΔWACC=−wd×rd×ΔT","meaning":"Độ nhạy thuế khi component rates/weights fixed.","conditions":"Simplified derivative."},{"name":"Project discount adjustment","expr":"r_project=WACC+project-specific risk adjustment","meaning":"Cách tư duy nếu project khác business risk.","conditions":"Illustrative, not a prescribed CFAI calculation."},{"name":"Debt interest cost","expr":"Annual interest expense≈face principal×contractual coupon","meaning":"Cash coupon đối với bond par.","conditions":"rd current market can differ from contractual coupon."},{"name":"Total capitalization","expr":"Total market capital=D_mkt+E_mkt","meaning":"Mẫu số market weights.","conditions":"Add preferred if present."},{"name":"Cost spread","expr":"Credit spread≈yield on issuer debt−matched benchmark rate","meaning":"Compensation for credit and market risks.","conditions":"Same maturity/currency."},{"name":"Gross versus net debt","expr":"Net debt≈interest-bearing debt−cash−marketable securities","meaning":"Công cụ leverage khác total debt.","conditions":"Definition can differ across analysts."}],"examples":[{"question_en":"An issuer targets debt 40%, equity 60%; rd=5%, re=12%, tax 25%. Compute WACC.","answer":"8.70%","steps_vi":["Debt cost after tax=5%×0,75=3,75%.","WACC=0,4×3,75%+0,6×12%=8,70%.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"Target market-consistent mix assumed."},{"question_en":"A company has 30% debt at rd=6%, 70% equity at re=12%, tax rate 20%. Compute WACC.","answer":"9.84%","steps_vi":["After-tax debt cost=6%×0,80=4,8%.","WACC=0,3×4,8%+0,7×12%=9,84%.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"Same as independently recomputed formula."},{"question_en":"A firm has market debt $60m and market equity $40m. Compute wd and we.","answer":"60%; 40%","steps_vi":["Tổng market capitalization=60+40=100m.","Debt weight=60/100=60%, equity=40/100=40%."],"check":"Market values not book."},{"question_en":"A listed issuer has 2 million shares at $30 each. Find market equity value.","answer":"$60 million","steps_vi":["E_mkt=2 triệu cổ phiếu×30 USD=60 triệu USD.","Không dùng giá trị sổ sách nếu hỏi trọng số thị trường."],"check":"No treasury shares unless specified."},{"question_en":"A company has market debt $25m and equity $75m; rd=6%, re=12%, tax=25%. WACC?","answer":"10.13%","steps_vi":["Debt contribution=0,25×6%×0,75=1,125%.","Equity contribution=0,75×12%=9%; tổng WACC=10,125%≈10,13%."],"check":"Rounding to 2 decimals."},{"question_en":"A company uses debt 50% at rd=8%, equity 50% at re=15%, tax=30%. WACC?","answer":"10.30%","steps_vi":["Debt contribution=0,5×8%×0,7=2,8%.","Equity=0,5×15%=7,5%, WACC=10,3%.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"Debt interest deductible."},{"question_en":"Issuer rd=7%, tax=30%. Compute after-tax cost of debt.","answer":"4.90%","steps_vi":["rd_after=7%×(1−0,30)=4,90%.","Tax adjustment only applies because deductible interest assumed.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"Pretax vs aftertax."},{"question_en":"A firm's cost of equity is 12%, and it has no interest-bearing debt. Compute WACC.","answer":"12%","steps_vi":["wd=0, we=1 nên WACC=0+1×12%.","All-equity cost reflects equity opportunity cost."],"check":"No debt."},{"question_en":"An issuer has market debt $40m, equity $160m. Compute debt weight.","answer":"20%","steps_vi":["wd=40/(40+160)=0,20.","Không lấy debt/total assets book nếu đề dùng market values."],"check":"Market capital basis."},{"question_en":"A firm's 100,000 shares trade at $50, and debt is worth $15m. Compute equity and debt weights.","answer":"25% equity; 75% debt","steps_vi":["Equity market=100.000×50=5m, debt=15m.","We=5/20=25%, Wd=15/20=75%.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"100k shares units."},{"question_en":"Debt has face $100m but trades at 95% of par. Find its approximate market value.","answer":"$95 million","steps_vi":["Debt mkt=100×0,95=95 triệu USD.","Đừng dùng par 100 nếu market weight được yêu cầu."],"check":"Price as percent par."},{"question_en":"Risk-free rate is 3% and issuer credit spread is 2%. Approximate rd.","answer":"5%","steps_vi":["Chi phí nợ xấp xỉ 3%+2%=5% theo cách đơn giản.","Cần spread cùng maturity, currency."],"check":"Simple yield decomposition."},{"question_en":"A capital structure is 60% debt, rd=5%, tax changes from 20% to 30%, re and weights fixed. WACC changes by:","answer":"Decrease by 0.30 percentage points","steps_vi":["ΔWACC=−0,6×5%×0,10=−0,30 điểm %.","Không phải giảm 0,30% của giá trị WACC ban đầu."],"check":"Percentage points."},{"question_en":"A firm sells preferred shares with weight 10%, rp=8%, while wd=30%, rd=6%, equity weight=60%, re=12%, tax=25%. WACC?","answer":"9.35%","steps_vi":["Debt=0,3×6%×0,75=1,35%; equity=0,6×12%=7,2%.","Preferred=0,1×8%=0,8%; tổng=9,35%."],"check":"Extension with preferred."},{"question_en":"An issuer reborrows at current market yield 9% despite an old bond coupon of 5%. Which rate is more relevant to marginal cost of debt?","answer":"9%","steps_vi":["Required market return hiện tại thể hiện cơ hội tài trợ mới.","Coupon cũ không phải giá vốn cho funding mới."],"check":"Market current cost."},{"question_en":"A company raises its market equity value while its debt market value remains stable. Which WACC weight changes?","answer":"Equity weight rises; debt weight falls","steps_vi":["Tổng capitalization tăng ở phía equity nên tỷ trọng equity tăng.","WACC cuối cùng còn tùy re/rd và rủi ro mới."],"check":"Values and rates both matter."}],"questions":[{"stem_en":"The after-tax cost of debt is most appropriately calculated as:","options":["Pretax cost of debt × (1−tax rate).","Cost of equity × (1−tax rate).","Coupon rate + tax rate."],"correct":0,"why_vi":"Interest được khấu trừ giúp rd_after=rd×(1−T).","trap_vi":"Equity return not tax deductible."},{"stem_en":"Which weighting generally reflects current market capitalization in WACC?","options":["Historical asset values.","Market values of debt and equity.","The firm's revenue split by segment."],"correct":1,"why_vi":"Trọng số market phản ánh giá của capital providers trên thị trường.","trap_vi":"Target weights may be used if specifically given."},{"stem_en":"An issuer has debt weight 40%, pretax rd 5%, equity weight 60%, re 12%, tax 25%. WACC is:","options":["10.70%.","12.00%.","8.70%."],"correct":2,"why_vi":"WACC=0,4×5%×0,75+0,6×12%=8,70%. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"After-tax debt."},{"stem_en":"Which component of WACC is typically adjusted for corporate tax deductibility?","options":["Debt financing.","Common equity.","Preferred dividends."],"correct":0,"why_vi":"Lãi vay có lá chắn thuế theo giả định; equity dividend không.","trap_vi":"Tax treatment context."},{"stem_en":"A company has no debt. Its WACC generally equals:","options":["Zero.","Its cost of equity.","Tax rate."],"correct":1,"why_vi":"Khi we=1, WACC=re. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"All-equity firm."},{"stem_en":"An issuer's old bond pays 4% coupon but its new comparable bond YTM is 7%. Its current cost of debt is better estimated by:","options":["Historic 4% coupon.","The average tax rate.","Current market 7% yield."],"correct":2,"why_vi":"Rd là required return hiện tại của creditors.","trap_vi":"Coupon and YTM differ."},{"stem_en":"A firm has market debt $30m and equity $70m. Its debt weight is:","options":["30%.","70%.","42.86%."],"correct":0,"why_vi":"wd=30/(30+70)=30%. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Market capitalization weights."},{"stem_en":"A company changes from 30% to 40% debt. Holding rd and re fixed, the direction of WACC depends on:","options":["Shares outstanding alone.","After-tax rd relative to re.","Its last-year tax cash flow only."],"correct":1,"why_vi":"Nếu rd_after thấp hơn re, tăng wd làm blended cost thấp trong phép tính tĩnh.","trap_vi":"Component costs may change with leverage."},{"stem_en":"An issuer's debt yield is 6%, tax 20%. Its after-tax rd is:","options":["6.20%.","1.20%.","4.80%."],"correct":2,"why_vi":"6%×(1−0,2)=4,8%. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Pretax required yield."},{"stem_en":"For market equity value, an analyst generally uses:","options":["Shares outstanding × market share price.","Total liabilities × share count.","Book retained earnings × P/E."],"correct":0,"why_vi":"Giá trị thị trường equity=market share price×shares.","trap_vi":"Not book value."},{"stem_en":"A project with much higher business risk than the issuer's main business should generally be discounted using:","options":["The company's unadjusted historical coupon necessarily.","A risk-appropriate project required return.","Zero because project risk is not financing."],"correct":1,"why_vi":"Hurdle phản ánh rủi ro riêng dự án; WACC công ty có thể không phù hợp.","trap_vi":"Risk comparability."},{"stem_en":"Which statement best describes WACC?","options":["Average accounting income growth.","Book-value ratio of total assets.","Weighted required returns of capital suppliers."],"correct":2,"why_vi":"WACC là tỷ suất yêu cầu tổng hợp, không phải ROIC thực tế.","trap_vi":"Cost not achieved return."},{"stem_en":"A firm's 100,000 shares at $50 and debt market value $15m imply equity weight of:","options":["25%.","75%.","50%."],"correct":0,"why_vi":"E=5m, D=15m, we=5/20=25%. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Market not par."},{"stem_en":"The tax advantage of debt in a simplified WACC formula primarily arises because:","options":["All debt is risk free.","Interest reduces taxable income when deductible.","Debt always costs more than equity."],"correct":1,"why_vi":"Tax-deductible interest làm giảm rd sau thuế.","trap_vi":"Conditional on tax benefit."},{"stem_en":"Under simple assumptions, a higher marginal tax rate and fixed positive debt weight generally:","options":["Raises after-tax debt cost.","Has no effect on debt cost.","Lowers after-tax debt cost."],"correct":2,"why_vi":"Rd(1−T) giảm khi T tăng, nếu mọi thứ khác giữ nguyên.","trap_vi":"Simplified sensitivity."},{"stem_en":"A company leases aircraft under a long-term financing arrangement. The lease most likely:","options":["Creates a debt-like fixed payment obligation.","Necessarily has no effect on financing risk.","Is always common equity."],"correct":0,"why_vi":"Nghĩa vụ thuê dài hạn có tính chất debt-like và liên quan capital structure.","trap_vi":"Accounting varies with arrangement."},{"stem_en":"When a bond trades below par, its market value for WACC is generally:","options":["Greater than face automatically.","Less than face if quoted below par.","Equal to coupon rate times face."],"correct":1,"why_vi":"Giá market dưới par làm D_mkt nhỏ hơn face.","trap_vi":"Bond price vs face."},{"stem_en":"An analyst must select between book and market capital weights. The best action is to:","options":["Always use whichever gives a smaller WACC.","Ignore the question convention.","Follow the requested basis and state its limitations."],"correct":2,"why_vi":"Trọng số cần nhất quán với capital market/current target assumptions.","trap_vi":"Book and market diverge."},{"stem_en":"If a project FCF is discounted at WACC, deducting interest again from that FCF may:","options":["Double count financing costs.","Increase project NPV accurately.","Eliminate tax shield."],"correct":0,"why_vi":"FCFF không trừ interest khi dùng WACC đã phản ánh financing cost.","trap_vi":"Consistent cash-flow definition."},{"stem_en":"The weighted-average cost of capital is most directly useful for:","options":["Estimating inventory units.","Discounting cash flows of similarly risky investments.","Calculating daily stock price returns mechanically."],"correct":1,"why_vi":"WACC có thể là hurdle rate khi project risk phù hợp issuer's operations.","trap_vi":"Adjust for project risk."},{"stem_en":"At a marginal tax rate of 25%, a firm with pretax rd 8% has after-tax debt cost of:","options":["8%.","2%.","6%."],"correct":2,"why_vi":"8%×(1−0,25)=6%. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Tax shield."}],"cards":[{"front_en":"Explain: Cost of capital as opportunity cost","back_vi":"Cost of capital là required return của nhà cung cấp vốn khi đầu tư vào issuer có mức rủi ro phù hợp, dùng để đánh giá đầu tư."},{"front_en":"Explain: Debt investor versus equity investor","back_vi":"Debt thường có nghĩa vụ trả lãi/gốc, quyền ưu tiên trước equity khi thanh lý; equity chịu residual risk cao hơn nên required return thường cao hơn."},{"front_en":"Explain: Debt pretax required return","back_vi":"rd là return required hiện tại trên nợ có rủi ro tương đương; thường được ước lượng từ YTM/current debt market rates, không chỉ coupon lịch sử."},{"front_en":"Explain: Tax deductibility of interest","back_vi":"Nếu interest được khấu trừ thuế, chi phí debt sau thuế = rd(1−T) với marginal corporate tax rate."},{"front_en":"Explain: Equity required return","back_vi":"re là return expected by equity investors given risk; có thể ước lượng bằng CAPM hoặc mô hình khác nếu có dữ liệu."},{"front_en":"Explain: WACC basic definition","back_vi":"WACC là average required return của tất cả nguồn capital, weighted by proportions, và debt adjusted for deductibility."},{"front_en":"Explain: WACC two-component","back_vi":"Với debt/equity: WACC=wd×rd×(1−T)+we×re; preferred stock nếu có dùng weight/cost riêng."},{"front_en":"Explain: Market weights","back_vi":"Market value của debt/equity phản ánh cơ cấu giá thị trường hiện tại khi tính WACC; book weights có thể khác đáng kể."},{"front_en":"Explain: Target weights","back_vi":"Management có thể dùng target mix cho capital planning, nhất là khi market values biến động mạnh; phải biết đề yêu cầu current versus target."},{"front_en":"Explain: Market value of equity","back_vi":"MV_equity=shares outstanding×current share price; không nhất thiết bằng share capital+retained earnings trên sổ sách."},{"front_en":"Explain: Market value of debt","back_vi":"MV_debt là PV hiện tại của debt CF hoặc market price×face units; có thể khác par/book value."},{"front_en":"Explain: Debt weight","back_vi":"Trọng số debt theo giá thị trường = Market D/(Market D+Market E), điều chỉnh mẫu số nếu có preferred stock."},{"front_en":"Explain: Equity weight","back_vi":"Trọng số equity theo giá thị trường = Market E/(Market D+Market E), nếu issuer chỉ có debt và equity."},{"front_en":"Explain: Marginal tax rate","back_vi":"Đối với future cost of financing, dùng tax rate thích hợp trong các assumptions của đề; thực tế tax shield có thể bị hạn chế."},{"front_en":"Explain: Interpret WACC","back_vi":"WACC 9% nghĩa là blended expected required return của financing providers theo giả định; không đảm bảo issuer earned 9%."},{"front_en":"Explain: WACC as project hurdle","back_vi":"Có thể dùng WACC cho project có risk gần tương tự issuer; project risk khác cần hurdle điều chỉnh."},{"front_en":"Explain: Debt tax rate effect","back_vi":"Khi rd và weights cố định, marginal tax rate tăng khiến after-tax rd và WACC giảm nếu debt deductible."},{"front_en":"Explain: Leases and capital funding","back_vi":"Quyền sử dụng máy bay/bất động sản qua leases có tính chất debt-like vì tạo nghĩa vụ fixed payments; cần xem ghi nhận và leverage."},{"front_en":"Explain: Floating rate debt risk","back_vi":"Cost of debt có thể tăng khi benchmark rate tăng và issuer refinances; floating-rate debt phản ứng nhanh."},{"front_en":"Explain: Credit spread and debt yield","back_vi":"Market rate risk-free component + credit spread (simplified) phản ánh compensation cho default/liquidity/term risks."},{"front_en":"Explain: WACC sensitivity to weight","back_vi":"Dịch tỷ trọng debt sang equity có thể thay blended cost, nhưng re/rd có thể cũng đổi vì leverage risk."},{"front_en":"Explain: Book-versus-market distinction","back_vi":"Giá thị trường của equity biến động làm weights thay đổi dù vốn sổ sách không đổi; ghi rõ dùng vốn thị trường hay mục tiêu."},{"front_en":"Explain: Project financing and business risk","back_vi":"Dự án có operating cash-flow volatility cao cần hurdle tương ứng cao; cost of debt/equity phản ánh issuer's risks."},{"front_en":"Explain: Financing costs versus cash flow definition","back_vi":"Khi chiết khấu FCFF tại WACC, không trừ interest expense khỏi FCFF thêm lần nữa; nếu FCFE dùng re."},{"front_en":"Explain: Analyst WACC checklist","back_vi":"Xác định debt/equity market values, current rd, re, marginal T, tax deductibility, target policy và project risk."}]},{"id":"CFA26-03-06-LOS02","letter":"6.b","title_en":"Factors Affecting Capital Structure and WACC","outcome_en":"explain factors affecting capital structure and the weighted-average cost of capital","overview_vi":"Phân tích lifecycle, business model, top-down market/industry rates, bottom-up issuer credit, operating leverage và financial leverage; tính các ví dụ coverage, debt/equity, net debt/EBITDA và ROE sensitivity.","source":[{"id":"CFA Institute Curriculum 2026 — Corporate Issuers LM6","pages":"189–199 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading25","pages":"265–267 (physical PDF)"},{"id":"SAPP Corporate Issuers 2026 — Module6","pages":"228–242 (physical PDF)"}],"sections":[{"heading":"Capital structure determinants","body":"Cơ cấu nợ/vốn chủ phụ thuộc business model, lifecycle, asset base, risk, khả năng tạo tiền và capital market conditions.","trap":"There is no universal target leverage ratio."},{"heading":"Early-stage companies","body":"Startup thường có revenue/cash flow thấp hoặc âm, thiếu collateral, rủi ro default cao, nên chủ yếu tìm equity từ founder, employees, venture capital.","trap":"Venture equity is risky and expensive in required-return terms."},{"heading":"Growth stage issuers","body":"Công ty đang mở rộng cần tài trợ sản phẩm và capex, dùng equity/debt tùy khả năng tạo CF và quality of assets; leverage có thể tăng khi ổn định.","trap":"Growth itself does not guarantee debt capacity."},{"heading":"Mature stage issuers","body":"Doanh nghiệp trưởng thành với CF ổn định thường có thể huy động debt dài hạn, bonds và leases; chính sách hoàn vốn cổ đông cũng quan trọng.","trap":"Mature firms can still be capital-light and carry little debt."},{"heading":"Capital-intensive model","body":"Hãng hàng không, utilities, manufacturers cần nhiều tangible long-lived assets, thường hỗ trợ secured financing nhưng demand risk vẫn có.","trap":"Asset-heavy does not automatically imply lowest credit risk."},{"heading":"Capital-light model","body":"Software/platform doanh nghiệp có thể ít tài sản thế chấp, sử dụng nhiều intangible value, nguồn equity/internal CF phù hợp hơn khi CF biến động.","trap":"Capital-light profitability can support debt later."},{"heading":"Collateral quality","body":"Real estate, vehicles, aircraft và receivables chất lượng cao có thể cầm cố; collateral làm creditors dễ thu hồi, tăng debt access.","trap":"Collateral value can fall in distress."},{"heading":"Stable versus volatile cash flows","body":"CF đều và dự báo được làm debt service bền hơn; CF chu kỳ/biến động cần cushion hoặc tỷ trọng equity lớn hơn.","trap":"Positive expected profits cannot guarantee debt payment dates."},{"heading":"Top-down market conditions","body":"Risk-free yield, liquidity, investor risk appetite và credit spreads trên thị trường làm rd/re biến đổi theo thời gian.","trap":"The firm's financing conditions are not purely management controlled."},{"heading":"Top-down industry conditions","body":"Ngành có fixed costs/market cyclicality khác nhau dẫn đến beta và khả năng sử dụng nợ khác nhau.","trap":"Compare peers and business sensitivity."},{"heading":"Bottom-up issuer conditions","body":"Credit history, profitability, cash coverage, leverage, governance, liquidity và rating quyết định required financing costs.","trap":"Company-specific risk matters even with same industry."},{"heading":"Business operating leverage","body":"Operating leverage là mức fixed operating costs cao so với variable costs; làm EBIT nhạy với revenue changes.","trap":"Operating leverage is NOT the same as debt leverage."},{"heading":"Fixed versus variable operating cost","body":"Chi phí cố định không đổi khi sales biến động trong phạm vi capacity, variable costs thường tỷ lệ theo output.","trap":"Fixed cost classification may change over long horizons."},{"heading":"Operating leverage high","body":"Khi fixed costs lớn, doanh thu tăng làm EBIT tăng nhanh, nhưng sales giảm gây profit drop mạnh.","trap":"High operating leverage boosts both upside and downside."},{"heading":"Degree of operating leverage","body":"DOL≈%ΔEBIT/%ΔSales; tại một điểm, DOL=contribution margin/EBIT trong CVP linear model.","trap":"Formula assumes consistent operating range and nonzero EBIT."},{"heading":"Financial leverage","body":"Debt/lease fixed interest obligations làm residual profit và ROE của equity nhạy với EBIT.","trap":"Financial leverage arises from funding, not production costs."},{"heading":"Interest coverage","body":"EBIT/interest expense đo khả năng trả lãi từ profit hoạt động; càng thấp thường debt risk càng cao.","trap":"Earnings-based coverage is not equivalent to cash availability."},{"heading":"Financial leverage magnification","body":"Với interest fixed, khi EBIT tăng thì residual income equity tăng tỷ lệ lớn hơn; khi EBIT giảm equity chịu rủi ro mạnh.","trap":"Higher expected ROE comes with downside risk."},{"heading":"Debt-to-equity","body":"D/E=interest-bearing debt/equity, phải nhất quán book vs market.","trap":"Debt coverage and book equity can be volatile."},{"heading":"Net debt","body":"Net debt thường là debt trừ cash và liquid securities; đo leverage sau liquidity offset.","trap":"Not a perfect substitute for cash-flow stress tests."},{"heading":"Net debt/EBITDA","body":"Thước đo leverage vận hành theo số lần EBITDA, thường dùng covenants/ratings; không tự động đo khả năng chi trả lãi chính xác.","trap":"EBITDA is not free cash flow."},{"heading":"Interest obligations timing","body":"Cash interest/payment due dates có thể gây distress ngay cả khi annual EBIT dương, cần xét liquidity và debt maturities.","trap":"Coverage is annual ratio, not cash calendar."},{"heading":"Equity issuance and signals","body":"Equity raise có thể bị thị trường diễn giải là stock overpriced hoặc có funding need; signaling phụ thuộc bất cân xứng thông tin.","trap":"A capital raise is not by itself evidence of mispricing."},{"heading":"Leases versus borrowing","body":"Thuê tài sản thay vì mua bằng debt có thể hỗ trợ capacity và kiểm soát capex cash timing, nhưng vẫn là fixed obligations.","trap":"Leasing is not always off-balance-sheet under current standards."},{"heading":"Credit spreads and rating","body":"Rating xuống làm rd cao, cost of capital tăng; giữ rating có thể là mục tiêu target capital structure.","trap":"Ratings reflect anticipated risk, not only current leverage."},{"heading":"Financing exposure checklist","body":"Xem lifecycle, assets/collateral, EBIT volatility, debt capacity, interest coverage, WACC sensitivity, credit cycles và rollover maturities.","trap":"Avoid applying an industry average blindly."}],"formulas":[{"name":"Operating income (EBIT)","expr":"EBIT=Revenue−fixed operating cost−variable operating costs","meaning":"Profit hoạt động trước interest/tax.","conditions":"CVP simplified model."},{"name":"Variable cost","expr":"Variable cost=variable cost ratio×revenue","meaning":"Chi phí biến thiên theo sales trong mô hình tuyến tính.","conditions":"Relevant operating range."},{"name":"Contribution margin","expr":"Contribution margin=Revenue−variable costs","meaning":"Doanh thu còn lại trang trải fixed costs rồi EBIT.","conditions":"Gross margin differs if definitions differ."},{"name":"Degree of operating leverage","expr":"DOL≈%ΔEBIT/%ΔSales","meaning":"Độ nhạy EBIT với biến động sales.","conditions":"Near base point, when changes small."},{"name":"DOL CVP","expr":"DOL=(Revenue−variable costs)/EBIT","meaning":"Công thức điểm trong linear cost model.","conditions":"EBIT nonzero."},{"name":"Interest coverage","expr":"Interest coverage=EBIT/Interest expense","meaning":"Khả năng trả lãi dựa trên EBIT.","conditions":"Interest positive and same period."},{"name":"Debt/equity","expr":"D/E=interest-bearing debt/equity","meaning":"Đòn bẩy tài chính.","conditions":"State market versus book value basis."},{"name":"Net debt","expr":"Net debt=debt−cash−marketable securities","meaning":"Số nợ sau trừ liquidity.","conditions":"May use differing definitions."},{"name":"Net debt/EBITDA","expr":"Net debt/EBITDA=(debt−liquid funds)/EBITDA","meaning":"Leverage proxy used in lending.","conditions":"EBITDA not cash flow."},{"name":"Pretax equity profit","expr":"Pretax profit to equity≈EBIT−interest expense","meaning":"Lợi nhuận residual trước thuế trong ví dụ đơn giản.","conditions":"Ignore nonoperating items."},{"name":"Simplified pretax ROE","expr":"Pretax ROE=(EBIT−interest)/equity","meaning":"Minh họa leverage magnifies equity returns.","conditions":"Not after-tax return unless tax given."},{"name":"Financial leverage sensitivity","expr":"DFL≈%Δpretax equity profit/%ΔEBIT","meaning":"Độ nhạy earnings to interest obligations.","conditions":"Fixed interest and simplified EBIT model."},{"name":"DFL formula","expr":"DFL=EBIT/(EBIT−Interest)","meaning":"Khi net pretax profit positive and interest fixed.","conditions":"Simplified no preferred dividend model."},{"name":"ROE change","expr":"ΔROE≈Δpretax profit/equity (equity fixed)","meaning":"Kiểm tra stress scenarios.","conditions":"Not total shareholder return."},{"name":"Interest coverage stress","expr":"Coverage_stress=(EBIT_base×stress factor)/interest fixed","meaning":"Downside rate sensitivity.","conditions":"Ignore change in interest and other factors."}],"examples":[{"question_en":"A firm earns revenue $100m, has fixed operating cost $50m and variable costs 20% of sales. Compute EBIT.","answer":"$30 million","steps_vi":["Variable cost=100×20%=20m.","EBIT=100−50−20=30m.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"Simplified cost model."},{"question_en":"Sales rise 10% in the preceding high-fixed-cost firm. What is new EBIT?","answer":"$38 million","steps_vi":["Revenue mới=110m, variable cost=22m, fixed vẫn 50m.","EBIT=110−22−50=38m; tăng 26,67% so với base 30m."],"check":"Relevant range."},{"question_en":"A lower-fixed-cost firm has revenue $100m, fixed cost $20m and variable costs 50% of sales. Find EBIT.","answer":"$30 million","steps_vi":["Variable costs=100×50%=50m.","EBIT=100−20−50=30m, bằng base của firm fixed-cost cao."],"check":"Compare operating sensitivities."},{"question_en":"Revenue rises to $110m for lower-fixed-cost firm. Find EBIT.","answer":"$35 million","steps_vi":["Variable cost=110×50%=55m, fixed=20m.","EBIT=110−55−20=35m; chỉ tăng 16,67%."],"check":"Lower operating leverage."},{"question_en":"Find base DOL for high-fixed-cost firm with revenue $100m, VC $20m, EBIT $30m.","answer":"2.67×","steps_vi":["Contribution margin=100−20=80m.","DOL=80/30≈2,67 lần; sales tăng 10% ⇒ EBIT tăng xấp xỉ 26,67%."],"check":"Linear CVP assumptions."},{"question_en":"Find base DOL for low-fixed-cost firm with sales $100m, VC $50m, EBIT $30m.","answer":"1.67×","steps_vi":["Contribution=100−50=50m; EBIT=30m.","DOL=50/30≈1,67 lần."],"check":"Fixed-cost mix affects sensitivity."},{"question_en":"An issuer has EBIT $30m and interest expense $6m. Find interest coverage.","answer":"5.0×","steps_vi":["Coverage=EBIT/interest=30/6=5 lần.","So sánh debt covenants và biến động EBIT."],"check":"Not liquidity calendar."},{"question_en":"A firm has debt $120m and book equity $80m. Compute D/E.","answer":"1.50×","steps_vi":["D/E=120/80=1,5.","Ghi rõ dùng book values trong ví dụ này."],"check":"150% = 1.5x."},{"question_en":"Debt $120m, cash $20m, EBITDA $50m. Find net debt/EBITDA.","answer":"2.00×","steps_vi":["Net debt=120−20=100m.","Ratio=100/50=2×; phải xét việc cash có restricted không."],"check":"Simple definition."},{"question_en":"Issuer A has EBIT $30m, interest $2m, equity $80m. Find pretax ROE.","answer":"35.00%","steps_vi":["Pretax profit=30−2=28m.","Pretax ROE=28/80=35%; chưa tính tax."],"check":"Simple financing model."},{"question_en":"Issuer B has the same EBIT $30m, interest $9m and equity $40m. Find pretax ROE.","answer":"52.50%","steps_vi":["Pretax profit=30−9=21m.","Pretax ROE=21/40=52,5%, cao hơn A do leverage."],"check":"Downside also amplified."},{"question_en":"If EBIT declines 25% to $22.5m, firm B interest stays $9m and equity $40m. Pretax ROE?","answer":"33.75%","steps_vi":["Pretax profit=22,5−9=13,5m.","ROE=13,5/40=33,75%, giảm mạnh khi OI đi xuống."],"check":"Fixed interest."},{"question_en":"If EBIT declines 25% to $22.5m, firm A interest stays $2m and equity $80m. Pretax ROE?","answer":"25.63%","steps_vi":["Pretax profit=22,5−2=20,5m.","ROE=20,5/80=25,625%≈25,63%.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"Compare risk not only level."},{"question_en":"Debt $150m, cash $30m, marketable securities $20m, EBITDA $50m. Net debt/EBITDA?","answer":"2.0×","steps_vi":["Net debt=150−30−20=100m.","Debt/EBITDA sau khi trừ liquid funds =100/50=2×."],"check":"Cash may be restricted."},{"question_en":"An issuer has EBIT $40m and interest $10m. DFL in simplified model?","answer":"1.33×","steps_vi":["DFL=40/(40−10)=40/30≈1,33.","Earnings on equity nhạy hơn EBIT khi có lãi vay cố định."],"check":"Before tax."},{"question_en":"A firm has $80m debt and $20m equity, with the same EBIT as an all-equity firm. Which typically has more volatile equity earnings?","answer":"Levered firm","steps_vi":["Interest expense cố định tạo sensitivity earnings cho equity cao.","Không phải chắc chắn ROE thực tế cao hơn trong mọi trạng thái."],"check":"Leverage downside."},{"question_en":"A startup reports annual operating losses and few tangible assets. Which financing is more likely initially?","answer":"Founder/venture equity","steps_vi":["Revenue và collateral yếu hạn chế khả năng vay debt truyền thống.","Leases/convertible debt vẫn có thể xuất hiện."],"check":"Early lifecycle."},{"question_en":"An aircraft leasing firm holds valuable movable assets and stable contractual leases. What financing feature is likely important?","answer":"Collateral-supported borrowing","steps_vi":["Aircraft có thể làm collateral hỗ trợ debt, nhưng default và asset values vẫn rủi ro.","Debt capacity differs from software startup."],"check":"Collateral condition."}],"questions":[{"stem_en":"Which combination most strongly supports greater debt capacity?","options":["Stable cash flows and valuable collateral.","Highly unpredictable cash flows and no collateral.","Persistent negative EBIT with no financing alternatives."],"correct":0,"why_vi":"Cash flows đều và collateral có thể bảo vệ creditors.","trap_vi":"No universal guarantee."},{"stem_en":"High operating leverage generally means:","options":["A greater proportion of variable operating costs.","EBIT is relatively sensitive to changes in sales.","A higher share of equity financing."],"correct":1,"why_vi":"Fixed operating cost cao làm EBIT biến động mạnh khi revenue thay đổi.","trap_vi":"Operating versus financial leverage."},{"stem_en":"Financial leverage is most directly associated with:","options":["A higher fixed production cost ratio.","Higher sales price elasticity.","Fixed debt financing obligations."],"correct":2,"why_vi":"Interest/debt obligations làm returns của equity nhạy với EBIT.","trap_vi":"Financing not operations."},{"stem_en":"A firm has EBIT $40m and interest expense $8m. Interest coverage is:","options":["5.0×.","0.20×.","32.0×."],"correct":0,"why_vi":"Coverage=40/8=5×. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Before tax/interest."},{"stem_en":"An issuer has interest-bearing debt $120m and equity $80m. D/E is:","options":["0.67×.","1.50×.","2.00×."],"correct":1,"why_vi":"120/80=1,50×. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Debt numerator."},{"stem_en":"A company has debt $100m, cash $20m, and EBITDA $40m. Net debt/EBITDA equals:","options":["2.50×.","1.50×.","2.00×."],"correct":2,"why_vi":"Net debt=80m; chia EBITDA40m→2×. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Exclude noncash debt?"},{"stem_en":"Which company typically relies more on founder/venture equity in its initial stage?","options":["A startup with negative free cash flow.","A mature regulated utility with stable cash flow.","A large asset-backed aircraft lessor."],"correct":0,"why_vi":"Startup thiếu track record và collateral để borrow cheaply.","trap_vi":"Early-stage fundraising."},{"stem_en":"A company with high fixed operating costs is likely to exhibit:","options":["Lower EBIT sensitivity at all revenue levels.","Higher operating leverage.","No need for financing."],"correct":1,"why_vi":"Fixed-cost share lớn khuếch đại biến động EBIT.","trap_vi":"Avoid confusing with debt leverage."},{"stem_en":"The relevant top-down factor affecting cost of debt most directly is:","options":["Old management salary.","Existing inventory color.","Government interest rate and credit market spreads."],"correct":2,"why_vi":"Lãi suất thị trường và spreads chung thay đổi rd.","trap_vi":"Top down not issuer-specific."},{"stem_en":"Which is a bottom-up issuer-specific factor?","options":["Credit history and interest coverage.","National inflation rate only.","Global investor risk appetite only."],"correct":0,"why_vi":"Credit profile và debt metrics của issuer ảnh hưởng financing terms.","trap_vi":"Macro factors also matter."},{"stem_en":"A company earns EBIT $30m with interest $6m. Its interest coverage is:","options":["0.20×.","5×.","24×."],"correct":1,"why_vi":"30/6=5 lần; EBIT nên lớn so với annual interest.","trap_vi":"Not CFO."},{"stem_en":"A high-fixed-cost manufacturer sees sales fall sharply. Its EBIT is likely to:","options":["Be immune to sales changes.","Rise automatically due to depreciation.","Decline disproportionately, other things equal."],"correct":2,"why_vi":"Fixed costs không giảm tương ứng khiến EBIT giảm nhanh.","trap_vi":"Relevant sales range."},{"stem_en":"What is the main effect of financial leverage on equity returns?","options":["Magnifies gains and losses as operating profit changes.","Guarantees higher realized equity return.","Eliminates default risk."],"correct":0,"why_vi":"Debt interest fixed làm residual profit/equity biến động lớn hơn.","trap_vi":"Downside risk."},{"stem_en":"An issuer's debt credit spread widens while government rates are unchanged. Its new borrowing cost likely:","options":["Falls.","Rises.","Is unchanged by definition."],"correct":1,"why_vi":"Rd tăng theo widening spread dù risk-free unchanged.","trap_vi":"Current market yield."},{"stem_en":"A finance company has long-lived assets financed only by overnight debt. Its most obvious risk is:","options":["Operating margin compression only.","Equity dilution risk only.","Refinancing / maturity mismatch."],"correct":2,"why_vi":"Nợ đáo hạn liên tục trước khi asset cash flows tới làm rollover risk.","trap_vi":"Maturity matching."},{"stem_en":"Which is usually more important for an early-stage technology venture than a mature utility?","options":["Equity funding availability.","Covered interest parity.","Fixed coupon preservation."],"correct":0,"why_vi":"Startup phụ thuộc equity và investor risk tolerance nhiều hơn vì thiếu collateral.","trap_vi":"Business model and stage."},{"stem_en":"When EBIT drops 25% but interest payments are fixed, financial leverage most likely causes:","options":["Equity profit to be unchanged.","Equity profit to drop more sharply as a percentage.","Interest to drop by exactly 25%."],"correct":1,"why_vi":"Lãi vay không giảm cùng EBIT, residual profit chịu cú sốc lớn hơn.","trap_vi":"Pretax model."},{"stem_en":"A company with DOL of 2.5× sees sales increase 4%, holding relevant assumptions. EBIT approximately rises:","options":["2.5%.","1.6%.","10%."],"correct":2,"why_vi":"ΔEBIT≈DOL×ΔSales=2,5×4%=10%. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Linear approximation."},{"stem_en":"Leases of aircraft can be relevant to capital structure because they:","options":["Create contractual fixed payment obligations.","Are always pure common equity.","Never affect leverage."],"correct":0,"why_vi":"Operating needs fixed assets có thể financed bằng lease với debt-like characteristics.","trap_vi":"Contract review needed."},{"stem_en":"In evaluating leverage, an analyst should check:","options":["Revenue alone.","Debt maturity schedule and liquidity alongside ratios.","Only number of shares issued historically."],"correct":1,"why_vi":"Coverage và net debt ratio không thể hiện đầy đủ cash due dates.","trap_vi":"Funding liquidity."}],"cards":[{"front_en":"Explain: Capital structure determinants","back_vi":"Cơ cấu nợ/vốn chủ phụ thuộc business model, lifecycle, asset base, risk, khả năng tạo tiền và capital market conditions."},{"front_en":"Explain: Early-stage companies","back_vi":"Startup thường có revenue/cash flow thấp hoặc âm, thiếu collateral, rủi ro default cao, nên chủ yếu tìm equity từ founder, employees, venture capital."},{"front_en":"Explain: Growth stage issuers","back_vi":"Công ty đang mở rộng cần tài trợ sản phẩm và capex, dùng equity/debt tùy khả năng tạo CF và quality of assets; leverage có thể tăng khi ổn định."},{"front_en":"Explain: Mature stage issuers","back_vi":"Doanh nghiệp trưởng thành với CF ổn định thường có thể huy động debt dài hạn, bonds và leases; chính sách hoàn vốn cổ đông cũng quan trọng."},{"front_en":"Explain: Capital-intensive model","back_vi":"Hãng hàng không, utilities, manufacturers cần nhiều tangible long-lived assets, thường hỗ trợ secured financing nhưng demand risk vẫn có."},{"front_en":"Explain: Capital-light model","back_vi":"Software/platform doanh nghiệp có thể ít tài sản thế chấp, sử dụng nhiều intangible value, nguồn equity/internal CF phù hợp hơn khi CF biến động."},{"front_en":"Explain: Collateral quality","back_vi":"Real estate, vehicles, aircraft và receivables chất lượng cao có thể cầm cố; collateral làm creditors dễ thu hồi, tăng debt access."},{"front_en":"Explain: Stable versus volatile cash flows","back_vi":"CF đều và dự báo được làm debt service bền hơn; CF chu kỳ/biến động cần cushion hoặc tỷ trọng equity lớn hơn."},{"front_en":"Explain: Top-down market conditions","back_vi":"Risk-free yield, liquidity, investor risk appetite và credit spreads trên thị trường làm rd/re biến đổi theo thời gian."},{"front_en":"Explain: Top-down industry conditions","back_vi":"Ngành có fixed costs/market cyclicality khác nhau dẫn đến beta và khả năng sử dụng nợ khác nhau."},{"front_en":"Explain: Bottom-up issuer conditions","back_vi":"Credit history, profitability, cash coverage, leverage, governance, liquidity và rating quyết định required financing costs."},{"front_en":"Explain: Business operating leverage","back_vi":"Operating leverage là mức fixed operating costs cao so với variable costs; làm EBIT nhạy với revenue changes."},{"front_en":"Explain: Fixed versus variable operating cost","back_vi":"Chi phí cố định không đổi khi sales biến động trong phạm vi capacity, variable costs thường tỷ lệ theo output."},{"front_en":"Explain: Operating leverage high","back_vi":"Khi fixed costs lớn, doanh thu tăng làm EBIT tăng nhanh, nhưng sales giảm gây profit drop mạnh."},{"front_en":"Explain: Degree of operating leverage","back_vi":"DOL≈%ΔEBIT/%ΔSales; tại một điểm, DOL=contribution margin/EBIT trong CVP linear model."},{"front_en":"Explain: Financial leverage","back_vi":"Debt/lease fixed interest obligations làm residual profit và ROE của equity nhạy với EBIT."},{"front_en":"Explain: Interest coverage","back_vi":"EBIT/interest expense đo khả năng trả lãi từ profit hoạt động; càng thấp thường debt risk càng cao."},{"front_en":"Explain: Financial leverage magnification","back_vi":"Với interest fixed, khi EBIT tăng thì residual income equity tăng tỷ lệ lớn hơn; khi EBIT giảm equity chịu rủi ro mạnh."},{"front_en":"Explain: Debt-to-equity","back_vi":"D/E=interest-bearing debt/equity, phải nhất quán book vs market."},{"front_en":"Explain: Net debt","back_vi":"Net debt thường là debt trừ cash và liquid securities; đo leverage sau liquidity offset."},{"front_en":"Explain: Net debt/EBITDA","back_vi":"Thước đo leverage vận hành theo số lần EBITDA, thường dùng covenants/ratings; không tự động đo khả năng chi trả lãi chính xác."},{"front_en":"Explain: Interest obligations timing","back_vi":"Cash interest/payment due dates có thể gây distress ngay cả khi annual EBIT dương, cần xét liquidity và debt maturities."},{"front_en":"Explain: Equity issuance and signals","back_vi":"Equity raise có thể bị thị trường diễn giải là stock overpriced hoặc có funding need; signaling phụ thuộc bất cân xứng thông tin."},{"front_en":"Explain: Leases versus borrowing","back_vi":"Thuê tài sản thay vì mua bằng debt có thể hỗ trợ capacity và kiểm soát capex cash timing, nhưng vẫn là fixed obligations."},{"front_en":"Explain: Credit spreads and rating","back_vi":"Rating xuống làm rd cao, cost of capital tăng; giữ rating có thể là mục tiêu target capital structure."},{"front_en":"Explain: Financing exposure checklist","back_vi":"Xem lifecycle, assets/collateral, EBIT volatility, debt capacity, interest coverage, WACC sensitivity, credit cycles và rollover maturities."}]},{"id":"CFA26-03-06-LOS03","letter":"6.c","title_en":"Modigliani–Miller Propositions","outcome_en":"explain the Modigliani–Miller propositions regarding capital structure","overview_vi":"Phân biệt các mệnh đề MM trong thế giới không thuế và có thuế TNDN; nêu rõ assumptions, arbitrage intuition, firm value, cost of equity, WACC và vì sao lý thuyết không biện minh vay nợ vô hạn trong thực tế.","source":[{"id":"CFA Institute Curriculum 2026 — Corporate Issuers LM6","pages":"199–208 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading25","pages":"268–273 (physical PDF)"},{"id":"SAPP Corporate Issuers 2026 — Module6","pages":"244–265 (physical PDF)"}],"sections":[{"heading":"Capital structure irrelevance baseline","body":"Trong perfect markets không thuế/transaction/distress/agency, lựa chọn debt versus equity không làm thay đổi tổng giá trị cash-flow-producing assets của firm.","trap":"Do not assert irrelevance when major market frictions exist."},{"heading":"MM homogeneous expectations","body":"Investors đồng thuận về expected operating cash flows và business risk; differences in financing không thay đổi investment opportunities của firm.","trap":"Assumption, not empirical observation."},{"heading":"MM perfect capital markets","body":"Không transaction costs, không taxes, thông tin như nhau, không bankruptcy costs; investors có thể replicate leverage.","trap":"Real markets have taxes, frictions and distress."},{"heading":"MM homogeneous borrowing conditions","body":"Nhà đầu tư vay/cho vay cùng điều kiện đơn giản, arbitrage loại bỏ những chênh lệch giá không bền vững do cơ cấu funding.","trap":"Personal leverage replication may be imperfect in practice."},{"heading":"MM absence of agency costs","body":"Managers act to maximize shareholder wealth; không tốn kém vì xung đột shareholders-creditors-managers.","trap":"Agency problems may alter debt value."},{"heading":"MM independence of financing and investment","body":"Quyết định đầu tư hoạt động và phương án financing tách rời về dòng tiền trong giả định cơ sở.","trap":"Financing can constrain investment in reality."},{"heading":"MM Proposition I without corporate taxes","body":"V_L=V_U: giá trị levered bằng giá trị all-equity khi không có taxes và financing frictions.","trap":"No valuation premium from borrowing alone."},{"heading":"MM Proposition II without corporate taxes","body":"re tăng cùng D/E với slope r0−rd, bù đúng lợi thế vốn nợ rẻ để WACC không đổi.","trap":"A falling simple debt weight is not automatic value creation."},{"heading":"Unlevered cost of capital","body":"r0 là return yêu cầu trên assets của company khi all-equity financed, tương ứng business risk cơ sở.","trap":"Do not confuse with risk-free rate."},{"heading":"Homemade leverage concept","body":"Investor có thể tự vay để replicate risky payoff thay vì firm vay, nên chỉ thay cơ cấu claims chứ không làm asset cash flow tự sinh ra.","trap":"Arbitrage depends on frictionless borrowing."},{"heading":"Cost of equity leverage effect","body":"Nếu D/E tăng, shareholders giữ claim residual rủi ro hơn; re tăng dù debt thường có lower explicit rate.","trap":"Equity becomes riskier with leverage."},{"heading":"WACC invariance no taxes","body":"Với no-tax MM, wd rd+we re=r0 cho mọi mix tuân assumptions.","trap":"re cannot stay fixed as D changes under MM II."},{"heading":"Unlevered equity beta business risk","body":"Risk trên all-equity financing phản ánh business asset risk; leveraged equity risk chứa thêm financing risk.","trap":"Risk can migrate between claimholders, not disappear."},{"heading":"Corporate tax interest shield","body":"Khi interest deductible, borrowing tạo tax saving; trong model perpetual debt với tax rate T, PV shield=T×D.","trap":"Tax shield depends on deductions and persistence."},{"heading":"MM Proposition I with corporate taxes","body":"V_L=V_U+T×D trong simplified perpetuity model; firm value tăng nhờ PV tax shield.","trap":"Not a universal formula for changing debt path/tax losses."},{"heading":"MM Proposition II with corporate taxes","body":"re=r0+(r0−rd)(1−T)D/E trong specified MM tax model, khác công thức no-tax vì factor 1−T.","trap":"Don't omit factor in taxed expression."},{"heading":"Cost of debt after tax under MM","body":"Debt góp phần rd(1−T) vào WACC; khi leverage tăng, re của equity vẫn có thể tăng vì residual risk.","trap":"Tax-adjusted debt cost and risk changes both matter."},{"heading":"WACC falls in corporate-tax-only MM","body":"Nếu chỉ có corporate tax và nợ duy trì vĩnh viễn, tax shield làm total firm value cao hơn và overall WACC thấp hơn khi tăng debt.","trap":"This prediction is not optimal unlimited debt in reality."},{"heading":"Riskless debt assumption in stylized example","body":"Nhiều phép tính MM giới thiệu rd không đổi và borrowing fixed; nếu risk và rd đổi, cần mô hình phù hợp assumptions.","trap":"Constant rd is not always realistic."},{"heading":"Firm value equals debt plus equity","body":"Sau recapitalization, V_L=D+E theo market values; E suy ra bằng V_L−D chứ không luôn bằng V_U−D khi có tax shield.","trap":"Tax shield changes firm total value."},{"heading":"Unlevered versus levered equity claim","body":"D tăng không trực tiếp làm business asset CF tăng; equity return biến động lớn hơn do fixed contractual debt payoffs.","trap":"Leverage reallocates operating risk."},{"heading":"Perpetual cash flow valuation","body":"Với unlevered constant perpetual operating cash flow CF, V_U=CF/r0; minh họa logic asset risk and discount rate.","trap":"CF must be after-corporate-tax unlevered FCFF consistently."},{"heading":"Market arbitrage rationale","body":"Nếu hai firms giống operating assets nhưng vốn hóa khác chỉ vì tài trợ, investors có động cơ mua tài sản rẻ và tạo payoff tương đương.","trap":"Financing equivalence subject to assumptions."},{"heading":"Tax shield intuition","body":"Chính phủ chịu phần economic burden của deductible interest, nên tổng cash available to debt/equity providers có thể tăng.","trap":"Actual laws may limit interest deductibility."},{"heading":"Beyond MM: financial distress","body":"Vay quá mức làm tăng expected bankruptcy/legal/restructuring/costly lost-customer costs, bù lại lợi ích thuế.","trap":"Need trade-off theory for realistic optimum."},{"heading":"Beyond MM: agency, signaling, flexibility","body":"Debt disciplines free cash flow nhưng có thể tạo underinvestment, asset substitution và distress financing constraints.","trap":"No single leverage conclusion works for all firms."},{"heading":"MM versus real WACC","body":"Under no-tax MM, minimum WACC không phụ thuộc leverage; under corporate tax-only debt lowers WACC; thực tế WACC có thể giảm rồi tăng vì distress.","trap":"Always identify regime before solving."},{"heading":"Common exam distinction","body":"Cần nhớ: no-tax Prop I nêu firm value không đổi; no-tax Prop II làm re tăng; có thuế Prop I cộng TD; có thuế Prop II thêm hệ số (1−T).","trap":"Keep numbering and assumptions consistent."}],"formulas":[{"name":"MM no-tax Proposition I","expr":"V_L=V_U","meaning":"Capital-structure irrelevance.","conditions":"Perfect markets without taxes or distress costs."},{"name":"MM no-tax Proposition II","expr":"re=r0+(r0−rd)×D/E","meaning":"Equity required return rises with leverage.","conditions":"MM no corporate tax assumptions."},{"name":"WACC without corporate tax","expr":"WACC=(D/V)rd+(E/V)re=r0","meaning":"Weighted cost constant across D/E.","conditions":"No-tax MM."},{"name":"Corporate-tax debt shield perpetual","expr":"PV(debt tax shield)=T×D","meaning":"PV annual deductibility in simplified MM tax perpetuity.","conditions":"Fixed debt perpetually outstanding, deductions usable."},{"name":"MM with corporate tax Proposition I","expr":"V_L=V_U+T×D","meaning":"Firm value rises by tax shield.","conditions":"Corporate taxes only, no distress/agency costs."},{"name":"MM with corporate tax Proposition II","expr":"re=r0+(r0−rd)(1−T)D/E","meaning":"Equity cost with deductible debt tax shield.","conditions":"Tax rate T and perpetual simplified debt."},{"name":"WACC with corporate tax","expr":"WACC=(D/V)rd(1−T)+(E/V)re","meaning":"Overall after-tax funding hurdle.","conditions":"Market financing weights sum to 1."},{"name":"Equity market value from firm value","expr":"E=V_L−D","meaning":"Residual shareholder claim after recapitalization.","conditions":"All amounts market-valued."},{"name":"Debt to equity ratio","expr":"D/E=D_mkt/E_mkt","meaning":"Leverage used in MM cost equity.","conditions":"D and E positive."},{"name":"Unlevered firm perpetuity value","expr":"V_U=FCFF/r0","meaning":"Stylized unlevered business value.","conditions":"Constant perpetual post-tax FCFF."},{"name":"No-tax example re","expr":"re=10%+(10%−5%)×(40/60)=13.3333%","meaning":"Required equity return with D40, E60.","conditions":"r0 and rd fixed."},{"name":"Taxed example re","expr":"re=10%+(10%−5%)(1−25%)×(40/70)=12.1429%","meaning":"Required equity return under taxed MM.","conditions":"Vu=100, D=40, T=.25."},{"name":"Taxed example WACC","expr":"WACC=40/110×5%×.75+70/110×12.142857%=9.0909%","meaning":"Overall WACC declines versus r0 10%.","conditions":"Tax shield assumptions satisfied."},{"name":"Value gain from shield","expr":"V_L−V_U=T×D","meaning":"Benefit of perpetual deductible borrowing.","conditions":"Not a blanket real-world arbitrage claim."},{"name":"Claim total","expr":"V_L=D+E","meaning":"Balance market claims.","conditions":"Preferred claims added if present."},{"name":"Unlevered required return","expr":"r0=(D/V)rd+(E/V)re (without taxes)","meaning":"Recover asset risk discount rate.","conditions":"MM no taxes."},{"name":"Tax shield interest saving per year","expr":"Corporate tax saving≈T×rd×D","meaning":"Annual deduction benefit in basic fixed-rate setting.","conditions":"Firm is profitable; interest deduction allowed."},{"name":"No-tax debt weight","expr":"wd=D/(D+E)","meaning":"Funding mix.","conditions":"Market values under model."},{"name":"Taxed equity weight","expr":"we=(V_U+TD−D)/(V_U+TD)","meaning":"Equity funding weight under ideal MM recapitalization.","conditions":"E=VL−D."},{"name":"Delta firm value","expr":"ΔV_L≈T×ΔD","meaning":"Value sensitivity in pure corporate-tax perpetual model.","conditions":"Constant rate T and zero distress."}],"examples":[{"question_en":"Under no-tax MM, Vu=$100m, debt=$40m. Compute VL.","answer":"$100 million","steps_vi":["Proposition I no taxes: VL=VU, không có tax shield.","Phần equity market value=100−40=60 triệu USD."],"check":"Perfect market."},{"question_en":"Under no-tax MM, r0=10%, rd=5%, D=$40m, E=$60m. Calculate re.","answer":"13.33%","steps_vi":["D/E=40/60=0,6667.","re=10%+(10%−5%)×0,6667=13,33%.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"WACC remains 10%."},{"question_en":"Under no-tax MM, rd=5%, D/V=40%, re=13.3333%, E/V=60%. Calculate WACC.","answer":"10.00%","steps_vi":["WACC=0,4×5%+0,6×13,3333%.","2%+8%=10%, đúng r0."],"check":"Component equity cost must adjust."},{"question_en":"Vu=$100m, perpetual debt=$40m, corporate tax=25%. Calculate VL under tax-only MM.","answer":"$110 million","steps_vi":["PV debt shield=T×D=0,25×40=10 triệu USD.","VL=100+10=110 triệu USD."],"check":"Ignore distress by assumption."},{"question_en":"For VL=$110m and debt=$40m, compute market equity E.","answer":"$70 million","steps_vi":["E=V_L−D.","110−40=70 triệu USD."],"check":"Not Vu−D here."},{"question_en":"Under tax-only MM, r0=10%, rd=5%, T=25%, D=40m, E=70m. Compute re.","answer":"12.14%","steps_vi":["re=10%+5%×0,75×(40/70).","10%+2,142857%=12,142857%, ≈12,14%.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"Factor (1−T)."},{"question_en":"Under tax-only MM, D=40m, E=70m, rd=5%, re=12.142857%, T=25%. WACC?","answer":"9.09%","steps_vi":["wd=40/110, we=70/110; after-tax rd=3,75%.","WACC=(40/110)×3,75%+(70/110)×12,142857%=9,0909%.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"Use leveraged total VL denominator."},{"question_en":"Vu=$200m, T=30%, D=$50m. Find VL under pure corporate-tax MM.","answer":"$215 million","steps_vi":["PV tax shield=0,30×50=15 triệu USD.","VL=200+15=215 triệu USD."],"check":"Fixed perpetual debt."},{"question_en":"Vu=$80m, tax rate=20%, permanent debt=$25m. Calculate tax shield PV.","answer":"$5 million","steps_vi":["TD=0,2×25=5 triệu USD.","PV tiết kiệm thuế lý tưởng là 5 triệu USD."],"check":"Interest deductible."},{"question_en":"In MM with taxes, Vu=$150m, VL=$174m, tax=30%. Infer perpetual debt D.","answer":"$80 million","steps_vi":["VL−Vu=24 triệu USD.","D=24/0,30=80 triệu USD."],"check":"Only tax shield difference."},{"question_en":"Under no-tax MM, r0=12%, rd=6%, D/E=0.5. Find re.","answer":"15.00%","steps_vi":["Spread của asset required return với debt=6%.","re=12%+6%×0,5=15%."],"check":"No tax factor."},{"question_en":"Under corporate-tax MM, r0=12%, rd=6%, D/E=0.5, T=25%. re?","answer":"14.25%","steps_vi":["re=12%+6%×0,75×0,5.","12%+2,25%=14,25%.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"Tax-adjusted slope."},{"question_en":"In no-tax MM, D=$30m, E=$70m, rd=4%, re=10%. Calculate WACC.","answer":"8.20%","steps_vi":["WACC=0,3×4%+0,7×10%.","1,2%+7%=8,2%.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"This equals r0 under assumptions."},{"question_en":"A firm with Vu=$120m, perpetual debt D=$60m, tax 25% reports VL=$135m. Check.","answer":"Correct under tax-only MM","steps_vi":["TD=0,25×60=15 triệu USD.","120+15=135 triệu USD đúng simplified MM with taxes."],"check":"Real distress excluded."},{"question_en":"If permanent debt increases from $20m to $30m and T=20% under tax-only MM, change in VL?","answer":"+$2 million","steps_vi":["ΔD=10 triệu USD.","ΔV=T×ΔD=0,2×10=2 triệu USD."],"check":"Not a realistic universal recommendation."},{"question_en":"No-tax MM: r0=9%, rd=5%, D/E=1.0. Compute re.","answer":"13.00%","steps_vi":["re=r0+(r0−rd)×D/E.","9%+4%=13%.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"Distinguish from WACC."},{"question_en":"Taxed MM: r0=9%, rd=5%, D/E=1.0, T=25%. Compute re.","answer":"12.00%","steps_vi":["Spread của required asset return với rd=4%.","9%+4%×0,75=12%."],"check":"Lower than no-tax re at same D/E."},{"question_en":"A company with Vu=$250m, permanent D=$100m and T=21%. Ideal VL?","answer":"$271 million","steps_vi":["PV shield=21%×100=21m.","VL=250+21=271m.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"Perpetuity assumption."},{"question_en":"For ideal VL=$271m, permanent debt=$100m. What is E?","answer":"$171 million","steps_vi":["Equity=V_L−D.","271−100=171m.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"Using levered market capitalization."},{"question_en":"Under no-tax MM, should a $100m debt-for-equity recapitalization increase total asset value?","answer":"No, under assumptions","steps_vi":["Financing chỉ thay claims được phân bổ.","VL=VU; không có new operating cash flows/tax benefit."],"check":"Assumptions critical."},{"question_en":"Under pure corporate-tax MM, D=$0 yields VL=VU regardless T.","answer":"True","steps_vi":["TD=0 khi không có debt.","Không có PV tax shield của interest nếu không vay."],"check":"Model identity."},{"question_en":"If no-tax WACC is 11%, what happens when the issuer increases debt and re adjusts exactly under MM?","answer":"Stays 11%","steps_vi":["Prop II làm re tăng đủ để bù debt rẻ hơn.","Capital structure irrelevance means WACC constant."],"check":"No taxes or frictions."},{"question_en":"Under tax-only MM, why can firm value rise with borrowing?","answer":"Interest tax shield","steps_vi":["Interest deductible giảm thu nhập tính thuế và làm PV tax saving dương.","Không phải vì bản thân debt tạo thêm operating cash flow."],"check":"Tax benefit requires taxable income."},{"question_en":"What limitation invalidates VL=VU+TD for a temporary one-year loan?","answer":"Debt is not perpetually maintained","steps_vi":["Công thức TD là PV shield perpetual, không áp dụng máy móc cho finite debt path.","Cần định giá các shield hàng năm."],"check":"Do not blindly use TD."},{"question_en":"A firm with same operating assets but greater D/E has higher re in no-tax MM. Explain.","answer":"Equity bears higher financial risk","steps_vi":["Các cổ đông residual chịu volatility cao hơn do fixed debt claims.","Lợi thế debt rẻ không làm tổng WACC thấp hơn vì re tăng."],"check":"Risk allocation."},{"question_en":"When tax law disallows interest deductibility, what happens to corporate debt tax shield?","answer":"No benefit from disallowed deduction","steps_vi":["Không tạo được tax saving hợp lệ từ interest không được khấu trừ.","Cần xem giới hạn và tax capacity."],"check":"Assumptions differ."},{"question_en":"A tax-only MM model yields VL=$130m and Vu=$120m with tax 25%. What permanent D?","answer":"$40 million","steps_vi":["Chênh value=10 triệu USD.","D=(130−120)/0,25=40 triệu USD."],"check":"No distress."},{"question_en":"A tax-only MM firm has D/V=20%, after-tax rd=4%, E/V=80%, re=11%. Calculate WACC.","answer":"9.60%","steps_vi":["0,2×4%+0,8×11%.","0,8%+8,8%=9,6%.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"Debt already after tax."}],"questions":[{"stem_en":"Under perfect no-tax MM, the market value of a leveraged firm compared with an otherwise identical unlevered firm is:","options":["Equal.","Lower because equity is more volatile.","Higher by the present value of interest deductions."],"correct":0,"why_vi":"Proposition I: VL=VU khi không tax/frictions.","trap_vi":"Tax shield requires corporate taxes."},{"stem_en":"Under MM without taxes, increasing D/E generally causes re to:","options":["Remain constant.","Increase as equity assumes more financial risk.","Decrease as debt becomes cheaper."],"correct":1,"why_vi":"Proposition II cho re=r0+(r0−rd)D/E. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Cost of equity adjusts."},{"stem_en":"A firm has no corporate taxes and r0=10%, rd=5%, D/E=0.5. re equals:","options":["7.5%.","10.0%.","12.5%."],"correct":2,"why_vi":"re=10%+5%×0,5=12,5%. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Use no-tax formula."},{"stem_en":"Which is assumed in basic no-tax MM?","options":["Perfect markets with no taxes or distress costs.","Managers maximize value but investors have private asymmetric information.","Persistent annual corporate interest tax shields."],"correct":0,"why_vi":"Không thuế, no distress/transaction/agency trong mô hình cơ sở.","trap_vi":"Assumption not reality."},{"stem_en":"No-tax MM with D/V=40%, E/V=60%, rd=5% and re=13.3333% gives WACC closest to:","options":["12%.","10%.","8%."],"correct":1,"why_vi":"0,4×5%+0,6×13,3333%=10%. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"WACC equal r0."},{"stem_en":"A firm has Vu=$100m, permanent debt=$40m and T=25%. Tax-only MM VL is:","options":["$90m.","$140m.","$110m."],"correct":2,"why_vi":"V_L=100+0,25×40=110 triệu USD.","trap_vi":"Ignore distress under assumption."},{"stem_en":"The PV of the perpetual corporate interest tax shield under simplified MM is:","options":["T × D.","D/(1−T).","VU/T."],"correct":0,"why_vi":"Tax benefit PV=TD khi debt perpetual và có đầy đủ deduction.","trap_vi":"Not universal finite-debt PV."},{"stem_en":"The tax-adjusted MM Proposition II formula for cost of equity contains:","options":["−(r0−rd)(1−T)D/E.","+(r0−rd)(1−T)D/E.","+(r0−rd)D/E."],"correct":1,"why_vi":"Corporate tax case có hệ số (1−T).","trap_vi":"No-tax formula omits T."},{"stem_en":"If Vu=$200m, permanent D=$50m, T=30% and no distress costs, VL equals:","options":["$250m.","$200m.","$215m."],"correct":2,"why_vi":"200+0,30×50=215 triệu USD.","trap_vi":"Do not subtract D twice."},{"stem_en":"What is most likely to increase as D/E rises under MM with no taxes?","options":["Equity required return.","The company's unlevered cost of capital.","Operating asset cash flow."],"correct":0,"why_vi":"Equity càng residual/risky khi debt lớn.","trap_vi":"Operating assets unchanged."},{"stem_en":"Under pure no-tax MM, the firm's WACC as its debt proportion increases is best described as:","options":["Rising continuously.","Constant.","Falling continuously."],"correct":1,"why_vi":"Cost equity tăng để offset debt rẻ hơn.","trap_vi":"Prop II offsets Prop I."},{"stem_en":"The principal reason corporate-tax-only MM predicts VL>VU with deductible debt is:","options":["Stronger market demand for the product.","Elimination of bankruptcy risk in actual markets.","The debt interest tax shield."],"correct":2,"why_vi":"Tax saving có present value dương theo giả định.","trap_vi":"No new operating cash flows."},{"stem_en":"For Vu=$100m, D=$40m, T=25%, a tax-only MM firm has market equity worth:","options":["$70m.","$110m.","$60m."],"correct":0,"why_vi":"VL=110m; E=VL−D=70m. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Don't use Vu−D."},{"stem_en":"Under tax-only MM, r0=10%, rd=5%, T=25% and D/E=40/70. re closest to:","options":["10.00%.","12.14%.","13.33%."],"correct":1,"why_vi":"re=10%+5%×75%×40/70≈12,14%. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Tax adjustment."},{"stem_en":"Using debt weight 40/110, equity weight 70/110, rd=5%, re=12.142857% and T=25%, WACC closest to:","options":["10.00%.","12.14%.","9.09%."],"correct":2,"why_vi":"WACC=(40/110)×3,75%+(70/110)×12,142857%=9,09%. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Value weights total 110."},{"stem_en":"In a leveraged company's balance sheet after ideal tax-shield value creation, E_mkt is:","options":["VL−D.","VU+ D.","VU−D."],"correct":0,"why_vi":"Market equity=market levered firm value trừ debt.","trap_vi":"Equity residual value."},{"stem_en":"A company has Vu=$80m, T=20%, permanent debt $25m. Its tax-only VL equals:","options":["$105m.","$85m.","$80m."],"correct":1,"why_vi":"VL=80+0,2×25=85 triệu USD.","trap_vi":"PV shield 5m."},{"stem_en":"Under no-tax MM, a higher D/E holding operating assets fixed primarily:","options":["Reduces the firm's operating volatility mechanically.","Creates a corporate interest tax shield.","Redistributes financing risk to equity."],"correct":2,"why_vi":"Debt là fixed claim và equity bears more payoff variability.","trap_vi":"No tax benefit."},{"stem_en":"Corporate-tax-only MM predicts that increasing perpetual debt generally:","options":["Increases firm value through deductible interest.","Forces a unique finite optimum even without distress costs.","Makes the tax shield disappear."],"correct":0,"why_vi":"VL=VU+TD tăng khi D tăng theo mô hình; thiếu distress costs.","trap_vi":"Model not real-world optimum."},{"stem_en":"Which assumption is inconsistent with the original MM perfect-markets model?","options":["Equal expected operating CF for otherwise identical assets.","High bankruptcy restructuring costs.","Investors can borrow on comparable terms."],"correct":1,"why_vi":"Mô hình không có financial distress costs; thực tế sẽ khác.","trap_vi":"Label assumptions."},{"stem_en":"A firm has r0=12%, rd=6%, T=25%, and D/E=0.5. Under MM with taxes re is:","options":["15.00%.","12.75%.","14.25%."],"correct":2,"why_vi":"re=12%+6%×0,75×0,5=14,25%. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Distinguish no-tax 15%."},{"stem_en":"A firm has r0=12%, rd=6%, and D/E=0.5 under no-tax MM. re is:","options":["15.00%.","13.50%.","14.25%."],"correct":0,"why_vi":"No-tax re=12%+6%×0,5=15%. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Omits 1−T."},{"stem_en":"Compared with perfect no-tax MM, adding deductible corporate interest while excluding distress costs implies WACC:","options":["Must exceed re.","Can decrease as debt increases.","Must remain r0."],"correct":1,"why_vi":"Tax shield làm blended cost after-tax thấp hơn trong mô hình tax-only.","trap_vi":"Real-world distress offsets."},{"stem_en":"Which practical risk makes pure corporate-tax MM an unrealistic recommendation for unlimited borrowing?","options":["Changes in the number of customers only.","The definition of a common share.","Financial distress and agency costs."],"correct":2,"why_vi":"Distress, covenants, agency and costs làm borrowing không thể tăng mãi.","trap_vi":"Need static trade-off."},{"stem_en":"If D rises by $10m and T=20%, with all tax-only MM assumptions, VL changes by:","options":["$2m.","$8m.","$10m."],"correct":0,"why_vi":"ΔVL=TΔD=20%×10=2 triệu USD.","trap_vi":"Infinite debt not feasible in practice."},{"stem_en":"Why does the cost of equity rise with leverage in MM Proposition II?","options":["Debt becomes an asset of the issuer.","Equity is the riskier residual claim after debt obligations.","Shares become risk-free."],"correct":1,"why_vi":"Fixed claims của debt làm residual return cho cổ đông biến động mạnh.","trap_vi":"Operating risk unaffected."},{"stem_en":"A temporary debt issue should NOT automatically use PV tax shield=TD because:","options":["Interest is always nondeductible.","Market value cannot be defined.","The perpetual-debt assumption is not satisfied."],"correct":2,"why_vi":"T×D bắt nguồn từ tax savings duy trì perpetually; finite borrowing cần discount schedule.","trap_vi":"Check actual cash flows."},{"stem_en":"In no-tax MM, two firms with identical operating assets but different debt ratios should have:","options":["Equal total market value.","Unequal PV of identical operating free cash flows.","Different business risk by definition."],"correct":0,"why_vi":"Prop I yêu cầu cùng total value khi financing không làm thay cash flows.","trap_vi":"Arbitrage intuition."},{"stem_en":"An analyst using MM must first determine whether the question assumes:","options":["Inventory accounting method.","Corporate taxes and distress costs.","The share ticker symbol."],"correct":1,"why_vi":"Kết quả VL/WACC khác nhiều giữa no tax/tax-only/real-world.","trap_vi":"Assumptions determine solution."},{"stem_en":"A firm with Vu=$150m, VL=$174m and T=30% has permanent debt D equal to:","options":["$24m.","$52m.","$80m."],"correct":2,"why_vi":"(174−150)/0,3=80 triệu USD.","trap_vi":"Tax shield assumption."}],"cards":[{"front_en":"Explain: Capital structure irrelevance baseline","back_vi":"Trong perfect markets không thuế/transaction/distress/agency, lựa chọn debt versus equity không làm thay đổi tổng giá trị cash-flow-producing assets của firm."},{"front_en":"Explain: MM homogeneous expectations","back_vi":"Investors đồng thuận về expected operating cash flows và business risk; differences in financing không thay đổi investment opportunities của firm."},{"front_en":"Explain: MM perfect capital markets","back_vi":"Không transaction costs, không taxes, thông tin như nhau, không bankruptcy costs; investors có thể replicate leverage."},{"front_en":"Explain: MM homogeneous borrowing conditions","back_vi":"Nhà đầu tư vay/cho vay cùng điều kiện đơn giản, arbitrage loại bỏ những chênh lệch giá không bền vững do cơ cấu funding."},{"front_en":"Explain: MM absence of agency costs","back_vi":"Managers act to maximize shareholder wealth; không tốn kém vì xung đột shareholders-creditors-managers."},{"front_en":"Explain: MM independence of financing and investment","back_vi":"Quyết định đầu tư hoạt động và phương án financing tách rời về dòng tiền trong giả định cơ sở."},{"front_en":"Explain: MM Proposition I without corporate taxes","back_vi":"V_L=V_U: giá trị levered bằng giá trị all-equity khi không có taxes và financing frictions."},{"front_en":"Explain: MM Proposition II without corporate taxes","back_vi":"re tăng cùng D/E với slope r0−rd, bù đúng lợi thế vốn nợ rẻ để WACC không đổi."},{"front_en":"Explain: Unlevered cost of capital","back_vi":"r0 là return yêu cầu trên assets của company khi all-equity financed, tương ứng business risk cơ sở."},{"front_en":"Explain: Homemade leverage concept","back_vi":"Investor có thể tự vay để replicate risky payoff thay vì firm vay, nên chỉ thay cơ cấu claims chứ không làm asset cash flow tự sinh ra."},{"front_en":"Explain: Cost of equity leverage effect","back_vi":"Nếu D/E tăng, shareholders giữ claim residual rủi ro hơn; re tăng dù debt thường có lower explicit rate."},{"front_en":"Explain: WACC invariance no taxes","back_vi":"Với no-tax MM, wd rd+we re=r0 cho mọi mix tuân assumptions."},{"front_en":"Explain: Unlevered equity beta business risk","back_vi":"Risk trên all-equity financing phản ánh business asset risk; leveraged equity risk chứa thêm financing risk."},{"front_en":"Explain: Corporate tax interest shield","back_vi":"Khi interest deductible, borrowing tạo tax saving; trong model perpetual debt với tax rate T, PV shield=T×D."},{"front_en":"Explain: MM Proposition I with corporate taxes","back_vi":"V_L=V_U+T×D trong simplified perpetuity model; firm value tăng nhờ PV tax shield."},{"front_en":"Explain: MM Proposition II with corporate taxes","back_vi":"re=r0+(r0−rd)(1−T)D/E trong specified MM tax model, khác công thức no-tax vì factor 1−T."},{"front_en":"Explain: Cost of debt after tax under MM","back_vi":"Debt góp phần rd(1−T) vào WACC; khi leverage tăng, re của equity vẫn có thể tăng vì residual risk."},{"front_en":"Explain: WACC falls in corporate-tax-only MM","back_vi":"Nếu chỉ có corporate tax và nợ duy trì vĩnh viễn, tax shield làm total firm value cao hơn và overall WACC thấp hơn khi tăng debt."},{"front_en":"Explain: Riskless debt assumption in stylized example","back_vi":"Nhiều phép tính MM giới thiệu rd không đổi và borrowing fixed; nếu risk và rd đổi, cần mô hình phù hợp assumptions."},{"front_en":"Explain: Firm value equals debt plus equity","back_vi":"Sau recapitalization, V_L=D+E theo market values; E suy ra bằng V_L−D chứ không luôn bằng V_U−D khi có tax shield."},{"front_en":"Explain: Unlevered versus levered equity claim","back_vi":"D tăng không trực tiếp làm business asset CF tăng; equity return biến động lớn hơn do fixed contractual debt payoffs."},{"front_en":"Explain: Perpetual cash flow valuation","back_vi":"Với unlevered constant perpetual operating cash flow CF, V_U=CF/r0; minh họa logic asset risk and discount rate."},{"front_en":"Explain: Market arbitrage rationale","back_vi":"Nếu hai firms giống operating assets nhưng vốn hóa khác chỉ vì tài trợ, investors có động cơ mua tài sản rẻ và tạo payoff tương đương."},{"front_en":"Explain: Tax shield intuition","back_vi":"Chính phủ chịu phần economic burden của deductible interest, nên tổng cash available to debt/equity providers có thể tăng."},{"front_en":"Explain: Beyond MM: financial distress","back_vi":"Vay quá mức làm tăng expected bankruptcy/legal/restructuring/costly lost-customer costs, bù lại lợi ích thuế."},{"front_en":"Explain: Beyond MM: agency, signaling, flexibility","back_vi":"Debt disciplines free cash flow nhưng có thể tạo underinvestment, asset substitution và distress financing constraints."},{"front_en":"Explain: MM versus real WACC","back_vi":"Under no-tax MM, minimum WACC không phụ thuộc leverage; under corporate tax-only debt lowers WACC; thực tế WACC có thể giảm rồi tăng vì distress."},{"front_en":"Explain: Common exam distinction","back_vi":"Cần nhớ: no-tax Prop I nêu firm value không đổi; no-tax Prop II làm re tăng; có thuế Prop I cộng TD; có thuế Prop II thêm hệ số (1−T)."}]},{"id":"CFA26-03-06-LOS04","letter":"6.d","title_en":"Optimal and Target Capital Structure","outcome_en":"describe optimal and target capital structures","overview_vi":"Mô tả capital structure tối ưu theo static trade-off và các tác động của distress, agency, asymmetric information, signaling, pecking order; phân biệt cơ cấu vốn target là policy thực tế, không nhất thiết trùng optimum theo lý thuyết.","source":[{"id":"CFA Institute Curriculum 2026 — Corporate Issuers LM6","pages":"208–215 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading25","pages":"273–277 (physical PDF)"},{"id":"SAPP Corporate Issuers 2026 — Module6","pages":"266–283 (physical PDF)"}],"sections":[{"heading":"Optimal capital structure definition","body":"Cơ cấu vốn optimal là mix debt/equity tối đa hóa enterprise value, tương ứng tối thiểu hóa WACC khi operating CF và risk held consistently.","trap":"A target policy is not automatically optimal."},{"heading":"Static trade-off framework","body":"Khi tăng borrowing, PV interest tax shield cải thiện value nhưng PV expected financial distress costs tăng; firm chọn mức cân bằng.","trap":"Not pure tax-only MM."},{"heading":"Debt tax benefit","body":"Interest deductible giúp giảm taxable income và tăng PV cash available to investors nếu có taxable profit.","trap":"Tax law and limitations matter."},{"heading":"Direct distress costs","body":"Legal fees, advisers, bankruptcy proceedings, restructuring costs và asset-sale process trực tiếp làm giảm value khi distress.","trap":"Costs are not only lawyers' bills."},{"heading":"Indirect distress costs","body":"Supplier/customer confidence mất, employees nghỉ, delayed investment, mất contracts và operating inefficiency làm tổn thất dù chưa formal bankruptcy.","trap":"Indirect costs may exceed direct costs."},{"heading":"Expected financial distress costs","body":"PV expected distress reflects probability × severity × time value; leverage tăng có thể làm both probability and loss tăng.","trap":"An expected cost can matter without actual bankruptcy occurring."},{"heading":"Marginal optimum","body":"Optimal D* khi additional PV tax benefit bằng additional PV expected distress/agency costs, đạt value maximum.","trap":"Higher debt beyond D* can reduce firm value."},{"heading":"WACC U-shape intuition","body":"WACC có thể giảm khi debt tax benefits dominate rồi tăng khi debt risk/distress pushes rd/re higher.","trap":"Functional shape illustrative, not guaranteed smooth for all firms."},{"heading":"Static trade-off value relation","body":"V_L≈V_U+PV(tax shield)−PV(expected distress costs), có thể cộng agency/friction terms trong model đầy đủ.","trap":"Approximate decomposition, no universal numerical formula."},{"heading":"Financial flexibility","body":"Cash buffer, undrawn credit lines, strong rating và low leverage giúp tài trợ opportunities hoặc chống shocks khi vốn bên ngoài đắt.","trap":"Value of flexibility is difficult to quantify exactly."},{"heading":"Debt capacity and credit rating","body":"Management thường đặt rating target để có nguồn vốn ổn định và bảo vệ chi phí future borrowing.","trap":"Rating target is a strategy, not a math optimum."},{"heading":"Agency costs of equity","body":"Excess free cash flow có thể khiến management đầu tư kém hiệu quả/tiêu dùng perks; debt repayment requirement có thể discipline managers.","trap":"Debt benefits are not only tax shield."},{"heading":"Agency costs of debt","body":"Leverage cao có thể tạo risk shifting, debt overhang/underinvestment và incentive conflicts giữa shareholder-creditors.","trap":"More debt can create costs even when distress is not immediate."},{"heading":"Risk shifting / asset substitution","body":"Equity holders có thể muốn dự án rủi ro hơn vì downside partly borne by lenders khi near-distress; creditors anticipate and demand higher yield.","trap":"Ethical/covenant implications."},{"heading":"Underinvestment / debt overhang","body":"Một positive-NPV project có thể không được shareholders funding nếu phần lớn benefits chuyển sang debt creditors.","trap":"Issuer value loss despite positive project NPV."},{"heading":"Free cash flow hypothesis","body":"Debt payments ép management sử dụng cash kỷ luật hơn, giảm unproductive spending nếu managers có discretion lớn.","trap":"Too much debt harms flexibility."},{"heading":"Asymmetric information","body":"Managers biết nhiều hơn investors về issuer quality, dẫn đến external financing potentially adverse selection.","trap":"Financing announcements send information."},{"heading":"Equity issuance signaling","body":"Equity financing có thể bị thị trường hiểu management cho rằng stock overvalued; phản ứng phụ thuộc context, không phải định luật.","trap":"Never assert equity always mispriced."},{"heading":"Pecking-order theory","body":"Firms thường ưu tiên retained earnings/internal funds, rồi debt, cuối cùng new equity do information asymmetry/issuance costs; không phải rule bất biến.","trap":"Pecking order is different from static trade-off optimum."},{"heading":"Target capital structure definition","body":"Target là debt/equity policy management theo rating, financing flexibility, solvency and strategic constraints; thường hiện qua ranges/metrics.","trap":"Target may differ from theoretically optimal mix."},{"heading":"Target book-value metrics","body":"Do market values thay đổi mạnh, issuer có thể dùng book debt/equity, net debt/EBITDA hoặc rating để quản lý target.","trap":"Don't automatically use target book weights for current market WACC when not specified."},{"heading":"Current versus target WACC weights","body":"Cost of capital for forward-looking projects may use planned/target capital mix; current market mix dùng khi question explicitly asks current market weights.","trap":"State basis and consistency."},{"heading":"Capital structure and business lifecycle","body":"Giai đoạn mới thành lập có uncertainty cao nên thường ưu tiên equity/internal funds; doanh nghiệp trưởng thành có cash flow ổn định có thể chịu được debt nhiều hơn, tùy asset profile.","trap":"No one-size-fits-all debt ratio."},{"heading":"Debt contract covenants","body":"Covenants như giới hạn debt mới, dividend restrictions và collateral requirements khiến cơ cấu vốn thực tế bị ràng buộc.","trap":"Covenants can create cliff risks."},{"heading":"Cyclicality and distress risk","body":"Cyclical cash flows và high operating leverage khiến financial leverage nguy hiểm hơn, so optimal debt lower all else equal.","trap":"Stable business may hold more debt."},{"heading":"Debt maturity matching","body":"Lịch đáo hạn liabilities phải tương thích với vòng đời assets và expected cash flows; dùng funding ngắn hạn cho asset dài hạn tạo rollover risk.","trap":"Solvency and liquidity can diverge."},{"heading":"Trade-off incremental comparison","body":"So sánh PV tax benefit và PV incremental expected distress (plus agency effects) tại các mức debt; chọn value cao nhất thay vì ratio thấp nhất.","trap":"Marginal effects matter."},{"heading":"Credit spread feedback","body":"Khi debt tăng, market credit spread và rd có thể tăng, re cũng tăng; phải cập nhật component costs nếu tính real-world WACC.","trap":"Fixed rd assumption breaks at high leverage."},{"heading":"Optimal versus target example","body":"Hypothetical models có thể cho D*=80m nhưng board đặt target 60m để giữ rating/liquidity buffer; cả hai không mâu thuẫn.","trap":"Management may intentionally deviate for flexibility."},{"heading":"Distress loss isn't debt book amount","body":"Expected financial distress cost không tự bằng principal outstanding; nó là PV tổn thất kinh tế do distress relative to otherwise healthy firm.","trap":"Don't subtract entire debt twice."},{"heading":"Corporate capital structure checklist","body":"Nhìn tax capacity, asset collateral, volatility, coverage, credit rating, maturities, market access, agency/conflict và target policy trước khi kết luận.","trap":"Max tax shield is not the objective."}],"formulas":[{"name":"Static trade-off value decomposition","expr":"V_L≈V_U+PV(tax shields)−PV(expected financial distress costs)","meaning":"Đánh đổi PV lợi ích thuế và tổn thất kỳ vọng.","conditions":"Approximation; may add agency and other costs."},{"name":"Net debt","expr":"Net debt≈interest-bearing debt−cash−marketable securities","meaning":"Proxy xác định leverage target.","conditions":"Definitions vary."},{"name":"Debt/equity","expr":"D/E=debt/equity","meaning":"Capital structure ratio.","conditions":"Specify market or book."},{"name":"Debt weight","expr":"wd=D/(D+E)","meaning":"Funding mix.","conditions":"State valuation basis."},{"name":"Debt-to-capital","expr":"D/(D+E)","meaning":"Share of total financing from debt.","conditions":"Two-class funding only."},{"name":"Interest coverage","expr":"Interest coverage=EBIT/interest expense","meaning":"Ability to service interest.","conditions":"Proxy, not complete cash analysis."},{"name":"Net debt/EBITDA","expr":"Net debt/EBITDA=(debt−cash)/EBITDA","meaning":"Leverage used in rating/covenant context.","conditions":"EBITDA positive."},{"name":"Equity funding weight","expr":"we=E/(D+E)=1−wd","meaning":"Residual capital share.","conditions":"No preferred class."},{"name":"Weighted funding hurdle","expr":"WACC=wd rd(1−T)+we re","meaning":"Cost of capital at selected mix.","conditions":"Risk/costs coherent with chosen mix."},{"name":"Corporate tax shield incremental","expr":"ΔPV(tax shield)≈T×ΔD","meaning":"Simplified incremental permanent debt.","conditions":"Profit available and no limits."},{"name":"Expected distress loss simple","expr":"Expected loss≈Pr(distress)×loss given distress","meaning":"Scenario-weighted cost illustration.","conditions":"Timing/discounter needed for PV."},{"name":"Value under target candidates","expr":"V(D_i)=Vu+PV(TaxShield_i)−PV(Distress_i)","meaning":"Compare alternative debt plans.","conditions":"Keep asset business CF consistent."},{"name":"Marginal optimum criterion","expr":"Marginal PV tax benefit≈marginal PV expected distress cost","meaning":"Describes D* at interior maximum.","conditions":"Smooth static trade-off illustration."},{"name":"Interest saving per period","expr":"Tax benefit≈deductible interest×marginal T","meaning":"Corporate tax saving.","conditions":"Legal deductibility and taxable income."},{"name":"Leverage funding mix","expr":"Target debt ratio=target debt/(target debt+target equity)","meaning":"Management policy ratio.","conditions":"Could use book-value proxies."},{"name":"Debt capacity proxy","expr":"Max debt≈target net debt/EBITDA×forecast EBITDA+cash","meaning":"Reverse simplified leverage ceiling.","conditions":"Illustrative, not prescribed CFAI formula."},{"name":"Target gap","expr":"Debt gap=target debt−current debt","meaning":"Approx planned refinancing or issuance.","conditions":"Must consider growth and market conditions."},{"name":"Value benefit of restructuring","expr":"Incremental firm value=Value_new−Value_old","meaning":"Compare capital plans.","conditions":"Comparable cash flows and discount basis."},{"name":"Debt tax shield reduction","expr":"Lost tax shield≈T×reduction in permanent debt","meaning":"Illustrative marginal effect.","conditions":"Tax capacity and permanence."},{"name":"Distress cost increase","expr":"Δexpected distress cost=cost_high_debt−cost_low_debt","meaning":"Cost of extra borrowing.","conditions":"Present-value terms."},{"name":"Net tax-minus-distress","expr":"Financing value added≈PV(tax shields)−PV(distress)","meaning":"Value added by financing relative to unlevered.","conditions":"Simplified decomposition."},{"name":"Stable financing coverage","expr":"Interest coverage ratio=EBIT/annual interest","meaning":"Covenant/issuer risk proxy.","conditions":"EBIT not operating cash flow."},{"name":"Target funding range","expr":"D/E_target in [lower,upper]","meaning":"Management may use ranges rather than precise point.","conditions":"Illustrative policy notation."},{"name":"Funding hierarchy","expr":"Internal funds→debt→new equity","meaning":"Pecking-order preference.","conditions":"Descriptive, not algebraic law."},{"name":"Market-value capitalization","expr":"V_mkt=D_mkt+E_mkt","meaning":"Values financing claims.","conditions":"May include preferred."}],"examples":[{"question_en":"A company has Vu=$200m, perpetual D=$80m, tax 25%, PV expected distress cost $10m. Estimate VL.","answer":"$210 million","steps_vi":["Tax benefit=25%×80=20 triệu USD.","VL=200+20−10=210 triệu USD."],"check":"Static trade-off illustration."},{"question_en":"With Vu=$200m, D=$120m, T=25%, PV distress costs $40m, find VL.","answer":"$190 million","steps_vi":["PV shield=0,25×120=30 triệu USD.","VL=200+30−40=190 triệu USD."],"check":"Excess debt can destroy value."},{"question_en":"Which debt level yields higher value, D=$80m with V=$210m or D=$120m with V=$190m?","answer":"$80 million debt","steps_vi":["Mức D=80 tạo V=210m, lớn hơn 190m khi D=120.","Giá trị cao nhất trong candidates, không phải tối đa nợ."],"check":"Simple discrete optimization."},{"question_en":"A firm with Vu=$150m, tax shield PV $18m and expected distress costs PV $5m has VL of:","answer":"$163 million","steps_vi":["Giá trị tăng ròng=18−5=13m.","VL=150+13=163 triệu USD."],"check":"No additional agency terms."},{"question_en":"An issuer's total debt is $90m, cash is $25m, EBITDA is $26m. Net debt/EBITDA?","answer":"2.50×","steps_vi":["Net debt=90−25=65 triệu USD.","65/26=2,5×."],"check":"Liquidity definition."},{"question_en":"A company has debt $75m and equity $125m. Debt-to-capital ratio?","answer":"37.50%","steps_vi":["Total capital=75+125=200m.","Debt weight=75/200=37,5%.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"State market vs book weights."},{"question_en":"Management targets D/E=0.5 and equity $120m. What target debt?","answer":"$60 million","steps_vi":["D/E=0,5.","D=0,5×120=60 triệu USD."],"check":"Same valuation basis."},{"question_en":"A company has EBIT $50m and annual interest expense $10m. Interest coverage?","answer":"5.00×","steps_vi":["Interest coverage=EBIT/interest.","50/10=5 lần, chưa phản ánh cash due dates."],"check":"Credit proxy."},{"question_en":"An analyst estimates 10% default probability and $40m loss conditional on distress; illustrative expected cost?","answer":"$4 million","steps_vi":["E(loss)=10%×40m.","Expected cost=4 triệu USD trước discount/time issues."],"check":"Probability-weighted illustration."},{"question_en":"A new leverage policy adds $12m PV shields and $18m PV distress; incremental value?","answer":"−$6 million","steps_vi":["ΔV=12−18=−6m.","Debt plan làm giảm value 6 triệu USD nếu CF hoạt động không đổi."],"check":"Marginal trade-off."},{"question_en":"A financing plan yields tax shield PV $30m and distress PV $8m. Net financing contribution?","answer":"$22 million","steps_vi":["Net gain=30−8.","Thêm 22 triệu USD vào unlevered value theo model đơn giản."],"check":"Ignore agency for illustration."},{"question_en":"A company cuts permanent debt by $20m with marginal corporate T=25%, holding tax capacity. PV tax shield decline?","answer":"$5 million","steps_vi":["T×reduced debt=0,25×20.","Tax shield PV giảm 5 triệu USD trong lý thuyết perpetual."],"check":"Real distress risk may also fall."},{"question_en":"A firm has debt $100m, cash $20m, and EBITDA $40m. Net debt/EBITDA?","answer":"2.00×","steps_vi":["Net debt=80m.","80/40=2,0×.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"Ratio ignores capex."},{"question_en":"If $100m of debt is 40% of total funding, what is equity financing?","answer":"$150 million","steps_vi":["Tổng funding=100/0,4=250m.","Equity=250−100=150m."],"check":"Two sources."},{"question_en":"Current debt is $60m and management targets $85m debt, other things fixed. Debt gap?","answer":"+$25 million","steps_vi":["Debt gap=85−60=25m.","Cần thêm 25m debt so với current, chưa tính maturity."],"check":"Illustrative."},{"question_en":"A firm has current debt $120m, current equity $180m. D/E?","answer":"0.667×","steps_vi":["D/E=120/180=0,6667.","Khoảng 0,667 lần."],"check":"Market/book must align."},{"question_en":"A firm targets debt ratio 30% in $500m total market capital. Target D?","answer":"$150 million","steps_vi":["Target D=500×30%=150m.","Equity expected=350m.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"Financing plan."},{"question_en":"A company with tax shield PV $22m and distress PV $12m has net leverage benefit of:","answer":"$10 million","steps_vi":["22−12=10m.","Financing tăng giá trị 10m tương đối với Vu."],"check":"Simplified model."},{"question_en":"Issuer A has net debt $45m, EBITDA $30m. Calculate net debt/EBITDA.","answer":"1.50×","steps_vi":["45/30=1,5.","Target ratio proxy, không phải cost equity."],"check":"EBITDA positive."},{"question_en":"A board expects new debt to save $6m in tax PV but raise PV distress costs by $11m. Should it add debt, all else equal?","answer":"No","steps_vi":["Net Δvalue=6−11=−5 triệu USD.","Không nên theo static trade-off khi cost vượt benefit."],"check":"All else equal assumption."},{"question_en":"One company's required return on equity is 14%, after-tax debt cost 6%, with 70% equity 30% debt. WACC?","answer":"11.60%","steps_vi":["WACC=0,7×14%+0,3×6%.","9,8%+1,8%=11,6%.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"Use after-tax debt cost provided."},{"question_en":"A firm has $80m equity, $20m debt. Debt-to-capital?","answer":"20%","steps_vi":["Total financing=100m.","20/100=20%.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"Two financing types."},{"question_en":"A company has $150m assets financed by D=$50m and E=$100m. Debt/equity?","answer":"0.50×","steps_vi":["D/E=50/100.","0,5 lần."],"check":"No other claims."},{"question_en":"In static trade-off, if marginal distress cost PV is $7m and marginal tax benefit is $4m, value change?","answer":"−$3 million","steps_vi":["ΔV=4−7=−3m.","Additional borrowing reduces value 3m.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"Discrete approximation."},{"question_en":"A company with Vu=$300m, tax shield PV $35m, distress cost PV $22m: VL?","answer":"$313 million","steps_vi":["Net gain=35−22=13m.","VL=300+13=313 triệu USD."],"check":"Other costs ignored."},{"question_en":"A target range of D/E=0.4–0.6 and equity market value $100m suggests debt between:","answer":"$40m and $60m","steps_vi":["D=D/E×100m.","Target D khoảng 40–60m theo cùng market equity."],"check":"Equity held fixed illustration."},{"question_en":"A firm with debt $70m, equity $130m has market debt weight:","answer":"35%","steps_vi":["Total funding=200m.","70/200=35%.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"If market values given."},{"question_en":"A company has current D=$40m and target D=$55m. What change in debt funding?","answer":"+$15 million","steps_vi":["55−40=15m.","Cần 15m additional debt nếu giữ mục tiêu đơn giản."],"check":"No refinancing details."},{"question_en":"A company loses a tax shield PV of $8m after deleveraging but reduces expected distress cost PV by $20m. Net value change?","answer":"+$12 million","steps_vi":["Lost tax benefit −8m, avoided distress +20m.","ΔV=20−8=+12m.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"Asset CF unchanged."},{"question_en":"A company has E=$90m, D=$60m. What is target debt weight if those are the planned values?","answer":"40%","steps_vi":["wd=D/(D+E)=60/150.","40%.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"Planned rather than current weights."},{"question_en":"An issuer has tax shield PV $40m, distress PV $35m at current debt. Net financing value?","answer":"$5 million","steps_vi":["40−35=5m.","Net value addition=5m, không phải 75m."],"check":"Simplified model."},{"question_en":"If a firm adds $50m of permanent debt at T=25%, what ideal tax shield PV before distress?","answer":"$12.5 million","steps_vi":["Tax shield=0,25×50.","12,5 triệu USD."],"check":"Ideal perpetual borrowing."},{"question_en":"At 5% annual cost of debt and $100m debt, deductible annual interest is $5m. At T=25%, tax savings?","answer":"$1.25 million per year","steps_vi":["Tax saving=5m×0,25.","Tiết kiệm thuế 1,25m/năm nếu đủ taxable profit."],"check":"Annual not PV."},{"question_en":"A firm has EBIT $12m and interest $6m. Interest coverage?","answer":"2.00×","steps_vi":["12/6=2 lần.","Thấp hơn coverage 5×, chỉ là một tín hiệu risk."],"check":"No cash schedule."},{"question_en":"A firm with net debt $96m and EBITDA $32m has net debt/EBITDA equal to:","answer":"3.00×","steps_vi":["96/32=3.","3 lần."],"check":"EBITDA before capex."},{"question_en":"If expected restructuring costs rise from PV $10m to $25m when more debt is used, incremental cost?","answer":"$15 million","steps_vi":["Δcost=25−10=15m.","Đây là cost gia tăng do đòn bẩy cao hơn."],"check":"Compare scenarios."},{"question_en":"An issuer's financing plan has VL=$260m with current debt and VL=$275m with target debt, holding asset operations constant. Value gain?","answer":"$15 million","steps_vi":["275−260=15m.","Target plan adds 15m modeled value.","Lưu ý: cần giữ các giả định và đơn vị trong đề khi diễn giải kết quả."],"check":"Need validate assumptions."},{"question_en":"The tax-only MM model predicts debt forever raises value, but actual static trade-off recognizes:","answer":"Expected distress costs","steps_vi":["Tax benefit PV tăng nhưng distress PV cũng tăng.","Optimal finite D* có thể tồn tại thực tế."],"check":"Qualitative conceptual scenario."}],"questions":[{"stem_en":"In static trade-off theory, the optimal level of debt is where:","options":["Marginal tax-shield benefit balances marginal distress cost.","Debt equals twice equity for all firms.","Debt is always zero."],"correct":0,"why_vi":"D* đạt value max khi marginal benefit≈marginal cost.","trap_vi":"No universal target leverage."},{"stem_en":"An issuer has Vu=$200m, tax-shield PV=$20m, and distress cost PV=$10m. Estimated VL is:","options":["$220m.","$210m.","$190m."],"correct":1,"why_vi":"V_L=200+20−10=210m. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Static trade-off."},{"stem_en":"The direct costs of financial distress most likely include:","options":["Customers moving away due to uncertainty.","Loss of key employees due to financial stress.","Bankruptcy legal and restructuring fees."],"correct":2,"why_vi":"Direct costs là phí luật sư, advisers và xử lý tái cấu trúc.","trap_vi":"Indirect costs include lost sales/relationships."},{"stem_en":"The indirect costs of financial distress most likely include:","options":["Loss of supplier and customer confidence.","The corporate tax rate.","Annual coupon payments by definition."],"correct":0,"why_vi":"Distress làm customers/suppliers rút lui, mất contracts.","trap_vi":"Cash interest is financing cost, not distress cost by itself."},{"stem_en":"A firm has debt $90m, cash $25m, and EBITDA $26m. Net debt/EBITDA is:","options":["2.88×.","2.50×.","3.46×."],"correct":1,"why_vi":"Net debt=65m; 65/26=2,5×. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Net rather than gross debt."},{"stem_en":"A firm has debt $75m and equity $125m. Its debt-to-capital ratio is:","options":["60%.","62.5%.","37.5%."],"correct":2,"why_vi":"D/(D+E)=75/200=37,5%. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Not D/E."},{"stem_en":"The pecking-order theory generally predicts an issuer prefers:","options":["Internal funds, debt, then new equity.","Government grants, then equity, then debt by rule.","Equity first, then debt, then cash."],"correct":0,"why_vi":"Asymmetric information/issuance costs góp phần tạo thứ tự retained cash→debt→equity.","trap_vi":"This is not absolute law."},{"stem_en":"Which statement best describes a target capital structure?","options":["The current bond coupon rate only.","Management's intended financing mix under practical constraints.","A mathematically proven global minimum debt cost."],"correct":1,"why_vi":"Target là policy/ratio/rating mục tiêu, có thể khác optimum.","trap_vi":"Target can use book metrics."},{"stem_en":"A company with EBIT $50m and interest expense $10m has interest coverage of:","options":["0.2×.","40×.","5×."],"correct":2,"why_vi":"EBIT/interest=50/10=5×. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Doesn't replace cash flow study."},{"stem_en":"Debt can mitigate agency problems of excess free cash flow because:","options":["Contractual debt service can constrain wasteful spending.","It makes operating volatility equal to zero.","It eliminates managers from the firm."],"correct":0,"why_vi":"Debt discipline cash vì issuer phải trả interest/principal.","trap_vi":"Too much debt brings other agency costs."},{"stem_en":"Why can heavy borrowing create shareholder–creditor conflicts?","options":["Creditors control every investment.","Equity may prefer risk-shifting projects near distress.","Shareholders always bear all creditor losses with no limited liability."],"correct":1,"why_vi":"Risk shifting/asset substitution có thể chuyển downside cho creditors.","trap_vi":"Agency costs of debt."},{"stem_en":"Underinvestment (debt overhang) describes a situation where:","options":["All positive-NPV projects are automatically funded.","Management always buys back stock immediately.","A positive-NPV project may be rejected if benefits flow mainly to existing creditors."],"correct":2,"why_vi":"Equity may not capture enough NPV under heavy debt. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Firm value lost."},{"stem_en":"A board's desire to preserve an investment-grade rating is most directly:","options":["A constraint informing target capital structure.","Proof that debt has zero cost.","Evidence of no debt financing."],"correct":0,"why_vi":"Rating target ảnh hưởng allowed leverage/financing flexibility.","trap_vi":"Not exact D*."},{"stem_en":"In static trade-off, if adding debt increases PV tax savings by $6m but distress costs by $11m, total value:","options":["Rises $17m.","Falls $5m.","Rises $5m."],"correct":1,"why_vi":"ΔV=6−11=−5m. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Marginal comparison."},{"stem_en":"The adverse-selection rationale is most associated with:","options":["Homogeneous expectations in frictionless markets.","No information differences whatsoever.","Asymmetric information between managers and investors."],"correct":2,"why_vi":"Managers có private signals, investors interpret financing actions.","trap_vi":"Motivates pecking-order preference."},{"stem_en":"Which approach correctly assesses capital structure of a cyclical, fixed-cost manufacturer?","options":["Consider operating leverage, CF volatility, debt capacity, and maturities.","Ignore financing costs because EBIT is positive.","Debt ratio alone proves safety."],"correct":0,"why_vi":"High cyclicality + high DOL tăng financing fragility.","trap_vi":"Risk integration."},{"stem_en":"A company plans D/E=0.5 with target equity $120m. Target debt equals:","options":["$120m.","$60m.","$240m."],"correct":1,"why_vi":"D=0,5×120=60m. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Same basis for E and D."},{"stem_en":"The financing flexibility of a conservative balance sheet is valuable mainly because:","options":["It ensures no taxes ever.","It eliminates all agency costs.","It allows borrowing/investing under future shocks or opportunities."],"correct":2,"why_vi":"Cushion cung cấp capacity khi markets tighten hoặc project attractive.","trap_vi":"Opportunity value."},{"stem_en":"In a simple trade-off scenario with Vu=$200m, D=$120m, T=25%, expected distress cost PV=$40m, VL equals:","options":["$190m.","$200m.","$230m."],"correct":0,"why_vi":"Tax shield=30m; V=200+30−40=190m. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Compare lower leverage scenario."},{"stem_en":"Expected financial distress costs represent:","options":["The entire principal of outstanding debt.","Present value of probability-weighted economic losses from distress.","Interest expense plus dividends exactly."],"correct":1,"why_vi":"Expected cost xem xác suất, severity và thời điểm.","trap_vi":"Do not subtract all debt again."},{"stem_en":"A firm has net debt=$45m and EBITDA=$30m. Net debt/EBITDA equals:","options":["0.67×.","15×.","1.5×."],"correct":2,"why_vi":"45/30=1,5 lần.","trap_vi":"Accounting proxy."},{"stem_en":"Management considers issuing equity when managers believe shares are undervalued. In signaling theory managers may:","options":["Hesitate to issue shares due to dilution and market interpretation.","Ignore financing choices because information is perfect.","Always prefer immediate issuance regardless of price."],"correct":0,"why_vi":"Equity issuance khi undervalued có thể gây dilution và thông tin bất cân xứng.","trap_vi":"Context-dependent signal."},{"stem_en":"An issuer with increasing debt might have rising rd even if risk-free rates are unchanged because:","options":["Operating assets must become safer.","Its credit spread widens due to default risk.","Tax rates are always zero."],"correct":1,"why_vi":"Higher leverage có thể làm lenders require higher credit spread.","trap_vi":"Top/bottom factors."},{"stem_en":"A financial covenant limiting incremental borrowing is best interpreted as:","options":["An accounting definition of equity value.","A source of risk-free financing.","A real-world constraint on target debt capacity."],"correct":2,"why_vi":"Covenants làm không thể tăng debt theo tax-only MM vô hạn.","trap_vi":"Contractual constraints."},{"stem_en":"The difference between optimal and target capital structure is that:","options":["Optimal is theoretical value-maximizing mix; target is management policy that may deviate.","Both terms mean the firm's current historical coupon.","Target always minimizes WACC exactly."],"correct":0,"why_vi":"Optimal trade-off value max; target theo strategy, rating, book ratios. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Don't conflate."},{"stem_en":"Which firm generally has greater debt capacity, all else equal?","options":["An early-stage pre-revenue venture.","A firm with stable contracted cash flows and collateral.","A firm with erratic cash flows and no collateral."],"correct":1,"why_vi":"Stable CF/collateral giúp creditors recover và forecast debt service.","trap_vi":"Conditional on other risk factors."},{"stem_en":"A company has a tax benefit PV of $22m and distress cost PV of $12m from a proposed financing structure. Net contribution relative to unlevered value is:","options":["+$34m.","−$10m.","+$10m."],"correct":2,"why_vi":"22−12=10m. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Tax minus distress."},{"stem_en":"A company with $100m debt and $20m cash has EBITDA=$40m. Net debt/EBITDA:","options":["2×.","3×.","2.5×."],"correct":0,"why_vi":"Net debt=80m; 80/40=2×. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Ratios ignore debt maturity."},{"stem_en":"A firm deleverages and loses $8m in tax-shield PV but avoids $20m in expected distress PV. Change in total value:","options":["−$12m.","+$12m.","−$28m."],"correct":1,"why_vi":"Δvalue=−8+20=+12m. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Can prefer lower debt."},{"stem_en":"The ratio management often uses for target capitalization in practice is:","options":["Exactly current market share price alone.","Price/earnings ratio alone.","Book leverage and debt-to-cash-flow metrics."],"correct":2,"why_vi":"Market price biến động mạnh, target dùng sách/rating/coverage.","trap_vi":"See CFAI p215."},{"stem_en":"Which theory focuses on balancing the tax advantages of debt against increasing bankruptcy and distress costs?","options":["Static trade-off theory.","Dividend discount model.","MM without taxes."],"correct":0,"why_vi":"Static trade-off tìm D* maximize value.","trap_vi":"Tax-only MM excludes distress."},{"stem_en":"If a firm has high growth option value and risky cash flows, higher debt may be less attractive because:","options":["Interest becomes tax-free income for the issuer.","Financial distress and underinvestment can damage option value.","Debt causes stock price to equal zero immediately."],"correct":1,"why_vi":"Debt overhead có thể ngăn positive-NPV options và tăng distress risk.","trap_vi":"Growth and flexibility."},{"stem_en":"Which issuer characteristic usually supports more debt, other things equal?","options":["Zero operating history and zero cash receipts.","Extreme earnings volatility with weak liquidity.","Stable cash flows and tangible collateral."],"correct":2,"why_vi":"Cash stability và collateral có thể giảm borrowing costs.","trap_vi":"Trade-off."},{"stem_en":"In a target funding policy, management might accept a lower theoretical value than the static model's peak to:","options":["Preserve flexibility and credit rating under uncertainty.","Ensure new equity has no risk.","Maximize bankruptcy fees."],"correct":0,"why_vi":"Target có thể thận trọng hơn D* mô hình để giữ buffer.","trap_vi":"Policy not exact optimum."},{"stem_en":"The main practical reason a firm's cost of equity may increase as leverage rises is:","options":["Tax law removes interest payments.","The residual equity claim becomes riskier.","It loses all residual downside risk."],"correct":1,"why_vi":"Equity bears residual earnings after fixed debt obligations. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Leverage raises re."},{"stem_en":"A company with debt=$70m, equity=$130m has a debt weight of:","options":["53.8%.","65%.","35%."],"correct":2,"why_vi":"wd=70/200=35%. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Debt-to-capital vs D/E."},{"stem_en":"Under static trade-off, the value-maximizing D* occurs before debt becomes so high that:","options":["Additional expected distress costs exceed additional tax benefits.","Debt investors receive any interest.","Tax benefits always vanish at zero debt."],"correct":0,"why_vi":"Sau D* marginal cost > marginal benefit, V declines. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Value-maximizing choice."},{"stem_en":"Asymmetric information and the preference for internal funding are most closely associated with:","options":["CAPM security market line.","Pecking-order financing theory.","Pure MM no-tax irrelevance."],"correct":1,"why_vi":"Pecking order internal→debt→equity. Đây là kết luận theo các giả định được nêu trong đề.","trap_vi":"Not a strict universal rule."}],"cards":[{"front_en":"Explain: Optimal capital structure definition","back_vi":"Cơ cấu vốn optimal là mix debt/equity tối đa hóa enterprise value, tương ứng tối thiểu hóa WACC khi operating CF và risk held consistently."},{"front_en":"Explain: Static trade-off framework","back_vi":"Khi tăng borrowing, PV interest tax shield cải thiện value nhưng PV expected financial distress costs tăng; firm chọn mức cân bằng."},{"front_en":"Explain: Debt tax benefit","back_vi":"Interest deductible giúp giảm taxable income và tăng PV cash available to investors nếu có taxable profit."},{"front_en":"Explain: Direct distress costs","back_vi":"Legal fees, advisers, bankruptcy proceedings, restructuring costs và asset-sale process trực tiếp làm giảm value khi distress."},{"front_en":"Explain: Indirect distress costs","back_vi":"Supplier/customer confidence mất, employees nghỉ, delayed investment, mất contracts và operating inefficiency làm tổn thất dù chưa formal bankruptcy."},{"front_en":"Explain: Expected financial distress costs","back_vi":"PV expected distress reflects probability × severity × time value; leverage tăng có thể làm both probability and loss tăng."},{"front_en":"Explain: Marginal optimum","back_vi":"Optimal D* khi additional PV tax benefit bằng additional PV expected distress/agency costs, đạt value maximum."},{"front_en":"Explain: WACC U-shape intuition","back_vi":"WACC có thể giảm khi debt tax benefits dominate rồi tăng khi debt risk/distress pushes rd/re higher."},{"front_en":"Explain: Static trade-off value relation","back_vi":"V_L≈V_U+PV(tax shield)−PV(expected distress costs), có thể cộng agency/friction terms trong model đầy đủ."},{"front_en":"Explain: Financial flexibility","back_vi":"Cash buffer, undrawn credit lines, strong rating và low leverage giúp tài trợ opportunities hoặc chống shocks khi vốn bên ngoài đắt."},{"front_en":"Explain: Debt capacity and credit rating","back_vi":"Management thường đặt rating target để có nguồn vốn ổn định và bảo vệ chi phí future borrowing."},{"front_en":"Explain: Agency costs of equity","back_vi":"Excess free cash flow có thể khiến management đầu tư kém hiệu quả/tiêu dùng perks; debt repayment requirement có thể discipline managers."},{"front_en":"Explain: Agency costs of debt","back_vi":"Leverage cao có thể tạo risk shifting, debt overhang/underinvestment và incentive conflicts giữa shareholder-creditors."},{"front_en":"Explain: Risk shifting / asset substitution","back_vi":"Equity holders có thể muốn dự án rủi ro hơn vì downside partly borne by lenders khi near-distress; creditors anticipate and demand higher yield."},{"front_en":"Explain: Underinvestment / debt overhang","back_vi":"Một positive-NPV project có thể không được shareholders funding nếu phần lớn benefits chuyển sang debt creditors."},{"front_en":"Explain: Free cash flow hypothesis","back_vi":"Debt payments ép management sử dụng cash kỷ luật hơn, giảm unproductive spending nếu managers có discretion lớn."},{"front_en":"Explain: Asymmetric information","back_vi":"Managers biết nhiều hơn investors về issuer quality, dẫn đến external financing potentially adverse selection."},{"front_en":"Explain: Equity issuance signaling","back_vi":"Equity financing có thể bị thị trường hiểu management cho rằng stock overvalued; phản ứng phụ thuộc context, không phải định luật."},{"front_en":"Explain: Pecking-order theory","back_vi":"Firms thường ưu tiên retained earnings/internal funds, rồi debt, cuối cùng new equity do information asymmetry/issuance costs; không phải rule bất biến."},{"front_en":"Explain: Target capital structure definition","back_vi":"Target là debt/equity policy management theo rating, financing flexibility, solvency and strategic constraints; thường hiện qua ranges/metrics."},{"front_en":"Explain: Target book-value metrics","back_vi":"Do market values thay đổi mạnh, issuer có thể dùng book debt/equity, net debt/EBITDA hoặc rating để quản lý target."},{"front_en":"Explain: Current versus target WACC weights","back_vi":"Cost of capital for forward-looking projects may use planned/target capital mix; current market mix dùng khi question explicitly asks current market weights."},{"front_en":"Explain: Capital structure and business lifecycle","back_vi":"Giai đoạn mới thành lập có uncertainty cao nên thường ưu tiên equity/internal funds; doanh nghiệp trưởng thành có cash flow ổn định có thể chịu được debt nhiều hơn, tùy asset profile."},{"front_en":"Explain: Debt contract covenants","back_vi":"Covenants như giới hạn debt mới, dividend restrictions và collateral requirements khiến cơ cấu vốn thực tế bị ràng buộc."},{"front_en":"Explain: Cyclicality and distress risk","back_vi":"Cyclical cash flows và high operating leverage khiến financial leverage nguy hiểm hơn, so optimal debt lower all else equal."},{"front_en":"Explain: Debt maturity matching","back_vi":"Lịch đáo hạn liabilities phải tương thích với vòng đời assets và expected cash flows; dùng funding ngắn hạn cho asset dài hạn tạo rollover risk."},{"front_en":"Explain: Trade-off incremental comparison","back_vi":"So sánh PV tax benefit và PV incremental expected distress (plus agency effects) tại các mức debt; chọn value cao nhất thay vì ratio thấp nhất."},{"front_en":"Explain: Credit spread feedback","back_vi":"Khi debt tăng, market credit spread và rd có thể tăng, re cũng tăng; phải cập nhật component costs nếu tính real-world WACC."},{"front_en":"Explain: Optimal versus target example","back_vi":"Hypothetical models có thể cho D*=80m nhưng board đặt target 60m để giữ rating/liquidity buffer; cả hai không mâu thuẫn."},{"front_en":"Explain: Distress loss isn't debt book amount","back_vi":"Expected financial distress cost không tự bằng principal outstanding; nó là PV tổn thất kinh tế do distress relative to otherwise healthy firm."},{"front_en":"Explain: Corporate capital structure checklist","back_vi":"Nhìn tax capacity, asset collateral, volatility, coverage, credit rating, maturities, market access, agency/conflict và target policy trước khi kết luận."}]}],"version":"2.4","language":"Vietnamese teaching with English CFA terms and English practice","qa_status":"DETAILED_DRAFT_PENDING_INDEPENDENT_ACADEMIC_AUDIT"},{"module_id":"CFA26-03-07","module_title":"Business Models","subject":"Corporate Issuers","sources":"CFAI Corporate Issuers 2026, Kaplan Book1 2026, SAPP Corporate Slide 2026","los":[{"id":"CFA26-03-07-LOS01","letter":"7.a","title_en":"Key Features of Business Models","outcome_en":"describe key features of business models","overview_vi":"Phân tích một business model theo “who/what/where/how much”, value proposition, pricing strategy, customer segmentation, channels, key inputs và cost structure; kiểm tra tính nhất quán giữa lời kể của management và bằng chứng kinh doanh.","source":[{"id":"CFA Institute Curriculum 2026 — Corporate Issuers LM7","pages":"221–237 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading26","pages":"277–280 (physical PDF)"},{"id":"SAPP Corporate Issuers 2026 — Module7","pages":"290–309 (physical PDF)"}],"sections":[{"heading":"Business model definition","body":"Business model mô tả logic doanh nghiệp tạo và thu value: ai là customer, bán gì, đưa sản phẩm đến customer bằng cách nào, định giá ra sao, cần đầu vào gì và kiếm lợi nhuận thế nào.","trap":"A mission statement alone is not a business model."},{"heading":"Who: customer segments","body":"Xác định nhóm khách hàng mục tiêu theo geography, demographic, needs, preferences, behavior, price sensitivity và willingness to pay.","trap":"Total addressable market is not the same as reachable customer base."},{"heading":"Who: business versus consumer clients","body":"B2B customers thường là doanh nghiệp với chu kỳ procurement riêng; B2C bán cho end users; khác biệt tác động acquisition cost, pricing và retention.","trap":"Distribution route can differ even for similar product."},{"heading":"Customer segmentation","body":"Segmentation chia khách theo đặc điểm quan trọng để thiết kế sản phẩm, channel, pricing và marketing phù hợp.","trap":"Different segments may demand distinct unit economics."},{"heading":"Why: value proposition","body":"Value proposition là lý do customer chọn sản phẩm: price, quality, convenience, speed, brand, ecosystem, customization hoặc superior service.","trap":"Product description is not a demonstrated customer benefit."},{"heading":"What: products and services","body":"Phân tích hàng hóa hữu hình, service, digital access, software license hoặc bundled product; mỗi loại có gross margin và fixed costs khác nhau.","trap":"Categorization can be blended across offerings."},{"heading":"What: breadth and product differentiation","body":"Doanh nghiệp có thể bán standardized low-price mass-market items hoặc differentiated premium offerings; khả năng chuyển chi phí sang customer thường khác nhau.","trap":"Premium pricing does not automatically mean higher net profits."},{"heading":"Where: sales channels","body":"Channels có thể là direct sales, own stores, e-commerce, wholesale, distribution partner, broker, franchise hoặc marketplaces.","trap":"Different channels imply different revenue recognition and cost dynamics."},{"heading":"Direct-to-consumer channel","body":"DTC giúp kiểm soát trải nghiệm, data khách hàng và gross selling price, nhưng có chi phí fulfillment, marketing, salesforce, returns và customer support.","trap":"Direct sales is not cost-free."},{"heading":"Indirect distribution channel","body":"Reseller/distributor giúp reach market nhanh hơn và mở rộng quy mô nhưng issuer chia sẻ gross margin và hạn chế customer relationship direct.","trap":"Channel margin is compensation for functions performed."},{"heading":"Omnichannel strategies","body":"Kết hợp website, stores, distributor/franchise và mobile nhằm tiếp cận customers ở nhiều điểm chạm; phải quản lý giá, inventory và conflict.","trap":"Omnichannel can create cannibalization as well as reach."},{"heading":"How much: pricing model","body":"Pricing model mô tả phương thức khách hàng trả tiền: one-time unit price, subscriptions, usage-based fees, interest spreads, commissions, license hoặc maintenance.","trap":"Revenue is not necessarily equal to billed cash in a given period."},{"heading":"Cost-plus pricing","body":"Công ty cộng markup trên unit cost để tạo giá, thường dễ áp dụng cho products có cost minh bạch; competition và willingness-to-pay vẫn giới hạn mức giá.","trap":"Cost-plus doesn't guarantee demand."},{"heading":"Value-based pricing","body":"Đặt giá theo lợi ích và willingness to pay của customer thay vì chỉ unit cost; requires differentiated value.","trap":"High stated value proposition needs evidence."},{"heading":"Competitive/market pricing","body":"Với sản phẩm ít khác biệt và nhiều competitors, prices thường được cạnh tranh market xác lập; cost discipline trở nên then chốt.","trap":"Low prices may require volume and efficiency."},{"heading":"Dynamic pricing","body":"Giá có thể biến động theo time, demand, inventory capacity và segment như flights/hotels; kiểm tra pricing power và customer fairness.","trap":"Dynamic pricing is not a guaranteed profit increase."},{"heading":"Price discrimination","body":"Bán cùng/similar products với mức giá khác nhau cho groups/conditions dựa trên willingness to pay để tăng monetization, tùy luật và channel.","trap":"Different prices need not imply unlawful discrimination in all cases."},{"heading":"Bundling","body":"Kết hợp complementary products/services dưới một package price; có thể tăng uptake và customer convenience nhưng che yếu economics của từng component.","trap":"Package margin should be tested."},{"heading":"Razor-and-blade pricing","body":"Thiết bị nền bán giá thấp, sau đó kiếm lợi từ proprietary/repeat consumables; profitability phụ thuộc installed base và retention.","trap":"Generic compatible consumables can weaken the strategy."},{"heading":"Freemium and add-on pricing","body":"Basic version miễn phí/giá thấp để thu hút rồi monetization premium features; phải kiểm tra conversion, support burden và costs.","trap":"Free users are not necessarily profitable."},{"heading":"Penetration versus premium pricing","body":"Penetration đặt giá thấp tăng users/scale, premium dùng perceived differentiation; đánh đổi growth, margins và brand positioning.","trap":"Higher volumes do not always offset lower margins."},{"heading":"Subscription recurring revenue","body":"Khách trả theo kỳ để có quyền truy cập service/product, giúp forecast revenue nếu churn thấp; nhưng acquisition cost, renewal và retention rất quan trọng.","trap":"Recurring billing can coexist with high churn."},{"heading":"Pricing unit and quantity","body":"Một người dùng, chiếc xe, transaction, subscription seat hoặc GB data có thể là đơn vị charge; phải nhất quán volume và price.","trap":"Misreading the billing unit distorts revenue forecasts."},{"heading":"Key inputs and suppliers","body":"Business model cần raw materials, labor skills, logistics, intellectual property, data, capital equipment, distribution rights hoặc cloud services.","trap":"Critical suppliers may also be competitors."},{"heading":"Value chain positioning","body":"Vị trí trong supply chain (resource→manufacturer→distributor→retailer→consumer) ảnh hưởng margins, power, working capital và commodity exposure.","trap":"Revenue pass-through capacity differs by position."},{"heading":"Cost structure","body":"Fixed versus variable costs và economies of scale/scope quyết định operating leverage khi volume thay đổi.","trap":"Gross margin alone does not reveal fixed-cost risk."},{"heading":"Unit economics","body":"Phân tích price per unit, variable contribution, customer acquisition cost, service cost và lifetime value giúp đánh giá value capture.","trap":"Illustrative metrics depend on how company defines customers."},{"heading":"Customer acquisition and retention","body":"Growth có thể đến từ paid marketing, word-of-mouth, cross-sell hoặc network effects; retention determines how much value customer cohort contributes.","trap":"Customer count growth does not prove profitability."},{"heading":"Switching costs and competitive moats","body":"Integration, data portability, training, compatibility hoặc contracts có thể giảm churn nhưng cũng tạo customer backlash khi quá cao.","trap":"Switching cost is distinct from price differentiation."},{"heading":"Fixed-asset flexibility","body":"Leased production capacity có thể scale up/down nhanh hơn owned long-lived specialized equipment; elasticity in costs affects sensitivity to demand shocks.","trap":"Lease costs can still be fixed by contract."},{"heading":"Brand and intangible assets","body":"Brand, patents, expertise, software và data tạo differentiation nhưng đôi khi khó làm collateral và khó xác định value.","trap":"Intangibles require independent proof of returns."},{"heading":"Management narrative versus evidence","body":"Analyst đối chiếu model công ty công bố với cost/revenue segments, customer concentration, unit economics, suppliers, distribution contracts và competitors.","trap":"Promotional language may exaggerate addressable market."},{"heading":"Business model scenario analysis","body":"Xem chuyện gì xảy ra khi input prices tăng, competitor price giảm, demand shock hoặc key supplier ngưng: earnings sensitivity phụ thuộc actual model.","trap":"One forecast doesn't describe downside."},{"heading":"Execution and scalability","body":"Kế hoạch mở rộng phải xem capacity, supply constraints, demand, distribution, skilled workers và capital needs; revenue growth chưa đủ chứng minh scalability.","trap":"High growth may consume cash."},{"heading":"Balance-sheet and cash-flow implications","body":"Subscription thu tiền trước, retail tồn kho nhiều, banks có loans/deposits, software có intangible-heavy inputs; model liên quan risk và liquidity.","trap":"Accounting classification does not replace economic logic."},{"heading":"Key model checklist","body":"Hỏi WHO buys, WHAT value, WHERE channels, HOW priced, WHO supplies, unit economics, growth strategy, competition và risks trước khi forecast.","trap":"Compare to peers rather than management claims alone."}],"formulas":[{"name":"Business model matrix","expr":"WHO×WHAT×WHERE×HOW MUCH","meaning":"Khung bốn câu hỏi để đọc logic tạo và nhận value.","conditions":"Qualitative CFAI framework, not an arithmetic formula."},{"name":"Per-unit revenue","expr":"Revenue=price per unit×units sold","meaning":"Tách giá và volume khi phân tích doanh thu.","conditions":"Mix and rebates may alter real revenue."},{"name":"Gross margin","expr":"Gross margin=(Revenue−COGS)/Revenue","meaning":"Đo mức spread giữa selling price và direct accounting costs.","conditions":"COGS definitions relevant."},{"name":"Contribution margin","expr":"Contribution=Revenue−variable costs","meaning":"Phần còn lại sau biến phí dùng trang trải fixed costs.","conditions":"Operating cost classification required."},{"name":"Contribution margin ratio","expr":"(Revenue−VariableCosts)/Revenue","meaning":"Tỷ lệ đóng góp khi sales thay đổi.","conditions":"Relevant range, same period."},{"name":"Unit contribution","expr":"Unit contribution=unit selling price−unit variable cost","meaning":"Một unit có thể tạo bao nhiêu để cover fixed costs.","conditions":"Cannot ignore fixed costs for full profit."},{"name":"Break-even units","expr":"Fixed costs/unit contribution","meaning":"Số unit hòa vốn theo mô hình chi phí tuyến tính.","conditions":"Positive unit contribution."},{"name":"Markup on cost","expr":"Selling price=cost×(1+markup percentage)","meaning":"Giá từ cost-plus pricing.","conditions":"Markup differs from margin."},{"name":"Margin on sales","expr":"Gross margin=(price−cost)/price","meaning":"Đo margin trên doanh thu.","conditions":"Not same as markup on cost."},{"name":"Price elasticity sign","expr":"%ΔQuantity/%ΔPrice","meaning":"Xác định price sensitivity, thường âm cho demand downward-sloping.","conditions":"Holding other conditions fixed."},{"name":"Subscription revenue","expr":"Active paying subscribers×fee per period","meaning":"Revenue run-rate xấp xỉ nếu fee ổn định.","conditions":"Reflect churn, discounts, timing for actual revenue."},{"name":"Average revenue per user (ARPU)","expr":"Segment revenue/average active paying users","meaning":"Monetization per user.","conditions":"Use consistent population and period."},{"name":"Customer acquisition cost","expr":"CAC=sales+marketing spend/new acquired paying customers","meaning":"Minh họa cost thu hút một paying customer.","conditions":"Definition depends on firm metrics."},{"name":"Customer retention","expr":"Retention=customers remaining from cohort/customers at start","meaning":"Khả năng giữ customers.","conditions":"Exclude new additions in numerator."},{"name":"Customer churn rate","expr":"Churn=lost customers/start-of-period customer count","meaning":"Tỷ lệ rời bỏ.","conditions":"Approx 1−retention for cohort measure."},{"name":"Simple customer contribution","expr":"Lifetime contribution≈period contribution×expected periods","meaning":"Sơ đồ unit economics minh họa.","conditions":"Not full discounted customer LTV."},{"name":"Price increase revenue effect","expr":"Revenue_new=Price_old×(1+ΔP)×Units_old×(1+ΔQ)","meaning":"Kết hợp giá và lượng, không cộng đơn giản hai tỷ lệ lớn.","conditions":"Approx elasticity may derive quantity change."},{"name":"Operating profit simplified","expr":"EBIT=unit contribution×units−fixed operating costs","meaning":"Operating leverage trong simple product model.","conditions":"Constant price/unit variable costs."},{"name":"Sales mix revenues","expr":"Total revenue=Σ(price_i×units_i)","meaning":"Công ty đa sản phẩm theo danh mục.","conditions":"Currency/time same."},{"name":"Value capture test","expr":"Added customer value >? delivered costs and price","meaning":"Câu hỏi kinh tế: có tạo surplus đủ để giữ profit?","conditions":"Conceptual not specified CFAI calculation."},{"name":"Channel economics","expr":"Net revenue to issuer≈retail price−intermediary margin","meaning":"Cách minh họa indirect channel effect.","conditions":"Depends legal form and recognition."}],"examples":[{"question_en":"A product sells 10,000 units at $40. Estimate annual sales revenue.","answer":"$400,000","steps_vi":["Tính doanh thu bằng số lượng×đơn giá.","10.000×40=400.000 USD."],"check":"Exclude returns/discounts."},{"question_en":"A device sells for $50 and variable cost is $30. Calculate unit contribution.","answer":"$20 per unit","steps_vi":["Contribution của một unit=50−30.","Mỗi unit đóng góp 20 USD để trang trải fixed costs."],"check":"Fixed costs excluded."},{"question_en":"A manufacturer has fixed costs $120,000 and unit contribution $20. Break-even sales volume?","answer":"6,000 units","steps_vi":["Dùng break-even units=fixed cost/unit contribution.","120.000/20=6.000 sản phẩm."],"check":"Simple linear costs."},{"question_en":"A retailer's sales are $500,000 and COGS is $350,000. Gross margin?","answer":"30%","steps_vi":["Lợi nhuận gộp=500−350=150 nghìn USD.","Gross margin=150/500=30%."],"check":"Cost allocation matters."},{"question_en":"A unit costs $80 and firm applies a 25% markup on cost. Selling price?","answer":"$100","steps_vi":["Markup tính trên cost=80×25%=20.","Price=80+20=100 USD; không nhầm 25% sales margin."],"check":"Markup base."},{"question_en":"A supplier charges $100 and resale price is $125. Markup on cost?","answer":"25%","steps_vi":["Markup=25/100.","Kết quả 25%; gross margin sales=25/125=20%."],"check":"Markup differs from margin."},{"question_en":"A $20 service has 100,000 monthly paying users. Monthly revenue run rate?","answer":"$2 million","steps_vi":["Doanh thu xấp xỉ fee×paid users.","20×100.000=2.000.000 USD/tháng."],"check":"Before discounts/churn."},{"question_en":"A SaaS firm generates $12m ARR from 10,000 paying accounts. Annual revenue per account?","answer":"$1,200","steps_vi":["Annual revenue/account=12.000.000/10.000.","ARPU năm=1.200 USD."],"check":"Same user definition."},{"question_en":"A company spends $900,000 to acquire 3,000 new customers. Average CAC?","answer":"$300","steps_vi":["Cost acquisition chia số paying acquired customers.","900.000/3.000=300 USD/customer."],"check":"Cost definitions vary."},{"question_en":"Of 10,000 initial users, 8,500 remain at year-end. Cohort retention?","answer":"85%","steps_vi":["Retention=8.500/10.000.","Tỷ lệ giữ khách=85%, tương đương churn cohort 15%."],"check":"Not net customer growth."},{"question_en":"A firm starts with 5,000 subscribers, loses 600, and gains 900. Starting-cohort churn?","answer":"12%","steps_vi":["Chỉ lấy subscribers mất từ base đầu kỳ.","Churn=600/5.000=12%, không dùng net change 300."],"check":"New subscriptions not in numerator."},{"question_en":"A company raises price by 5%, quantity falls by 2%. Approx revenue change?","answer":"+2.9%","steps_vi":["Factor revenue=(1,05×0,98)−1.","1,029−1=+2,9%; không phải cộng đúng 3%."],"check":"Cross-product included."},{"question_en":"A software business has revenue $8m and variable cost $2m. Contribution margin ratio?","answer":"75%","steps_vi":["Contribution=8−2=6m.","Contribution margin ratio=6/8=75%.","Cần giải thích kết quả theo đơn vị kinh tế và điều kiện của bài."],"check":"Fixed expenses follow."},{"question_en":"A marketplace handles $100m gross transaction value and keeps 8% fees. Gross fee revenue?","answer":"$8 million","steps_vi":["Fee receipts xấp xỉ GMV×take rate.","100×8%=8 triệu USD, trước refund/fee concessions."],"check":"GMV is not issuer revenue."},{"question_en":"A manufacturer sells 2,000 units at $70 with variable cost $45/unit and fixed costs $30,000. EBIT?","answer":"$20,000","steps_vi":["Total contribution=(70−45)×2.000=50.000 USD.","EBIT=50.000−30.000=20.000 USD.","Cần giải thích kết quả theo đơn vị kinh tế và điều kiện của bài."],"check":"Simple linear model."},{"question_en":"A retail product has cost $70 and price $100. Gross margin as a % of sales?","answer":"30%","steps_vi":["Sales margin=(100−70)/100.","Gross margin 30%, cost markup=30/70≈42,86%.","Cần giải thích kết quả theo đơn vị kinh tế và điều kiện của bài."],"check":"Margin denominator."},{"question_en":"A pricing model shifts from $100 one-off fee to $12 monthly subscription. Revenue in 12 months from a retained customer?","answer":"$144","steps_vi":["Subscription annual revenue=12×12 USD.","Tổng 144 USD nếu khách giữ đầy đủ 12 tháng."],"check":"Before acquisition/support costs."},{"question_en":"A company charges 200,000 transactions at $0.75 each. Revenue?","answer":"$150,000","steps_vi":["Transaction fee×count.","200.000×0,75=150.000 USD.","Cần giải thích kết quả theo đơn vị kinh tế và điều kiện của bài."],"check":"Take-rate billing."},{"question_en":"A firm sells two products: 1,000 at $50 and 2,000 at $20. Total revenue?","answer":"$90,000","steps_vi":["Product A=50.000; B=40.000.","Tổng 90.000 USD; cần đánh giá mix khi lợi nhuận biên khác nhau."],"check":"Count both SKUs."},{"question_en":"A service provider increases paid seats from 8,000 to 9,000 at $100/year. Annual recurring revenue increase?","answer":"$100,000","steps_vi":["Incremental seats=1.000.","1.000×100=100.000 USD nếu fee không đổi."],"check":"Churn and promotions ignored."},{"question_en":"A wholesaler purchases goods for $60 and sells to retailer for $75. Gross unit spread?","answer":"$15","steps_vi":["Gross spread=75−60.","15 USD, chưa trừ transportation hoặc overhead."],"check":"Not operating profit."},{"question_en":"A firm has $1m marketing expenditure and acquires 2,500 paying users. CAC?","answer":"$400","steps_vi":["CAC=1.000.000/2.500.","400 USD/user theo định nghĩa chi phí đã cho."],"check":"Attribution assumptions."},{"question_en":"A firm sells 50,000 units at price $20 then price $22 with volume 48,000. Change in revenue?","answer":"+5.6%","steps_vi":["Old revenue=1.000.000 USD, new=1.056.000 USD.","Doanh thu tăng 5,6% dù volume giảm."],"check":"Price and volume jointly."},{"question_en":"A direct retailer earns $100 sales but spends $15 fulfillment and $10 acquisition cost. Contribution before goods costs?","answer":"$75","steps_vi":["Revenue less specified channel costs=100−15−10.","Còn 75 USD trước COGS và các chi phí khác."],"check":"Not full EBIT."},{"question_en":"One customer contributes $20 each quarter over 12 quarters with no discounting. Illustrative undiscounted contribution?","answer":"$240","steps_vi":["Simple contribution=20×12.","Tổng 240 USD chưa discount, churn risk hay acquisition cost."],"check":"Illustrative LTV only."},{"question_en":"A subscription platform has 15,000 users each paying $8/month. Monthly recurring revenue?","answer":"$120,000","steps_vi":["Tính MRR=15.000×8 USD.","120.000 USD/tháng trước churn và chiết khấu."],"check":"Simplified MRR."}],"questions":[{"stem_en":"What is the best description of a business model?","options":["How a company creates, delivers, and captures value.","Only its capital structure.","A list of management slogans only."],"correct":0,"why_vi":"Business model cần nêu khách hàng, sản phẩm, channel, pricing và inputs.","trap_vi":"Financial structure is separate."},{"stem_en":"In the WHO–WHAT–WHERE–HOW MUCH framework, WHO refers mainly to:","options":["Depreciation methods.","Customer segments and target markets.","Corporate borrowing rates."],"correct":1,"why_vi":"WHO là khách hàng nào có nhu cầu và willingness-to-pay phù hợp.","trap_vi":"Audience definition."},{"stem_en":"The WHAT in business model analysis is primarily:","options":["Only the company's office locations.","Government bond yields.","The products/services offered and their value proposition."],"correct":2,"why_vi":"WHAT thể hiện products/services và value proposition với khách hàng.","trap_vi":"Why buy matters."},{"stem_en":"The WHERE element most directly addresses:","options":["Distribution channels used to reach customers.","Marginal corporate tax rate.","Input commodity price level alone."],"correct":0,"why_vi":"WHERE là channels như online, own-store, wholesale và franchise.","trap_vi":"Not necessarily geography only."},{"stem_en":"HOW MUCH is most closely related to:","options":["Historical coupon debt.","Pricing model and customer charges.","Number of employees."],"correct":1,"why_vi":"HOW MUCH mô tả giá và đơn vị tính phí như monthly fee, per unit hoặc commission.","trap_vi":"Pricing and billing."},{"stem_en":"Customer segmentation is useful because it helps the firm:","options":["Eliminate cost of goods sold.","Avoid identifying specific users.","Tailor offerings, prices, and channels to groups."],"correct":2,"why_vi":"Segmentation giúp tailor offer/price/channel theo nhu cầu và sức mua.","trap_vi":"Segments have different economics."},{"stem_en":"A value proposition is best characterized as:","options":["Why customers prefer the product over alternatives.","A list of outstanding shares only.","The fact that an asset is tangible."],"correct":0,"why_vi":"Value proposition thể hiện lợi ích thực tế đối với buyer: price, quality, convenience, service.","trap_vi":"Must be supported."},{"stem_en":"A firm with high-volume undifferentiated products is most likely to compete on:","options":["Intentionally low production output.","Cost efficiency and pricing.","Complex customer-only customization."],"correct":1,"why_vi":"Standardized product cạnh tranh bằng price và cost control.","trap_vi":"Low unit margins require scale."},{"stem_en":"The principal benefit of direct-to-consumer sales is:","options":["Automatic elimination of returns.","Guaranteed no marketing expenditure.","Closer customer relationship and channel control."],"correct":2,"why_vi":"DTC kiểm soát relationship, data và experience nhưng chịu acquisition/fulfillment cost.","trap_vi":"Cost tradeoff."},{"stem_en":"Which feature is most directly associated with indirect distribution?","options":["Selling through wholesalers or resellers.","No intermediaries involved.","Complete ownership of every store."],"correct":0,"why_vi":"Indirect channels dựa vào intermediaries để reach market và thường chia sẻ margin.","trap_vi":"Channel margin."},{"stem_en":"A company uses its own store, website, and wholesale partners. This is:","options":["A pure risk-free investment.","An omnichannel approach.","Only a single-channel model."],"correct":1,"why_vi":"Omnichannel kết hợp nhiều points of customer contact.","trap_vi":"Conflict management required."},{"stem_en":"In a razor-and-blade model, earnings often depend heavily on:","options":["Zero customer switching costs always.","One-off sale of low-margin equipment only.","Repeat purchases of consumables."],"correct":2,"why_vi":"Giá thiết bị nền có thể thấp, profit nằm ở consumables mua lặp lại.","trap_vi":"Compatible alternatives threaten margin."},{"stem_en":"Which pricing strategy most directly exploits differences in willingness to pay across customer segments?","options":["Price discrimination.","Uniform below-cost pricing for all by law.","An unvarying tax rate."],"correct":0,"why_vi":"Price discrimination đặt mức giá khác nhau theo segment/volume/time phù hợp nhu cầu.","trap_vi":"Legal/context considerations."},{"stem_en":"A company uses cost-plus pricing on $80 cost at 25% markup. Selling price equals:","options":["$105.","$100.","$106.67."],"correct":1,"why_vi":"80×1,25=100 USD; markup dựa cost chứ không phải sale price.","trap_vi":"Markup vs margin."},{"stem_en":"A product costs $70 and sells for $100. Gross margin as % of sales is:","options":["70%.","42.86%.","30%."],"correct":2,"why_vi":"(100−70)/100=30%; markup on cost là 42,86%.","trap_vi":"Denominator matters."},{"stem_en":"A SaaS company bills 20,000 subscribers $10 each month. Monthly run-rate revenue is:","options":["$200,000.","$20,000.","$2,000,000."],"correct":0,"why_vi":"20.000×10=200.000 USD/tháng, giả định fee đồng nhất.","trap_vi":"Churn ignored."},{"stem_en":"A firm spent $600,000 acquiring 2,000 paying customers. CAC is:","options":["$1,200.","$300.","$600."],"correct":1,"why_vi":"CAC=600.000/2.000=300 USD/customer. Giải thích lựa chọn dựa trên loại hình kinh doanh và đơn vị tạo doanh thu.","trap_vi":"Define acquired customer."},{"stem_en":"A high gross margin with high fixed selling expenses means:","options":["Fixed costs are necessarily zero.","Net profitability is guaranteed.","Operating profit can still be low or negative."],"correct":2,"why_vi":"Fixed overhead và marketing có thể ăn hết gross profit.","trap_vi":"Gross margin not EBIT."},{"stem_en":"If 8,500 of an opening 10,000 customers remain, retention is:","options":["85%.","15%.","1.176×."],"correct":0,"why_vi":"Retention=8.500/10.000=85%. Giải thích lựa chọn dựa trên loại hình kinh doanh và đơn vị tạo doanh thu.","trap_vi":"New customers excluded."},{"stem_en":"A company seeks early scale via low prices and thin margins. Which pricing is most consistent?","options":["Charging by debt spread.","Penetration pricing.","Premium skimming only."],"correct":1,"why_vi":"Penetration pricing ưu tiên scale/market share ban đầu dù margin thấp.","trap_vi":"Need unit economics."},{"stem_en":"An analyst should respond to a management claim of a huge total market by:","options":["Ignoring unit economics.","Accepting the claim without evidence.","Testing customer segments, channels, actual ability to reach/pay."],"correct":2,"why_vi":"Market lớn không có nghĩa issuer nắm được demand; kiểm tra thực chứng.","trap_vi":"Management narrative bias."},{"stem_en":"Which is a key supplier risk in a technology-enabled model?","options":["Reliance on a difficult-to-switch cloud infrastructure provider.","Unlimited free cloud capacity.","No input dependencies."],"correct":0,"why_vi":"Supplier concentration/cloud lock-in có thể gây disruption hoặc pricing power của supplier.","trap_vi":"Risk even when supplier also competitor."},{"stem_en":"In a multi-product business, total revenue is:","options":["Always identical to gross transaction value.","The sum of individual product prices times quantities.","Average selling price without volume."],"correct":1,"why_vi":"Tổng ΣP_i×Q_i, revenue recognition tùy hoạt động.","trap_vi":"Mix changes matter."},{"stem_en":"A company raises prices 5% while volume declines 2%. Revenue changes by approximately:","options":["+7.0%.","−3.0%.","+2.9%."],"correct":2,"why_vi":"Revenue factor=1,05×0,98=1,029. Giải thích lựa chọn dựa trên loại hình kinh doanh và đơn vị tạo doanh thu.","trap_vi":"Cross term."},{"stem_en":"What most directly creates high operating leverage?","options":["A high proportion of fixed operating costs.","Purely variable costs and no fixed cost.","No sales volume changes."],"correct":0,"why_vi":"Fixed operating costs khiến EBIT nhạy với changes in revenue.","trap_vi":"Not same as financial leverage."},{"stem_en":"Which channel is most directly associated with retailers selling directly to end users?","options":["Natural resource extraction only.","Physical stores and digital storefronts.","Interbank loan contracts."],"correct":1,"why_vi":"Retail channels tiếp xúc end customers, qua store và e-commerce.","trap_vi":"Goods sourcing another component."},{"stem_en":"A business earns $75 selling merchandise bought for $60. Gross unit spread equals:","options":["$135.","$60.","$15."],"correct":2,"why_vi":"75−60=15 USD trước other costs.","trap_vi":"Gross spread only."},{"stem_en":"For a recurring-subscription model, which metric is especially informative?","options":["Subscriber retention and churn.","Debt issued in prior decades.","Warehouse floor area alone."],"correct":0,"why_vi":"Retention/churn quyết định recurring revenue durability.","trap_vi":"Counts without paid conversion misleading."},{"stem_en":"A firm charges $12 monthly for 12 months to one retained subscriber. Revenue is:","options":["$1,200.","$144.","$12."],"correct":1,"why_vi":"12×12=144 USD nếu customer giữ cả năm.","trap_vi":"Before costs."},{"stem_en":"A firm sells a proprietary machine cheaply but sells high-margin replacements repeatedly. Which model is most consistent?","options":["Market price parity for generic goods.","Broker model only.","Razor-and-blade pricing."],"correct":2,"why_vi":"Consumables repeat purchases là nơi monetization chính.","trap_vi":"Installed base critical."},{"stem_en":"When reviewing a business model, analysts should NOT rely solely on:","options":["Management's promotional description.","Source data and observable segment metrics.","Supplier contracts and customer concentration."],"correct":0,"why_vi":"Analyst đối chiếu statement với thực tế, đối thủ, channels và chi phí.","trap_vi":"Avoid wishful projections."},{"stem_en":"A manufacturer sells 2,000 units at $70, incurs $45 variable costs/unit and $30,000 fixed costs. EBIT equals:","options":["$140,000.","$20,000.","$50,000."],"correct":1,"why_vi":"Contribution=2.000×25=50.000, EBIT=50.000−30.000=20.000 USD. Giải thích lựa chọn dựa trên loại hình kinh doanh và đơn vị tạo doanh thu.","trap_vi":"Linear cost assumptions."},{"stem_en":"A user community helps product users solve each other's issues, reducing issuer support costs. This is:","options":["A tax deduction for interest.","An issuer's debt maturity schedule.","A crowdsourcing / user community benefit."],"correct":2,"why_vi":"User community tạo shared knowledge và có thể giảm support cost.","trap_vi":"Moderation still needed."},{"stem_en":"A company uses different price points for business and student segments based on demand. It is applying:","options":["Segmented pricing / price discrimination.","Cost of debt estimation.","Debt-to-equity analysis."],"correct":0,"why_vi":"Pricing theo willingness-to-pay khác nhau giữa segments.","trap_vi":"Compliance/context matters."},{"stem_en":"The most valuable follow-up question about a new DTC channel is:","options":["Is the company's bank loan floating-rate?","What are its acquisition and fulfillment costs relative to revenue?","Does the firm have enough common shares?"],"correct":1,"why_vi":"DTC kiểm soát customer nhưng phát sinh marketing/returns/fulfillment costs.","trap_vi":"Analyze net margin."},{"stem_en":"In assessing the firm's scalability, the best focus is:","options":["The corporate logo color.","Only growth in homepage traffic.","Unit economics, capacity, required inputs, and channel cost behavior."],"correct":2,"why_vi":"Scale chỉ có giá trị nếu growth có economics phù hợp và không bị inputs hạn chế.","trap_vi":"Profitable unit scale."},{"stem_en":"An issuer with a long sales channel involving several distributors is most likely to:","options":["Share margin with intermediaries.","Avoid any channel margins.","Automatically earn retail price on every unit."],"correct":0,"why_vi":"Các distributor nhận compensation cho inventory, reach và logistics.","trap_vi":"Revenue accounting may differ."},{"stem_en":"If the fixed costs are $120,000 and unit contribution is $20, break-even units equal:","options":["140,000.","6,000.","2,400."],"correct":1,"why_vi":"120.000/20=6.000 units; trước đó EBIT=0.","trap_vi":"Linear cost model."},{"stem_en":"A marketplace's gross transaction value is $100m and take rate is 8%. Approx fee revenue?","options":["$92m.","$100m.","$8m."],"correct":2,"why_vi":"100m×8%=8m là phí issuer nhận, không phải GMV toàn bộ.","trap_vi":"Gross versus net platform accounting."},{"stem_en":"A firm has 5,000 starting customers, 600 cancellations and 900 newly acquired. Opening cohort churn is:","options":["12%.","6%.","18%."],"correct":0,"why_vi":"Churn cohort=600/5.000=12%, không dùng net additions.","trap_vi":"Consistent denominator."}],"cards":[{"front_en":"Explain: Business model definition","back_vi":"Business model mô tả logic doanh nghiệp tạo và thu value: ai là customer, bán gì, đưa sản phẩm đến customer bằng cách nào, định giá ra sao, cần đầu vào gì và kiếm lợi nhuận thế nào."},{"front_en":"Explain: Who: customer segments","back_vi":"Xác định nhóm khách hàng mục tiêu theo geography, demographic, needs, preferences, behavior, price sensitivity và willingness to pay."},{"front_en":"Explain: Who: business versus consumer clients","back_vi":"B2B customers thường là doanh nghiệp với chu kỳ procurement riêng; B2C bán cho end users; khác biệt tác động acquisition cost, pricing và retention."},{"front_en":"Explain: Customer segmentation","back_vi":"Segmentation chia khách theo đặc điểm quan trọng để thiết kế sản phẩm, channel, pricing và marketing phù hợp."},{"front_en":"Explain: Why: value proposition","back_vi":"Value proposition là lý do customer chọn sản phẩm: price, quality, convenience, speed, brand, ecosystem, customization hoặc superior service."},{"front_en":"Explain: What: products and services","back_vi":"Phân tích hàng hóa hữu hình, service, digital access, software license hoặc bundled product; mỗi loại có gross margin và fixed costs khác nhau."},{"front_en":"Explain: What: breadth and product differentiation","back_vi":"Doanh nghiệp có thể bán standardized low-price mass-market items hoặc differentiated premium offerings; khả năng chuyển chi phí sang customer thường khác nhau."},{"front_en":"Explain: Where: sales channels","back_vi":"Channels có thể là direct sales, own stores, e-commerce, wholesale, distribution partner, broker, franchise hoặc marketplaces."},{"front_en":"Explain: Direct-to-consumer channel","back_vi":"DTC giúp kiểm soát trải nghiệm, data khách hàng và gross selling price, nhưng có chi phí fulfillment, marketing, salesforce, returns và customer support."},{"front_en":"Explain: Indirect distribution channel","back_vi":"Reseller/distributor giúp reach market nhanh hơn và mở rộng quy mô nhưng issuer chia sẻ gross margin và hạn chế customer relationship direct."},{"front_en":"Explain: Omnichannel strategies","back_vi":"Kết hợp website, stores, distributor/franchise và mobile nhằm tiếp cận customers ở nhiều điểm chạm; phải quản lý giá, inventory và conflict."},{"front_en":"Explain: How much: pricing model","back_vi":"Pricing model mô tả phương thức khách hàng trả tiền: one-time unit price, subscriptions, usage-based fees, interest spreads, commissions, license hoặc maintenance."},{"front_en":"Explain: Cost-plus pricing","back_vi":"Công ty cộng markup trên unit cost để tạo giá, thường dễ áp dụng cho products có cost minh bạch; competition và willingness-to-pay vẫn giới hạn mức giá."},{"front_en":"Explain: Value-based pricing","back_vi":"Đặt giá theo lợi ích và willingness to pay của customer thay vì chỉ unit cost; requires differentiated value."},{"front_en":"Explain: Competitive/market pricing","back_vi":"Với sản phẩm ít khác biệt và nhiều competitors, prices thường được cạnh tranh market xác lập; cost discipline trở nên then chốt."},{"front_en":"Explain: Dynamic pricing","back_vi":"Giá có thể biến động theo time, demand, inventory capacity và segment như flights/hotels; kiểm tra pricing power và customer fairness."},{"front_en":"Explain: Price discrimination","back_vi":"Bán cùng/similar products với mức giá khác nhau cho groups/conditions dựa trên willingness to pay để tăng monetization, tùy luật và channel."},{"front_en":"Explain: Bundling","back_vi":"Kết hợp complementary products/services dưới một package price; có thể tăng uptake và customer convenience nhưng che yếu economics của từng component."},{"front_en":"Explain: Razor-and-blade pricing","back_vi":"Thiết bị nền bán giá thấp, sau đó kiếm lợi từ proprietary/repeat consumables; profitability phụ thuộc installed base và retention."},{"front_en":"Explain: Freemium and add-on pricing","back_vi":"Basic version miễn phí/giá thấp để thu hút rồi monetization premium features; phải kiểm tra conversion, support burden và costs."},{"front_en":"Explain: Penetration versus premium pricing","back_vi":"Penetration đặt giá thấp tăng users/scale, premium dùng perceived differentiation; đánh đổi growth, margins và brand positioning."},{"front_en":"Explain: Subscription recurring revenue","back_vi":"Khách trả theo kỳ để có quyền truy cập service/product, giúp forecast revenue nếu churn thấp; nhưng acquisition cost, renewal và retention rất quan trọng."},{"front_en":"Explain: Pricing unit and quantity","back_vi":"Một người dùng, chiếc xe, transaction, subscription seat hoặc GB data có thể là đơn vị charge; phải nhất quán volume và price."},{"front_en":"Explain: Key inputs and suppliers","back_vi":"Business model cần raw materials, labor skills, logistics, intellectual property, data, capital equipment, distribution rights hoặc cloud services."},{"front_en":"Explain: Value chain positioning","back_vi":"Vị trí trong supply chain (resource→manufacturer→distributor→retailer→consumer) ảnh hưởng margins, power, working capital và commodity exposure."},{"front_en":"Explain: Cost structure","back_vi":"Fixed versus variable costs và economies of scale/scope quyết định operating leverage khi volume thay đổi."},{"front_en":"Explain: Unit economics","back_vi":"Phân tích price per unit, variable contribution, customer acquisition cost, service cost và lifetime value giúp đánh giá value capture."},{"front_en":"Explain: Customer acquisition and retention","back_vi":"Growth có thể đến từ paid marketing, word-of-mouth, cross-sell hoặc network effects; retention determines how much value customer cohort contributes."},{"front_en":"Explain: Switching costs and competitive moats","back_vi":"Integration, data portability, training, compatibility hoặc contracts có thể giảm churn nhưng cũng tạo customer backlash khi quá cao."},{"front_en":"Explain: Fixed-asset flexibility","back_vi":"Leased production capacity có thể scale up/down nhanh hơn owned long-lived specialized equipment; elasticity in costs affects sensitivity to demand shocks."},{"front_en":"Explain: Brand and intangible assets","back_vi":"Brand, patents, expertise, software và data tạo differentiation nhưng đôi khi khó làm collateral và khó xác định value."},{"front_en":"Explain: Management narrative versus evidence","back_vi":"Analyst đối chiếu model công ty công bố với cost/revenue segments, customer concentration, unit economics, suppliers, distribution contracts và competitors."},{"front_en":"Explain: Business model scenario analysis","back_vi":"Xem chuyện gì xảy ra khi input prices tăng, competitor price giảm, demand shock hoặc key supplier ngưng: earnings sensitivity phụ thuộc actual model."},{"front_en":"Explain: Execution and scalability","back_vi":"Kế hoạch mở rộng phải xem capacity, supply constraints, demand, distribution, skilled workers và capital needs; revenue growth chưa đủ chứng minh scalability."},{"front_en":"Explain: Balance-sheet and cash-flow implications","back_vi":"Subscription thu tiền trước, retail tồn kho nhiều, banks có loans/deposits, software có intangible-heavy inputs; model liên quan risk và liquidity."},{"front_en":"Explain: Key model checklist","back_vi":"Hỏi WHO buys, WHAT value, WHERE channels, HOW priced, WHO supplies, unit economics, growth strategy, competition và risks trước khi forecast."}]},{"id":"CFA26-03-07-LOS02","letter":"7.b","title_en":"Types of Business Models","outcome_en":"describe various types of business models","overview_vi":"Nhận dạng 8 mô hình conventional của CFAI, các hybrid/variations, business model innovation, digital network effects one-sided/two-sided, platforms, franchises và rủi ro value chain, supplier, channel.","source":[{"id":"CFA Institute Curriculum 2026 — Corporate Issuers LM7","pages":"238–250 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading26","pages":"277–280 (physical PDF)"},{"id":"SAPP Corporate Issuers 2026 — Module7","pages":"309–322 (physical PDF)"}],"sections":[{"heading":"Eight conventional model families","body":"CFAI phân loại 8 nhóm conventional: natural resource producer, manufacturer, distributor, retailer, broker, bank, service producer, software/services.","trap":"Many issuers blend categories rather than fit a single label."},{"heading":"Natural resource producer","body":"Khai thác hoặc sản xuất raw natural resources, bán cho refiners/distributors dựa trên spot/forward contracts; quyền khai thác, capex và commodity pricing quan trọng.","trap":"Exposure to commodity prices can dominate margins."},{"heading":"Manufacturer","body":"Biến raw materials thành finished goods; bán cho distributor hoặc end users, cần equipment, labor, design, IP và procurement.","trap":"A manufacturer can outsource physical production."},{"heading":"Distributor","body":"Mua hàng từ manufacturers và vận chuyển/lưu trữ/cung ứng cho retailers; earnings thường đến từ spreads, logistics fees và scale efficiency.","trap":"Distribution is not the same as final customer retail."},{"heading":"Retailer","body":"Bán finished goods trực tiếp đến end users qua stores/digital storefront, kiếm markup và đôi khi membership/service fees.","trap":"Inventory, returns, rent and logistics can drive profit."},{"heading":"Broker","body":"Kết nối buyers/sellers trong deals, earning commission/listing/transaction fees; network of participants, trust và liquidity then chốt.","trap":"Trading volume need not equal issuer revenue."},{"heading":"Bank","body":"Huy động funds/deposits và cung cấp loans/leases, earning interest spread/fees; balance-sheet risk, credit quality, regulation và funding costs rất quan trọng.","trap":"Revenue and leverage metrics differ from nonfinancial firms."},{"heading":"Service producer","body":"Cung cấp expertise/time/service outcomes, kiếm service fees; quan hệ khách, staff utilization, specialization ảnh hưởng revenue/expenses.","trap":"Labor often major input."},{"heading":"Software/services","body":"Bán software licenses, subscription/SaaS, maintenance/support qua direct/digital partners, cần technical expertise, platform và distribution.","trap":"Initial development cost differs from marginal delivery cost."},{"heading":"Private-label or contract manufacturing","body":"Supplier làm sản phẩm theo thiết kế/brand của client; client tập trung R&D/marketing, producer phụ thuộc buyer contracts và utilization.","trap":"Brand owner may not own factories."},{"heading":"Value-added reseller","body":"Distributor/reseller bổ sung installation, customization, service hoặc support, nâng revenue per transaction nhưng cần skilled labor.","trap":"Adding service changes cost structure."},{"heading":"Franchising","body":"Franchisor cấp brand/process rights cho franchisee, nhận royalties/fees; franchisee thường gánh capex, operation và một phần địa phương risk.","trap":"Franchise royalties are not all franchisee end-sales."},{"heading":"Licensing model","body":"Chủ sở hữu IP cho đối tác sử dụng quyền, thường nhận royalty/fee; khác direct manufacturing hoặc franchising full operating system.","trap":"Royalty rates and exclusivity affect revenues."},{"heading":"Asset-light operating model","body":"Doanh nghiệp outsource production/physical assets, giữ brand/software/customer relationship; cần kiểm tra supplier concentration và quality control.","trap":"Low owned assets can conceal contractual risk."},{"heading":"Asset-heavy operating model","body":"Issuer trực tiếp sở hữu hotels, factories, utilities hoặc fleets, chịu depreciation/maintenance capex và fixed costs; có control assets cao hơn.","trap":"Asset ownership creates operating leverage."},{"heading":"Business model innovation","body":"Thay đổi cách phục vụ khách, channel, pricing hoặc cost structure, có thể xảy ra ngay cả khi underlying technology không mới.","trap":"Product innovation and business model innovation are distinct."},{"heading":"Software-as-a-service (SaaS)","body":"Chuyển từ upfront perpetual licenses sang recurring access fees, đòi hỏi retention, cloud reliability, product upgrades và customer success.","trap":"Recurring revenue can still be unprofitable due acquisition/support."},{"heading":"Low-cost airline innovation","body":"Điểm then chốt là no-frills service, point-to-point flights, standardized operations, low fares và digital distribution; cost structure khác full-service carriers.","trap":"Low price itself is not a sustainable model without cost advantage."},{"heading":"Discount brokerage innovation","body":"Direct/digital channels và low commissions, self-service replace branch-based full advice; economics từ scale, order flow, spreads hoặc subscriptions tùy model.","trap":"Free-to-user services may monetize differently."},{"heading":"E-commerce model innovation","body":"Online marketplace/retailer giảm geographic store constraints nhưng tăng need for fulfillment, returns, marketing và cybersecurity.","trap":"Digital channel does not abolish logistics."},{"heading":"Network effects concept","body":"Giá trị mạng cho từng participant tăng khi số users (hoặc opposite-side users) tăng; một barrier to entry nếu interactions đủ hữu ích.","trap":"Mere user-count growth is not proof of valuable network effects."},{"heading":"One-sided network effects","body":"Một nhóm users tạo value cho nhau, ví dụ communication/peer-to-peer network; key metric là connected user activity.","trap":"One-sided network is distinct from one-sided pricing."},{"heading":"Two-sided/multi-sided platforms","body":"Kết nối hai hoặc nhiều nhóm như buyers–sellers, riders–drivers, cardholders–merchants; tăng một side có thể thu hút side kia.","trap":"Cross-side interactions must actually create value."},{"heading":"Cross-side network effect","body":"More merchants attract customers, more customers attract merchants; network quality có thể bão hòa hoặc xấu đi nếu congestion/fraud.","trap":"Price subsidies can help launch a platform."},{"heading":"Platform pricing and take rate","body":"Một side có thể dùng miễn phí để tăng engagement, side kia trả commission/listing fee; gross merchandise value khác recognized platform fee revenue.","trap":"Revenue recognition depends on principal versus agent status."},{"heading":"Crowdsourcing community","body":"Users đóng góp reviews, photos, software mods hoặc advice, tăng product attractiveness và giảm 일부 content/support costs, nhưng phải kiểm duyệt chất lượng.","trap":"A community needs trust and moderation."},{"heading":"Sharing economy models","body":"Nền tảng matching unused assets/capacity với users, thường asset ownership nằm ngoài platform; trust, verification, regulatory costs và liquidity quan trọng.","trap":"Asset-light platform still faces reputation risk."},{"heading":"Hotel platform evolution","body":"Hotels từ single-site sang brands/franchises, online booking platforms và home-sharing; ownership, franchise, bookings và commissions ảnh hưởng financial statements khác nhau.","trap":"Gross bookings are not necessarily platform revenue."},{"heading":"Supply chain shock exposure","body":"Raw resource producer có thể hưởng tăng commodity price, manufacturer chịu input-cost pressure, distributors/retailers tùy pass-through/competition.","trap":"Outcome depends hedges, contracts and demand elasticity."},{"heading":"Distribution bargaining power","body":"Large retailers có thể ép supplier margins; manufacturers có branded differentiated goods thường pass-through tốt hơn commoditized products.","trap":"Contract length modifies timing."},{"heading":"Scale and scope economies","body":"Unit costs có thể giảm nhờ volume, shared logistics/data/software; economies of scope kết hợp products/services dưới cùng inputs.","trap":"Scale does not guarantee better network quality."},{"heading":"Network defensibility and switching costs","body":"High user liquidity, data network effects, reputation và integrations có thể bảo vệ platform; analyst cần xem multi-homing, competition and fees.","trap":"Users can join multiple platforms at low costs."},{"heading":"Winner-take-most caveat","body":"Network effect markets đôi khi tập trung vì one platform reaches liquidity threshold; nhưng regulation, multi-homing, niche product variation hạn chế monopoly.","trap":"Network effects don't imply perpetual monopoly."},{"heading":"Conventional versus innovative mix","body":"Một company có thể vừa bán products trực tiếp vừa vận hành marketplace và licensing; phân tích revenue streams độc lập tránh nhãn dán đơn giản.","trap":"Classify by economics, not buzzwords."},{"heading":"Business model risk and profitability","body":"Đánh giá customer acquisition, pricing power, channel economics, fixed inputs, supplier concentration, technology disruption và cash conversion.","trap":"No business model is risk free."},{"heading":"Regulatory and trust dependence","body":"Banking, travel, healthcare và platforms phụ thuộc compliance và user trust; network scale lớn cũng có systemic/cybersecurity risks.","trap":"Regulation can shape value proposition."},{"heading":"Analyst classification checklist","body":"So sánh WHO/WHAT/WHERE/PRICE/INPUTS của issuer với conventional model; xác định hybrid, network effects, monetization và khả năng duy trì profit.","trap":"Source document descriptions need independent corroboration."}],"formulas":[{"name":"Natural resource operating revenue","expr":"Revenue≈quantity produced×realized commodity price","meaning":"Giá bán actual hợp đồng có thể khác spot.","conditions":"Hedging, royalties and mix matter."},{"name":"Manufacturing gross profit","expr":"GP=finished goods sales−COGS","meaning":"Spread sau raw materials/direct production expense.","conditions":"Cost definitions and inventory method matter."},{"name":"Distributor gross spread","expr":"Gross spread=distribution resale revenue−procurement cost","meaning":"Phản ánh kinh tế distributor trước logistics/overhead.","conditions":"Pricing and freight accounting vary."},{"name":"Retailer gross margin","expr":"(Retail sales−COGS)/retail sales","meaning":"Phần chênh selling price so với purchase.","conditions":"Does not subtract rent/returns/marketing."},{"name":"Broker fee revenue","expr":"Fees≈transaction value×commission rate","meaning":"Broker kiếm commission trên transactions.","conditions":"Not equal to all value traded."},{"name":"Bank net interest income","expr":"Interest income−interest expense","meaning":"Nguồn kiếm tiền nền của bank cho credit/funding activities.","conditions":"Fees and provisions also matter."},{"name":"Service producer utilization","expr":"Billable hours/available professional hours","meaning":"Efficiency staffing-based services.","conditions":"Different compensation and pricing mix."},{"name":"Software recurring annual revenue","expr":"ARR≈paying subscriptions×annual contract price","meaning":"Recurring contracted/annualized value.","conditions":"Actual recognized revenue subject accounting policy."},{"name":"Franchise royalties","expr":"Royalty revenue≈franchisee gross sales×royalty %","meaning":"Chủ thương hiệu nhận fee trên hoạt động franchisee.","conditions":"Upfront fees excluded."},{"name":"Licensing revenue","expr":"Royalty≈licensed unit sales×royalty per unit","meaning":"Monetization IP licensing.","conditions":"Fixed minimum fees can change revenue."},{"name":"Asset turnover","expr":"Revenue/average assets","meaning":"Đánh giá capital intensity khi comparables phù hợp.","conditions":"Market conditions and accounting matter."},{"name":"Broker take rate","expr":"Fee revenue/gross transaction value","meaning":"Platform/intermediary monetization %.","conditions":"Gross value not issuer revenue."},{"name":"One-sided network size","expr":"Active connected users","meaning":"Metric for same-side user utility.","conditions":"Quantity is not quality; no universal formula."},{"name":"Cross-side coverage","expr":"Active buyers×available sellers (conceptual)","meaning":"Minh họa khả năng matching hai sides.","conditions":"Not a CFAI prescribed network formula."},{"name":"Two-sided fee monetization","expr":"Fee rev≈GMV×take rate","meaning":"Giá trị giao dịch chuyển thành platform revenue.","conditions":"Principal versus agent, refunds matter."},{"name":"Retail inventory turnover","expr":"COGS/average inventory","meaning":"Working capital intensity của retail/distributor.","conditions":"Different periods and inventory definition."},{"name":"Contribution per service job","expr":"Price per job−variable job cost","meaning":"Khả năng sinh profit của contract services.","conditions":"Excludes fixed salaries/overhead."},{"name":"Unit cost scale","expr":"Fixed cost per unit=total fixed costs/output units","meaning":"Cost dilution when scale grows.","conditions":"Fixed cost total assumed constant within range."},{"name":"Subscription retention","expr":"Retained paying accounts/start cohort accounts","meaning":"Revenue stickiness across periods.","conditions":"Excludes new customers."},{"name":"Royalty plus initial fee","expr":"Franchisor revenue≈royalties+upfront franchise fees","meaning":"Simplified revenue channels.","conditions":"Accounting timing differs."},{"name":"Marketplace transaction count","expr":"GMV=transactions×average transaction value","meaning":"Describes economic platform activity.","conditions":"Does not imply platform earned all GMV."}],"examples":[{"question_en":"A broker handles $25m in transaction volume and charges 1.2%. Calculate fee revenue.","answer":"$300,000","steps_vi":["Commission=25.000.000×0,012.","Phí kiếm được 300.000 USD; volume giao dịch không phải revenue."],"check":"Broker model."},{"question_en":"A distributor buys 10,000 units at $8 and resells at $10. Gross spread?","answer":"$20,000","steps_vi":["Unit spread=10−8=2 USD.","Gross spread=2×10.000=20.000 USD trước freight và overhead."],"check":"Distributor model."},{"question_en":"A retailer generates $2m sales with $1.4m COGS. Gross margin?","answer":"30%","steps_vi":["GP=2−1,4=0,6 triệu USD.","Gross margin=0,6/2=30%."],"check":"Retail channel costs excluded."},{"question_en":"A natural resource producer sells 200,000 barrels at realized price $65. Revenue?","answer":"$13 million","steps_vi":["Sản lượng×giá thực thu.","200.000×65=13.000.000 USD trước royalties/costs."],"check":"Realized not spot if hedged."},{"question_en":"A bank earns $50m interest income, pays $32m interest expense. Net interest income?","answer":"$18 million","steps_vi":["NII=interest income−interest expense.","50−32=18 triệu USD, chưa trừ credit losses."],"check":"Do not confuse with net income."},{"question_en":"A service firm bills 18,000 professional hours out of 30,000 available. Utilization?","answer":"60%","steps_vi":["Utilization=billable/available.","18.000/30.000=60%.","Cần giải thích kết quả theo đơn vị kinh tế và điều kiện của bài."],"check":"Time-based services."},{"question_en":"A software company sells 5,000 yearly subscriptions at $300. Annual run rate?","answer":"$1.5 million","steps_vi":["ARR xấp xỉ paid subscriptions×annual fee.","5.000×300=1.500.000 USD/năm."],"check":"Accounting revenue may differ."},{"question_en":"A franchise brand collects 6% royalty on franchisee annual sales of $20m. Royalty revenue?","answer":"$1.2 million","steps_vi":["Royalty=20×6% triệu USD.","Franchisor thu 1,2 triệu USD, không phải sales20m."],"check":"Upfront fees separate."},{"question_en":"A software licensor gets $4 per unit on 100,000 third-party devices. Royalty?","answer":"$400,000","steps_vi":["Licensed units×per-unit fee.","100.000×4=400.000 USD.","Cần giải thích kết quả theo đơn vị kinh tế và điều kiện của bài."],"check":"License model."},{"question_en":"A marketplace processes $80m merchandise and keeps 5% transaction fees. Fee revenue?","answer":"$4 million","steps_vi":["GMV×take rate=80m×5%.","Platform fee revenue 4m, không phải toàn bộ GMV80m."],"check":"Platform net revenue."},{"question_en":"A retailer with $1.2m COGS and average inventory $300,000 has inventory turnover?","answer":"4.0×","steps_vi":["Turnover=COGS/average inventory.","1.200.000/300.000=4 lần."],"check":"Retail WC intensity."},{"question_en":"A service provider charges $120/job and pays $75 in variable job cost. Contribution?","answer":"$45 per job","steps_vi":["Unit contribution=120−75.","45 USD/service before fixed support costs.","Cần giải thích kết quả theo đơn vị kinh tế và điều kiện của bài."],"check":"Price minus variable cost."},{"question_en":"A brand owns no factories but pays contract producers $40/unit and sells at $85. Gross unit spread?","answer":"$45","steps_vi":["Gross spread=85−40.","45 USD trước design/marketing/logistics, dù issuer asset-light."],"check":"Contract manufacturer relationships."},{"question_en":"A manufacturer has $1m fixed plant expense and makes 100,000 units. Fixed plant cost per unit?","answer":"$10","steps_vi":["Fixed cost allocation=1m/100k.","10 USD/unit khi production 100.000.","Cần giải thích kết quả theo đơn vị kinh tế và điều kiện của bài."],"check":"Relevant range."},{"question_en":"If manufacturer output doubles to 200,000 units with unchanged $1m fixed plant expense, cost per unit?","answer":"$5","steps_vi":["Unit allocation=1m/200k.","5 USD/unit nếu total fixed costs không đổi."],"check":"Capacity assumptions."},{"question_en":"A marketplace has average transaction value $50 and 200,000 transactions. GMV?","answer":"$10 million","steps_vi":["GMV=50×200.000.","10m USD là tổng transaction value, không phải net platform fee."],"check":"Distinguish accounting revenue."},{"question_en":"A two-sided platform's buyer base grows 20% but seller base stays flat. Which risk might rise?","answer":"Matching quality/capacity bottleneck","steps_vi":["Buyer demand tăng nhưng số seller không đổi; availability/congestion có thể xấu đi.","Cross-side balance quan trọng hơn gross users alone."],"check":"Qualitative platform risk."},{"question_en":"A firm collects $250,000 royalties and $50,000 initial franchise fees. Combined stated fees?","answer":"$300,000","steps_vi":["Royalties+initial fees=250k+50k.","Tổng receipts theo dữ liệu đề=300k, revenue recognition timing có thể khác."],"check":"Franchisor model."},{"question_en":"A broker processes 1,000 deals, each $20,000, at 1% commission. Revenue?","answer":"$200,000","steps_vi":["Traded value=1.000×20.000=20m USD.","Fee revenue=20m×1%=200.000 USD.","Cần giải thích kết quả theo đơn vị kinh tế và điều kiện của bài."],"check":"Broker not principal."},{"question_en":"A bank receives 8% interest on $100m loans and pays 3% on $80m interest-bearing deposits. Net interest income?","answer":"$5.6 million","steps_vi":["Interest received=8m, paid=2,4m.","Net interest income=5,6m USD; chưa tính loan-loss provisions."],"check":"Simplified mix."},{"question_en":"A service firm bills 12,000 hours at $150/hour. Service revenue?","answer":"$1.8 million","steps_vi":["Fees=12.000×150.","1,8m USD trước labor và overhead."],"check":"Hours/utilization."},{"question_en":"A retailer sells product at $100 with $75 COGS. Gross unit margin?","answer":"25%","steps_vi":["Gross profit=25 USD.","Gross margin=25/100=25%.","Cần giải thích kết quả theo đơn vị kinh tế và điều kiện của bài."],"check":"Not markup on cost 33.3%."},{"question_en":"A distributor's $1m goods cost rises 10% while resale revenue stays $1.25m. New gross spread?","answer":"$150,000","steps_vi":["New COGS=1,1m USD.","Spread=1,25m−1,1m=150k, giảm từ 250k."],"check":"Commodity cost pass-through."},{"question_en":"A platform has $30m GMV and 6% fee, but waives fees on half the transactions. Revenue?","answer":"$900,000","steps_vi":["Fee-bearing GMV=15m USD.","15m×6%=900k; không được lấy toàn GMV."],"check":"Pricing subsidies."},{"question_en":"A subscription company starts with 10,000 paying users and retains 9,100. Cohort retention?","answer":"91%","steps_vi":["Retention=9.100/10.000.","91% trước users mới."],"check":"Recurring revenue quality."},{"question_en":"A manufacturer produces 500 units with variable cost $300 and sells at $500. Contribution total?","answer":"$100,000","steps_vi":["Contribution/unit=500−300=200 USD.","500×200=100.000 USD để trả fixed costs."],"check":"Manufacturing operating leverage."}],"questions":[{"stem_en":"Which conventional business model primarily monetizes raw materials or extracted commodities?","options":["Natural resource producer.","Broker.","Retailer."],"correct":0,"why_vi":"Resource producer kiếm tiền từ quyền khai thác và sản lượng raw materials với giá bán commodity.","trap_vi":"Exposure to realized prices."},{"stem_en":"A company transforms raw materials into finished goods and sells to retailers. It is primarily a:","options":["Bank.","Manufacturer.","Broker."],"correct":1,"why_vi":"Manufacturer tạo thành phẩm từ inputs, cần production capacity và quality control.","trap_vi":"May outsource factories."},{"stem_en":"A firm purchases manufactured products and transports them to retailers. Its main model is:","options":["Software subscription.","Natural resource production.","Distribution."],"correct":2,"why_vi":"Distributor phối hợp inventory/logistics và gross trading spreads.","trap_vi":"Distinct from retail end user."},{"stem_en":"A retailer's primary customer base is generally:","options":["End consumers.","Only upstream raw material suppliers.","Only bond investors."],"correct":0,"why_vi":"Retailer bán goods trực tiếp cho end users, qua store/digital.","trap_vi":"Consumer channels."},{"stem_en":"A business earns commissions for matching buyers and sellers. The primary model is:","options":["Resource producer.","Broker.","Asset-owning manufacturer."],"correct":1,"why_vi":"Broker nhận fee cho kết nối, transaction value khác fee revenue.","trap_vi":"Intermediary economics."},{"stem_en":"A bank's net interest income is chiefly:","options":["Gross value of loans issued.","Customer subscriptions times fee.","Interest income minus interest expense."],"correct":2,"why_vi":"Bank kiếm spread trên interest-bearing assets và funding liabilities.","trap_vi":"Credit losses separately."},{"stem_en":"A consulting firm selling specialized hours and expertise is best described as:","options":["Service producer.","Natural resource producer.","Retailer holding large inventories."],"correct":0,"why_vi":"Service producer bán expertise/time-based outcomes.","trap_vi":"Skilled people key input."},{"stem_en":"A cloud software issuer earning monthly access fees is most likely a:","options":["Distributor of groceries.","Software/service subscription provider.","Oil producer."],"correct":1,"why_vi":"SaaS monetization recurring access và needs digital service infrastructure.","trap_vi":"Costs of acquisition."},{"stem_en":"A franchise model commonly involves:","options":["Franchisor owning every store as a mandatory rule.","Zero brand rights.","Licensing brand/operating system for royalties/fees."],"correct":2,"why_vi":"Franchisor monetizes rights; franchisee thường chịu local operations/capex.","trap_vi":"Royalty ≠ franchisee sales."},{"stem_en":"A contract manufacturer primarily:","options":["Produces goods for another company's brand.","Operates a financial exchange.","Collects loan interest spreads."],"correct":0,"why_vi":"Contract manufacturer làm hàng thay client/brand owner theo agreement.","trap_vi":"Customer concentration risk."},{"stem_en":"A value-added reseller differs from a pure distributor because it:","options":["Only stores raw oil barrels.","Provides installation, customization or support.","Must own the source company's intellectual property."],"correct":1,"why_vi":"VAR bổ sung service tạo differentiation và cost base.","trap_vi":"Labor cost matters."},{"stem_en":"Which activity is most consistent with licensing?","options":["Owning and operating a retail store only.","Mining and trading raw ore.","Granting use of intellectual property in exchange for fees."],"correct":2,"why_vi":"IP owner cấp quyền sử dụng và nhận royalties/fees.","trap_vi":"Contract rights important."},{"stem_en":"A franchisee reports sales $20m and pays 6% royalty. Royalty earned by franchisor is:","options":["$1.2m.","$20m.","$18.8m."],"correct":0,"why_vi":"20×6%=1,2m, không phải consolidated gross franchisee sales.","trap_vi":"Royalty base."},{"stem_en":"A marketplace processes $80m gross value and receives 5% fee. Expected fee revenue is:","options":["$80m.","$4m.","$76m."],"correct":1,"why_vi":"80×5%=4m là platform fee, tùy principal–agent accounting.","trap_vi":"GMV ≠ issuer revenue."},{"stem_en":"The most important property of a valuable network effect is:","options":["Advertising expenditure rises.","All software becomes free.","The network becomes more useful as relevant users participate."],"correct":2,"why_vi":"Network utility tăng khi nhiều participants tương tác hữu ích.","trap_vi":"Counts must create interactions."},{"stem_en":"A peer-to-peer messaging application exhibits mostly:","options":["One-sided network effects.","Two-sided bank interest margins.","Natural resource extraction."],"correct":0,"why_vi":"Users cùng một loại tạo tiện ích qua messaging cho nhau.","trap_vi":"One-sided meaning type of users."},{"stem_en":"A ride-sharing platform matching riders and drivers illustrates:","options":["Only own-store retail.","Two-sided network effects.","A risk-free collateral instrument."],"correct":1,"why_vi":"Nhiều drivers giúp riders, nhiều riders thu hút drivers.","trap_vi":"Cross-side matching."},{"stem_en":"A firm brings many buyers to a marketplace, thereby attracting sellers. This is:","options":["No network effect.","Corporate debt tax shield.","Cross-side network effect."],"correct":2,"why_vi":"Buyer volume làm seller side hấp dẫn và ngược lại.","trap_vi":"Platform balance."},{"stem_en":"If a platform subsidizes one group of users to attract another group that pays fees, it is using:","options":["Two-sided platform pricing.","A guaranteed profit loophole.","Only physical inventory markup."],"correct":0,"why_vi":"Có thể charge one side và support side kia để xây liquidity.","trap_vi":"Needs sustainable take rate."},{"stem_en":"Network effects most likely create barriers to entry when:","options":["Customers are unable to communicate.","Existing connected user network adds genuine utility.","Users can never switch legally."],"correct":1,"why_vi":"Liquidity/network utility giúp incumbent khó bị thay thế khi users active.","trap_vi":"Multi-homing can weaken moat."},{"stem_en":"The primary economics of a software-as-a-service model includes:","options":["Exclusively one-off hardware sales.","No customer acquisition cost.","Recurring subscriptions with retention and cloud support."],"correct":2,"why_vi":"SaaS có recurring fee nhưng phải trả cloud/retention/CAC.","trap_vi":"Gross recurring billings not net profit."},{"stem_en":"Which is most closely associated with an asset-light model?","options":["Outsourcing production while retaining brand and customers.","Owning every factory and all inventory by necessity.","Having no contractual obligations."],"correct":0,"why_vi":"Asset-light có thể thuê ngoài production nhưng chịu supplier/risk.","trap_vi":"Leases/commitments matter."},{"stem_en":"A manufacturer earning $75 per item with $60 goods cost has gross unit spread:","options":["$135.","$15.","$60."],"correct":1,"why_vi":"75−60=15 USD trước operating costs.","trap_vi":"Unit basis."},{"stem_en":"A bank earns $50m interest and pays $32m interest. Net interest income is:","options":["$82m.","$50m.","$18m."],"correct":2,"why_vi":"NII=50−32=18m, không phải operating income cuối cùng.","trap_vi":"Credit losses and fees omitted."},{"stem_en":"Business model innovation can occur without new technology when a company:","options":["Changes distribution and pricing to serve customers differently.","Issues common shares at a premium.","Merely changes its legal company name."],"correct":0,"why_vi":"Innovation là thay who/what/channel/price, không đòi hỏi technology mới.","trap_vi":"Distinct from product invention."},{"stem_en":"An ultra-low-cost airline model most likely relies on:","options":["Luxury full service with highest fixed costs.","Standardized operations and no-frills low fares.","Deposit-funded banking assets."],"correct":1,"why_vi":"Low-cost carriers kết hợp simple service/cost base và digital direct sales.","trap_vi":"Cost advantage critical."},{"stem_en":"A discount brokerage business most likely emphasizes:","options":["Traditional advisory only at high commissions.","Natural resource production.","Direct digital trading with low commissions."],"correct":2,"why_vi":"Direct/digital + low fee là innovation so với full-service broker.","trap_vi":"Alternative revenues must be assessed."},{"stem_en":"What differentiates a marketplace from a first-party retailer?","options":["It may connect external sellers with buyers rather than owning all goods sold.","It must own all seller inventory.","It never earns transaction fees."],"correct":0,"why_vi":"Marketplace broker intermediation; retail thường own inventory.","trap_vi":"Accounting principal–agent."},{"stem_en":"A user community creating reviews that attract customers illustrates:","options":["Debt financing risk.","Crowdsourcing and user-generated content.","Physical factory depreciation."],"correct":1,"why_vi":"Community đóng góp reviews/content để tăng discovery/trust.","trap_vi":"Moderation needed."},{"stem_en":"Compared with an owned-hotel model, a franchise hotel group may have:","options":["Higher owned property capex for every location.","No brand standards at all.","More royalty revenue with less direct property ownership."],"correct":2,"why_vi":"Franchisor scale qua franchises và phí, franchisees thường own/operate assets.","trap_vi":"Not risk-free."},{"stem_en":"A firm sells differentiated premium goods directly, while another distributes generic low-cost products. A key difference is:","options":["Pricing power and channel/operating costs.","Corporate legal form only.","Both necessarily earn equal margin."],"correct":0,"why_vi":"Differentiation, volume và fixed costs khiến economics khác nhau.","trap_vi":"Need demand/cost evidence."},{"stem_en":"A distributor sees commodity input prices rise but cannot raise resale prices. Profit margin is likely to:","options":["Increase automatically.","Compress.","Become risk free."],"correct":1,"why_vi":"Higher input cost với selling price cố định làm spread giảm.","trap_vi":"Contracts/hedges may mitigate."},{"stem_en":"A natural resource producer with unhedged commodity sales might benefit most directly from:","options":["Higher shipping insurance costs.","Higher manufacturing wages.","Higher realized commodity prices."],"correct":2,"why_vi":"Resource revenue ∝ volume×price; prices tăng có thể nâng revenue nhưng costs cũng có thể đổi.","trap_vi":"Quantity/cost matters."},{"stem_en":"When a marketplace reports $100m in GMV and $8m in fees, which is normally closer to the platform's transaction-fee revenue?","options":["$8m.","$100m.","$108m."],"correct":0,"why_vi":"Platform chỉ được hưởng take rate/fees trong agent model.","trap_vi":"Verify revenue recognition."},{"stem_en":"A network can become less attractive despite growth in user count if:","options":["All new users are perfectly matched.","Congestion, spam or poor counterpart availability increases.","Every user creates equal positive value."],"correct":1,"why_vi":"Interaction quality/congestion và fraud có thể giảm utility dù users tăng.","trap_vi":"User count insufficient."},{"stem_en":"A firm owns no production sites but depends on one contract manufacturer. Major risk is:","options":["Guaranteed lower demand volatility.","Automatic monopoly power.","Supplier concentration/disruption risk."],"correct":2,"why_vi":"Supplier dependency/quality/lead times là rủi ro lớn dù asset-light.","trap_vi":"Outsourcing is not risk elimination."},{"stem_en":"A software provider charges 5,000 customers $300 per year. Annual contracted run-rate revenue is:","options":["$1.5m.","$150,000.","$15m."],"correct":0,"why_vi":"5.000×300=1,5m USD/năm trước churn/discount.","trap_vi":"ARR simplified."},{"stem_en":"A brokerage executes 1,000 deals of $20,000 each at a 1% commission. Fee revenue is:","options":["$20m.","$200,000.","$2m."],"correct":1,"why_vi":"Gross traded volume=20m, 1% phí=200k USD.","trap_vi":"Broker revenue."},{"stem_en":"The most suitable way to classify a hybrid company is to:","options":["Choose one marketing label and ignore segment data.","Call every issuer a platform.","Analyze each revenue stream's customers, offering, channel, price, and inputs."],"correct":2,"why_vi":"Hybrid có nhiều revenue models; cần tách segment economics và nhận diện rủi ro riêng.","trap_vi":"Detailed classification."}],"cards":[{"front_en":"Explain: Eight conventional model families","back_vi":"CFAI phân loại 8 nhóm conventional: natural resource producer, manufacturer, distributor, retailer, broker, bank, service producer, software/services."},{"front_en":"Explain: Natural resource producer","back_vi":"Khai thác hoặc sản xuất raw natural resources, bán cho refiners/distributors dựa trên spot/forward contracts; quyền khai thác, capex và commodity pricing quan trọng."},{"front_en":"Explain: Manufacturer","back_vi":"Biến raw materials thành finished goods; bán cho distributor hoặc end users, cần equipment, labor, design, IP và procurement."},{"front_en":"Explain: Distributor","back_vi":"Mua hàng từ manufacturers và vận chuyển/lưu trữ/cung ứng cho retailers; earnings thường đến từ spreads, logistics fees và scale efficiency."},{"front_en":"Explain: Retailer","back_vi":"Bán finished goods trực tiếp đến end users qua stores/digital storefront, kiếm markup và đôi khi membership/service fees."},{"front_en":"Explain: Broker","back_vi":"Kết nối buyers/sellers trong deals, earning commission/listing/transaction fees; network of participants, trust và liquidity then chốt."},{"front_en":"Explain: Bank","back_vi":"Huy động funds/deposits và cung cấp loans/leases, earning interest spread/fees; balance-sheet risk, credit quality, regulation và funding costs rất quan trọng."},{"front_en":"Explain: Service producer","back_vi":"Cung cấp expertise/time/service outcomes, kiếm service fees; quan hệ khách, staff utilization, specialization ảnh hưởng revenue/expenses."},{"front_en":"Explain: Software/services","back_vi":"Bán software licenses, subscription/SaaS, maintenance/support qua direct/digital partners, cần technical expertise, platform và distribution."},{"front_en":"Explain: Private-label or contract manufacturing","back_vi":"Supplier làm sản phẩm theo thiết kế/brand của client; client tập trung R&D/marketing, producer phụ thuộc buyer contracts và utilization."},{"front_en":"Explain: Value-added reseller","back_vi":"Distributor/reseller bổ sung installation, customization, service hoặc support, nâng revenue per transaction nhưng cần skilled labor."},{"front_en":"Explain: Franchising","back_vi":"Franchisor cấp brand/process rights cho franchisee, nhận royalties/fees; franchisee thường gánh capex, operation và một phần địa phương risk."},{"front_en":"Explain: Licensing model","back_vi":"Chủ sở hữu IP cho đối tác sử dụng quyền, thường nhận royalty/fee; khác direct manufacturing hoặc franchising full operating system."},{"front_en":"Explain: Asset-light operating model","back_vi":"Doanh nghiệp outsource production/physical assets, giữ brand/software/customer relationship; cần kiểm tra supplier concentration và quality control."},{"front_en":"Explain: Asset-heavy operating model","back_vi":"Issuer trực tiếp sở hữu hotels, factories, utilities hoặc fleets, chịu depreciation/maintenance capex và fixed costs; có control assets cao hơn."},{"front_en":"Explain: Business model innovation","back_vi":"Thay đổi cách phục vụ khách, channel, pricing hoặc cost structure, có thể xảy ra ngay cả khi underlying technology không mới."},{"front_en":"Explain: Software-as-a-service (SaaS)","back_vi":"Chuyển từ upfront perpetual licenses sang recurring access fees, đòi hỏi retention, cloud reliability, product upgrades và customer success."},{"front_en":"Explain: Low-cost airline innovation","back_vi":"Điểm then chốt là no-frills service, point-to-point flights, standardized operations, low fares và digital distribution; cost structure khác full-service carriers."},{"front_en":"Explain: Discount brokerage innovation","back_vi":"Direct/digital channels và low commissions, self-service replace branch-based full advice; economics từ scale, order flow, spreads hoặc subscriptions tùy model."},{"front_en":"Explain: E-commerce model innovation","back_vi":"Online marketplace/retailer giảm geographic store constraints nhưng tăng need for fulfillment, returns, marketing và cybersecurity."},{"front_en":"Explain: Network effects concept","back_vi":"Giá trị mạng cho từng participant tăng khi số users (hoặc opposite-side users) tăng; một barrier to entry nếu interactions đủ hữu ích."},{"front_en":"Explain: One-sided network effects","back_vi":"Một nhóm users tạo value cho nhau, ví dụ communication/peer-to-peer network; key metric là connected user activity."},{"front_en":"Explain: Two-sided/multi-sided platforms","back_vi":"Kết nối hai hoặc nhiều nhóm như buyers–sellers, riders–drivers, cardholders–merchants; tăng một side có thể thu hút side kia."},{"front_en":"Explain: Cross-side network effect","back_vi":"More merchants attract customers, more customers attract merchants; network quality có thể bão hòa hoặc xấu đi nếu congestion/fraud."},{"front_en":"Explain: Platform pricing and take rate","back_vi":"Một side có thể dùng miễn phí để tăng engagement, side kia trả commission/listing fee; gross merchandise value khác recognized platform fee revenue."},{"front_en":"Explain: Crowdsourcing community","back_vi":"Users đóng góp reviews, photos, software mods hoặc advice, tăng product attractiveness và giảm 일부 content/support costs, nhưng phải kiểm duyệt chất lượng."},{"front_en":"Explain: Sharing economy models","back_vi":"Nền tảng matching unused assets/capacity với users, thường asset ownership nằm ngoài platform; trust, verification, regulatory costs và liquidity quan trọng."},{"front_en":"Explain: Hotel platform evolution","back_vi":"Hotels từ single-site sang brands/franchises, online booking platforms và home-sharing; ownership, franchise, bookings và commissions ảnh hưởng financial statements khác nhau."},{"front_en":"Explain: Supply chain shock exposure","back_vi":"Raw resource producer có thể hưởng tăng commodity price, manufacturer chịu input-cost pressure, distributors/retailers tùy pass-through/competition."},{"front_en":"Explain: Distribution bargaining power","back_vi":"Large retailers có thể ép supplier margins; manufacturers có branded differentiated goods thường pass-through tốt hơn commoditized products."},{"front_en":"Explain: Scale and scope economies","back_vi":"Unit costs có thể giảm nhờ volume, shared logistics/data/software; economies of scope kết hợp products/services dưới cùng inputs."},{"front_en":"Explain: Network defensibility and switching costs","back_vi":"High user liquidity, data network effects, reputation và integrations có thể bảo vệ platform; analyst cần xem multi-homing, competition and fees."},{"front_en":"Explain: Winner-take-most caveat","back_vi":"Network effect markets đôi khi tập trung vì one platform reaches liquidity threshold; nhưng regulation, multi-homing, niche product variation hạn chế monopoly."},{"front_en":"Explain: Conventional versus innovative mix","back_vi":"Một company có thể vừa bán products trực tiếp vừa vận hành marketplace và licensing; phân tích revenue streams độc lập tránh nhãn dán đơn giản."},{"front_en":"Explain: Business model risk and profitability","back_vi":"Đánh giá customer acquisition, pricing power, channel economics, fixed inputs, supplier concentration, technology disruption và cash conversion."},{"front_en":"Explain: Regulatory and trust dependence","back_vi":"Banking, travel, healthcare và platforms phụ thuộc compliance và user trust; network scale lớn cũng có systemic/cybersecurity risks."},{"front_en":"Explain: Analyst classification checklist","back_vi":"So sánh WHO/WHAT/WHERE/PRICE/INPUTS của issuer với conventional model; xác định hybrid, network effects, monetization và khả năng duy trì profit."}]}],"version":"2.5","language":"Vietnamese explanations with English CFA terms and English questions","qa_status":"DETAILED_DRAFT_PENDING_INDEPENDENT_ACADEMIC_AUDIT"}];